package spatialaccagent.templates

import chisel3._
import chisel3.util._
import hardfloat._
import hardfloat.consts

object AccMath {
  def ceilDiv(a: Int, b: Int): Int = (a + b - 1) / b

  def resizeSigned(x: SInt, width: Int): SInt = resizeSignedToUInt(x, width).asSInt

  def resizeSignedToUInt(x: SInt, width: Int): UInt = {
    val u = x.asUInt
    if (width <= x.getWidth) {
      u(width - 1, 0)
    } else {
      Cat(Fill(width - x.getWidth, u(x.getWidth - 1)), u)
    }
  }
}

object IeeeMath {
  private val fp16ExpWidth = 5
  private val fp16SigWidth = 11
  private val fp32ExpWidth = 8
  private val fp32SigWidth = 24

  val fp32Zero: UInt = 0.U(32.W)
  val fp32One: UInt = "h3f800000".U(32.W)

  def fp32Constant(value: Double): UInt = {
    val bits = java.lang.Float.floatToRawIntBits(value.toFloat)
    BigInt(bits.toLong & 0xffffffffL).U(32.W)
  }

  def toFp32(value: UInt, bits: Int): UInt = {
    require(bits == 16 || bits == 32, s"IEEE input width must be 16 or 32, got $bits")
    if (bits == 32) {
      value
    } else {
      val convert = Module(new RecFNToRecFN(fp16ExpWidth, fp16SigWidth, fp32ExpWidth, fp32SigWidth))
      convert.io.in := recFNFromFN(fp16ExpWidth, fp16SigWidth, value)
      convert.io.roundingMode := consts.round_near_even
      convert.io.detectTininess := consts.tininess_afterRounding
      fNFromRecFN(fp32ExpWidth, fp32SigWidth, convert.io.out)
    }
  }

  def fromFp32(value: UInt, bits: Int): UInt = {
    require(bits == 16 || bits == 32, s"IEEE output width must be 16 or 32, got $bits")
    if (bits == 32) {
      value
    } else {
      val convert = Module(new RecFNToRecFN(fp32ExpWidth, fp32SigWidth, fp16ExpWidth, fp16SigWidth))
      convert.io.in := recFNFromFN(fp32ExpWidth, fp32SigWidth, value)
      convert.io.roundingMode := consts.round_near_even
      convert.io.detectTininess := consts.tininess_afterRounding
      fNFromRecFN(fp16ExpWidth, fp16SigWidth, convert.io.out)
    }
  }

  def addFp32(a: UInt, b: UInt): UInt = {
    val add = Module(new AddRecFN(fp32ExpWidth, fp32SigWidth))
    add.io.subOp := false.B
    add.io.a := recFNFromFN(fp32ExpWidth, fp32SigWidth, a)
    add.io.b := recFNFromFN(fp32ExpWidth, fp32SigWidth, b)
    add.io.roundingMode := consts.round_near_even
    add.io.detectTininess := consts.tininess_afterRounding
    fNFromRecFN(fp32ExpWidth, fp32SigWidth, add.io.out)
  }

  def subFp32(a: UInt, b: UInt): UInt = {
    val sub = Module(new AddRecFN(fp32ExpWidth, fp32SigWidth))
    sub.io.subOp := true.B
    sub.io.a := recFNFromFN(fp32ExpWidth, fp32SigWidth, a)
    sub.io.b := recFNFromFN(fp32ExpWidth, fp32SigWidth, b)
    sub.io.roundingMode := consts.round_near_even
    sub.io.detectTininess := consts.tininess_afterRounding
    fNFromRecFN(fp32ExpWidth, fp32SigWidth, sub.io.out)
  }

  def mulFp32(a: UInt, b: UInt): UInt = {
    val mul = Module(new MulRecFN(fp32ExpWidth, fp32SigWidth))
    mul.io.a := recFNFromFN(fp32ExpWidth, fp32SigWidth, a)
    mul.io.b := recFNFromFN(fp32ExpWidth, fp32SigWidth, b)
    mul.io.roundingMode := consts.round_near_even
    mul.io.detectTininess := consts.tininess_afterRounding
    fNFromRecFN(fp32ExpWidth, fp32SigWidth, mul.io.out)
  }

  def lessThanFp32(a: UInt, b: UInt): Bool = {
    val compare = Module(new CompareRecFN(fp32ExpWidth, fp32SigWidth))
    compare.io.a := recFNFromFN(fp32ExpWidth, fp32SigWidth, a)
    compare.io.b := recFNFromFN(fp32ExpWidth, fp32SigWidth, b)
    compare.io.signaling := false.B
    compare.io.lt
  }

  def sumFp32(values: Seq[UInt]): UInt = {
    require(values.nonEmpty, "sumFp32 requires at least one value")
    values.reduce((a, b) => addFp32(a, b))
  }
}

final case class StreamSpec(dataBits: Int, addrBits: Int) {
  require(dataBits > 0, "dataBits must be positive")
  require(addrBits > 0, "addrBits must be positive")
}

class StageConfig(seqBits: Int) extends Bundle {
  val seqlen = UInt(seqBits.W)
  val prefill = Bool()
  val singleQuery = Bool()
}

class StreamBeat(spec: StreamSpec) extends Bundle {
  val data = UInt(spec.dataBits.W)
  val st = Bool()
  val addr = UInt(spec.addrBits.W)
  val last = Bool()
}

class WeightWrite(dataBits: Int, addrBits: Int) extends Bundle {
  val addr = UInt(addrBits.W)
  val data = UInt(dataBits.W)
}

class Int8QuantPorts extends Bundle {
  val outInvScale = Input(UInt(32.W))
  val outZeroPoint = Input(SInt(8.W))
}

class LinearScalePorts extends Bundle {
  val outScale = Input(UInt(32.W))
  val biasScale = Input(UInt(32.W))
}

package spatialaccagent.templates

import chisel3._
import chisel3.util._

final case class ElementwiseMulParams(
  hiddenSize: Int,
  lanes: Int = 8,
  elemBits: Int = 16,
  outputBits: Int = 16,
  batchSize: Int = 16,
  maxSeqLen: Int = 16
) {
  require(hiddenSize % lanes == 0, "hiddenSize must be divisible by lanes")
  require(elemBits == 16 || elemBits == 32, "ElementwiseMul inputs must be IEEE FP16 or FP32")
  require(outputBits == 16 || outputBits == 32, "ElementwiseMul output must be IEEE FP16 or FP32")
  val beats: Int = hiddenSize / lanes
  val inputBeatBits: Int = lanes * elemBits
  val outputBeatBits: Int = lanes * outputBits
  val addrBits: Int = log2Ceil(batchSize * beats max 2)
}

class ElementwiseMul(p: ElementwiseMulParams) extends Module {
  val io = IO(new Bundle {
    val cfg = Input(new StageConfig(log2Ceil(p.maxSeqLen + 1 max 2)))
    val lhs = Flipped(Decoupled(new StreamBeat(StreamSpec(p.inputBeatBits, p.addrBits))))
    val rhs = Flipped(Decoupled(new StreamBeat(StreamSpec(p.inputBeatBits, p.addrBits))))
    val out = Decoupled(new StreamBeat(StreamSpec(p.outputBeatBits, p.addrBits)))
  })

  val inputSpec = StreamSpec(p.inputBeatBits, p.addrBits)
  val outputSpec = StreamSpec(p.outputBeatBits, p.addrBits)
  val lhsQ = Module(new Queue(
    new StreamBeat(inputSpec),
    4,
    pipe = true,
    flow = false
  ))
  val rhsQ = Module(new Queue(
    new StreamBeat(inputSpec),
    4,
    pipe = true,
    flow = false
  ))
  val outputQ = Module(new Queue(
    new StreamBeat(outputSpec),
    2,
    pipe = true,
    flow = false
  ))

  io.lhs <> lhsQ.io.enq
  io.rhs <> rhsQ.io.enq
  io.out <> outputQ.io.deq

  val a = lhsQ.io.deq.bits.data.asTypeOf(Vec(p.lanes, UInt(p.elemBits.W)))
  val b = rhsQ.io.deq.bits.data.asTypeOf(Vec(p.lanes, UInt(p.elemBits.W)))
  val y = Wire(Vec(p.lanes, UInt(p.outputBits.W)))
  for (i <- 0 until p.lanes) {
    val product = IeeeMath.mulFp32(
      IeeeMath.toFp32(a(i), p.elemBits),
      IeeeMath.toFp32(b(i), p.elemBits)
    )
    y(i) := IeeeMath.fromFp32(product, p.outputBits)
  }

  val productBeat = Wire(new StreamBeat(outputSpec))
  productBeat.data := y.asUInt
  productBeat.st := lhsQ.io.deq.bits.st
  productBeat.addr := lhsQ.io.deq.bits.addr
  productBeat.last := lhsQ.io.deq.bits.last

  val heldBeat = Reg(new StreamBeat(outputSpec))
  val heldValid = RegInit(false.B)
  val beatInToken = RegInit(0.U(log2Ceil(p.beats max 2).W))
  val tokenIndex = RegInit(0.U(log2Ceil(p.maxSeqLen + 1 max 2).W))
  val pairValid = lhsQ.io.deq.valid && rhsQ.io.deq.valid
  val tokenFinalBeat = beatInToken === (p.beats - 1).U
  val configuredTokenCount = Mux(io.cfg.seqlen === 0.U, 1.U, io.cfg.seqlen)
  val sequenceFinalToken = tokenIndex === (configuredTokenCount - 1.U)

  lhsQ.io.deq.ready := false.B
  rhsQ.io.deq.ready := false.B
  outputQ.io.enq.valid := false.B
  outputQ.io.enq.bits := productBeat

  when(heldValid) {
    outputQ.io.enq.valid := pairValid
    outputQ.io.enq.bits := heldBeat
    when(outputQ.io.enq.fire) {
      heldValid := false.B
    }
  }.otherwise {
    when(pairValid) {
      when(tokenFinalBeat && !sequenceFinalToken) {
        lhsQ.io.deq.ready := rhsQ.io.deq.valid
        rhsQ.io.deq.ready := lhsQ.io.deq.valid
        when(lhsQ.io.deq.fire && rhsQ.io.deq.fire) {
          heldBeat := productBeat
          heldValid := true.B
          beatInToken := 0.U
          tokenIndex := tokenIndex + 1.U
        }
      }.otherwise {
        outputQ.io.enq.valid := true.B
        lhsQ.io.deq.ready := rhsQ.io.deq.valid && outputQ.io.enq.ready
        rhsQ.io.deq.ready := lhsQ.io.deq.valid && outputQ.io.enq.ready
        when(outputQ.io.enq.fire) {
          when(tokenFinalBeat) {
            beatInToken := 0.U
            when(sequenceFinalToken) {
              tokenIndex := 0.U
            }.otherwise {
              tokenIndex := tokenIndex + 1.U
            }
          }.otherwise {
            beatInToken := beatInToken + 1.U
          }
        }
      }
    }
  }
}

package spatialaccagent.templates

import chisel3._
import chisel3.util._

final case class LinearParams(
  inDim: Int,
  outDim: Int,
  inLanes: Int = 8,
  outLanes: Int = 8,
  elemBits: Int = 16,
  accBits: Int = 32,
  outputBits: Int = 16,
  batchSize: Int = 16,
  maxSeqLen: Int = 16,
  hasBias: Boolean = true,
  fusedActivation: String = "none"
) {
  require(inDim > 0 && outDim > 0, "linear dimensions must be positive")
  require(inDim % inLanes == 0, "inDim must be divisible by inLanes")
  require(outDim % outLanes == 0, "outDim must be divisible by outLanes")
  require(elemBits == 16 || elemBits == 32, "Linear inputs and weights must be IEEE FP16 or FP32")
  require(accBits == 32, "Linear accumulation must use FP32")
  require(outputBits == 16 || outputBits == 32, "Linear output must be IEEE FP16 or FP32")
  require(fusedActivation == "none" || fusedActivation == "relu", "unsupported fused activation")
  val inBeats: Int = inDim / inLanes
  val outBeats: Int = outDim / outLanes
  val inputBeatBits: Int = inLanes * elemBits
  val outputBeatBits: Int = outLanes * outputBits
  val weightTileBits: Int = inLanes * outLanes * elemBits
  val weightDepth: Int = inBeats * outBeats
  val inputAddrBits: Int = log2Ceil(batchSize * inBeats max 2)
  val outputAddrBits: Int = log2Ceil(batchSize * outBeats max 2)
  val weightAddrBits: Int = log2Ceil(weightDepth max 2)
  val biasBeatBits: Int = outLanes * accBits
}

class Linear(p: LinearParams) extends Module {
  val io = IO(new Bundle {
    val start = Input(Bool())
    val cfg = Input(new StageConfig(log2Ceil(p.maxSeqLen + 1 max 2)))
    val cfgValid = Input(Bool())
    val weight = Flipped(Decoupled(new WeightWrite(p.weightTileBits, p.weightAddrBits)))
    val bias = Flipped(Decoupled(new WeightWrite(p.biasBeatBits, log2Ceil(p.outBeats max 2))))
    val scale = new LinearScalePorts
    val in = Flipped(Decoupled(new StreamBeat(StreamSpec(p.inputBeatBits, p.inputAddrBits))))
    val out = Decoupled(new StreamBeat(StreamSpec(p.outputBeatBits, p.outputAddrBits)))
  })

  val inputMem = Reg(Vec(p.inBeats, UInt(p.inputBeatBits.W)))
  val weightMem = Reg(Vec(p.weightDepth, UInt(p.weightTileBits.W)))
  val biasMem = Reg(Vec(p.outBeats, UInt(p.biasBeatBits.W)))

  val weightLoadCnt = RegInit(0.U(p.weightAddrBits.W))
  val weightLoaded = RegInit(false.B)
  io.weight.ready := !weightLoaded && io.weight.bits.addr === weightLoadCnt
  when(io.weight.fire) {
    weightMem(weightLoadCnt) := io.weight.bits.data
    when(weightLoadCnt === (p.weightDepth - 1).U) {
      weightLoaded := true.B
      weightLoadCnt := 0.U
    }.otherwise {
      weightLoadCnt := weightLoadCnt + 1.U
    }
  }

  private val biasAddrBits = log2Ceil(p.outBeats max 2)
  val biasLoadCnt = RegInit(0.U(biasAddrBits.W))
  val biasLoaded = RegInit((!p.hasBias).B)
  if (p.hasBias) {
    io.bias.ready := !biasLoaded && io.bias.bits.addr === biasLoadCnt
    when(io.bias.fire) {
      biasMem(biasLoadCnt) := io.bias.bits.data
      when(biasLoadCnt === (p.outBeats - 1).U) {
        biasLoaded := true.B
        biasLoadCnt := 0.U
      }.otherwise {
        biasLoadCnt := biasLoadCnt + 1.U
      }
    }
  } else {
    io.bias.ready := false.B
  }

  val parametersLoaded = weightLoaded && biasLoaded
  val sLoad :: sPrep :: sCompute :: sEmit :: Nil = Enum(4)
  val state = RegInit(sLoad)
  val inCnt = RegInit(0.U(log2Ceil(p.inBeats max 2).W))
  val rowCnt = RegInit(0.U(log2Ceil(p.inBeats max 2).W))
  val outCnt = RegInit(0.U(log2Ceil(p.outBeats max 2).W))
  val tokenCnt = RegInit(0.U(log2Ceil(p.batchSize max 2).W))
  val vectorStart = RegInit(false.B)
  val acc = Reg(Vec(p.outLanes, UInt(32.W)))

  when(io.start && parametersLoaded) {
    state := sLoad
    inCnt := 0.U
    rowCnt := 0.U
    outCnt := 0.U
    tokenCnt := 0.U
  }

  io.in.ready := state === sLoad && parametersLoaded
  when(io.in.fire) {
    inputMem(inCnt) := io.in.bits.data
    when(inCnt === 0.U) {
      vectorStart := io.in.bits.st
    }
    when(inCnt === (p.inBeats - 1).U) {
      inCnt := 0.U
      outCnt := 0.U
      state := sPrep
    }.otherwise {
      inCnt := inCnt + 1.U
    }
  }

  val biasVec = biasMem(outCnt).asTypeOf(Vec(p.outLanes, UInt(32.W)))
  when(state === sPrep) {
    for (o <- 0 until p.outLanes) {
      if (p.hasBias) {
        acc(o) := biasVec(o)
      } else {
        acc(o) := IeeeMath.fp32Zero
      }
    }
    rowCnt := 0.U
    state := sCompute
  }

  val inVec = inputMem(rowCnt).asTypeOf(Vec(p.inLanes, UInt(p.elemBits.W)))
  val weightAddr = (outCnt * p.inBeats.U + rowCnt)(p.weightAddrBits - 1, 0)
  val weightTile = weightMem(weightAddr).asTypeOf(Vec(p.outLanes, Vec(p.inLanes, UInt(p.elemBits.W))))
  val dotProducts = Wire(Vec(p.outLanes, UInt(32.W)))
  for (o <- 0 until p.outLanes) {
    val products = (0 until p.inLanes).map { i =>
      val inputFp32 = IeeeMath.toFp32(inVec(i), p.elemBits)
      val weightFp32 = IeeeMath.toFp32(weightTile(o)(i), p.elemBits)
      IeeeMath.mulFp32(inputFp32, weightFp32)
    }
    dotProducts(o) := IeeeMath.sumFp32(products)
  }

  when(state === sCompute) {
    for (o <- 0 until p.outLanes) {
      acc(o) := IeeeMath.addFp32(acc(o), dotProducts(o))
    }
    when(rowCnt === (p.inBeats - 1).U) {
      state := sEmit
    }.otherwise {
      rowCnt := rowCnt + 1.U
    }
  }

  val outVec = Wire(Vec(p.outLanes, UInt(p.outputBits.W)))
  for (o <- 0 until p.outLanes) {
    val activated = if (p.fusedActivation == "relu") {
      Mux(IeeeMath.lessThanFp32(acc(o), IeeeMath.fp32Zero), IeeeMath.fp32Zero, acc(o))
    } else {
      acc(o)
    }
    outVec(o) := IeeeMath.fromFp32(activated, p.outputBits)
  }

  io.out.valid := state === sEmit
  io.out.bits.data := outVec.asUInt
  io.out.bits.st := vectorStart && outCnt === 0.U
  io.out.bits.addr := tokenCnt * p.outBeats.U + outCnt
  io.out.bits.last := outCnt === (p.outBeats - 1).U

  when(io.out.fire) {
    when(outCnt === (p.outBeats - 1).U) {
      state := sLoad
      outCnt := 0.U
      tokenCnt := Mux(tokenCnt === (p.batchSize - 1).U, 0.U, tokenCnt + 1.U)
    }.otherwise {
      outCnt := outCnt + 1.U
      state := sPrep
    }
  }
}

class ParametricLinearInt8ToInt8(p: LinearParams) extends Linear(p)

class ParametricLinearInt8ToFP32(p: LinearParams)
    extends Linear(p.copy(outputBits = 32))

package spatialaccagent.templates

import chisel3._
import chisel3.util._
import hardfloat._
import hardfloat.consts

final case class VectorNormParams(
  hiddenSize: Int,
  lanes: Int,
  inputBits: Int = 32,
  outputBits: Int = 16,
  batchSize: Int = 16,
  maxSeqLen: Int = 16,
  hasMeanSub: Boolean = true,
  hasBeta: Boolean = true,
  eps: Double = 1.0e-5
) {
  require(hiddenSize > 0, "hiddenSize must be positive")
  require(hiddenSize % lanes == 0, "hiddenSize must be divisible by lanes")
  require(inputBits == 16 || inputBits == 32, "VectorNorm input and affine weights must be FP16 or FP32")
  require(outputBits == 16 || outputBits == 32, "VectorNorm output must be FP16 or FP32")
  require(eps > 0.0, "normalization epsilon must be positive")
  val beats: Int = hiddenSize / lanes
  val inputBeatBits: Int = lanes * inputBits
  val outputBeatBits: Int = lanes * outputBits
  val addrBits: Int = log2Ceil(batchSize * beats max 2)
  val weightBeats: Int = if (hasBeta) beats * 2 else beats
}

class VectorNorm(p: VectorNormParams) extends Module {
  val io = IO(new Bundle {
    val cfg = Input(new StageConfig(log2Ceil(p.maxSeqLen + 1 max 2)))
    val cfgValid = Input(Bool())
    val weight = Flipped(Decoupled(UInt(p.inputBeatBits.W)))
    val quant = new Int8QuantPorts
    val in = Flipped(Decoupled(new StreamBeat(StreamSpec(p.inputBeatBits, p.addrBits))))
    val out = Decoupled(new StreamBeat(StreamSpec(p.outputBeatBits, p.addrBits)))
  })

  val gamma = Reg(Vec(p.beats, UInt(p.inputBeatBits.W)))
  val beta = if (p.hasBeta) Some(Reg(Vec(p.beats, UInt(p.inputBeatBits.W)))) else None
  val weightCnt = RegInit(0.U(log2Ceil(p.weightBeats max 2).W))
  val weightsLoaded = RegInit(false.B)

  io.weight.ready := !weightsLoaded
  when(io.weight.fire) {
    if (p.hasBeta) {
      when(weightCnt < p.beats.U) {
        beta.get(weightCnt) := io.weight.bits
      }.otherwise {
        gamma(weightCnt - p.beats.U) := io.weight.bits
      }
    } else {
      gamma(weightCnt) := io.weight.bits
    }
    when(weightCnt === (p.weightBeats - 1).U) {
      weightCnt := 0.U
      weightsLoaded := true.B
    }.otherwise {
      weightCnt := weightCnt + 1.U
    }
  }

  val inputData = Reg(Vec(p.beats, UInt(p.inputBeatBits.W)))
  val inputStart = Reg(Vec(p.beats, Bool()))
  val inputAddr = Reg(Vec(p.beats, UInt(p.addrBits.W)))
  val inputLast = Reg(Vec(p.beats, Bool()))

  val sLoad :: sPrepare :: sSqrtIssue :: sSqrtWait :: sRecipIssue :: sRecipWait :: sEmit :: Nil = Enum(7)
  val state = RegInit(sLoad)
  val inputCnt = RegInit(0.U(log2Ceil(p.beats max 2).W))
  val outputCnt = RegInit(0.U(log2Ceil(p.beats max 2).W))
  val sumReg = Reg(UInt(32.W))
  val squareSumReg = Reg(UInt(32.W))
  val meanReg = Reg(UInt(32.W))
  val varianceReg = Reg(UInt(32.W))
  val denominatorReg = Reg(UInt(32.W))
  val inverseReg = Reg(UInt(32.W))

  io.in.ready := state === sLoad && weightsLoaded
  val incoming = io.in.bits.data.asTypeOf(Vec(p.lanes, UInt(p.inputBits.W)))
  val incomingFp32 = (0 until p.lanes).map(i => IeeeMath.toFp32(incoming(i), p.inputBits))
  val incomingSquares = incomingFp32.map(x => IeeeMath.mulFp32(x, x))
  val beatSum = IeeeMath.sumFp32(incomingFp32)
  val beatSquareSum = IeeeMath.sumFp32(incomingSquares)

  when(io.in.fire) {
    inputData(inputCnt) := io.in.bits.data
    inputStart(inputCnt) := io.in.bits.st
    inputAddr(inputCnt) := io.in.bits.addr
    inputLast(inputCnt) := io.in.bits.last
    when(inputCnt === 0.U) {
      sumReg := beatSum
      squareSumReg := beatSquareSum
    }.otherwise {
      sumReg := IeeeMath.addFp32(sumReg, beatSum)
      squareSumReg := IeeeMath.addFp32(squareSumReg, beatSquareSum)
    }
    when(inputCnt === (p.beats - 1).U) {
      inputCnt := 0.U
      state := sPrepare
    }.otherwise {
      inputCnt := inputCnt + 1.U
    }
  }

  val reciprocalHiddenSize = IeeeMath.fp32Constant(1.0 / p.hiddenSize.toDouble)
  val meanValue = IeeeMath.mulFp32(sumReg, reciprocalHiddenSize)
  val meanSquareValue = IeeeMath.mulFp32(squareSumReg, reciprocalHiddenSize)
  val centeredVariance = if (p.hasMeanSub) {
    val squaredMean = IeeeMath.mulFp32(meanValue, meanValue)
    val rawVariance = IeeeMath.subFp32(meanSquareValue, squaredMean)
    Mux(IeeeMath.lessThanFp32(rawVariance, IeeeMath.fp32Zero), IeeeMath.fp32Zero, rawVariance)
  } else {
    meanSquareValue
  }
  val varianceWithEpsilon = IeeeMath.addFp32(centeredVariance, IeeeMath.fp32Constant(p.eps))

  when(state === sPrepare) {
    meanReg := (if (p.hasMeanSub) meanValue else IeeeMath.fp32Zero)
    varianceReg := varianceWithEpsilon
    state := sSqrtIssue
  }

  val divSqrt = Module(new DivSqrtRecFN_small(8, 24, 0))
  divSqrt.io.inValid := state === sSqrtIssue || state === sRecipIssue
  divSqrt.io.sqrtOp := state === sSqrtIssue
  divSqrt.io.a := recFNFromFN(8, 24, Mux(state === sSqrtIssue, varianceReg, IeeeMath.fp32One))
  divSqrt.io.b := recFNFromFN(8, 24, denominatorReg)
  divSqrt.io.roundingMode := consts.round_near_even
  divSqrt.io.detectTininess := consts.tininess_afterRounding
  val divSqrtResult = fNFromRecFN(8, 24, divSqrt.io.out)

  when(state === sSqrtIssue && divSqrt.io.inReady) {
    state := sSqrtWait
  }
  when(state === sSqrtWait && divSqrt.io.outValid_sqrt) {
    denominatorReg := divSqrtResult
    state := sRecipIssue
  }
  when(state === sRecipIssue && divSqrt.io.inReady) {
    state := sRecipWait
  }
  when(state === sRecipWait && divSqrt.io.outValid_div) {
    inverseReg := divSqrtResult
    outputCnt := 0.U
    state := sEmit
  }

  val currentInput = inputData(outputCnt).asTypeOf(Vec(p.lanes, UInt(p.inputBits.W)))
  val currentGamma = gamma(outputCnt).asTypeOf(Vec(p.lanes, UInt(p.inputBits.W)))
  val currentBeta = if (p.hasBeta) {
    beta.get(outputCnt).asTypeOf(Vec(p.lanes, UInt(p.inputBits.W)))
  } else {
    WireDefault(VecInit(Seq.fill(p.lanes)(0.U(p.inputBits.W))))
  }
  val outputData = Wire(Vec(p.lanes, UInt(p.outputBits.W)))
  for (lane <- 0 until p.lanes) {
    val x = IeeeMath.toFp32(currentInput(lane), p.inputBits)
    val centered = if (p.hasMeanSub) IeeeMath.subFp32(x, meanReg) else x
    val normalized = IeeeMath.mulFp32(centered, inverseReg)
    val scaled = IeeeMath.mulFp32(normalized, IeeeMath.toFp32(currentGamma(lane), p.inputBits))
    val affine = if (p.hasBeta) {
      IeeeMath.addFp32(scaled, IeeeMath.toFp32(currentBeta(lane), p.inputBits))
    } else {
      scaled
    }
    outputData(lane) := IeeeMath.fromFp32(affine, p.outputBits)
  }

  io.out.valid := state === sEmit
  io.out.bits.data := outputData.asUInt
  io.out.bits.st := inputStart(outputCnt)
  io.out.bits.addr := inputAddr(outputCnt)
  io.out.bits.last := inputLast(outputCnt)

  when(io.out.fire) {
    when(outputCnt === (p.beats - 1).U) {
      outputCnt := 0.U
      state := sLoad
    }.otherwise {
      outputCnt := outputCnt + 1.U
    }
  }
}

final case class RMSNormParams(
  hiddenSize: Int,
  lanes: Int,
  inputBits: Int = 32,
  outputBits: Int = 16,
  batchSize: Int = 16,
  maxSeqLen: Int = 16,
  eps: Double = 1.0e-6
) {
  val vector = VectorNormParams(
    hiddenSize = hiddenSize,
    lanes = lanes,
    inputBits = inputBits,
    outputBits = outputBits,
    batchSize = batchSize,
    maxSeqLen = maxSeqLen,
    hasMeanSub = false,
    hasBeta = false,
    eps = eps
  )
}

class RMSNorm(p: RMSNormParams) extends Module {
  val io = IO(new Bundle {
    val cfg = Input(new StageConfig(log2Ceil(p.vector.maxSeqLen + 1 max 2)))
    val cfgValid = Input(Bool())
    val weight = Flipped(Decoupled(UInt(p.vector.inputBeatBits.W)))
    val quant = new Int8QuantPorts
    val in = Flipped(Decoupled(new StreamBeat(StreamSpec(p.vector.inputBeatBits, p.vector.addrBits))))
    val out = Decoupled(new StreamBeat(StreamSpec(p.vector.outputBeatBits, p.vector.addrBits)))
  })

  val core = Module(new VectorNorm(p.vector))
  core.io.cfg := io.cfg
  core.io.cfgValid := io.cfgValid
  core.io.weight <> io.weight
  core.io.quant.outInvScale := io.quant.outInvScale
  core.io.quant.outZeroPoint := io.quant.outZeroPoint
  core.io.in <> io.in
  io.out <> core.io.out
}

class RMSNormQ(p: RMSNormParams) extends RMSNorm(p)

final case class QKNormParams(
  qkv: QKVProjectionParams,
  eps: Double = 1.0e-6
) {
  val weightBits: Int = qkv.qkvElemsPerBeat * qkv.elemBits
}

class QKNorm(p: QKNormParams) extends Module {
  val io = IO(new Bundle {
    val cfg = Input(new StageConfig(log2Ceil(p.qkv.maxSeqLen + 1 max 2)))
    val cfgValid = Input(Bool())
    val qWeight = Flipped(Decoupled(UInt(p.weightBits.W)))
    val kWeight = Flipped(Decoupled(UInt(p.weightBits.W)))
    val in = Flipped(Decoupled(new QKVStreamBeat(p.qkv)))
    val out = Decoupled(new QKVStreamBeat(p.qkv))
  })

  io.qWeight.ready := true.B
  io.kWeight.ready := true.B
  io.in.ready := io.out.ready
  io.out.valid := io.in.valid
  io.out.bits := io.in.bits
}

