          end else begin
            word_lane <= word_lane + 4'd1;
            runtime_word_index <= runtime_word_index + 11'd1;
            runtime_data_q <= select_word(read_data_q, word_lane + 4'd1);
            runtime_addr_q <= runtime_word_index + 11'd1;
            runtime_last_q <= ((runtime_word_index + 11'd1) == (RUNTIME_WORDS - 11'd1));
          end
        end
      end
      S_KERNEL_START: begin
        kernel_start_q <= 1'b0;
        kernel_invocation_launched <= 1'b0;
        trace_current_layer_index <= layer_index;
        input_axi_index <= 20'd0;
        prefetch_index <= 20'd0;
        output_write_index <= 20'd0;
        output_accept_count <= 12'd0;
        output_token_beat_count <= 7'd0;
        kernel_token_rearm_pending <= 1'b0;
        output_fifo_write_index <= 10'd0;
        output_fifo_read_index <= 10'd0;
        output_fifo_count <= 10'd0;
        output_ingress_half <= 1'b0;
        output_ingress_low <= 256'd0;
        input_launch_limit <= (layer_index == LAST_LAYER) ?
                              {10'd0, ACTIVATION_AXI_BEATS} :
                              {10'd0, ACTIVATION_AXI_BEATS_PER_TOKEN};
        output_pair_valid <= 1'b0;
        kernel_input_valid_q <= 1'b0;
        state <= S_COMPUTE_RUN;
      end
      S_COMPUTE_RUN: begin
        if (output_pair_valid) begin
          axi_awaddr_q <= activation_write_base(layer_index) + beat_offset(output_write_index);
          axi_awlen_q <= 8'd0;
          axi_awvalid_q <= 1'b1;
          axi_wdata_q <= output_pair_data;
          axi_wstrb_q <= 64'hffffffffffffffff;
          axi_wlast_q <= 1'b1;
          axi_wvalid_q <= 1'b1;
          write_aw_done <= 1'b0;
          write_w_done <= 1'b0;
          output_pair_valid <= 1'b0;
          state <= S_COMPUTE_OUT_AW;
        end else if ((output_fifo_count != 10'd0) &&
                     !(kernel_output_fire && output_ingress_half)) begin
          output_pair_data <= output_fifo[output_fifo_read_index];
          output_pair_valid <= 1'b1;
          output_fifo_read_index <= output_fifo_read_index + 10'd1;
          output_fifo_count <= output_fifo_count - 10'd1;
        end else if ((input_axi_index < {10'd0, ACTIVATION_AXI_BEATS}) &&
                     (input_axi_index < input_launch_limit)) begin
          axi_araddr_q <= activation_read_base(layer_index) + beat_offset(input_axi_index);
          axi_arlen_q <= 8'd0;
          axi_arvalid_q <= 1'b1;
          state <= S_COMPUTE_INPUT_AR;
        end else if ((layer_index != LAST_LAYER) && (prefetch_index < WEIGHT_AXI_BEATS)) begin
          if (prefetch_index == 20'd0) begin
            trace_weight_prefetch_start <= 1'b1;
            trace_current_layer_index <= layer_index;
            trace_prefetch_layer_index <= layer_index + 5'd1;
          end
          axi_araddr_q <= weight_image_layer_base(layer_index + 5'd1) + beat_offset(prefetch_index);
          axi_arlen_q <= 8'd0;
          axi_arvalid_q <= 1'b1;
          state <= S_COMPUTE_PREF_AR;
        end else if ((output_accept_count == {1'b0, KERNEL_TRANSFER_BEATS}) &&
                     (output_write_index == {10'd0, ACTIVATION_AXI_BEATS}) &&
                     (output_fifo_count == 10'd0) &&
                     !output_ingress_half && !output_pair_valid) begin
          trace_layer_output_complete <= 1'b1;
          trace_current_layer_index <= layer_index;
          state <= S_LAYER_DONE;
        end
      end
      S_COMPUTE_INPUT_AR: begin
        if (axi_arvalid_q && c0_ddr4_s_axi_arready) begin
          axi_arvalid_q <= 1'b0;
          axi_rready_q <= 1'b1;
          state <= S_COMPUTE_INPUT_R;
        end
      end
      S_COMPUTE_INPUT_R: begin
        if (axi_rready_q && c0_ddr4_s_axi_rvalid) begin
          read_data_q <= c0_ddr4_s_axi_rdata;
          axi_error_q <= axi_error_q | (c0_ddr4_s_axi_rresp != 2'b00) | (~c0_ddr4_s_axi_rlast);
          axi_rready_q <= 1'b0;
          kernel_input_valid_q <= 1'b1;
          kernel_input_data_q <= c0_ddr4_s_axi_rdata[255:0];
          state <= S_COMPUTE_INPUT_LO;
        end
      end
      S_COMPUTE_INPUT_LO: begin
        if (kernel_input_valid_q && kernel_input_ready) begin
          if ((input_axi_index == 20'd0) && !kernel_invocation_launched) begin
            kernel_input_valid_q <= 1'b0;
            state <= S_COMPUTE_ARM;
          end else begin
            kernel_input_data_q <= read_data_q[511:256];
            state <= S_COMPUTE_INPUT_HI;
          end
        end
      end
      S_COMPUTE_ARM: begin
        kernel_start_q <= 1'b1;
        kernel_invocation_launched <= 1'b1;
        trace_kernel_start <= 1'b1;
        trace_current_layer_index <= layer_index;
        kernel_input_valid_q <= 1'b0;
        kernel_input_data_q <= read_data_q[511:256];
        state <= S_COMPUTE_INPUT_HI;
      end
      S_COMPUTE_INPUT_HI: begin
        if (!kernel_input_valid_q) begin
          kernel_input_valid_q <= 1'b1;
          kernel_input_data_q <= read_data_q[511:256];
        end else if (kernel_input_valid_q && kernel_input_ready) begin
          kernel_input_valid_q <= 1'b0;
          input_axi_index <= input_axi_index + 20'd1;
          state <= S_COMPUTE_RUN;
        end
      end
      S_COMPUTE_PREF_AR: begin
        if (axi_arvalid_q && c0_ddr4_s_axi_arready) begin
          axi_arvalid_q <= 1'b0;
          axi_rready_q <= 1'b1;
          state <= S_COMPUTE_PREF_R;
        end
      end
      S_COMPUTE_PREF_R: begin
        if (axi_rready_q && c0_ddr4_s_axi_rvalid) begin
          read_data_q <= c0_ddr4_s_axi_rdata;
          axi_error_q <= axi_error_q | (c0_ddr4_s_axi_rresp != 2'b00) | (~c0_ddr4_s_axi_rlast);
          axi_rready_q <= 1'b0;
          axi_awaddr_q <= inactive_weight_bank_base(layer_index) + beat_offset(prefetch_index);
          axi_awlen_q <= 8'd0;
          axi_awvalid_q <= 1'b1;
          axi_wdata_q <= c0_ddr4_s_axi_rdata;
          axi_wstrb_q <= 64'hffffffffffffffff;
          axi_wlast_q <= 1'b1;
          axi_wvalid_q <= 1'b1;
          write_aw_done <= 1'b0;
          write_w_done <= 1'b0;
          state <= S_COMPUTE_PREF_AW;
        end
      end
      S_COMPUTE_PREF_AW: begin
        if (axi_awvalid_q && c0_ddr4_s_axi_awready) begin
          axi_awvalid_q <= 1'b0;
          write_aw_done <= 1'b1;
        end
        if (axi_wvalid_q && c0_ddr4_s_axi_wready) begin
          axi_wvalid_q <= 1'b0;
          write_w_done <= 1'b1;
        end
        if ((write_aw_done || (axi_awvalid_q && c0_ddr4_s_axi_awready)) && (write_w_done || (axi_wvalid_q && c0_ddr4_s_axi_wready))) begin
          axi_bready_q <= 1'b1;
          state <= S_COMPUTE_PREF_B;
        end
      end
      S_COMPUTE_PREF_B: begin
        if (axi_bready_q && c0_ddr4_s_axi_bvalid) begin
          axi_bready_q <= 1'b0;
          axi_error_q <= axi_error_q | (c0_ddr4_s_axi_bresp != 2'b00);
          prefetch_index <= prefetch_index + 20'd1;
          if ((prefetch_index + 20'd1) == WEIGHT_AXI_BEATS) begin
            trace_weight_prefetch_complete <= 1'b1;
            trace_current_layer_index <= layer_index;
            trace_prefetch_layer_index <= layer_index + 5'd1;
            input_launch_limit <= {10'd0, ACTIVATION_AXI_BEATS};
          end
          state <= S_COMPUTE_RUN;
        end
      end
      S_COMPUTE_OUT_AW: begin
        if (axi_awvalid_q && c0_ddr4_s_axi_awready) begin
          axi_awvalid_q <= 1'b0;
          write_aw_done <= 1'b1;
        end
        if (axi_wvalid_q && c0_ddr4_s_axi_wready) begin
          axi_wvalid_q <= 1'b0;
          write_w_done <= 1'b1;
        end
        if ((write_aw_done || (axi_awvalid_q && c0_ddr4_s_axi_awready)) && (write_w_done || (axi_wvalid_q && c0_ddr4_s_axi_wready))) begin
          axi_bready_q <= 1'b1;
          state <= S_COMPUTE_OUT_B;
        end
      end
      S_COMPUTE_OUT_B: begin
        if (axi_bready_q && c0_ddr4_s_axi_bvalid) begin
          axi_bready_q <= 1'b0;
          axi_error_q <= axi_error_q | (c0_ddr4_s_axi_bresp != 2'b00);
          output_write_index <= output_write_index + 20'd1;
          state <= S_COMPUTE_RUN;
        end
      end
      S_LAYER_DONE: begin
        if (layer_index == LAST_LAYER) begin
          kernel_reset_q <= 1'b1;
          reset_count <= 11'd0;
          state <= S_FINAL_RESET;
        end else if (prefetch_index == WEIGHT_AXI_BEATS) begin
          trace_weight_bank_switch <= 1'b1;
          trace_activation_bank_switch <= 1'b1;
          trace_current_layer_index <= layer_index;
          layer_index <= layer_index + 5'd1;
          kernel_reset_q <= 1'b1;
          reset_count <= 11'd0;
          state <= S_KERNEL_RESET;
        end
      end
      S_FINAL_RESET: begin
        kernel_reset_q <= 1'b1;
        trace_private_kernel_reset <= 1'b1;
        if (reset_count == 11'd7) begin
          reset_count <= 11'd0;
          state <= S_FINAL_COPY_SETUP;
        end else begin
          reset_count <= reset_count + 11'd1;
        end
      end
      S_FINAL_COPY_SETUP: begin
        trace_final_writeback_start <= 1'b1;
        trace_current_layer_index <= LAST_LAYER;
        copy_src_base <= activation_write_base(LAST_LAYER);
        copy_dst_base <= OUTPUT_TOKENS_BASE;
        copy_beats <= {10'd0, ACTIVATION_AXI_BEATS};
        copy_index <= 20'd0;
        copy_return_state <= S_COMPLETE;
        copy_updates_prefetch <= 1'b0;
        copy_trace_prefetch <= 1'b0;
        copy_trace_final <= 1'b1;
        state <= S_COPY_AR;
      end
      S_COMPLETE: begin
        busy_q <= 1'b0;
        kernel_reset_q <= 1'b1;
        if (batch_count_q != 3'd0) begin
          batch_count_q <= batch_count_q - 3'd1;
        end
        if (result_count_q != 3'd7) begin
          result_count_q <= result_count_q + 3'd1;
        end
        state <= S_IDLE;
      end
      default: begin
        state <= S_IDLE;
        kernel_reset_q <= 1'b1;
      end
    endcase
  end
end

endmodule

module spatialacc_axi4_protocol_monitor #(
  parameter ADDR_WIDTH = 37,
  parameter DATA_WIDTH = 512,
  parameter ID_WIDTH = 4,
  parameter READ_OUTSTANDING_LIMIT = 2,
  parameter WRITE_OUTSTANDING_LIMIT = 2
)(
  input aclk,
  input aresetn,
  input calib_complete,
  input [ID_WIDTH-1:0] awid,
  input [ADDR_WIDTH-1:0] awaddr,
  input [7:0] awlen,
  input [2:0] awsize,
  input [1:0] awburst,
  input awlock,
  input [3:0] awcache,
  input [2:0] awprot,
  input awvalid,
  input awready,
  input [DATA_WIDTH-1:0] wdata,
  input [(DATA_WIDTH/8)-1:0] wstrb,
  input wlast,
  input wvalid,
  input wready,
  input [ID_WIDTH-1:0] bid,
  input [1:0] bresp,
  input bvalid,
  input bready,
  input [ID_WIDTH-1:0] arid,
  input [ADDR_WIDTH-1:0] araddr,
  input [7:0] arlen,
  input [2:0] arsize,
  input [1:0] arburst,
  input arlock,
  input [3:0] arcache,
  input [2:0] arprot,
  input arvalid,
  input arready,
  input [DATA_WIDTH-1:0] rdata,
  input [ID_WIDTH-1:0] rid,
  input [1:0] rresp,
  input rlast,
  input rvalid,
  input rready
);
  reg violation;
  reg aw_hold;
  reg [ID_WIDTH-1:0] awid_hold;
  reg [ADDR_WIDTH-1:0] awaddr_hold;
  reg [7:0] awlen_hold;
  reg [2:0] awsize_hold;
  reg [1:0] awburst_hold;
  reg awlock_hold;
  reg [3:0] awcache_hold;
  reg [2:0] awprot_hold;
  reg ar_hold;
  reg [ID_WIDTH-1:0] arid_hold;
  reg [ADDR_WIDTH-1:0] araddr_hold;
  reg [7:0] arlen_hold;
  reg [2:0] arsize_hold;
  reg [1:0] arburst_hold;
  reg arlock_hold;
  reg [3:0] arcache_hold;
  reg [2:0] arprot_hold;
  reg w_hold;
  reg [DATA_WIDTH-1:0] wdata_hold;
  reg [(DATA_WIDTH/8)-1:0] wstrb_hold;
  reg wlast_hold;
  reg [ID_WIDTH-1:0] expected_bid;
  reg expected_bid_valid;
  reg [ID_WIDTH-1:0] expected_rid;
  reg expected_rid_valid;
  integer read_outstanding;
  integer write_outstanding;
  integer expected_w_beats;
  integer seen_w_beats;
  integer expected_r_beats;
  integer seen_r_beats;
  integer aw_bytes;
  integer ar_bytes;

  always @(posedge aclk) begin
    if (!aresetn) begin
      violation <= 1'b0;
      aw_hold <= 1'b0;
      ar_hold <= 1'b0;
      w_hold <= 1'b0;
      expected_bid <= {ID_WIDTH{1'b0}};
      expected_bid_valid <= 1'b0;
      expected_rid <= {ID_WIDTH{1'b0}};
      expected_rid_valid <= 1'b0;
      read_outstanding <= 0;
      write_outstanding <= 0;
      expected_w_beats <= 0;
      seen_w_beats <= 0;
      expected_r_beats <= 0;
      seen_r_beats <= 0;
    end else begin
      if (!calib_complete && (awvalid || arvalid || wvalid)) begin
        violation <= 1'b1;
      end
      if (awvalid && !awready && !aw_hold) begin
        aw_hold <= 1'b1;
        awid_hold <= awid;
        awaddr_hold <= awaddr;
        awlen_hold <= awlen;
        awsize_hold <= awsize;
        awburst_hold <= awburst;
        awlock_hold <= awlock;
        awcache_hold <= awcache;
        awprot_hold <= awprot;
      end else if (awvalid && !awready && aw_hold) begin
        if ((awid_hold != awid) || (awaddr_hold != awaddr) ||
            (awlen_hold != awlen) || (awsize_hold != awsize) ||
            (awburst_hold != awburst) || (awlock_hold != awlock) ||
            (awcache_hold != awcache) || (awprot_hold != awprot)) begin
          violation <= 1'b1;
        end
      end
      if (awvalid && awready) begin
        aw_hold <= 1'b0;
        expected_bid <= awid;
        expected_bid_valid <= 1'b1;
        write_outstanding <= write_outstanding + 1;
        expected_w_beats <= awlen + 1;
        seen_w_beats <= 0;
        aw_bytes = (awlen + 1) << awsize;
        if (awburst != 2'b01) violation <= 1'b1;
        if (awsize > 3'b110) violation <= 1'b1;
        if ((awaddr[11:0] + aw_bytes) > 4096) violation <= 1'b1;
      end
      if (wvalid && !wready && !w_hold) begin
        w_hold <= 1'b1;
        wdata_hold <= wdata;
        wstrb_hold <= wstrb;
        wlast_hold <= wlast;
      end else if (wvalid && !wready && w_hold) begin
        if ((wdata_hold != wdata) || (wstrb_hold != wstrb) || (wlast_hold != wlast)) begin
          violation <= 1'b1;
        end
      end
      if (wvalid && wready) begin
        w_hold <= 1'b0;
        if (wlast != (seen_w_beats == (expected_w_beats - 1))) begin
          violation <= 1'b1;
        end
        seen_w_beats <= seen_w_beats + 1;
      end
      if (bvalid && bready) begin
        if (write_outstanding <= 0) violation <= 1'b1;
        else write_outstanding <= write_outstanding - 1;
        if (!expected_bid_valid || (bid != expected_bid)) violation <= 1'b1;
        expected_bid_valid <= 1'b0;
        if (bresp != 2'b00) violation <= 1'b1;
      end
      if (arvalid && !arready && !ar_hold) begin
        ar_hold <= 1'b1;
        arid_hold <= arid;
        araddr_hold <= araddr;
        arlen_hold <= arlen;
        arsize_hold <= arsize;
        arburst_hold <= arburst;
        arlock_hold <= arlock;
        arcache_hold <= arcache;
        arprot_hold <= arprot;
      end else if (arvalid && !arready && ar_hold) begin
        if ((arid_hold != arid) || (araddr_hold != araddr) ||
            (arlen_hold != arlen) || (arsize_hold != arsize) ||
            (arburst_hold != arburst) || (arlock_hold != arlock) ||
            (arcache_hold != arcache) || (arprot_hold != arprot)) begin
          violation <= 1'b1;
        end
      end
      if (arvalid && arready) begin
        ar_hold <= 1'b0;
        expected_rid <= arid;
        expected_rid_valid <= 1'b1;
        read_outstanding <= read_outstanding + 1;
        expected_r_beats <= arlen + 1;
        seen_r_beats <= 0;
        ar_bytes = (arlen + 1) << arsize;
        if (arburst != 2'b01) violation <= 1'b1;
        if (arsize > 3'b110) violation <= 1'b1;
        if ((araddr[11:0] + ar_bytes) > 4096) violation <= 1'b1;
      end
      if (rvalid && rready) begin
        if (!expected_rid_valid || (rid != expected_rid)) violation <= 1'b1;
        if (rresp != 2'b00) violation <= 1'b1;
        if (rlast != (seen_r_beats == (expected_r_beats - 1))) begin
          violation <= 1'b1;
        end
        if (rlast) begin
          if (read_outstanding <= 0) violation <= 1'b1;
          else read_outstanding <= read_outstanding - 1;
          expected_rid_valid <= 1'b0;
        end
        seen_r_beats <= seen_r_beats + 1;
      end
      if (read_outstanding > READ_OUTSTANDING_LIMIT) violation <= 1'b1;
      if (write_outstanding > WRITE_OUTSTANDING_LIMIT) violation <= 1'b1;
      if ((wvalid && wready) && (wstrb == {(DATA_WIDTH/8){1'b0}})) violation <= 1'b1;
      if ($isunknown({awid, awaddr, awlen, awsize, awburst, awlock, awcache, awprot,
                      awvalid, awready, wdata, wstrb, wlast, wvalid, wready,
                      bid, bresp, bvalid, bready, arid, araddr, arlen, arsize,
                      arburst, arlock, arcache, arprot, arvalid, arready, rdata,
                      rid, rresp, rlast, rvalid, rready})) begin
        violation <= 1'b1;
      end
      if (violation) begin
        $fatal(1, "SPATIALACC_AXI_PROTOCOL_VIOLATION");
      end
    end
  end
endmodule

module spatialacc_exact_board_multilayer_tb;
  localparam integer TARGET_LAYERS = 1;
  localparam integer LAST_LAYER = TARGET_LAYERS - 1;
  localparam integer BEATS_PER_LAYER = 1792;
  localparam integer TARGET_TOKENS = 16;
