  reg [3:0] c0_ddr4_s_axi_bid;
  reg [1:0] c0_ddr4_s_axi_bresp;
  reg c0_ddr4_s_axi_bvalid;
  wire [3:0] c0_ddr4_s_axi_arid;
  wire [36:0] c0_ddr4_s_axi_araddr;
  wire [7:0] c0_ddr4_s_axi_arlen;
  wire [2:0] c0_ddr4_s_axi_arsize;
