  function automatic [31:0] payload_digest256(input [255:0] value);
    integer digest_lane;
    reg [31:0] digest;
    begin
      digest = 32'd0;
      for (digest_lane = 0; digest_lane < 8; digest_lane = digest_lane + 1) begin
        digest = digest ^ value[(digest_lane*32) +: 32];
      end
      payload_digest256 = digest;
    end
  endfunction

