      $display("SPATIALACC_STAGE_TRACE stage=%s cycle=%0d token=%0d beat=%0d event=%s signal=%s scalar_value=%s",
               stage_name, cycle_count, token_index, beat_index, event_name,
               signal_name, json_logic(scalar_value));
    end
  endtask

