            )
        },
        "checkpoint_artifacts": checkpoint_artifact_result,
        "remote_resource_policy": {
            "vcs_parallel_compile_jobs": vcs_compile_jobs,
            "vcs_parallel_compile_args_applied": sorted(
                set(vcs_parallel_args_applied)
