`define	INSTR_REGINDEX_OFFSET	25
`define	INSTR_CONTEXT_OFFSET	0
`define	INSTR_WIDTH (`INSTR_OP_WIDTH+`INSTR_REGINDEX_WIDTH+`INSTR_CONTEXT_WIDTH)   // 32

// op
`define	INPUT_LOAD		3'b000
`define	PARAM_LOAD		3'b001
`define	PROCESS			3'b010
`define OUTPUT_STORE	3'b011


// input data type
`define IS_DATA         2'b01
`define IS_PARAM        2'b10
