wire	[2*`DATAWIDTH+4-1:0]	data_to_pat_11 [3:0];
wire	[2*`DATAWIDTH+4-1:0]	data_to_pat_12 [3:0];
wire	[2*`DATAWIDTH+4-1:0]	data_to_pat_21 [3:0];
wire	[2*`DATAWIDTH+4-1:0]	data_to_pat_22 [3:0];

wire	[2*`DATAWIDTH+4-1:0]	data_to_pat_31 [3:0];
wire	[2*`DATAWIDTH+4-1:0]	data_to_pat_32 [3:0];
wire	[2*`DATAWIDTH+4-1:0]	data_to_pat_41 [3:0];
wire	[2*`DATAWIDTH+4-1:0]	data_to_pat_42 [3:0];

(*keep="true"*)	reg			param_wr_enable	[MICRO_PE_NUM-1:0];
(*keep="true"*) reg	[6:0]	param_wr_addr	[MICRO_PE_NUM-1:0];
(*keep="true"*) reg	[`DATAWIDTH*8-1:0]	param_wr_data [MICRO_PE_NUM-1:0];

(*keep="true"*)	reg	[5:0]	param_rd_addr	[MICRO_PE_NUM-1:0];
(*keep="true"*) reg         param_tdm_sel_tmp [MICRO_PE_NUM-1:0];
(*keep="true"*) reg			param_tdm_sel	[MICRO_PE_NUM-1:0];

reg                         out_param_tdm_sel_tmp;
//reg     [5:0]               out_param_tdm_addr_tmp;


wire	[2*`DATAWIDTH+4-1:0]	data_to_pat	[15:0];

(*keep="true"*)reg 	[3:0]		data_to_pat_valid_dly2;

(*keep="true"*)reg  [3:0]       acc_clear_dly2;    

wire    [47:0]                  pre_result_1 [3:0],
                                pre_result_2 [3:0],
                                pre_result_3 [3:0];

(*keep="true"*)reg	[1:0]		config_interconnection[3:0]; // to reduce the fanout
(*keep="true"*)reg				config_relu_enable [3:0];
(*keep="true"*)reg				config_branch_add_enable [3:0];
(*keep="true"*)reg              config_specific_enable [3:0];
(*keep="true"*)reg	[5:0]		config_branch_add_enable_rep [3:0];
reg								pe_result_sel_dly;



always @(posedge clk_sys) begin
	config_interconnection[0] <= iConfig_interconnection;
	config_interconnection[1] <= iConfig_interconnection;
	config_interconnection[2] <= iConfig_interconnection;
	config_interconnection[3] <= iConfig_interconnection;

	config_relu_enable[0] <= iConfig_relu_enable;
	config_relu_enable[1] <= iConfig_relu_enable;
	config_relu_enable[2] <= iConfig_relu_enable;
	config_relu_enable[3] <= iConfig_relu_enable;

	config_branch_add_enable[0] <= iConfig_branch_add_enable;
	config_branch_add_enable[1] <= iConfig_branch_add_enable;
	config_branch_add_enable[2] <= iConfig_branch_add_enable;
	config_branch_add_enable[3] <= iConfig_branch_add_enable;

	config_specific_enable[0] <= iConfig_specific_enable;
	config_specific_enable[1] <= iConfig_specific_enable;
	config_specific_enable[2] <= iConfig_specific_enable;
	config_specific_enable[3] <= iConfig_specific_enable;

	config_branch_add_enable_rep[0] <= {6{config_branch_add_enable[0]}};
	config_branch_add_enable_rep[1] <= {6{config_branch_add_enable[1]}};
	config_branch_add_enable_rep[2] <= {6{config_branch_add_enable[2]}};
	config_branch_add_enable_rep[3] <= {6{config_branch_add_enable[3]}};

end

assign	oConfig_interconnection = config_interconnection[0];
assign	oConfig_relu_enable = config_relu_enable[0];
assign	oConfig_branch_add_enable = config_branch_add_enable[0];
assign  oConfig_specific_enable = config_specific_enable[0];

always @(posedge clk_sys) begin
    data_to_pat_valid_dly2 <= {4{config_branch_add_enable[0] ? iBranch_in_datavalid : iAcc_valid}};
    acc_clear_dly2 <= {4{iAcc_clear}};
end

genvar num;
generate

for(num=0;num<MICRO_PE_NUM;num=num+1) begin
	if(num < MICRO_PE_NUM/2)
		always @(posedge clk_sys) begin
			param_wr_enable[num] <= iParam_wr_enable & (iParam_id[5:1] == INDEX) & (iParam_id[0] == 1'b0);
			param_wr_data[num] <= {iParam_wr_data[(7+num*8)*`DATAWIDTH+:`DATAWIDTH],iParam_wr_data[(6+num*8)*`DATAWIDTH+:`DATAWIDTH],
								   iParam_wr_data[(5+num*8)*`DATAWIDTH+:`DATAWIDTH],iParam_wr_data[(4+num*8)*`DATAWIDTH+:`DATAWIDTH],
								   iParam_wr_data[(3+num*8)*`DATAWIDTH+:`DATAWIDTH],iParam_wr_data[(2+num*8)*`DATAWIDTH+:`DATAWIDTH],
								   iParam_wr_data[(1+num*8)*`DATAWIDTH+:`DATAWIDTH],iParam_wr_data[(0+num*8)*`DATAWIDTH+:`DATAWIDTH]};
		end
	else
		always @(posedge clk_sys) begin
			param_wr_enable[num] <= iParam_wr_enable & (iParam_id[5:1] == INDEX) & (iParam_id[0] == 1'b1);
			param_wr_data[num] <= {iParam_wr_data[(7+(num-MICRO_PE_NUM/2)*8)*`DATAWIDTH+:`DATAWIDTH],iParam_wr_data[(6+(num-MICRO_PE_NUM/2)*8)*`DATAWIDTH+:`DATAWIDTH],
								   iParam_wr_data[(5+(num-MICRO_PE_NUM/2)*8)*`DATAWIDTH+:`DATAWIDTH],iParam_wr_data[(4+(num-MICRO_PE_NUM/2)*8)*`DATAWIDTH+:`DATAWIDTH],
								   iParam_wr_data[(3+(num-MICRO_PE_NUM/2)*8)*`DATAWIDTH+:`DATAWIDTH],iParam_wr_data[(2+(num-MICRO_PE_NUM/2)*8)*`DATAWIDTH+:`DATAWIDTH],
								   iParam_wr_data[(1+(num-MICRO_PE_NUM/2)*8)*`DATAWIDTH+:`DATAWIDTH],iParam_wr_data[(0+(num-MICRO_PE_NUM/2)*8)*`DATAWIDTH+:`DATAWIDTH]};
		end

	always @(posedge clk_sys) begin
		param_wr_addr[num] <= iParam_wr_addr;
	end

	always @(posedge clk_sys) begin
		param_rd_addr[num] <= iParam_rd_addr;
	end

	always @(posedge clk_dsp) begin
		param_tdm_sel_tmp[num] <= iParam_tdm_sel;
		param_tdm_sel[num] <= param_tdm_sel_tmp[num];
	end
end

endgenerate

always @(posedge clk_sys) begin
	oParam_wr_enable <= iParam_wr_enable;
	oParam_wr_addr <= iParam_wr_addr;
	oParam_id <= iParam_id;
	oParam_wr_data <= iParam_wr_data;	
	oParam_rd_addr <= iParam_rd_addr;
end


always @(posedge clk_sys) begin
    oData1 <= iData1;
    oData2 <= iData2;
    oData3 <= iData3;
    oData4 <= iData4;
end

always @(posedge clk_dsp) begin
    out_param_tdm_sel_tmp <= iParam_tdm_sel;
	oParam_tdm_sel <= out_param_tdm_sel_tmp;
	pe_result_sel_dly <= iPE_result_sel;
	oPE_result_sel <= pe_result_sel_dly;
end

always @(posedge clk_sys) begin
	oAcc_valid <= iAcc_valid;
	oAcc_clear <= iAcc_clear;
end

genvar j;
generate
	for(j=0;j<4;j=j+1) begin
		// first 2 pat
		assign	data_to_pat[j+4*0] = config_branch_add_enable[0] ? 
										iBranch_in_data_1[(j+4*0)*(2*`DATAWIDTH+4)+:2*`DATAWIDTH+4] :
										data_to_pat_11[j];

		assign	data_to_pat[j+4*1] = config_branch_add_enable[1] ?
										iBranch_in_data_1[(j+4*1)*(2*`DATAWIDTH+4)+:2*`DATAWIDTH+4] :
										data_to_pat_12[j];

		// second 2 pat
		assign	data_to_pat[j+4*2] = config_branch_add_enable[2] ?
										iBranch_in_data_2[(j+4*0)*(2*`DATAWIDTH+4)+:2*`DATAWIDTH+4] :
										data_to_pat_21[j];

		assign	data_to_pat[j+4*3] = config_branch_add_enable[3] ? 
										iBranch_in_data_2[(j+4*1)*(2*`DATAWIDTH+4)+:2*`DATAWIDTH+4] :
										data_to_pat_22[j];
	end 
endgenerate

