`include "fucore.vh"
module	bias_buffer (
			//
				input		                             clk,
				input		                             rst,
			//
				input	[3:0]	                         iBias_data_valid,
				input	[511:0]	                         iBias_data,
				input	[3:0]	                         iBias_border,
			//
			    input                                    iChanged_bias,
				output	reg [`BIAS_BUFFER_DATAWIDTH-1:0] oBias_rd_data
		);

reg  [`BIAS_BUFFER_DATAWIDTH-1:0]   data_mem [2:0];
(*keep="true"*)reg  [2:0]           data_flag [15:0];
reg  [`BIAS_BUFFER_DATAWIDTH-1:0]   data_tmp;
(*keep="true"*)reg  [15:0]          in_bias_data_valid;
(*keep="true"*)reg  [15:0]          changed_bias;

always @(posedge clk)
    oBias_rd_data <= data_mem[0];

genvar j;
generate
for(j=0;j<16;j=j+1) begin
    always @(posedge clk) begin
        in_bias_data_valid[j] <= iBias_data_valid[3];
        changed_bias[j] <= iChanged_bias;
        if(iBias_data_valid[0])
            data_tmp[0*512+j*32+:32] <= iBias_data[j*32+:32];
        if(iBias_data_valid[1])
            data_tmp[1*512+j*32+:32] <= iBias_data[j*32+:32];
        if(iBias_data_valid[2])
            data_tmp[2*512+j*32+:32] <= iBias_data[j*32+:32];
        if(iBias_data_valid[3])
            data_tmp[3*512+j*32+:32] <= iBias_data[j*32+:32];
    end
end
endgenerate

genvar i;
generate
for(i=0;i<16;i=i+1) begin : repeat_i
always @(posedge clk)
    if(rst)
        data_flag[i] <= 3'b0;
    else
        case(data_flag[i])
            3'b000 : 
                if(in_bias_data_valid[i])
                    data_flag[i] <= 3'b001;
            3'b001 :
                case({in_bias_data_valid[i],changed_bias[i]})
                    2'b11:  data_flag[i] <= 3'b001;
                    2'b10:  data_flag[i] <= 3'b011;
                    2'b01:  data_flag[i] <= 3'b000;
                    default:
                            data_flag[i] <= data_flag[i];
                endcase
                /*
                if(in_bias_data_valid[i] & changed_bias[i])
                    data_flag[i] <= 2'b01;
                else if(in_bias_data_valid[i] & (~changed_bias[i]))
                    data_flag[i] <= 2'b11;
                else if((~in_bias_data_valid[i]) & changed_bias[i])
                    data_flag[i] <= 2'b00;
                */
            3'b011 :
                case({in_bias_data_valid[i],changed_bias[i]})
                    2'b11: data_flag[i] <= 3'b011;
                    2'b10: data_flag[i] <= 3'b111;
                    2'b01: data_flag[i] <= 3'b001;
                    default: data_flag[i] <= data_flag[i];
                endcase
            3'b111 :
                case({in_bias_data_valid[i],changed_bias[i]})
                    2'b11: data_flag[i] <= 3'b111;
                    2'b10: data_flag[i] <= 3'b111;
                    2'b01: data_flag[i] <= 3'b011;
                    default: data_flag[i] <= data_flag[i];
                endcase
                /*
                if(in_bias_data_valid[i])
                    data_flag[i] <= 2'b11;
                else if((~in_bias_data_valid[i]) & changed_bias[i])
                    data_flag[i] <= 2'b01;
                 */
            default:
                data_flag[i] <= 3'b00;
        endcase

//
always @(posedge clk) begin
    case(data_flag[i])
        3'b000:
            begin
                if(in_bias_data_valid[i])
                    data_mem[0][i*128+:128] <= data_tmp[i*128+:128];
                    data_mem[1][i*128+:128] <= data_mem[1][i*128+:128];
                    data_mem[2][i*128+:128] <= data_mem[2][i*128+:128];
                end
        3'b001:
            begin
                case({in_bias_data_valid[i],changed_bias[i]})
                    2'b11:  
                        begin
                            data_mem[0][i*128+:128] <= data_tmp[i*128+:128];
                            data_mem[1][i*128+:128] <= data_mem[1][i*128+:128];
                            data_mem[2][i*128+:128] <= data_mem[2][i*128+:128];
                        end
                    2'b10:
                        begin
                            data_mem[0][i*128+:128] <= data_mem[0][i*128+:128];
                            data_mem[1][i*128+:128] <= data_tmp[i*128+:128];
                            data_mem[2][i*128+:128] <= data_mem[2][i*128+:128];
                        end
                    default:
                        begin
                            data_mem[0][i*128+:128] <= data_mem[0][i*128+:128];
                            data_mem[1][i*128+:128] <= data_mem[1][i*128+:128];
                            data_mem[2][i*128+:128] <= data_mem[2][i*128+:128];
                        end
                endcase       
            end
        3'b011:
            begin
                case({in_bias_data_valid[i],changed_bias[i]})
                    2'b11:  
                        begin
                            data_mem[0][i*128+:128] <= data_mem[1][i*128+:128];
                            data_mem[1][i*128+:128] <= data_tmp[i*128+:128];
                            data_mem[2][i*128+:128] <= data_mem[2][i*128+:128];
                        end
                    2'b10:
                        begin
                            data_mem[0][i*128+:128] <= data_mem[0][i*128+:128];
                            data_mem[1][i*128+:128] <= data_mem[1][i*128+:128];
                            data_mem[2][i*128+:128] <= data_tmp[i*128+:128];
                        end
                    2'b01:
                        begin
                            data_mem[0][i*128+:128] <= data_mem[1][i*128+:128];
                            data_mem[1][i*128+:128] <= data_mem[1][i*128+:128];
                            data_mem[2][i*128+:128] <= data_mem[2][i*128+:128];
                        end
                    default:
                        begin
                            data_mem[0][i*128+:128] <= data_mem[0][i*128+:128];
                            data_mem[1][i*128+:128] <= data_mem[1][i*128+:128];
                            data_mem[2][i*128+:128] <= data_mem[1][i*128+:128];
                        end
                endcase  
            end
        3'b111:
            begin
                case({in_bias_data_valid[i],changed_bias[i]})
                    2'b11 :
                        begin
                            data_mem[0][i*128+:128] <= data_mem[1][i*128+:128];
                            data_mem[1][i*128+:128] <= data_mem[2][i*128+:128];
                            data_mem[2][i*128+:128] <= data_tmp[i*128+:128];
                        end
                    2'b10 : // in this case, drop the oldest bias, error will detected
                        begin
                            data_mem[0][i*128+:128] <= data_mem[1][i*128+:128];
                            data_mem[1][i*128+:128] <= data_mem[2][i*128+:128];
                            data_mem[2][i*128+:128] <= data_tmp[i*128+:128];
                        end
                    2'b01 :
                        begin
                            data_mem[0][i*128+:128] <= data_mem[1][i*128+:128];
                            data_mem[1][i*128+:128] <= data_mem[2][i*128+:128];
                            data_mem[2][i*128+:128] <= data_tmp[i*128+:128];
                        end
                    default:
                        begin
                            data_mem[0][i*128+:128] <= data_mem[0][i*128+:128];
                            data_mem[1][i*128+:128] <= data_mem[1][i*128+:128];
                            data_mem[2][i*128+:128] <= data_mem[2][i*128+:128];
                        end
                endcase
            end
        default:
            begin
                data_mem[0][i*128+:128] <= data_mem[0][i*128+:128];
                data_mem[1][i*128+:128] <= data_mem[1][i*128+:128];
                data_mem[2][i*128+:128] <= data_mem[2][i*128+:128];
            end
   endcase
end
end
endgenerate



endmodule

module data_organization (
	input			clk,
	input			rst,
	input	[255:0]	iRead_data,
	input			iRead_data_valid,
	input	[9:0]	iCol_count,
	input	[3:0]	iKernel_col_count,
	input	[3:0]	iKernel_row_count,
	input 			iMode,
	input           iIs_32_mode,

	output	[511:0]	oResult,
	output 			oResult_valid
	);
//lantency 4(gen_addr) + 21 (URAM_LATENCY) + 3 + 1
localparam LATENCY = 29;

reg 	 				mode_count;
reg 					data_sel;
reg [1:0]				store_sel;

//
reg [1023:0]    		rd_data_store;
reg [1023:0]			data_store_1;
reg [1023:0]			data_store_2;
reg [1023:0]			data_store_3;

//
reg [9:0]	col_count [LATENCY-1:0];
reg [3:0]	kernel_col_count [LATENCY-1:0];
reg [3:0]	kernel_row_count [LATENCY-1:0];
(*keep="true"*)reg [9:0]	col_count_dly [1:0];
reg [3:0]	kernel_col_count_dly [1:0];
reg [3:0]	kernel_row_count_dly;
reg			read_data_valid_dly[1:0];
reg			mode_count_dly;
reg			data_sel_dly;

wire        mode_count_meet_border; 


//added by xtfan
reg         mode_dly [2:0];
reg         is_32_mode_dly [2:0];
(*keep="true"*)reg         mode_rep [3:0];

always @(posedge clk) begin: loop_dly
    integer i;
    mode_dly[0] <= iMode;
    mode_dly[1] <= mode_dly[0];
    mode_dly[2] <= mode_dly[1];

    is_32_mode_dly[0] <= iIs_32_mode;
    is_32_mode_dly[1] <= is_32_mode_dly[0];
    is_32_mode_dly[2] <= is_32_mode_dly[1];

    mode_rep[0] <= mode_dly[2];
    mode_rep[1] <= mode_dly[2];
    mode_rep[2] <= mode_dly[2];
    mode_rep[3] <= mode_dly[2];

end

//

always @(posedge clk) begin : dly
	integer i;
	col_count[0] <= iCol_count;
	kernel_col_count[0] <= iKernel_col_count;
	kernel_row_count[0] <= iKernel_row_count;

	for(i=1;i<LATENCY;i=i+1) begin
	   col_count[i] <= col_count[i-1];
	   kernel_col_count[i] <= kernel_col_count[i-1];
	   kernel_row_count[i] <= kernel_row_count[i-1];

	end
end

always @(posedge clk)
	if(rst)
		mode_count <= 1'b0;
	else if(iRead_data_valid) begin
		if(mode_count_meet_border)
			mode_count <= 1'b0;
		else
			mode_count <= mode_count + 1;
	end

assign	mode_count_meet_border = (mode_count == mode_rep[0]);

always @(posedge clk)
	if(rst)
		data_sel <= 1'b0;
	else if(is_32_mode_dly[2]==0||iRead_data_valid==0)
	    data_sel <= 1'b0;
	else if(iRead_data_valid & mode_count_meet_border) begin
		data_sel <= ~data_sel;
	end

//store
always @(posedge clk)
	if(rst)
		rd_data_store <= 0;
	else if(iRead_data_valid) begin
		case(mode_rep[1])
				1'b0: //32
					if(data_sel)
						rd_data_store[511:256] <= iRead_data;
					else begin
						rd_data_store[255:0] <= iRead_data;
					end
				1'b1: //64
					case(mode_count)
						2'b0:
							if(data_sel)
								rd_data_store[511:256] <= iRead_data;
							else begin
								rd_data_store[255:0] <= iRead_data;
							end
						2'b1:
							if(data_sel)
								rd_data_store[512+511:512+256] <= iRead_data;
							else begin
								rd_data_store[512+255:512+0] <= iRead_data;
							end
					endcase
			endcase
	end

//
wire    store_condition;

assign store_condition = ((kernel_col_count[LATENCY-1]==3'd1 && col_count[LATENCY-1]!=0) || (kernel_col_count[LATENCY-1]==3'd2 && col_count[LATENCY-1]==0));

always @(posedge clk)
	if(rst) begin
		data_store_1 <= 1024'd0;
		data_store_2 <= 1024'd0;
		data_store_3 <= 1024'd0;
	end
	else if(iRead_data_valid) begin
		//if((kernel_col_count[LATENCY-1]==3'd1 && col_count[LATENCY-1]!=0) || (kernel_col_count[LATENCY-1]==3'd2 && col_count[LATENCY-1]==0)) begin
		if (store_condition) begin
			case(mode_rep[2])
				1'b0: //32
					case(kernel_row_count[LATENCY-1])
						2'b00:
							data_store_1[255:0] <= iRead_data;
						2'b01:
							data_store_2[255:0] <= iRead_data;
						2'b10:
							data_store_3[255:0] <= iRead_data;
					endcase
				1'b1: //64
					case(mode_count)
						2'b0:
							case(kernel_row_count[LATENCY-1])
								2'b00:
									data_store_1[255:0] <= iRead_data;
								2'b01:
									data_store_2[255:0] <= iRead_data;
								2'b10:
									data_store_3[255:0] <= iRead_data;
							endcase
						2'b1:
							case(kernel_row_count[LATENCY-1])
								2'b00:
									data_store_1[256+255:256+0] <= iRead_data;
								2'b01:
									data_store_2[256+255:256+0] <= iRead_data;
								2'b10:
									data_store_3[256+255:256+0] <= iRead_data;
							endcase
					endcase
			endcase
		end
	end

always @(posedge clk) begin
    col_count_dly[0] <= col_count[LATENCY-1];
    col_count_dly[1] <= col_count_dly[0];

    kernel_col_count_dly[0] <= kernel_col_count[LATENCY-1];
    kernel_col_count_dly[1] <= kernel_col_count_dly[0];

    kernel_row_count_dly <= kernel_row_count[LATENCY-1];

    read_data_valid_dly[0] <= iRead_data_valid;
    read_data_valid_dly[1] <= read_data_valid_dly[0];

    mode_count_dly <= mode_count;

    data_sel_dly <= data_sel;

end

//Write out
reg [511:0]    	output_data;

//data
always @(posedge clk)
		case(mode_rep[3])
			1'b0: //32
				if((kernel_col_count_dly[0]!=0 && col_count_dly[0]!=3'd0) || (col_count_dly[0]==3'd0)) begin
					if(!data_sel_dly) begin
						output_data[255:0] <= rd_data_store[511:256];
						output_data[511:256] <= rd_data_store[255:0];
					end
					else begin
						output_data[255:0] <= rd_data_store[255:0];
						output_data[511:256] <= rd_data_store[511:256];
					end

				end
				else begin
					if(data_sel_dly) begin
						output_data[511:256] <= rd_data_store[511:256];
						case(kernel_row_count_dly) 
								2'b00:
									output_data[255:0] <= data_store_1[255:0];
								2'b01:
									output_data[255:0] <= data_store_2[255:0];
								2'b10:
									output_data[255:0] <= data_store_3[255:0];
						endcase
					end
					else begin
						output_data[511:256] <= rd_data_store[255:0];
						case(kernel_row_count_dly) 
								2'b00:
									output_data[255:0] <= data_store_1[255:0];
								2'b01:
									output_data[255:0] <= data_store_2[255:0];
								2'b10:
									output_data[255:0] <= data_store_3[255:0];
						endcase
					end
				end
			1'b1: //64
					case(mode_count_dly) //yanshi
						2'b0:
							if((kernel_col_count_dly[0]!=0 && col_count_dly[0]!=3'd0) || (col_count_dly[0]==3'd0)) begin
								if(data_sel_dly) begin
									output_data[255:0] <= rd_data_store[255:0];
									output_data[511:256] <= rd_data_store[511:256];
								end
								else begin
									output_data[255:0] <= rd_data_store[511:256];
									output_data[511:256] <= rd_data_store[255:0];
								end

							end
							else begin
								if(data_sel_dly) begin
									output_data[511:256] <= rd_data_store[511:256];
									case(kernel_row_count_dly) //yanshi
											2'b00:
												output_data[255:0] <= data_store_1[255:0];
											2'b01:
												output_data[255:0] <= data_store_2[255:0];
											2'b10:
												output_data[255:0] <= data_store_3[255:0];
									endcase
								end
								else begin
									output_data[511:256] <= rd_data_store[255:0];
									case(kernel_row_count_dly) 
											2'b00:
												output_data[255:0] <= data_store_1[255:0];
											2'b01:
												output_data[255:0] <= data_store_2[255:0];
											2'b10:
												output_data[255:0] <= data_store_3[255:0];
									endcase
								end
							end
						2'b1:
							if((kernel_col_count_dly[0]!=0 && col_count_dly[0]!=3'd0) || (col_count_dly[0]==3'd0)) begin
								if(data_sel_dly) begin
									output_data[255:0] <= rd_data_store[512+255:512+0];
									output_data[511:256] <= rd_data_store[512+511:512+256];
								end
								else begin
									output_data[255:0] <= rd_data_store[512+511:512+256];
									output_data[511:256] <= rd_data_store[512+255:512+0];
								end

							end
							else begin
								if(data_sel_dly) begin
									output_data[511:256] <= rd_data_store[512+511:512+256];
									case(kernel_row_count_dly) //yanshi
											2'b00:
												output_data[255:0] <= data_store_1[256+255:256+0];
											2'b01:
												output_data[255:0] <= data_store_2[256+255:256+0];
											2'b10:
												output_data[255:0] <= data_store_3[256+255:256+0];
									endcase
								end
								else begin
									output_data[511:256] <= rd_data_store[512+255:512+0];
									case(kernel_row_count_dly) 
											2'b00:
												output_data[255:0] <= data_store_1[256+255:256+0];
											2'b01:
												output_data[255:0] <= data_store_2[256+255:256+0];
											2'b10:
												output_data[255:0] <= data_store_3[256+255:256+0];
									endcase
								end
							end
					endcase
			endcase

reg [511:0] result_dly[1:0];
reg         result_valid_dly [1:0];
always @(posedge clk) begin
    result_dly[0] <= output_data;
    result_dly[1] <= result_dly[0];
    result_valid_dly[0] <= (col_count_dly[1]==3'd0 && kernel_col_count_dly[1]==3'd0) ? 0:read_data_valid_dly[1];
    result_valid_dly[1] <= result_valid_dly[0];
end 
assign oResult = result_dly[1];
assign oResult_valid = result_valid_dly[1];


endmodule

//`include "fucore.h"
module	ddr_driver	#(parameter ADDR_OFFSET_H = 32'h0, parameter ADDR_OFFSET_L = 32'h0)(
		//
			input			mm_clk,
			input			mm_aresetn,
		// 
			input			ddr_write_enable,
			input	[32:0]	ddr_write_addr,
			input	[7:0]	ddr_write_cnt,
			output			write_finish,
			input           ddr_write_stop,
			output			ddr_write_rd,
			input	[511:0]	ddr_write_data,
			input           ddr_write_data_valid,
		//
			input			ddr_read_enable,
			input	[32:0]	ddr_read_addr,
			input	[7:0]	ddr_read_cnt,
			input   [3:0]   ddr_read_id,
			output          rd_instr_resp,
			output			read_finish,
			input           ddr_read_stop,
			output			ddr_read_valid,
			output	[511:0]	ddr_read_data,
			output  [3:0]   ddr_read_id_out,
		//
			input			init_calib_complete,
			output	[3:0]	m_axi_awid,
			output	[36:0]	m_axi_awaddr,
			output	[7:0]	m_axi_awlen,
			output			m_axi_awvalid,
			input			m_axi_awready,
			output	[511:0]	m_axi_wdata,
			output	[63:0]	m_axi_wstrb,
			output			m_axi_wlast,
			output			m_axi_wvalid,
			input			m_axi_wready,
			input	[3:0]	m_axi_bid,
			input	[1:0]	m_axi_bresp,
			input			m_axi_bvalid,
			output			m_axi_bready,

			output	[3:0]	m_axi_arid,
			output	[36:0]	m_axi_araddr,
			output	[7:0]	m_axi_arlen,
			output			m_axi_arvalid,
			input			m_axi_arready,
			input	[3:0]	m_axi_rid,
			input	[511:0]	m_axi_rdata,
			input	[1:0]	m_axi_rresp,
			input			m_axi_rlast,
			input			m_axi_rvalid,
			output			m_axi_rready
		);
parameter	IDLE	= 1'b0,
			WRITE	= 1'b1,
			READ	= 1'b1;

// axi signal write 

reg				mst_exec_wstate;
reg				mst_exec_wstate_dly;

reg 			write_done;
wire			start_single_burst;
reg             start_single_burst_dly;

reg				axi_awvalid;
reg	[36:0]		axi_awaddr;
reg	[7:0]		axi_awlen;
reg [7:0]       axi_awlen_tmp;

wire			axi_wvalid;
wire			axi_wlast;
reg				axi_bready;
reg [3:0]       axi_awid;

reg	[7:0]		write_count;
wire            write_count_meet_border;
reg [7:0]       wr_last_count;

wire            wr_data_fifo_full;
wire            wr_data_fifo_empty;
wire			local_buf_has_data;
reg				burst_write_active;

//
reg     [255:0] ddr_read_data_l256bit;
reg     [255:0] ddr_read_data_h256bit,ddr_read_data_h256bit_dly;
reg             ddr_read_data_store_valid;
reg     [7:0]   ddr_read_data_cnt,ddr_read_data_cnt_dly;
reg             ddr_read_valid_to_fifo;
reg     [511:0] ddr_read_data_to_fifo;


wire            ddr_rdaddr_fifo_full;
wire            ddr_rdaddr_fifo_empty;
wire            is_the_factor_of_8;
wire    [7:0]   len_for_factor_of_8;
reg     [3:0]   rd_id_dly [1:0];

reg             is_the_factor_of_8_dly [1:0];  
reg             write_addr_isnot_aligment;
reg     [3:0]   write_last_word_dly;
reg     [511:0] ddr_write_data_dly;

//====== write phase ===========//
// axi write state machine

always @(posedge mm_clk) begin
	if(~mm_aresetn)
		mst_exec_wstate	<= IDLE;
	else
		case(mst_exec_wstate)
			IDLE:
				if(ddr_write_enable & init_calib_complete)
					mst_exec_wstate <= WRITE;
				else
					mst_exec_wstate <= IDLE;
			WRITE:
				if(write_done)
					mst_exec_wstate <= IDLE;
				else
					mst_exec_wstate <= WRITE;
			default:
				mst_exec_wstate <= IDLE;
		endcase
	mst_exec_wstate_dly <= mst_exec_wstate; // generate a pulse signal to trigger a write burst
end

assign	start_single_burst = (mst_exec_wstate_dly != WRITE) & (mst_exec_wstate == WRITE);

always @(posedge mm_clk) begin
    start_single_burst_dly <= start_single_burst;
end
// generate awvalid, awaddr and awlen signals keep until awready assert

always @(posedge mm_clk) begin
	if(~mm_aresetn)
		axi_awvalid <= 1'b0;
	else if(start_single_burst)
		axi_awvalid <= 1'b1;
	else if(m_axi_awready)
		axi_awvalid <= 1'b0;
end

always @(posedge mm_clk)
	if(start_single_burst) begin
		axi_awaddr <= ddr_write_addr + {ADDR_OFFSET_H, ADDR_OFFSET_L};
		axi_awlen <= ddr_write_cnt + ddr_write_addr[5] - 1;
		axi_awlen_tmp <= ddr_write_cnt - 1;
		write_addr_isnot_aligment <= ddr_write_addr[5];
	end

always @(posedge mm_clk)
    if(~mm_aresetn)
        axi_awid <= 4'd0;
    else if(axi_awvalid & m_axi_awready)
        axi_awid <= axi_awid + 1;
// generate the signal to indicate the write data phase
always @(posedge mm_clk) begin
	if(~mm_aresetn)
		burst_write_active <= 1'b0;
	else if(start_single_burst_dly)
		burst_write_active <= 1'b1;
	else if(burst_write_active & (~ddr_write_stop) & (~wr_data_fifo_full) & write_count_meet_border) // write finish
		burst_write_active <= 1'b0;
end
// generate wvalid signal and keep until write finish

/*
always @(posedge mm_clk)
	axi_wvalid <= burst_write_active;
*/

//assign  axi_wvalid = burst_write_active;

always @(posedge mm_clk)
	if(~mm_aresetn)
		write_count <= 8'd0;
	else if(burst_write_active & (~ddr_write_stop) & (~wr_data_fifo_full)) begin
		if(write_count_meet_border)
			write_count <= 8'd0;
		else
			write_count <= write_count + 1;
	end

assign	write_count_meet_border = (write_count == axi_awlen_tmp);

always @(posedge mm_clk) begin
    write_last_word_dly[0] <= burst_write_active & (~ddr_write_stop) & (~wr_data_fifo_full) & write_count_meet_border & write_addr_isnot_aligment;
    write_last_word_dly[1] <= write_last_word_dly[0];
    write_last_word_dly[2] <= write_last_word_dly[1];
    write_last_word_dly[3] <= write_last_word_dly[2];
end
// axi write response channel
always @(posedge mm_clk)
    axi_bready <= 1'b1;
    /*
	if(~mm_aresetn)
		axi_bready <= 1'b0;
	else
		case(axi_bready)
			1'b0:	axi_bready <= m_axi_bvalid;
			1'b1:	axi_bready <= 1'b0;
		endcase
     */

// write finish signal

always @(posedge mm_clk) 
	if(~mm_aresetn)
		write_done <= 1'b0;
	else 
		case(write_done)
			1'b0 : write_done <= m_axi_bvalid & axi_bready;
			1'b1 : write_done <= 1'b0;
		endcase

assign	write_finish = write_done;
assign	ddr_write_rd = burst_write_active & (~ddr_write_stop) & (~wr_data_fifo_full);


//======= end write phase ==============//
reg				mst_exec_rstate;
reg				mst_exec_rstate_dly;

reg				axi_arvalid;
wire			start_single_burst_read;


reg	[36:0]		axi_araddr;
reg	[7:0]		axi_arlen;
wire			axi_rready;
reg             read_done;
reg             read_done_dly [1:0];
reg [3:0]       axi_rid;
reg     rd_instr_resp_dly1, rd_instr_resp_dly2, rd_instr_resp_dly3;

wire            fifo_empty;
wire            fifo_full;
reg             data_fifo_data_valid_dly[1:0];

always @(posedge mm_clk) begin
	if(~mm_aresetn)
		mst_exec_rstate <= IDLE;
	else
		case(mst_exec_rstate)
			IDLE:
				if(ddr_read_enable & (~ddr_rdaddr_fifo_full))
					mst_exec_rstate <= READ;
				else
					mst_exec_rstate <= IDLE;
			READ:

				if(rd_instr_resp_dly3)
					mst_exec_rstate <= IDLE;
				else
					mst_exec_rstate <= READ;

			default:
				mst_exec_rstate <= IDLE;
		endcase
	mst_exec_rstate_dly <= mst_exec_rstate;
end

assign	start_single_burst_read = (mst_exec_rstate_dly != READ) & (mst_exec_rstate == READ);


always @(posedge mm_clk) begin
	if(~mm_aresetn)
		axi_arvalid <= 1'b0;
	else if(start_single_burst_read)
		axi_arvalid <= 1'b1;
	else if(m_axi_arready)
		axi_arvalid <= 1'b0;
end

always @(posedge mm_clk) begin
    axi_rid <= ddr_read_id;
end

wire    [7:0]   axi_arlen_tmp;

always @(posedge mm_clk)
	if(start_single_burst_read) begin
		axi_araddr <= ddr_read_addr + {ADDR_OFFSET_H, ADDR_OFFSET_L};
		axi_arlen <= ddr_read_cnt + ddr_read_addr[5] - 1; // if the ddr_read_addr is not the factor of 8, add 1
	end

assign  axi_arlen_tmp =  ddr_read_cnt + ddr_read_addr[5] - 1;

 /*       
always @(posedge mm_clk)
	if(~mm_aresetn)
		axi_rready <= 1'b0;
	else if(m_axi_rvalid) begin
		if(m_axi_rlast & axi_rready)
			axi_rready <= 1'b0;
		else
			axi_rready <= 1'b1;
	end
*/

assign  axi_rready = ~fifo_full;
always @(posedge mm_clk) begin
	if(~mm_aresetn)
		read_done <= 1'b0;
	else 
		case(read_done)
			1'b0 : read_done <= m_axi_rvalid & axi_rready & m_axi_rlast;
			1'b1 : read_done <= 1'b0;
		endcase
    read_done_dly[0] <= read_done;
    read_done_dly[1] <= read_done_dly[0];
end

assign	read_finish = read_done_dly[0];



always @(posedge mm_clk) begin
    rd_instr_resp_dly1 <= axi_arvalid & m_axi_arready;
    rd_instr_resp_dly2 <= rd_instr_resp_dly1;
    rd_instr_resp_dly3 <= rd_instr_resp_dly2;
end 

assign  rd_instr_resp = rd_instr_resp_dly2;


//
 /*
reg     [255:0] ddr_read_data_l256bit;
reg             ddr_read_data_store_valid;

always @(posedge mm_clk) begin
    ddr_read_data_store_valid <= m_axi_rvalid && axi_rready;

    if (m_axi_rvalid && axi_rready) begin    
        ddr_read_data_l256bit <= m_axi_rdata;
    end
end

always @(posedge mm_clk) begin
	ddr_read_valid <= ddr_read_data_store_valid;
	ddr_read_data <= ddr_read_data_l256bit;
end
 */
assign	m_axi_awid = 0,//axi_awid,
		m_axi_awaddr = axi_awaddr,
		m_axi_awlen = axi_awlen,
		m_axi_awvalid = axi_awvalid,
		m_axi_bready = axi_bready,
		//m_axi_wdata = ,
		m_axi_wstrb = write_addr_isnot_aligment ? (wr_last_count == 0 ? 64'hffffffff00000000 : 
		                                           wr_last_count == axi_awlen ? 64'h00000000ffffffff :{64{1'b1}}) : {64{1'b1}},
		m_axi_wlast = wr_last_count == axi_awlen,
		m_axi_wvalid = ~wr_data_fifo_empty,

		m_axi_arvalid = axi_arvalid,
		m_axi_rready = axi_rready,
		m_axi_araddr = axi_araddr,
		m_axi_arlen = axi_arlen,
		m_axi_arid = axi_rid;

always @(posedge mm_clk) begin
    data_fifo_data_valid_dly[0] <= (~ddr_read_stop) & (~fifo_empty);
    data_fifo_data_valid_dly[1] <= data_fifo_data_valid_dly[0];
end

assign  ddr_read_valid = data_fifo_data_valid_dly[1];


always @(posedge mm_clk) begin
    if(~mm_aresetn)
        wr_last_count <= 0;
    else if(m_axi_wready & (~wr_data_fifo_empty)) begin
        if(m_axi_wlast)
            wr_last_count <= 0;
        else
            wr_last_count <= wr_last_count + 1;
    end
end

//==

always @(posedge mm_clk) begin
    ddr_read_data_store_valid <= m_axi_rvalid && axi_rready;
    if(~mm_aresetn)
        ddr_read_data_cnt <= 0;
    else if(m_axi_rvalid && axi_rready) begin
        if(ddr_read_data_cnt == len_for_factor_of_8)
            ddr_read_data_cnt <= 0;
        else   
            ddr_read_data_cnt <= ddr_read_data_cnt + 1;
    end

    ddr_read_data_cnt_dly<= ddr_read_data_cnt;

    if (m_axi_rvalid && axi_rready) begin    
        {ddr_read_data_h256bit,ddr_read_data_l256bit} <= m_axi_rdata;
        ddr_read_data_h256bit_dly <= ddr_read_data_h256bit;
    end
end

always @(posedge mm_clk) begin
    rd_id_dly[0] <= m_axi_rid;
    rd_id_dly[1] <= rd_id_dly[0];
    is_the_factor_of_8_dly[0] <= is_the_factor_of_8;
    is_the_factor_of_8_dly[1] <= is_the_factor_of_8_dly[0];
	ddr_read_valid_to_fifo <= is_the_factor_of_8_dly[0] ? ddr_read_data_store_valid & (ddr_read_data_cnt_dly != 0) : ddr_read_data_store_valid;
	ddr_read_data_to_fifo <= is_the_factor_of_8_dly[0] ? {ddr_read_data_l256bit,ddr_read_data_h256bit_dly} : {ddr_read_data_h256bit,ddr_read_data_l256bit};
end

//




ddr_rdaddr addr_fifo_inst (
    .clk    (mm_clk),
    .srst   (~mm_aresetn),
    .din    ({axi_arlen_tmp,ddr_read_addr[5]}),
    .wr_en  (start_single_burst_read),
    .rd_en  (m_axi_rvalid && axi_rready && m_axi_rlast),
    .dout   ({len_for_factor_of_8,is_the_factor_of_8}),
    .full   (),
    .empty  (ddr_rdaddr_fifo_empty),
    .prog_full  (ddr_rdaddr_fifo_full),
    .wr_rst_busy (),
    .rd_rst_busy ()
);

ddr_driver_rd_data_fifo  fifo_rd_inst (
    .clk    (mm_clk),
    .srst   (~mm_aresetn),
    .din    ({rd_id_dly[1], ddr_read_data_to_fifo}),
    .wr_en  (ddr_read_valid_to_fifo),
    .rd_en  ((~ddr_read_stop) & (~fifo_empty)),
    .dout   ({ddr_read_id_out, ddr_read_data}),
    .full   (),
    .empty  (fifo_empty),
    .prog_full  (fifo_full),
    .wr_rst_busy(),
    .rd_rst_busy()
  );

always @(posedge mm_clk)
    if(ddr_write_data_valid)
        ddr_write_data_dly <= ddr_write_data;


ddr_driver_wr_data_fifo fifo_wr_inst(
    .clk    (mm_clk),
    .srst   (~mm_aresetn),
    .din    (write_addr_isnot_aligment? {ddr_write_data[0+:256], ddr_write_data_dly[256+:256]} : ddr_write_data),
    .wr_en  (ddr_write_data_valid || write_last_word_dly[3]),
    .rd_en  (m_axi_wready & (~wr_data_fifo_empty)),
    .dout   (m_axi_wdata),
    .full   (),
    .empty  (wr_data_fifo_empty),
    .prog_full      (wr_data_fifo_full),
    .wr_rst_busy    (),
    .rd_rst_busy    ()
  );


	/*	
// for debug
reg     [31:0]      rd_count;
reg     [31:0]      wr_count;
always @(posedge mm_clk)
    if(~mm_aresetn) 
        rd_count <= 'b0;
    else if(m_axi_rvalid && m_axi_rready) 
        rd_count <= rd_count + 1;
always @(posedge mm_clk)
