module dequantization #(parameter CHANNEL = 32, parameter DATAWIDTH = 20)(
            input                                   clk,
            input                                   i_dequant_enable, // 0: none; 1: dequantization
            input   [7:0]                           i_scale_m,
            input   [4:0]                           i_scale_n,  
            input   [CHANNEL*DATAWIDTH-1:0]         i_data,
            output  reg [CHANNEL*DATAWIDTH-1:0]     o_data 
    ); // lantency : 5 clock cycles

reg     [3:0]   left_shift;
reg     [3:0]   right_shift;
wire    [DATAWIDTH+8-1:0]   scale_mult_result [CHANNEL-1:0];
reg     [27:0]  mult_dscale_rightshift [CHANNEL-1:0];
reg     [43:0]  mult_dscale_leftshift  [CHANNEL-1:0];
reg     [CHANNEL*DATAWIDTH-1:0] data_dly [4:0];
wire    [CHANNEL-1:0]   pos_carry_in, neg_carry_in;

always @(posedge clk) begin 
    left_shift <= i_scale_n[4] ? (~i_scale_n + 1'b1) : 4'b0;
    right_shift <= i_scale_n[4] ? 4'b0 : i_scale_n[3:0];

    //
    data_dly[0] <= i_data;
    data_dly[1] <= data_dly[0];
    data_dly[2] <= data_dly[1];
    data_dly[3] <= data_dly[2];
    data_dly[4] <= data_dly[3];
end


genvar i;

generate 
    for (i=0; i < CHANNEL; i=i+1) begin 
        scale_mult scale_mult_inst (
            .clk    (clk),
            .A      (i_data[i*DATAWIDTH+:DATAWIDTH]),
            .B      (i_scale_m),
            .P      (scale_mult_result[i])
        );

        assign pos_carry_in[i] = |((36'h1 << right_shift) & {scale_mult_result[i], 1'b0});
        assign neg_carry_in[i] = (|((36'h1 << right_shift) & {scale_mult_result[i], 1'b0})) & (|(((32'h1 << right_shift)-1) & {scale_mult_result[i], 1'b0}));

        always @(posedge clk) begin 
            mult_dscale_rightshift[i] <= scale_mult_result[i][27] ?  ({{16{scale_mult_result[i][27]}}, scale_mult_result[i]} >> right_shift) + neg_carry_in[i] : 
                                                                  ({{16{scale_mult_result[i][27]}}, scale_mult_result[i]} >> right_shift) + pos_carry_in[i] ; // round 
            mult_dscale_leftshift[i] <=  {{16{mult_dscale_rightshift[i][27]}}, mult_dscale_rightshift[i]} << left_shift;
        end

        always @(posedge clk) 
            o_data[i*DATAWIDTH+:DATAWIDTH] <= i_dequant_enable == 0  ? data_dly[4][i*DATAWIDTH+:DATAWIDTH] :
                                                (mult_dscale_leftshift[i][43] ? 
                                                    ((&mult_dscale_leftshift[i][43:DATAWIDTH-1]) ? mult_dscale_leftshift[i][0+:DATAWIDTH] :
                                                                                                 20'h80000) :
                                                    ((|mult_dscale_leftshift[i][43:DATAWIDTH-1]) ? 20'h7ffff  :
                                                                                                 mult_dscale_leftshift[i][0+:DATAWIDTH]));

    end
endgenerate






endmodule

