`include "fucore.vh"

module	fucore_unit_array #(parameter N = 8) (
			// global singals
				input				clk_sys,
				input				clk_dsp,
				input				rst,

			// input data path
				output	[N-1:0]		oInput_buffer_rd_enable,
				output	[17*N-1:0]	oInput_buffer_rd_addr,
				output  [N-1:0]     oInput_buffer_sel,
				output	[N-1:0]		oInput_buffer_pad_flag,
				output	[N-1:0]		oInput_buffer_specific_clear,

				output	[N*2-1:0]	oRd_inputbuffer_stride_mode,
				output	[N-1:0]		oRd_specific_enable,
				output	[N*2-1:0]	oRd_specific_mode,

				input	[512*N-1:0]	iData,
				input	[N-1:0]		iData_valid,

				output	[N-1:0]		oInput_buffer_wr_config_valid,
				output	[16*N-1:0]	oInput_buffer_wr_data_block_len,
				output	[17*N-1:0]	oInput_buffer_wr_data_block_startaddr,
				output	[N-1:0]		oInput_buffer_is_data_from_outchip,
				output  [2*N-1:0]   oInput_buffer_wr_data_block_stride,
				output  [16*N-1:0]  oInput_buffer_wr_data_block_sublen,

				input	[2*N-1:0]	iInput_buffer_status,
				input	[N-1:0]		iInput_buffer_wr_config_sel,
				output	[2*N-1:0]	oInput_buffer_status_clear,
			// input parameter path
				input	[511:0]		iParam,
				input				iParam_valid,
				output	 		    oParam_stop,
			// input bias path
				input	[511:0]		iBias,
				input				iBias_valid,
				output		        oBias_stop,
			// output data path
				output	reg [256*N-1:0]	oResult,
				output	reg [N*8-1:0]	oResult_valid,
				input				    iStop_from_output_io,

			// instruction interface
				input	[31:0]		iInstruction,
				input	[1:0]		iInstruction_id,
				input				iInstruction_valid,
	       // control & status signals
	            output  [3:0]		oStage_is_full,
				output	[3:0]		oConfig_ack,
				input				iInstruction_finish,
				output              oLast_data_block_proposal,
	            output  [1:0]		oFinish_block_indicator,
	            input   [1:0]		iFinish_block_indicator_clear,   
 		    //add
	            output      [N-1:0]     oIs_32_mode, 
			    output 		[10*N-1:0]	oCol_count,
			    output 		[4*N-1:0] 	oKernel_col_count,
			    output 		[4*N-1:0] 	oKernel_row_count,
			    output      [N-1:0]     oMode_32   

        ) ;

parameter   URAM_LATENCY = 21;
wire		clk;
wire		clk_if;

assign	clk = clk_sys;
assign	clk_if = clk_sys;
