genvar core;

reg     [N-1:0] previous_block_channel_is_half_utilization;
reg     [1:0]   channel_mask_sel_dly;
reg     [N-1:0] is_32_64_mode;

generate
    always @(posedge clk) begin 
        channel_mask_sel_dly <= channel_mask_sel;

    end 

    for(core=0;core<N;core=core+1) begin
        always @(posedge clk) begin 
            is_32_64_mode[core] <= (~oIs_32_mode[N-1]) & (rd_data_organization[2*32*core+:2] == 2'd1);

            if (rst)
                previous_block_channel_is_half_utilization[core] <= 1'b0;
            else if (finish_one_block_ack) // 32-64 mode
                previous_block_channel_is_half_utilization[core] <= is_32_64_mode[core] & (channel_mask_sel_dly == 2'd1); // 32-64 mode, po utilization is only 1/2 
        end

        pe_array_if_onecore pe_array_if_unit(
            .clk(clk),
            .rst(rst),
            .iData(iData[512*core+:512]),
            .iData_valid(iData_valid[core]),
            .iResult_reuse_sel_count(result_reuse_sel_count),
            .iData_buffer_organization(rd_mode_from_ib),

            .oData(in_data[`DATAWIDTH*64*core+:`DATAWIDTH*64]),
            .oData_valid(in_data_valid[core]),

            .iBias_data(gen_bias_data_sel),
            .oBias_data(in_bias[128*(2*`DATAWIDTH+4)*core+:128*(2*`DATAWIDTH+4)]),
            .iS_add_bias_valid(add_bias_valid),

            //.iResult_bit_sel(result_bit_sel),
            .iResult_bit_sel(4'b0),
            //.iBranch_bit_sel(branch_bit_sel),
            .iBranch_bit_sel(4'b0),
            .iResult_rd_organization(rd_data_organization[2*32*core+:2*32]),
            .iPrevious_blk_channel_is_half_utilization(previous_block_channel_is_half_utilization[core]),
            //
            .iSpecific_enable(oRd_specific_enable[N-1]),
            .iSpecific_sel_mask(specific_sel_mask),
            .iNum_in_each_row(num_each_row),
			.iS_conv_bypass(is_conv_bypass[core]),
            //
            .iIntermediate_data(rd_intermediate_data[`OUT_BUFFER_DATAWIDTH*core+:`OUT_BUFFER_DATAWIDTH]),
            .iIntermediate_32mode_width_step_eq_2(oIs_32_mode & (width_step == 2)),
