module	gen_instr_request (
			// global signals
			input				clk,
			input				rst,
			//
			input				iConfig_ready,
			input				iInstruction_ready,
            output              oConfig_clear,

			input		[31:0]	iAddr_offset,
			input		[31:0]	iLength,

			output	reg [31:0]	oDDR_instr_base_addr,
			output	reg [9:0]	oDDR_instr_burst_len,
			output	reg			oDDR_instr_wren,
			input				iDDR_instr_stop,

			input		[63:0]	iDDR_data,
			input				iDDR_data_stop,
			output				oDDR_data_rden,

			input				iInstr_buffer_rden,
			input		[9:0]	iInstr_buffer_rdaddr,
			output		[35:0]	oInstr_data,

			output		[9:0]	oRequest_len_0,
			output		[9:0]	oRequest_len_1,

			output		[1:0]	oBuffer_status,
			input		[1:0]	iBuffer_status_clear
		);
parameter   OUT_AXI_WIDTH = 512;
parameter   SHIFT_WIDTH = (OUT_AXI_WIDTH == 512) ? 3 : 
                          (OUT_AXI_WIDTH == 256) ? 2 : 0;

reg	[31:0]	clipb_access_size;
reg	[1:0]	clipb_require_status;
reg	[1:0]	clipb_buffer_status;

wire		clipb_require_valid;
reg			clipb_require_flag;
wire [9:0]	clipb_require_size;
wire [9:0]  clipb_require_size_tmp;

reg	[9:0]	clipb_access_len [1:0];
reg [9:0]   clipb_access_len_org [1:0];

wire		clipb_read_data_valid;
reg			clipb_read_data_valid_dly;
reg			clipb_write_ppbuf_flag;
reg	[9:0]	clipb_write_ppbuf_count;
wire		clipb_write_ppbuf_count_meet_border;
wire [9:0]	clipb_write_ppbuf_addr;
//

assign	oBuffer_status = clipb_buffer_status;

assign	clipb_require_valid = iConfig_ready & iInstruction_ready & (~(&clipb_require_status)) & (~iDDR_instr_stop);
assign	clipb_require_size = (iLength - clipb_access_size) > 512 ? 10'd512 : (iLength - clipb_access_size);

assign  clipb_require_size_tmp = ((clipb_require_size-1) >> SHIFT_WIDTH) + 1;
assign  oConfig_clear = ((iLength - clipb_access_size) <= 512) & clipb_require_valid;


always @(posedge clk)
	if(rst)
		clipb_access_size <= 32'd0;
	else if(clipb_require_valid) begin
		if((clipb_access_size + 512) >= iLength)
			clipb_access_size <= 32'd0;
		else
			clipb_access_size <= clipb_access_size + 10'd512;
	end

always @(posedge clk)
	if(rst)
		clipb_require_flag <= 1'b0;
	else if(clipb_require_valid)
		clipb_require_flag <= ~clipb_require_flag;

always @(posedge clk) 
	if(rst)
		clipb_require_status <= 2'd0;
	else begin
		if(iBuffer_status_clear[0])
			clipb_require_status[0] <= 1'b0;
		else if((~clipb_require_flag) & clipb_require_valid)
			clipb_require_status[0] <= 1'b1;

		if(iBuffer_status_clear[1])
			clipb_require_status[1] <= 1'b0;
		else if(clipb_require_flag & clipb_require_valid)
			clipb_require_status[1] <= 1'b1;
	end

always @(posedge clk) begin
	if((~clipb_require_flag) & clipb_require_valid) begin
		clipb_access_len[0] <= clipb_require_size_tmp << SHIFT_WIDTH;
		clipb_access_len_org[0] <= clipb_require_size;
    end
	if(clipb_require_flag & clipb_require_valid) begin
		clipb_access_len[1] <= clipb_require_size_tmp << SHIFT_WIDTH;
