`define DATAWIDTH 8
// 5 clock cycles
module activation_unit(
            input                           clk,
            input   [1:0]                   i_activate_type, // 0: none; 1: relu; 2: hardswish; 3: hardsigmoid
            input   [15:0]                  i_scale_value,
            input   [12:0]                  i_inverse_scale, // <m,n> format, n is signed, m => 8 bit
            input   [`DATAWIDTH-1:0]        i_data,
            output  reg [`DATAWIDTH-1:0]    o_data 
    ); 

/*                      0      ,    if x < -3
 *  hardsigmoid(x) =    1      ,    if x > 3
 *                      x/6+1/2,   otherwise
 *
 *                      0      ,    if x <= -3
 *  hardswish(x)   =    x      ,    if x >= 3 
 *                      x*x/6 + x/2, otherwise
 *
 *
 *                      0       ,   if x < 0
 *  relu(x)         =   
 *                      x       ,   otherwise 
 */


// 1/6 = 85/512
reg     [15:0]      low_border_value;
reg     [15:0]      high_border_value;

wire    [15:0]      scalex3;

reg                 is_low_boarder;
reg                 is_high_boarder;

reg     [5:0]       is_low_boarder_dly;
reg     [5:0]       is_high_boarder_dly;



assign  scalex3 = i_scale_value + (i_scale_value << 1);

always @(posedge clk) begin 
    low_border_value <= (~scalex3) + 1;
    high_border_value <= scalex3;
end


always @(posedge clk) begin
    is_low_boarder <=  i_data[7] ? {8'hff,i_data} <= low_border_value : 1'b0; // -3 
    is_high_boarder <= (~i_data[7]) ? {8'h0,i_data} >= high_border_value[7:0] : 1'b0; // 3  
    is_low_boarder_dly <= {is_low_boarder_dly[4:0], is_low_boarder};
    is_high_boarder_dly <= {is_high_boarder_dly[4:0], is_high_boarder};
end 

wire    [14:0]  mult_result;
wire    [7:0]   inv_scale_m;
reg     [7:0]   inv_scale_m_dly;
reg     [5:0]   inv_scale_n;
wire    [15:0]  mult_scale_value;
wire    [30:0]  mult_dscale;
reg     [7:0]   data_dly [6:0];
reg     [1:0]   activate_type_dly [6:0];
reg     [4:0]   left_shift, left_shift_dly[3:0];
reg     [4:0]   right_shift, right_shift_dly[3:0];
reg     [30:0]  mult_dscale_leftshift;
reg     [30:0]  mult_dscale_rightshift;

wire            pos_carry_in;
wire            neg_carry_in;
reg     [7:0]   swish_result;
reg     [7:0]   relu_result;

assign inv_scale_m = i_inverse_scale[5+:8];
always @(posedge clk) begin      
    inv_scale_n <= {i_inverse_scale[4], i_inverse_scale[4:0]};
end

always @(posedge clk) begin 
    data_dly[0] <= i_data;
    data_dly[1] <= data_dly[0];
    data_dly[2] <= data_dly[1];
    data_dly[3] <= data_dly[2];
    data_dly[4] <= data_dly[3];
    data_dly[5] <= data_dly[4];
    data_dly[6] <= data_dly[5];

    activate_type_dly[0] <= i_activate_type;
    activate_type_dly[1] <= activate_type_dly[0];
    activate_type_dly[2] <= activate_type_dly[1];
    activate_type_dly[3] <= activate_type_dly[2];
    activate_type_dly[4] <= activate_type_dly[3];
    activate_type_dly[5] <= activate_type_dly[4];
    activate_type_dly[6] <= activate_type_dly[5];

    left_shift <= inv_scale_n[5] ? (~inv_scale_n + 1'b1) : 4'd0;
    right_shift <= (inv_scale_n[5] == 0) ?  inv_scale_n[4:0] : 'b0; 

    left_shift_dly[0] <= left_shift;
    left_shift_dly[1] <= left_shift_dly[0];
    left_shift_dly[2] <= left_shift_dly[1];
    left_shift_dly[3] <= left_shift_dly[2];

    right_shift_dly[0] <= right_shift;
    right_shift_dly[1] <= right_shift_dly[0];
    right_shift_dly[2] <= right_shift_dly[1];
    right_shift_dly[3] <= right_shift_dly[2];  
end 

assign pos_carry_in = |((32'h1 << right_shift_dly[1]) & {mult_dscale, 1'b0});
assign neg_carry_in = (|((32'h1 << right_shift_dly[1]) & {mult_dscale, 1'b0})) & (|(((32'h1 << right_shift_dly[1])-1) & {mult_dscale, 1'b0}));

always @(posedge clk) begin 
    /*
    mult_dscale_rightshift <= mult_dscale[30] ?  ({{24{mult_dscale[30]}}, mult_dscale} >> right_shift_dly[1]) + neg_carry_in : 
                                                 ({{24{mult_dscale[30]}}, mult_dscale} >> right_shift_dly[1]) + pos_carry_in ; // round
    */
    mult_dscale_rightshift <=  (mult_dscale >> right_shift_dly[1]) + pos_carry_in; // always positive 
    mult_dscale_leftshift <= (mult_dscale_rightshift << left_shift_dly[2]) + {{15{data_dly[4][7]}}, data_dly[4], 8'b0};
    /*
    swish_result <= mult_dscale_leftshift[9] ? ((mult_dscale_leftshift[9:0] >> 2) + mult_dscale_leftshift[0] & mult_dscale_leftshift[1]):
                                               ((mult_dscale_leftshift[9:0] >> 2) + mult_dscale_leftshift[1]);
     */
    swish_result <= mult_dscale_leftshift[30] ? ((mult_dscale_leftshift >> 9) + ((|mult_dscale_leftshift[7:0]) & mult_dscale_leftshift[8])) :
                                               ((mult_dscale_leftshift >> 9) + mult_dscale_leftshift[8]);
    relu_result <= data_dly[5][7] ? 8'd0 : data_dly[5];
    case(activate_type_dly[6])
        2'd0:   o_data <= data_dly[6]; 
        2'd1:   o_data <= relu_result;
        2'd2:   if (is_low_boarder_dly[5])
                    o_data <= 8'd0;
                else if (is_high_boarder_dly[5])
                    o_data <= data_dly[6]; 
                else 
                    o_data <= swish_result;
        default:    o_data <= data_dly[6];
    endcase   
end                        
// two clock cycles
// 1/6 => 85/512
mult_coefficient  inst(
    .CLK    (clk),
    .A      (i_data),              // 8
    .P      (mult_result)          // 15          
);

mult_scale ms_inst (
    .CLK    (clk),
    .A      (i_data),
    .B      (inv_scale_m),
    .P      (mult_scale_value) // 16
);

mult_x mx_inst (
    .CLK    (clk),
    .A      (mult_result),
    .B      (mult_scale_value),
    .P      (mult_dscale)
);

endmodule

