always @(posedge clk) begin : gen_core_2
	integer core_2;
    begin
        gen_addr_1_p1 <= row_count*iHeight_step;
        gen_addr_1_p2 <= kernel_row_count - iPad_h_size;

		//gen_addr_1 <=  gen_addr_1_tmp*imap_width;

		gen_addr_2_p1 <= col_count*width_step;
		gen_addr_2_p2 <= iIs_32_mode ? (kernel_col_count - iPad_size + not_first_point) : (kernel_col_count - iPad_size);
		//gen_addr_2 <= gen_addr_2_tmp*im_num_dly;

        mem_sel_dly[0] <= iRd_mem_sel;
