		mem_sel_dly[2] <= mem_sel_dly[1];
		mem_sel_dly[3] <= mem_sel_dly[2];

		for(core_2=0;core_2<N;core_2=core_2+1) begin
		    //gen_addr_p1[core_2*17+:17] <= gen_addr_1*im_num_dly1;
		    gen_addr_p2[core_2*17+:17] <= {gen_addr_2[16],gen_addr_2} + im_num_count_dly[1] + data_block_start_addr_dly;
			gen_addr[core_2*17+:17] <= gen_addr_p1[core_2*17+:17] + gen_addr_p2[core_2*17+:17];

		end

		pad_mask_1 <= row_count*iHeight_step + kernel_row_count ;
		pad_mask_2 <= col_count*width_step + kernel_col_count + not_first_point;

		if(~((pad_mask_1 >= row_start) && (pad_mask_1 <= row_end) && (pad_mask_2 >= col_start) && (pad_mask_2 <= col_end)))
			pad_mask <= 1'b1;
