// 6 clock cycles mismatch between param and in_data, delay the param_read_addr for compensation
reg    [5:0]   param_read_addr_compensation_dly [5:0];
reg             param_read_enable_compensation_dly [5:0];

always @(posedge clk) begin : cc
    integer cc_i;   
    param_read_addr_compensation_dly[0] <= param_read_addr + param_buf_based_addr_dly[2];
    param_read_enable_compensation_dly[0] <= param_read_enable_dly[2];
    for(cc_i=1;cc_i<6;cc_i=cc_i+1) begin
        param_read_addr_compensation_dly[cc_i] <= param_read_addr_compensation_dly[cc_i-1];
        param_read_enable_compensation_dly[cc_i] <= param_read_enable_compensation_dly[cc_i-1];
    end
    oParam_read_addr <= param_read_addr_compensation_dly[5];
    oParam_read_enable <= param_read_enable_compensation_dly[5];
end

always @(posedge clk) begin
	param_read_enable_dly[0] <= work_flag ;
	param_read_enable_dly[1] <= param_read_enable_dly[0];
	param_read_enable_dly[2] <= param_read_enable_dly[1];
end


reg	rd_output_buffer_enable;

//

reg		is_add_bias_dly1,is_add_bias_dly2;
reg		is_read_intermediate_dly1,is_read_intermediate_dly2;
reg		is_read_intermediate_dly[9:0];
reg     add_bias_valid_dly [3:0];
reg     fc_layer_enable_dly [1:0];

always @(posedge clk) begin: dly_loop
	integer i;
	is_add_bias_dly1 <= iS_add_bias;
	is_add_bias_dly2 <= is_add_bias_dly1;
	is_read_intermediate_dly1 <= iS_read_intermediate;
	is_read_intermediate_dly2 <= is_read_intermediate_dly1;
	is_read_intermediate_dly[0] <= iS_read_intermediate & work_flag;
	add_bias_valid_dly[0] <= is_add_bias_dly2 & oPE_array_acc_clear;
	add_bias_valid_dly[1] <= add_bias_valid_dly[0];
	add_bias_valid_dly[2] <= add_bias_valid_dly[1];
	add_bias_valid_dly[3] <= add_bias_valid_dly[2];

	fc_layer_enable_dly[0] <= iFClayer_enable;
	fc_layer_enable_dly[1] <= fc_layer_enable_dly[0];
	for(i=1;i<10;i=i+1)
		is_read_intermediate_dly[i] <= is_read_intermediate_dly[i-1];
end

assign  oBias_status_clear = fc_layer_enable_dly[1] ? (~is_read_intermediate_dly[9]) & oChanged_param & (~param_buf_status_not_clear) : 
                                                      oChanged_param & (~param_buf_status_not_clear);

assign	oAdd_bias_valid = add_bias_valid_dly[3];

//
reg             specific_flag;
reg     [1:0]   specific_count;
reg     [9:0]   num_in_each_row;
reg             mask_valid;

always @(posedge clk) begin
    if(rst)
        specific_count <= 0;
    else if(iS_specific_enable & (pe_array_read_ob_for_branch_dly[2] || (specific_count != 0)) & is_read_intermediate_dly1)
        specific_count <= specific_count + 1'b1;
    else
        specific_count <= 0;
end

always @(posedge clk) begin
    if(rst)
        num_in_each_row <= 0;
    else if(specific_count == 2'd3) begin
        if(num_in_each_row == omap_width)
            num_in_each_row <= 0;
        else
            num_in_each_row <= num_in_each_row + 1'b1;
    end
end

always @(posedge clk)
    mask_valid <= is_read_intermediate_dly1 & iS_specific_enable & (pe_array_read_ob_for_branch_dly[2] || (specific_count != 0)) & (~((num_in_each_row == omap_width) & (specific_count > iSpecific_sel_mask)));


assign	oRead_intermediate_valid = (~iS_specific_enable) & (is_read_intermediate_dly[1] & oPE_array_acc_clear & (~is_branch_add_valid) || is_branch_add_valid & pe_array_read_ob_for_branch) ||
                                   mask_valid;
//assign	oRead_in_intermediate_zone = is_read_intermediate_dly[9];

endmodule

