module	input_data_bitwidth_conversion_bias (
			// global singnals
				input				clk,
				input				rst,
			// input data path
				input	[511:0]		iData,
				input				iData_valid,
			    output				oData_stop,

			// output parameter 
				output	[511:0]		oBias,
				output	[3:0]	    oBias_valid
		);

wire			full,empty;
wire			wr_rst_busy,rd_rst_busy;
wire	[511:0]	rd_data;
wire	[511:0]	fifo_rd_data;
reg				fifo_rd_data_valid;
//reg             fifo_rd_data_valid_dly1,fifo_rd_data_valid_dly2;
reg		[511:0]	reg_data;
//reg  	[16*128-1:0]	broadcast_data_combined;
reg		[1:0]	count;
reg     [3:0]  bias_valid;

//(* keep="true" *) reg     [511:0]  broadcast_data_layer_1 [3:0];

assign	fifo_rd_data = rd_data;

always @(posedge clk) begin
	if(rst)
		fifo_rd_data_valid <= 1'b0;
	else
		fifo_rd_data_valid <= (~empty) & (~rd_rst_busy);
		/*
    fifo_rd_data_valid_dly2 <= fifo_rd_data_valid_dly1;
    fifo_rd_data_valid_dly1 <= fifo_rd_data_valid;
    */
end
//
always @(posedge clk)
    reg_data <= fifo_rd_data;


always @(posedge clk) begin
	if(rst)
		count <= 2'd0;
	else begin
		if(fifo_rd_data_valid)
			if(count == 2'd3)
				count <= 2'd0;
			else
				count <= count + 1'b1;
	end
end




//assign	shift_data = reg_data | ({8160'b0,fifo_rd_data} << (count << 5));

assign  oBias = reg_data;
assign  oBias_valid = bias_valid;

always @(posedge clk) begin
	bias_valid[0]  <= fifo_rd_data_valid & (count == 2'd0); 
	bias_valid[1]  <= fifo_rd_data_valid & (count == 2'd1);
	bias_valid[2]  <= fifo_rd_data_valid & (count == 2'd2);
	bias_valid[3]  <= fifo_rd_data_valid & (count == 2'd3);  
end


assign  oData_stop = full;

reg             data_valid_flag;
reg  [511:0]    data_store;
wire [511:0]    data_write;

always @(posedge clk) begin
/*
    if(rst)
        data_valid_flag <= 1'b0;
    else if(iData_valid)
        data_valid_flag <= ~data_valid_flag;
    if(iData_valid)
        data_store <= iData;
 */
    data_store <= iData;
    data_valid_flag <= iData_valid;
end

//assign  data_write = {iData, data_store};
assign  data_write = data_store;



input_data_if_fifo fifo_unit
	(
		.srst(rst),
		.clk(clk),
		.din(data_write),
		.wr_en(/*iData_valid & data_valid_flag*/ data_valid_flag),
		.rd_en((~empty) & (~rd_rst_busy)),
		.dout(rd_data),
		.full(),
		.prog_full(full),
		.empty(empty),
		.wr_rst_busy(wr_rst_busy),
		.rd_rst_busy(rd_rst_busy)
	);



endmodule

