//
reg		[`INSTR_WIDTH-1:0]	instruction_syn_1,instruction_syn_2;
reg		[1:0]				instruction_id_syn_1,instruction_id_syn_2;
reg							instruction_valid_syn_1,instruction_valid_syn_2;
reg		[1:0]				pre_instruction_id;
wire						is_instruction_valid;
//


always @(posedge clk_out) begin
	instruction_syn_1 <= iInstruction;
	instruction_syn_2 <= instruction_syn_1;
	instruction_id_syn_1 <= iInstruction_id;
	instruction_id_syn_2 <= instruction_id_syn_1;
	instruction_valid_syn_1 <= iInstruction_valid;
	instruction_valid_syn_2 <= instruction_valid_syn_1;
end

always @(posedge clk_out)
	if(rst)
		pre_instruction_id <= 2'b11;
	else if(instruction_valid_syn_2)
		pre_instruction_id <= instruction_id_syn_2;

assign	is_instruction_valid = (pre_instruction_id != instruction_id_syn_2) & instruction_valid_syn_2;


assign	instr_op_sel = instruction_syn_2[`INSTR_OP_OFFSET+:`INSTR_OP_WIDTH];


always @(posedge clk_out)
	if(is_instruction_valid)
		instruction <= instruction_syn_2;

always @(posedge clk_out)
	if(rst)
		instr_reg_index <= 4'd0;
	else if(is_instruction_valid)
		instr_reg_index <= instruction_syn_2[`INSTR_REGINDEX_OFFSET+:`INSTR_REGINDEX_WIDTH];

always @(posedge clk_out) 
	if(is_instruction_valid) 
		case(instr_op_sel)
			`INPUT_LOAD :
				begin
					input_load_valid <= 1'b1;
					param_load_valid <= 1'b0;
					process_valid <= 1'b0;
					output_store_valid <= 1'b0;
				end
			`PARAM_LOAD : 
				begin
					input_load_valid <= 1'b0;
					param_load_valid <= 1'b1;
					process_valid <= 1'b0;
					output_store_valid <= 1'b0;
				end
			`PROCESS : 
				begin
					input_load_valid <= 1'b0;
					param_load_valid <= 1'b0;
					process_valid <= 1'b1;
					output_store_valid <= 1'b0;
				end
			`OUTPUT_STORE :
				begin
					input_load_valid <= 1'b0;
					param_load_valid <= 1'b0;
					process_valid <= 1'b0;
					output_store_valid <= 1'b1;
				end
			default:
				begin
					input_load_valid <= 1'b0;
					param_load_valid <= 1'b0;
					process_valid <= 1'b0;
					output_store_valid <= 1'b0;
				end
		endcase
	else begin
		input_load_valid <= 1'b0;
		param_load_valid <= 1'b0;
		process_valid <= 1'b0;
		output_store_valid <= 1'b0;
	end

//	

always @(posedge clk_out)
    if(rst)
        instruction_count <= 4'd0;
    else if(process_valid) begin
        if(instruction_count == 4'd8)
            instruction_count <= 4'd0;
        else
            instruction_count <= instruction_count + 1'b1;
    end

always @(posedge clk_out)
	if(rst)
		input_load_instr_count <= 3'd0;
	else if(input_load_valid) begin
		if(input_load_instr_count == 3'd2)
			input_load_instr_count <= 3'd0;
		else
			input_load_instr_count <= input_load_instr_count + 1;
	end

always @(posedge clk_out)
	if(rst)
		output_store_instr_count <= 3'd0;
	else if(output_store_valid) begin
		if(output_store_instr_count == 3'd6)
			output_store_instr_count <= 3'd0;
		else
			output_store_instr_count <= output_store_instr_count + 1;
	end

always @(posedge clk_out)
	if(input_load_valid) begin
		case(instr_reg_index)
			4'd0:
				begin
					cfs_ib_wr_data_block_len <= instruction[0+:16];
					cfs_ib_wr_data_block_startaddr[8:0] <= instruction[16+:9];
				end
			4'd1:
				begin
					cfs_ib_wr_data_block_startaddr[16:9] <= instruction[0+:8];
					cfs_ib_wr_is_data_from_outchip <= instruction[8];
					cfs_ib_wr_userate <= instruction[9+:2];
					cfs_ib_wr_data_block_sublen[0+:14] <= instruction[11+:14];
				end
	        4'd2:
	            begin
	                cfs_ib_wr_data_block_sublen[14+:2] <= instruction[0+:2];
	                cfs_ib_wr_data_block_stride <= instruction[2+:2];
	            end
		endcase
	end

always @(posedge clk_out)
	if(param_load_valid) begin
		cfs_ib_wr_param_block_len <= instruction[0+:8];	
		cfs_ib_wr_bias_block_len <= instruction[8+:4];
		cfs_ib_wr_param_sel   <= instruction[12+:2];
	end

always @(posedge clk_out)
	if(output_store_valid) begin
		case(instr_reg_index)
			4'd0:
				begin
					cfs_ob_rd_data_block_len <= instruction[0+:12];
					cfs_ob_rd_data_start_addr <= instruction[12+:12];
					cfs_ob_rd_result_bit_sel[0] <= instruction[24+:1];
				end
			4'd1:
				begin
					cfs_ob_rd_result_bit_sel[3:1] <= instruction[0+:3];
					cfs_ob_rd_pooling_enable <= instruction[3];
					cfs_ob_rd_deconv_enable_with_stride_neq_1 <= instruction[4];
					cfs_ob_rd_pooling_im_num <= instruction[5+:2];
					cfs_ob_rd_pooling_kernel_size <= instruction[7+:4];
					cfs_ob_rd_pooling_kernel_stride <= instruction[11+:2];
					cfs_ob_rd_pooling_pad_size <= instruction[13+:3];
					cfs_ob_rd_pooling_block_col[8:0] <= instruction[16+:9];
				end
			4'd2:
				begin
					cfs_ob_rd_pooling_block_col[9] <= instruction[0];
					cfs_ob_rd_pooling_omap_col <= instruction[1+:10];
					cfs_ob_rd_pooling_omap_row <= instruction[11+:10];
					cfs_ob_rd_pooling_row_start[3:0] <= instruction[21+:4];
				end
			4'd3:
				begin
				    cfs_ob_rd_pooling_row_start[9:4] <= instruction[0+:6];
					cfs_ob_rd_pooling_row_end <= instruction[6+:10];
					cfs_ob_rd_pooling_col_start[8:0] <= instruction[16+:9];
				end
			4'd4:
				begin
					cfs_ob_rd_pooling_col_start[9] <= instruction[0];
					cfs_ob_rd_pooling_col_end <= instruction[1+:10];
					cfs_ob_rd_pooling_channel_mode <= instruction[11+:2];
					cfs_ob_rd_is_average_pooling <= instruction[13];
					cfs_ob_rd_average_pooling_weight <= instruction[14+:8];
					cfs_ob_rd_up_sampling_enable <= instruction[22+:1];
					cfs_ob_rd_rep_read_enable <= instruction[23+:1];
					cfs_ob_rd_activation_type[0] <= instruction[24];
				end
	        4'd5:
	            begin 
	                cfs_ob_rd_activation_type[3:1] <= instruction[2:0];
	                cfs_ob_rd_activation_scale     <= instruction[3+:16];
	                cfs_ob_rd_activation_scale_m[5:0] <= instruction[19+:6];
	            end
	        4'd6: 
	            begin 
	                cfs_ob_rd_activation_scale_m[7:6] <= instruction[1:0];
	                cfs_ob_rd_activation_scale_n <= instruction[2+:5];            
	            end
 		endcase		
	end

always @(posedge clk_out)
	if(process_valid) begin
		case(instr_reg_index)
			4'd0:
				begin
					cfs_ib_rd_rep_num <= instruction[0+:8];
					cfs_ib_rd_kernel_col_size <= instruction[8+:4];
					cfs_ib_rd_kernel_square_size <= instruction[12+:8];
					cfs_ib_rd_omap_width[4:0] <= instruction[20+:5];
				end
			4'd1:
				begin
					cfs_ib_rd_omap_width[9:5] <= instruction[0+:5];
					cfs_ib_rd_omap_height <= instruction[5+:10];
					cfs_ib_rd_imap_width <= instruction[15+:10];
				end
			4'd2:
				begin
					cfs_ib_rd_pad_size <= instruction[0+:4];
					cfs_ib_rd_im_num <= instruction[4+:6];
					cfs_ib_rd_width_step <= instruction[10+:4];
					cfs_ib_rd_height_step <= instruction[14+:4];
					cfs_ib_rd_channel_big_than_16 <= instruction[18];
					cfs_ib_rd_overlap_rd_enable <= 1'b0;
					cfs_ib_rd_datablock_start_addr[5:0] <= instruction[19+:6];
				end
			4'd3:
				begin
					cfs_ib_rd_datablock_start_addr[17:6] <= instruction[0+:12];
					cfs_ib_rd_row_start <= instruction[12+:10];
					cfs_ib_rd_row_end[2:0] <= instruction[22+:3];
				end
			4'd4:
				begin
					cfs_ib_rd_row_end[9:3] <= instruction[0+:7];
					cfs_ib_rd_col_start <= instruction[7+:10];
					cfs_ib_rd_col_end[7:0] <= instruction[17+:8];
				end
			4'd5:
				begin
				    cfs_ib_rd_col_end[9:8] <= instruction[0+:2]; 
					cfs_ib_rd_fclayer_enable <= instruction[2];
					cfs_ib_rd_is_add_bias <= instruction[3];
					cfs_ib_rd_is_read_intermediate <= instruction[4];
					cfs_ib_rd_intermediate_enable <= 1'b0;//instruction[3];
					cfs_ib_rd_block_len_of_intermediate <= instruction[5+:12];
					cfs_ib_rd_data_organization <= instruction[17+:2];
					cfs_ib_rd_param_buf_status_not_clear <= instruction[19];
					cfs_ib_rd_inputbuffer_channel_mode <= instruction[20+:2];
					cfs_ib_rd_specific_enable <= instruction[22];
					cfs_ib_rd_specific_mode <= instruction[23+:2];
				end
			4'd6:
				begin
					cfs_ob_wr_is_intermediate_result <= instruction[0];
                    cfs_ob_wr_data_block_len  <= instruction[1+:12];
					cfs_pe_interconnection <= instruction[13+:2];
					cfs_pe_relu_enable <= instruction[15];
					cfs_pe_branch_add_enable <= instruction[16];
					cfs_pe_channel_mask_sel <= instruction[17+:2];
					cfs_pe_result_bit_sel <= instruction[19+:4];
					cfs_intermediate_shift_enable <= instruction[23];
					cfs_intermediate_right_shift_width[0] <= instruction[24+:1];
				end
			4'd7:
				begin
				    cfs_intermediate_right_shift_width[3:1] <= instruction[0+:3];
					cfs_intermediate_left_shift_width <= instruction[3+:3];
					cfs_pe_branch_bitshift <= instruction[6+:4];
					cfs_intermediate_sel_count <= instruction[10+:4];
					cfs_ib_rd_kernel_size <= instruction[14+:4];
					cfs_mult_scalar_enable <= instruction[18];
					cfs_specific_sel_mask <= instruction[19+:2];
					cfs_scalar_left_shift <= instruction[21+:4];
				end
			4'd8:
				begin
					cfs_ib_rd_is_conv_bypass <= instruction[0];
					cfs_ib_rd_pad_h_size <= {1'b0,instruction[1+:3]};
					cfs_ib_rd_is_enable_stride <= instruction[4];
					cfs_ib_rd_mem_sel <= instruction[5];
					cfs_ob_wr_scale_m <= instruction[6+:8];
					cfs_ob_wr_scale_n <= instruction[14+:5];
				end
		endcase
	end

//

always @(posedge clk_out) begin
	oCfs_ib_wr_param_config_valid <= param_load_valid;
	oCfs_ib_wr_config_valid <= input_load_valid & (input_load_instr_count == 3'd2);
	oCfs_ib_rd_config_valid <= process_valid & (instruction_count == 4'd8);
	oCfs_ob_rd_config_valid <= output_store_valid & (output_store_instr_count == 3'd6);
end

// configuration singals for the inputs of the input_buffer
assign	oCfs_ib_wr_data_block_len = cfs_ib_wr_data_block_len,
		oCfs_ib_wr_data_block_startaddr = cfs_ib_wr_data_block_startaddr,
		oCfs_ib_wr_is_data_from_outchip = cfs_ib_wr_is_data_from_outchip,
		oCfs_ib_wr_userate = cfs_ib_wr_userate,
		oCfs_ib_wr_param_block_len = cfs_ib_wr_param_block_len,
		oCfs_ib_wr_bias_block_len = cfs_ib_wr_bias_block_len,
		oCfs_ib_wr_param_sel = cfs_ib_wr_param_sel,
		oCfs_ib_wr_data_block_sublen = cfs_ib_wr_data_block_sublen,
		oCfs_ib_wr_data_block_stride = cfs_ib_wr_data_block_stride;

// configuration signals for the output of the input_buffer
assign	oCfs_ib_rd_rep_num = cfs_ib_rd_rep_num,
		oCfs_ib_rd_kernel_size = cfs_ib_rd_kernel_size,
		oCfs_ib_rd_kernel_col_size = cfs_ib_rd_kernel_col_size,
		oCfs_ib_rd_kernel_square_size = cfs_ib_rd_kernel_square_size,
		oCfs_ib_rd_omap_width = cfs_ib_rd_omap_width,
		oCfs_ib_rd_omap_height = cfs_ib_rd_omap_height,
		oCfs_ib_rd_imap_width = cfs_ib_rd_imap_width,
		oCfs_ib_rd_pad_size = cfs_ib_rd_pad_size,
		oCfs_ib_rd_im_num = cfs_ib_rd_im_num,
		oCfs_ib_rd_width_step = cfs_ib_rd_width_step,
		oCfs_ib_rd_height_step = cfs_ib_rd_height_step,
		oCfs_ib_rd_channel_big_than_16 = cfs_ib_rd_channel_big_than_16,
		oCfs_ib_rd_overlap_rd_enable = cfs_ib_rd_overlap_rd_enable,
		oCfs_ib_rd_datablock_start_addr = cfs_ib_rd_datablock_start_addr,
