		oCfs_ib_rd_row_end = cfs_ib_rd_row_end,
		oCfs_ib_rd_col_start = cfs_ib_rd_col_start,
		oCfs_ib_rd_col_end = cfs_ib_rd_col_end,
		oCfs_ib_rd_fclayer_enable = cfs_ib_rd_fclayer_enable,
		oCfs_ib_rd_is_add_bias = cfs_ib_rd_is_add_bias,
		oCfs_ib_rd_is_read_intermediate = cfs_ib_rd_is_read_intermediate,
		oCfs_ib_rd_intermediate_enable = cfs_ib_rd_intermediate_enable,
		oCfs_ib_rd_block_len_of_intermediate = cfs_ib_rd_block_len_of_intermediate,
		oCfs_ib_rd_data_organization = cfs_ib_rd_data_organization,
		oCfs_ib_rd_param_buf_status_not_clear = cfs_ib_rd_param_buf_status_not_clear,
		oCfs_ib_rd_inputbuffer_stride_mode = cfs_ib_rd_inputbuffer_channel_mode,
		oCfs_ib_rd_specific_enable = cfs_ib_rd_specific_enable,
