// configuration signals for inputs of the output_buffer
assign	oCfs_ob_wr_is_intermediate_result = cfs_ob_wr_is_intermediate_result,
		oCfs_ob_wr_data_block_len = cfs_ob_wr_data_block_len,
		oCfs_ob_wr_scale_m = cfs_ob_wr_scale_m,
