module	intermediate_buffer_rd_ctr(
			// global signals
				input				clk,
				input				rst,
			// configure signals
				input		[11:0]	iBlock_length,
				input		[1:0]	iIntermediate_data_organization,
				input               iIntermediate_width_step_eq_2,
				input               iS_branch_add_enable,
				input		[11:0]	iIntermediate_read_start_addr,
				input				iData_rd_enable,
				output reg			oData_rd_addr_valid,
				output reg	[11:0]	oData_rd_addr
		);
localparam  RD_URAM_LATENCY = 21;
localparam	LATENCY = 2+2 + RD_URAM_LATENCY; // in order to alias with the input of bias data in pe_array_if module

wire		data_addr_meet_border;
reg         data_addr_meet_border_dly;
reg  [11:0] gen_addr;
wire        data_rd_enable;
//reg  [9:0]  pre_addr;

reg	[1:0]	im_num_count;
reg			data_rd_enable_dly[LATENCY-1+2:0];
reg         width_step_eq_2;

assign  data_rd_enable = iS_branch_add_enable ? 
                               (iIntermediate_data_organization == 2'b11 ? data_rd_enable_dly[LATENCY+1] :
                                iIntermediate_data_organization == 2'b01 ? data_rd_enable_dly[LATENCY-3] :
                                                                           data_rd_enable_dly[LATENCY-3]
                               ):
                               (iIntermediate_data_organization == 2'b11 ? data_rd_enable_dly[LATENCY-4] :
                                iIntermediate_data_organization == 2'b01 ? data_rd_enable_dly[LATENCY-2] : 
                                                                           data_rd_enable_dly[LATENCY-1]);

always @(posedge clk) begin : dly
	integer i;
	data_rd_enable_dly[0] <= iData_rd_enable;
	for(i=1;i<LATENCY+2;i=i+1)
		data_rd_enable_dly[i] <= data_rd_enable_dly[i-1];

	width_step_eq_2 <= iIntermediate_width_step_eq_2;
end

always @(posedge clk)
	if(rst)
		im_num_count <= 2'd0;
	else if(data_rd_enable | (|im_num_count)) begin
		if(im_num_count == (width_step_eq_2 ? 2'd0 : iIntermediate_data_organization))
			im_num_count <= 2'd0;
		else
			im_num_count <= im_num_count + 1'b1;
	end

always @(posedge clk)
	if(rst)
		gen_addr <= 12'd0;
	else if(data_rd_enable | (|im_num_count))
		if(data_addr_meet_border)
			gen_addr <= 12'd0;
		else
			gen_addr <= gen_addr + 1'b1;

assign	data_addr_meet_border = (gen_addr == iBlock_length);

always @(posedge clk)
    data_addr_meet_border_dly <= data_addr_meet_border & (data_rd_enable | (|im_num_count));

always @(posedge clk)
    oData_rd_addr <= gen_addr + iIntermediate_read_start_addr;

always @(posedge clk)
	oData_rd_addr_valid <= data_rd_enable | (|im_num_count);

//always @(posedge clk)
//    if(rst)
//        pre_addr <= 10'd0;
//    else if(data_addr_meet_border_dly & iS_pp_buffer)
//        pre_addr <= oData_rd_addr + 1; 

endmodule

module	micro_controller (
		// global signals
			input					clk_sys,
			input					rst,
		// finish block indicator
			input	[1:0]			iFinish_block_indicator,
			output	[1:0]			oFinish_block_indicator_clear,
		// stage status
			input	[3:0]			iStage_full_status,			// {stop_from_status_of_param, stop_from_config_in_stage3, stop_from_config_in_stage2, stop_from_config_in_stage1}
			input	[3:0]			iConfig_stage_ack,
		// read dma 
			input					iRead_dma_instr_stop,		// read ddr
			output	reg [31:0]		oRead_dma_addr_offset,
			output	reg [9:0]		oRead_dma_data_len,
			output	reg [1:0]		oRead_dma_data_type,
			output	reg   			oRead_dma_ddr_sel,
			output  reg             oRead_dma_ddr_is_dsa,
			output	reg   			oRead_dma_instr_valid,
		// write dma
			input					iWrite_dma_instr_stop,      // write ddr
			output	reg [31:0]		oWrite_dma_addr_offset,
			output	reg [9:0]		oWrite_dma_data_len,
			output	reg				oWrite_dma_ddr_sel,
			output  reg [1:0]       oWrite_dma_is_final_result, // 00 -> normal; 01 -> final result; 10 -> dsa_op1; 11 -> dsa_op2
			output  reg [3:0]       oWrite_dma_stride,   // next_bic/current_boc
			output  reg [1:0]       oWrite_dma_sublen,   // if next_bic/current_boc != 1; then sublen = current_boc/32-1; else 0
			output	reg				oWrite_dma_instr_valid,
		// instruction for fucore
			output	[31:0]			oInstruction,
			output	reg [1:0]		oInstruction_id,
			output					oInstruction_valid,

		// ready flags to boot the processing
			input					iInstruction_ready,

			output                  oInstruction_finish,
			input                   iLast_data_block_proposal,
			output                  oBatch_finish,
		// configuration information
			input					iConfig_valid,
			input	[31:0]			iLength_of_clipb,		// clipb: configuration of loading input data, paramters and bias
			input	[31:0]			iLength_of_cc,			// cc: configuration of computing
			input	[31:0]			iLength_of_cw,			// cw: configuration of writeback
			input   [31:0]          iLength_of_ld,
			input   [31:0]          iLength_of_wt,

			input	[31:0]			iAddr_offset_clipb,
