			input	[31:0]			iAddr_offset_cw,
			input	[31:0]			iAddr_offset_ld,
			input	[31:0]			iAddr_offset_wt,
		// dma interface to ddr4
		// clipb
			output	[31:0]			oDDR_instr_base_addr_clipb,
			output	[9:0]			oDDR_instr_burst_len_clipb,
			output					oDDR_instr_wren_clipb,
