always @(posedge clk_sys) begin
	if(rst)
		instruction_port_mutex_flag[0] <= 1'b1;
	else
		instruction_port_mutex_flag[0] <= ~((~clipb_instr_fifo_full) & (~clipb_instr_fifo_wr_rst_busy));

	if(rst)
		instruction_port_mutex_flag[1] <= 1'b1;
	else if((cc_nstate == CC_PROC) && (cc_instruction_buf_data[33] == 1'b1) )
		instruction_port_mutex_flag[1] <= 1'b0;
	else if(cw_wt_cstate == CW_WT_CHECK)
		instruction_port_mutex_flag[1] <= 1'b1;

	if(rst)
		instruction_port_mutex_flag[2] <= 1'b1;
	else if((~cc_cw_instr_fifo_full) & (~cc_cw_instr_fifo_wr_rst_busy) & instruction_port_mutex_flag[1] & (cc_nstate != CC_PROC) || (~instruction_port_mutex_flag[1]) & (cw_wt_cstate == CW_WT_CHECK)) 
		instruction_port_mutex_flag[2] <= 1'b0;
	else if((cc_nstate == CC_PROC) && (cc_instruction_buf_data[33] == 1'b1))
		instruction_port_mutex_flag[2] <= 1'b1;
end

always @(posedge clk_sys)
	if(rst)
		abitor_flag <= 1'b0;
	else if((~cc_cw_instr_fifo_empty) & (~cc_cw_instr_fifo_rd_rst_busy))
		abitor_flag <= 1'b0;
	else if((~clipb_instr_fifo_empty) & (~clipb_instr_fifo_rd_rst_busy))
		abitor_flag <= 1'b1;

assign	cc_cw_instr_fifo_rden = (~abitor_flag) & (~cc_cw_instr_fifo_empty);
assign	clipb_instr_fifo_rden = abitor_flag & (~clipb_instr_fifo_empty);

always @(posedge clk_sys) begin
	cc_cw_instr_fifo_rden_dly <= cc_cw_instr_fifo_rden;
	clipb_instr_fifo_rden_dly <= clipb_instr_fifo_rden;
end

assign	oInstruction = cc_cw_instr_fifo_rden_dly ? cc_cw_instr_fifo_rd_data : 
                       clipb_instr_fifo_rden_dly ? clipb_instr_fifo_rd_data : 32'b0;
assign	oInstruction_valid = cc_cw_instr_fifo_rden_dly | clipb_instr_fifo_rden_dly;

always @(posedge clk_sys)
	if(rst)
		oInstruction_id <= 2'd0;
	else if(oInstruction_valid)
		oInstruction_id <= oInstruction_id + 1'b1;

//============================
// clipb
//============================
always @(posedge clk_sys)
	if(rst)
		clipb_cstate <= CLIPB_IDLE;
	else
		clipb_cstate <= clipb_nstate;

always @(*) begin
	clipb_nstate = CLIPB_IDLE;
	case(clipb_cstate)
		CLIPB_IDLE: 
			if((|clipb_instruction_buf_status) & (~cli_busy_flag) & (~clipb_layer_is_finish) &(~instruction_port_mutex_flag[0]) & (~iStage_full_status[3]) & 
			   ((~iStage_full_status[0]) || iStage_full_status[0] & cli_next_is_clpb) & (~instruction_finish_flag))
				clipb_nstate = CLIPB_RD;
			else 
				clipb_nstate = CLIPB_IDLE;
		CLIPB_RD:
			clipb_nstate = CLIPB_PROC;
		CLIPB_PROC:
			if(clipb_instruction_buf_data[33:32] == 2'b10)
			    clipb_nstate = CLIPB_DL;
			else if(clipb_instruction_buf_data[33:32] == 2'b11)
				clipb_nstate = CLIPB_WAIT;
			else
				clipb_nstate = CLIPB_IDLE;
				/*
		CLIPB_DL:
		    if(~iStage_full_status[0])
		        clipb_nstate = CLIPB_DL_WAIT;
		    else
			    clipb_nstate = CLIPB_DL;
			    */
	    CLIPB_DL:
	           clipb_nstate = CLIPB_DL_WAIT;
		CLIPB_DL_WAIT:
			if((|ld_instruction_buf_status) & (~iRead_dma_instr_stop))
				clipb_nstate = CLIPB_DL_RD;
			else
				clipb_nstate = CLIPB_DL_WAIT;
		CLIPB_DL_RD:
		    clipb_nstate = CLIPB_DL_PROC;
		CLIPB_DL_PROC:
			if(ld_instruction_buf_data[33:32] != 2'b10) begin
				if((|ld_instruction_buf_status) & (~iRead_dma_instr_stop))
					clipb_nstate = CLIPB_DL_RD;
				else
					clipb_nstate = CLIPB_DL_WAIT;
			end else  begin
				if((|clipb_instruction_buf_status) & (~cli_busy_flag) & (~clipb_layer_is_finish))
					clipb_nstate = CLIPB_RD;
				else
					clipb_nstate = CLIPB_IDLE;
			end
		CLIPB_WAIT:
			if(~iStage_full_status[3])
				clipb_nstate = CLIPB_PL;
			else
				clipb_nstate = CLIPB_WAIT;

		CLIPB_PL:
			clipb_nstate = CLIPB_PL_WAIT;
		CLIPB_PL_WAIT:
			if((|ld_instruction_buf_status) & (~iRead_dma_instr_stop))
				clipb_nstate = CLIPB_PL_RD;
			else
				clipb_nstate = CLIPB_PL_WAIT;
		CLIPB_PL_RD:
			clipb_nstate = CLIPB_PL_PROC;
		CLIPB_PL_PROC:
			if(ld_instruction_buf_data[33:32] != 2'b11) begin
				if((|ld_instruction_buf_status) & (~iRead_dma_instr_stop))
					clipb_nstate = CLIPB_PL_RD;
				else
					clipb_nstate = CLIPB_PL_WAIT;
			end else begin
				clipb_nstate = CLIPB_IDLE;
			end
		default: clipb_nstate = CLIPB_IDLE;
	endcase
end

assign clipb_instruction_buf_rden = (clipb_nstate == CLIPB_RD);// || (cli_count_flag & cli_count);
assign clipb_instruction_buf_rd_count_meet_border = (clipb_instruction_buf_rd_count == (clipb_instruction_buf_ppflag ? clipb_instruction_len[1]-1 : clipb_instruction_len[0]-1));
assign clipb_instruction_buf_rdaddr = clipb_instruction_buf_ppflag ? clipb_instruction_buf_rd_count + 10'd512 : clipb_instruction_buf_rd_count;
assign clipb_instruction_buf_status_clear[0] =  clipb_instruction_buf_rden & clipb_instruction_buf_rd_count_meet_border & (~clipb_instruction_buf_ppflag);
assign clipb_instruction_buf_status_clear[1] =  clipb_instruction_buf_rden & clipb_instruction_buf_rd_count_meet_border & clipb_instruction_buf_ppflag;
assign clipb_instruction_port_mutex_clear = (clipb_nstate == CLIPB_DL_PROC);
assign clipb_instruction_port_mutex_set = (clipb_nstate == CLIPB_RD);

