always @(posedge clk_sys)
    if(rst) 
        cli_next_is_clpb <= 1'b0;
    else if(clipb_cstate == CLIPB_PROC)
        cli_next_is_clpb <= (clipb_instruction_buf_data[34:32] == 3'b110);
    else if((clipb_cstate == CLIPB_PROC) && (clipb_instruction_buf_data[33:32] == 2'b11))
        cli_next_is_clpb <= 1'b0;

always @(posedge clk_sys)
	if(rst) begin
		cli_busy_flag <= 1'b0;
		clpb_busy_flag <= 1'b0;
	end else begin
		if(clipb_cstate == CLIPB_PROC && clipb_instruction_buf_data[33:32] == 2'b10)
			cli_busy_flag <= 1'b1;
		else if(iConfig_stage_ack[0])
			cli_busy_flag <= 1'b0;

		if(clipb_cstate == CLIPB_PROC && clipb_instruction_buf_data[33:32] == 2'b11)
			clpb_busy_flag <= 1'b1;
		else if(iConfig_stage_ack[3])
			clpb_busy_flag <= 1'b0;
	end

always @(posedge clk_sys)
	if(rst)
		clipb_layer_is_finish <= 1'b0;
	else if(clipb_cstate == CLIPB_PROC && clipb_instruction_buf_data[35:33] == 3'b001)
		clipb_layer_is_finish <= 1'b1;
	else if(cw_layer_is_finish)
		clipb_layer_is_finish <= 1'b0;

always @(posedge clk_sys) begin
	clipb_instruction_buf_rden_dly[0] <= clipb_instruction_buf_rden;
	clipb_instruction_buf_rden_dly[1] <= clipb_instruction_buf_rden_dly[0];
end

always @(posedge clk_sys) begin
    if(rst)
        cli_count_flag <= 0;
    else
        cli_count_flag <= clipb_instruction_buf_rden_dly[1] & (clipb_instruction_buf_data[33:32] == 2'b10);
end

always @(posedge clk_sys)
    if(rst)
        cli_count <= 1'b0;
    else if(clipb_instruction_buf_rden_dly[1] & (clipb_instruction_buf_data[33:32] == 2'b10))
        cli_count <= ~cli_count;

always @(posedge clk_sys) begin
    clipb_instruction_send_valid <= clipb_instruction_buf_rden_dly[1];
    if(clipb_instruction_buf_rden_dly[1])
        clipb_instruction <= clipb_instruction_buf_data[31:0];
end
/*
assign  clipb_instruction_send_valid = (clipb_cstate == CLIPB_DL) & (~iStage_full_status[0]) ||
                                       (clipb_cstate == CLIPB_WAIT) & (~iStage_full_status[3]);
*/


always @(posedge clk_sys) begin
	if(rst)
		clipb_instruction_buf_rd_count <= 10'd0;
	else if(clipb_instruction_buf_rden)
		if(clipb_instruction_buf_rd_count_meet_border)
			clipb_instruction_buf_rd_count <= 10'd0;
		else
			clipb_instruction_buf_rd_count <= clipb_instruction_buf_rd_count + 1'b1;
end

always @(posedge clk_sys)
	if(rst)
		clipb_instruction_buf_ppflag <= 1'b0;
	else if(clipb_instruction_buf_rden & clipb_instruction_buf_rd_count_meet_border)
		clipb_instruction_buf_ppflag <= ~clipb_instruction_buf_ppflag;

//
assign	ld_instruction_buf_rden = (clipb_nstate == CLIPB_DL_RD) || (clipb_nstate == CLIPB_PL_RD);
assign	ld_instruction_buf_rd_count_meet_border = (ld_instruction_buf_rd_count == (ld_instruction_buf_ppflag ? ld_instruction_len[1]-1 : ld_instruction_len[0]-1));
assign	ld_instruction_buf_rdaddr = ld_instruction_buf_ppflag ? ld_instruction_buf_rd_count + 10'd512 : ld_instruction_buf_rd_count;
assign	ld_instruction_buf_status_clear[0] = ld_instruction_buf_rden & ld_instruction_buf_rd_count_meet_border & (~ld_instruction_buf_ppflag);
assign	ld_instruction_buf_status_clear[1] = ld_instruction_buf_rden & ld_instruction_buf_rd_count_meet_border & ld_instruction_buf_ppflag;

