		cw_wt_cstate <= cw_wt_nstate;

always @(*) begin
	cw_wt_nstate = CW_WT_IDLE;
	case(cw_wt_cstate)
		CW_WT_IDLE:
			if((|cw_instruction_buf_status) & (~iStage_full_status[2]) & (~cw_busy_flag) & (~cc_busy_flag) & (~finish_block_indicator_clear_zone) & (|iFinish_block_indicator) & (~cc_cw_instr_fifo_full))
				cw_wt_nstate = CW_WT_LOCK;
			else
				cw_wt_nstate = CW_WT_IDLE;
	    CW_WT_LOCK:
	        if(cc_busy_flag)
	            cw_wt_nstate = CW_WT_IDLE;
	        else
	            cw_wt_nstate = CW_WT_CHECK;
		CW_WT_CHECK:
			if(cc_hasnot_cw_wt_sel)
				cw_wt_nstate = CW_WT_IDLE;
			else
				cw_wt_nstate = CW_WT_RD;
		CW_WT_RD:
			cw_wt_nstate = CW_WT_PROC;
		CW_WT_PROC:
			cw_wt_nstate = CW_WT_WT_WAIT;
		CW_WT_WT_WAIT:
			if((|wt_instruction_buf_status) & (~iWrite_dma_instr_stop))
				cw_wt_nstate = CW_WT_WT_RD;
			else
				cw_wt_nstate = CW_WT_WT_WAIT;
		CW_WT_WT_RD:
			cw_wt_nstate = CW_WT_WT_PROC;
		CW_WT_WT_PROC:
			if(wt_instruction_buf_data[33:32] != 2'b11) begin
				if((|wt_instruction_buf_status) & (~iWrite_dma_instr_stop))
					cw_wt_nstate = CW_WT_WT_RD;
				else
					cw_wt_nstate = CW_WT_WT_WAIT;
			end else
				cw_wt_nstate = CW_WT_IDLE;
		default:
			cw_wt_nstate = CW_WT_IDLE;
	endcase
end

