//=========
// cc
//=========

always @(posedge clk_sys)
	if(rst)
		cc_cstate <= CC_IDLE;
	else
		cc_cstate <= cc_nstate;

always @(*) begin
	cc_nstate = CC_IDLE;
	case(cc_cstate)
		CC_IDLE:
			if((|cc_instruction_buf_status) & (~iStage_full_status[1]) & (~cc_busy_flag) & (cc_status != 2'b11) & (~cc_cw_instr_fifo_full) & (~cw_busy_flag))
				cc_nstate = CC_RD;
			else
				cc_nstate = CC_IDLE;
		CC_RD:
			cc_nstate = CC_PROC;
		CC_PROC:
			if((cc_instruction_buf_data[33] != 1'b1)) begin
				if((|cc_instruction_buf_status))
					cc_nstate = CC_RD;
				else
					cc_nstate = CC_IDLE;
					//cc_nstate = CC_PROC;
			end else 
				cc_nstate = CC_NOP;

		CC_NOP:
			cc_nstate = CC_IDLE;
		default: cc_nstate = CC_IDLE;
	endcase
end

assign cc_instruction_buf_rden = (cc_nstate == CC_RD);
assign cc_instruction_buf_rd_count_meet_border = (cc_instruction_buf_rd_count == (cc_instruction_buf_ppflag ? cc_instruction_len[1]-1 : cc_instruction_len[0]-1));
assign cc_instruction_buf_rdaddr = cc_instruction_buf_ppflag ? cc_instruction_buf_rd_count + 10'd512 : cc_instruction_buf_rd_count;
assign cc_instruction_buf_status_clear[0] =  cc_instruction_buf_rden & cc_instruction_buf_rd_count_meet_border & (~cc_instruction_buf_ppflag);
assign cc_instruction_buf_status_clear[1] =  cc_instruction_buf_rden & cc_instruction_buf_rd_count_meet_border & cc_instruction_buf_ppflag;
assign cc_instruction_port_mutex_clear = (cc_nstate == CC_NOP);
assign cc_instruction_port_mutex_set = (cc_nstate == CC_RD);

always @(posedge clk_sys) 
	if(rst)
		cc_busy_flag <= 1'b0;
	else begin
		if(cc_nstate == CC_RD)
			cc_busy_flag <= 1'b1;
		else if(iConfig_stage_ack[1] || (cc_instruction_buf_status == 0))
			cc_busy_flag <= 1'b0;
	end

always @(posedge clk_sys) begin
	cc_instruction_buf_rden_dly[0] <= cc_instruction_buf_rden;
	cc_instruction_buf_rden_dly[1] <= cc_instruction_buf_rden_dly[0];
end

always @(posedge clk_sys)
    if(rst)
        cc_select <= 1'b0;
    else if((cc_cstate == CC_PROC) && (cc_instruction_buf_data[33] == 1'b1) && cc_instruction_buf_rden_dly[1])
        cc_select <= ~cc_select;

always @(posedge clk_sys)
    if(rst)
        cc_status <= 2'b0;
    else begin
        if(cc_instruction_port_mutex_clear & (~cc_select))
            cc_status[0] <= 1'b1;
        else if((~cw_wt_select) & (cw_wt_cstate == CW_WT_CHECK))
            cc_status[0] <= 1'b0;

        if(cc_instruction_port_mutex_clear & cc_select)
            cc_status[1] <= 1'b1;
        else if( cw_wt_select & (cw_wt_cstate == CW_WT_CHECK))
            cc_status[1] <= 1'b0;        

    end      
always @(posedge clk_sys)
	if(rst) begin
		cc_hasnot_cw_wt[0] <= 1'b0;
		cc_hasnot_cw_wt[1] <= 1'b0;
	end else begin 
        if((cc_cstate == CC_PROC) && (cc_instruction_buf_data[33] == 1'b1) && cc_instruction_buf_rden_dly[1] && (~cc_select))
		    cc_hasnot_cw_wt[0] <= (cc_instruction_buf_data[33:32] == 2'b10);
		else if((cc_cstate == CC_PROC) && (cc_instruction_buf_data[33] == 1'b1) && cc_instruction_buf_rden_dly[1] && cc_select)
		    cc_hasnot_cw_wt[1] <= (cc_instruction_buf_data[33:32] == 2'b10);
	end

always @(posedge clk_sys)
	if(rst) begin
		cc_layer_is_finish[0] <= 1'b0;
		cc_layer_is_finish[1] <= 1'b0;
	end else begin
	    if((cc_cstate == CC_PROC) && (cc_instruction_buf_data[33] == 1'b1) && cc_instruction_buf_rden_dly[1] && (~cc_select))
		    cc_layer_is_finish[0] <= (cc_instruction_buf_data[35:33] == 3'b001);
		else if((cc_cstate == CC_PROC) && (cc_instruction_buf_data[33] == 1'b1) && cc_instruction_buf_rden_dly[1] && cc_select)
		    cc_layer_is_finish[1] <= (cc_instruction_buf_data[35:33] == 3'b001);
	end

always @(posedge clk_sys) begin
	if(rst)
		cc_instruction_buf_rd_count <= 10'd0;
	else if(cc_instruction_buf_rden)
		if(cc_instruction_buf_rd_count_meet_border)
			cc_instruction_buf_rd_count <= 10'd0;
		else
			cc_instruction_buf_rd_count <= cc_instruction_buf_rd_count + 1'b1;
end

always @(posedge clk_sys)
	if(rst)
		cc_instruction_buf_ppflag <= 1'b0;
	else if(cc_instruction_buf_rden & cc_instruction_buf_rd_count_meet_border)
		cc_instruction_buf_ppflag <= ~cc_instruction_buf_ppflag;


assign	cc_cw_instruction_valid = cc_instruction_buf_rden_dly[1] | cw_instruction_buf_rden_dly[1];
assign	cc_cw_instruction_data = cc_instruction_buf_rden_dly[1] ? cc_instruction_buf_data[31:0] :
								 cw_instruction_buf_rden_dly[1] ? cw_instruction_buf_data[31:0] : 32'b0;
//=================================

always @(posedge clk_sys) begin
//
	config_valid_dly <= iConfig_valid;
//
	if(iConfig_valid & (~config_valid_dly)) begin
		length_of_clipb <= iLength_of_clipb;
		length_of_cc <= iLength_of_cc;
		length_of_cw <= iLength_of_cw;
		length_of_ld <= iLength_of_ld;
		length_of_wt <= iLength_of_wt;

		addr_offset_clipb <= iAddr_offset_clipb;

		addr_offset_cc <= iAddr_offset_cc;
		addr_offset_cw <= iAddr_offset_cw;
		addr_offset_ld <= iAddr_offset_ld;
		addr_offset_wt <= iAddr_offset_wt;
	end

	if(rst)
		config_flag <= 5'b0;
	else if((~iConfig_valid) & config_valid_dly || oInstruction_finish)
		config_flag <= 5'b11111;
	else begin
	    if(config_clear[0])
		  config_flag[0] <= 1'b0;

		if(config_clear[1])
		  config_flag[1] <= 1'b0;

		if(config_clear[2])
		  config_flag[2] <= 1'b0;

	    if(config_clear[3])
	      config_flag[3] <= 1'b0;

	    if(config_clear[4])
	      config_flag[4] <= 1'b0;
	end
end

