    weight_to_dsp_g1 <= weight_to_dsp_g1_t;
    weight_to_dsp_g2 <= weight_to_dsp_g2_t;
end



reg     [13:0]   weight_cache_g1 [63:0];

always @(posedge clk_sys) begin
    if((~iParam_wr_addr[6]) & iParam_wr_enable)
        weight_cache_g1[iParam_wr_addr[5:0]] <= {iParam_wr_data[14:8],iParam_wr_data[6:0]};

    {weight_d12[6:0],weight_d11[6:0]} <= weight_cache_g1[iParam_rd_addr[5:0]];
end



reg     [13:0]   weight_cache_g2 [63:0];

always @(posedge clk_sys) begin
    if(iParam_wr_addr[6] & iParam_wr_enable)
        weight_cache_g2[iParam_wr_addr[5:0]] <= {iParam_wr_data[14:8],iParam_wr_data[6:0]};
    {weight_d22[6:0],weight_d21[6:0]} <= weight_cache_g2[iParam_rd_addr[5:0]];
end

