reg     [27:0]  a_add_d;
reg     [17:0]  b_dly_1;
reg signed [17:0]   b_dly_2;
reg signed [45:0]   mult_result;


always @(posedge clk_dsp) begin
    a_dly_1 <= {weight_to_dsp_g1[7],weight_to_dsp_g1,18'b0};
    d_dly_1 <= {{19{weight_to_dsp_g2[7]}},weight_to_dsp_g2};
    b_dly_1 <= {{10{iData[7]}},iData};
    a_add_d <= {a_dly_1[26],a_dly_1} + {d_dly_1[26],d_dly_1};
    b_dly_2 <= b_dly_1;
    mult_result <= $signed(b_dly_2)*$signed(a_add_d);
    oResult_pcout <= {{2{mult_result[45]}},mult_result} +  iResult_pcin;
end

assign  oResult = oResult_pcout;


`endif
endmodule

