			input 			iIs_32_mode
		//
		);
localparam	URAM_LATENCY = 21;

//`define SAVE_FILE

parameter	WR_IDLE = 2'b00,
			WR_INSTR = 2'b01,
			WR_PROC = 2'b10,
			WR_DATA = 2'b11;

wire	wr_instr_full;
wire	wr_instr_empty;
wire	wr_instr_wr_rst_busy;
wire	wr_instr_rd_rst_busy;

wire	[7:0]  result_fifo_full;
wire	[7:0]  result_fifo_empty;
wire	[7:0]  wr_result_wr_rst_busy;
wire	[7:0]  wr_result_rd_rst_busy;

wire	wr_instr_rd_enable;
reg		wr_instr_data_valid;
wire	[34:0]	wr_instr_data;
reg		[34:0]	store_wr_instr;
reg		[10:0]	wr_count;
reg     [1:0]   wr_sublen_count;
wire            wr_sublen_count_meet_border;

reg     [9:0]   wr_count_len;
wire			wr_data_meet_border;
wire			wr_data_enable;
reg				wr_data_enable_dly;

wire            fifo_data_rd_disable;
wire    [10:0]  wr_len_tmp;


reg		[16:0]	wr_addr;
reg				wr_data_valid;
wire	[255:0]	wr_data;


reg		[1:0]	wr_cstate;
reg		[1:0]	wr_nstate;

//

reg		[1:0]	wr_status;
reg		[15:0]	in_data_count;
wire			in_data_count_meet_border;
reg     [1:0]   in_data_lock_clear, in_data_lock_clear_dly;

wire			in_data_count_valid;
reg 			status_sel;
reg 	[16:0]	wr_addr_from_offchip;
reg		[16:0]	wr_addr_from_offchip_dly; // fifo rd latency = 2 clock cycles

reg		[15:0]	wr_channel_p_addr;
reg				wr_channel_p_valid;
reg		[255:0]	wr_channel_p_data;

reg		[15:0]	wr_channel_q_addr;
reg				wr_channel_q_valid;
reg		[255:0]	wr_channel_q_data;


//

(*keep="true"*)reg		[15:0]	rd_channel_p_addr;
reg				rd_channel_p_valid;
wire	[255:0]	rd_channel_p_data;
wire			rd_channel_p_o_valid;

