reg		[2:0]	rd_data_sel_dly [URAM_LATENCY+2:0];

reg				is_first_layer_specific_dly [URAM_LATENCY-1+5+4+4:0];
reg		[1:0]	specific_mode_dly [URAM_LATENCY-1+5+4+4:0];
