assign	oWrite_dma_instr_stop = wr_instr_full || wr_instr_wr_rst_busy;
assign	oResult_stop =  result_fifo_full[7] || wr_result_wr_rst_busy[7];
//==============
// for write result channel 
//==============

always @(posedge clk)
	if(rst)
		wr_cstate <= WR_IDLE;
	else
		wr_cstate <= wr_nstate;

always @(*) begin
	wr_nstate = WR_IDLE;
	case(wr_cstate)
		WR_IDLE:
			if((~wr_instr_empty) & (~wr_instr_rd_rst_busy))
				wr_nstate = WR_INSTR;
			else
				wr_nstate = WR_IDLE;
		WR_INSTR:
			wr_nstate = WR_PROC;
		WR_PROC:
			wr_nstate = WR_DATA;
		WR_DATA:
			if(((~result_fifo_empty[7]) || fifo_data_rd_disable) & (~wr_result_rd_rst_busy[7]) & wr_data_meet_border & wr_data_enable)
				wr_nstate = WR_IDLE;
			else
				wr_nstate = WR_DATA;
		default:
			wr_nstate = WR_IDLE;
	endcase
end

assign	wr_instr_rd_enable = (wr_cstate == WR_INSTR);
assign	wr_data_enable = (wr_cstate == WR_DATA) & ((~result_fifo_empty[7]) || fifo_data_rd_disable) & (~wr_result_rd_rst_busy[7]) 
                         & (store_wr_instr[31] & (~(in_data_lock[0] & (~store_wr_instr[26]) || in_data_lock[1] & store_wr_instr[26])) || 
                            (~store_wr_instr[31]) & (~iResult_forward_to_ddr_stop));
always @(posedge clk) begin
    if(rst)
        wr_data_lock <= 2'b0;
    else begin
        if(((~result_fifo_empty[7]) || fifo_data_rd_disable) & (~wr_result_rd_rst_busy[7]) & wr_data_meet_border & wr_data_enable & store_wr_instr[31] & (~store_wr_instr[26]) )
            wr_data_lock[0] <= 1'b0;
        else if(wr_data_enable & store_wr_instr[31] & (~store_wr_instr[26]))
            wr_data_lock[0] <= 1'b1;

        if(((~result_fifo_empty[7]) || fifo_data_rd_disable) & (~wr_result_rd_rst_busy[7]) & wr_data_meet_border & wr_data_enable & store_wr_instr[31] & store_wr_instr[26])
            wr_data_lock[1] <= 1'b0;
        else if(wr_data_enable & store_wr_instr[31] & store_wr_instr[26])
            wr_data_lock[1] <= 1'b1;

    end

end


always @(posedge clk)
	wr_data_enable_dly <= wr_data_enable;

always @(posedge clk)
	wr_instr_data_valid <= wr_instr_rd_enable;

always @(posedge clk)
	if(wr_instr_data_valid)
		store_wr_instr <= wr_instr_data;

always @(posedge clk) begin 
    if (rst)
        wr_sublen_count <= 2'd0;
    else if (wr_data_enable & store_wr_instr[31] & (~store_wr_instr[32])) begin 
        if (wr_sublen_count_meet_border)
            wr_sublen_count <= 2'd0;
        else 
            wr_sublen_count <= wr_sublen_count + 1; 
    end
end 

assign wr_sublen_count_meet_border = wr_sublen_count == store_wr_instr[34:33];

always @(posedge clk)
	if(rst)
		wr_count <= 11'd0;
	else if(wr_data_enable & wr_sublen_count_meet_border & store_wr_instr[31] & (~store_wr_instr[32])) begin
		if(wr_data_meet_border)
			wr_count <= 11'd0;
		else
			wr_count <= wr_count + store_wr_instr[30:27];
	end

always @(posedge clk)
    if(rst)
        wr_count_len <= 10'd0;
    else if(wr_data_enable) begin
        if(wr_data_meet_border)
            wr_count_len <= 10'd0;
        else
            wr_count_len <= wr_count_len + 1;
    end




// for 512 datawidth
assign  wr_len_tmp = store_wr_instr[9:0] + 1;
assign  fifo_data_rd_disable = wr_data_meet_border & wr_len_tmp[2] & (~store_wr_instr[31]);
assign	wr_data_meet_border = wr_count_len == (store_wr_instr[31] ? store_wr_instr[9:0] : ((wr_len_tmp >> 2) + wr_len_tmp[2] - 1));
// for 256 datawidth
//assign  fifo_data_rd_disable = 1'b0;
//assign  wr_data_meet_border = (wr_count_len == (store_wr_instr[31] ? store_wr_instr[9:0] : (store_wr_instr[9:0]>>2)));
//

always @(posedge clk) begin
	wr_data_valid <= wr_data_enable & store_wr_instr[31] & (~store_wr_instr[32]);
	wr_addr <= wr_sublen_count + wr_count + store_wr_instr[26:10];
end

assign	oResult_forward_to_ddr = wr_data;
assign	oResult_forward_to_ddr_valid = wr_data_enable_dly & (~store_wr_instr[31]); // please check store_wr_instr[31]
assign	oResult_forward_to_ddr_is_final = store_wr_instr[32];

//==========
// for data from outchip channel
//==========
wire    port_is_lock;
wire    [1:0]   is_deadlock;  // to avoid deadlock;
reg     [1:0]   two_clockcycle_idle;
reg     [1:0]   sub_block_count;
wire            sub_block_count_meet_border;
reg     [15:0]  sub_block_addr;
assign  port_is_lock = wr_data_lock[0] & (~iWr_data_block_startaddr[16]) || wr_data_lock[1] & iWr_data_block_startaddr[16];

assign	in_data_count_valid = (~(iWr_syn_config_sel ^ oWr_config_sel)) & iWr_config_valid & (~(&wr_status)) & (two_clockcycle_idle == 2'b0) & 
                              (~port_is_lock) &((~iData_stop) & iWr_is_data_from_offchip || (~iWr_is_data_from_offchip));
assign	oData_read = in_data_count_valid & iWr_is_data_from_offchip & (|in_data_lock);

assign  is_deadlock = wr_data_lock & in_data_lock;
/*
// for debug 
reg [31:0]  in_data_count_dbg;

always @(posedge clk)
    if(rst)
        in_data_count_dbg <= 0;
    else if(iData_valid)
        in_data_count_dbg <= in_data_count_dbg + 1;

ila_onchip_buf ila_onchip_buf_inst(
