reg		[255:0]		rd_data_q,rd_data_p;
reg					rd_data_q_valid,rd_data_p_valid;
reg		[2:0]		rd_data_sel;

always @(posedge clk) begin : dly
	integer i,j,z;
	rd_data_organization_dly[0] <= iRd_data_organization;
	pad_flag_dly[0] <= iPad_flag;
	rd_data_sel_dly[0] <= iRd_data_addr[2:0];
	is_first_layer_specific_dly[0] <= iS_First_layer_specific;
	specific_mode_dly[0] <= iSpecific_mode;
	input_specific_clear_dly[0] <= iInput_Specific_clear;

	for(i=1;i<URAM_LATENCY+3;i=i+1) begin

		pad_flag_dly[i] <= pad_flag_dly[i-1];
		rd_data_sel_dly[i] <= rd_data_sel_dly[i-1];
	end

	for(j=1;j<URAM_LATENCY+13;j=j+1) begin

		is_first_layer_specific_dly[j] <= is_first_layer_specific_dly[j-1];
		specific_mode_dly[j] <= specific_mode_dly[j-1];

	end


	for(z=1;z<URAM_LATENCY+5;z=z+1) begin
	   input_specific_clear_dly[z] <= input_specific_clear_dly[z-1];
	   rd_data_organization_dly[z] <= rd_data_organization_dly[z-1];
	end
end

always @(posedge clk) begin
	rd_channel_p_valid <= iRd_data_enable & (~iRd_data_sel);
	rd_channel_p_addr <= iRd_data_addr[15:0] >> rd_data_organization_dly[5];//iRd_data_organization;

	rd_channel_q_valid <= iRd_data_enable & iRd_data_sel;
	rd_channel_q_addr <= iRd_data_addr[15:0] >> rd_data_organization_dly[5]; //iRd_data_organization;
end

always @(posedge clk) begin
	case(rd_data_organization_dly[URAM_LATENCY])
		2'd3:	// 4
			case(rd_data_sel_dly[URAM_LATENCY])
				3'd0: rd_data_p <= {8{rd_channel_p_data[31:0]}};
				3'd1: rd_data_p <= {8{rd_channel_p_data[63:32]}};
				3'd2: rd_data_p <= {8{rd_channel_p_data[95:64]}};
				3'd3: rd_data_p <= {8{rd_channel_p_data[127:96]}};
				3'd4: rd_data_p <= {8{rd_channel_p_data[159:128]}};
				3'd5: rd_data_p <= {8{rd_channel_p_data[191:160]}};
				3'd6: rd_data_p <= {8{rd_channel_p_data[223:192]}};
				3'd7: rd_data_p <= {8{rd_channel_p_data[255:224]}};
			endcase
		2'd2:   // 8
			case(rd_data_sel_dly[URAM_LATENCY][1:0])
				2'd0: rd_data_p <= {4{rd_channel_p_data[63:0]}};
				2'd1: rd_data_p <= {4{rd_channel_p_data[127:64]}};
				2'd2: rd_data_p <= {4{rd_channel_p_data[191:128]}};
				2'd3: rd_data_p <= {4{rd_channel_p_data[255:192]}};
			endcase
		2'd1:   // 16
			case(rd_data_sel_dly[URAM_LATENCY][0])
				1'b0: rd_data_p <= {2{rd_channel_p_data[127:0]}};
				1'b1: rd_data_p <= {2{rd_channel_p_data[255:128]}};
			endcase
		2'd0: rd_data_p <= rd_channel_p_data;
	endcase

	case(rd_data_organization_dly[URAM_LATENCY])
		2'd3:	
			case(rd_data_sel_dly[URAM_LATENCY])
				3'd0: rd_data_q <= {8{rd_channel_q_data[31:0]}}; // 4 data
				3'd1: rd_data_q <= {8{rd_channel_q_data[63:32]}};
				3'd2: rd_data_q <= {8{rd_channel_q_data[95:64]}};
				3'd3: rd_data_q <= {8{rd_channel_q_data[127:96]}};
				3'd4: rd_data_q <= {8{rd_channel_q_data[159:128]}};
				3'd5: rd_data_q <= {8{rd_channel_q_data[191:160]}};
				3'd6: rd_data_q <= {8{rd_channel_q_data[223:192]}};
				3'd7: rd_data_q <= {8{rd_channel_q_data[255:224]}};
			endcase
		2'd2:
			case(rd_data_sel_dly[URAM_LATENCY][1:0])
				2'd0: rd_data_q <= {4{rd_channel_q_data[63:0]}}; // 8 data
				2'd1: rd_data_q <= {4{rd_channel_q_data[127:64]}};
				2'd2: rd_data_q <= {4{rd_channel_q_data[191:128]}};
				2'd3: rd_data_q <= {4{rd_channel_q_data[255:192]}};
			endcase
		2'd1:
			case(rd_data_sel_dly[URAM_LATENCY][0])
				1'b0: rd_data_q <= {2{rd_channel_q_data[127:0]}}; // 16 data
				1'b1: rd_data_q <= {2{rd_channel_q_data[255:128]}};
			endcase
		2'd0: rd_data_q <= rd_channel_q_data; // 32 data
	endcase

	rd_data_p_valid <= rd_channel_p_o_valid;
	rd_data_q_valid <= rd_channel_q_o_valid;

	rd_data <= pad_flag_dly[URAM_LATENCY+1] ? 'b0 : (rd_data_q_valid ? rd_data_q : rd_data_p);
	rd_data_valid <= rd_data_q_valid | rd_data_p_valid;
end

