		if(input_specific_clear_dly[URAM_LATENCY+2])
			rd_data_valid_count <= 2'd0;
		else
			rd_data_valid_count <= rd_data_valid_count+1;

always @(posedge clk)
	store_valid <= input_specific_clear_dly[URAM_LATENCY+2] & rd_data_valid ;

always @(posedge clk) begin
/*
	rd_data_store[0][127:0] <= rd_data_organization_dly[URAM_LATENCY+2] == 2'd1 && rd_data_sel_dly[URAM_LATENCY+2] == 2'd0 && rd_data_valid ? rd_data[127:0] : 
									(rd_data_valid_count == 2'd0) && rd_data_valid ? rd_data[127:0] : rd_data_store[0][127:0];
	rd_data_store[0][255:128] <= rd_data_organization_dly[URAM_LATENCY+2] == 2'd1 && rd_data_sel_dly[URAM_LATENCY+2] == 2'd1 && rd_data_valid ? rd_data[127:0] :
									(rd_data_valid_count == 2'd0) && rd_data_valid ? rd_data[255:128] : rd_data_store[0][255:128];
*/
    if(rd_data_organization_dly[URAM_LATENCY+2] == 2'd1 && (rd_data_valid_count == 2'd0) && rd_data_valid)
        case(rd_data_sel_dly[URAM_LATENCY+2][0])
            1'b0 : rd_data_store[0][127:0] <= rd_data[127:0];
            1'b1 : rd_data_store[0][127:0] <= rd_data[255:128];
        endcase
    else if(rd_data_organization_dly[URAM_LATENCY+2] != 2'd1 && (rd_data_valid_count == 2'd0) && rd_data_valid)
        rd_data_store[0][127:0] <= rd_data[127:0];

    if(rd_data_organization_dly[URAM_LATENCY+2] == 2'd1 && (rd_data_valid_count == 2'd1) && rd_data_valid)
        case(rd_data_sel_dly[URAM_LATENCY+2][0])
            1'b0 : rd_data_store[0][255:128] <= rd_data[127:0];
            1'b1 : rd_data_store[0][255:128] <= rd_data[255:128];
        endcase
    else if(rd_data_organization_dly[URAM_LATENCY+2] != 2'd1 && (rd_data_valid_count == 2'd0) && rd_data_valid)
        rd_data_store[0][255:128] <= rd_data[255:128];

	rd_data_store[1] <= (rd_data_valid_count == 2'd1) && rd_data_valid ? rd_data : rd_data_store[1];
	rd_data_store[2] <= (rd_data_valid_count == 2'd2) && rd_data_valid ? rd_data : rd_data_store[2];

	//
	if(store_valid) begin
		rd_data_store_for_shift[0] <= rd_data_store[0];
		rd_data_store_for_shift[1] <= rd_data_store[1];
		rd_data_store_for_shift[2] <= rd_data_store[2];
	end else if(shift_flag) begin
		case(specific_mode_dly[URAM_LATENCY+3])
			2'd0:	{rd_data_store_for_shift[0],rd_data_store_for_shift[1],rd_data_store_for_shift[2]} <=
						{rd_data_store_for_shift[0][255:128],rd_data_store_for_shift[1],rd_data_store_for_shift[2],128'b0};
			2'd1:	{rd_data_store_for_shift[1],rd_data_store_for_shift[0]} <=
						{128'b0,rd_data_store_for_shift[1],rd_data_store_for_shift[0][255:128]};
			default:
					{rd_data_store_for_shift[0],rd_data_store_for_shift[1],rd_data_store_for_shift[2]} <= 
						{rd_data_store_for_shift[0],rd_data_store_for_shift[1],rd_data_store_for_shift[2]};
		endcase
	end
end

always @(posedge clk)
	if(rst)
		shift_count <= 2'd0;
	else if(shift_flag) begin
		case(specific_mode_dly[URAM_LATENCY+11])
			2'd0: // 11/4
				if(shift_count == 2'd2)
					shift_count <= 2'd0;
				else
					shift_count <= shift_count + 1;
			2'd1: // 7/2 or 5/2
				if(shift_count == 2'd1)
					shift_count <= 2'd0;
				else
					shift_count <= shift_count + 1;
			2'd2: // 3/2
				if(shift_count == 2'd1)
					shift_count <= 2'd0;
				else
					shift_count <= shift_count + 1;
			2'd3: // 3/1
				if(shift_count == 2'd1)
					shift_count <= 2'd0;
				else
					shift_count <= shift_count + 1;
		endcase
	end


always @(posedge clk)
	if(rst)
		shift_flag <= 1'b0;
	else if(store_valid & is_first_layer_specific_dly[URAM_LATENCY+8])
		shift_flag <= 1'b1;
	else if((specific_mode_dly[URAM_LATENCY+11] == 2'd0) & (shift_count == 2'd2) ||
			(specific_mode_dly[URAM_LATENCY+11] == 2'd1) & (shift_count == 2'd1) ||
			(specific_mode_dly[URAM_LATENCY+11] == 2'd2) & (shift_count == 2'd1) ||
			(specific_mode_dly[URAM_LATENCY+11] == 2'd3) & (shift_count == 2'd1) )
		shift_flag <= 1'b0;


always @(posedge clk)
	shift_flag_dly <= shift_flag;

always @(posedge clk)
	case(specific_mode_dly[URAM_LATENCY+3])
		2'd0:
			begin
				specific_out_data[255:0] <= rd_data_store_for_shift[0];
				specific_out_data[511:256] <= rd_data_store_for_shift[1];
			end
		2'd1:
			begin
				specific_out_data[127:0] <= rd_data_store_for_shift[0][127:0];
				specific_out_data[255:128] <= rd_data_store_for_shift[0][191:64];
				specific_out_data[383:256] <= rd_data_store_for_shift[0][255:128];
				specific_out_data[511:384] <= {rd_data_store_for_shift[1][63:0],rd_data_store_for_shift[0][255:192]};
			end
		2'd2:
			begin
				specific_out_data[127:0] <= rd_data_store_for_shift[0][127:0];
				specific_out_data[255:128] <= rd_data_store_for_shift[0][191:64];
				specific_out_data[383:256] <= rd_data_store_for_shift[0][255:128];
				specific_out_data[511:384] <= {rd_data_store_for_shift[1][63:0],rd_data_store_for_shift[0][255:192]};
			end
		2'd3:
			begin
				specific_out_data[127:0] <= rd_data_store_for_shift[0][127:0];
				specific_out_data[255:128] <= rd_data_store_for_shift[0][159:32];
				specific_out_data[383:256] <= rd_data_store_for_shift[0][191:64];
				specific_out_data[511:384] <= rd_data_store_for_shift[0][223:96];
			end
	endcase
// unspecific layer latency alignment
always @(posedge clk) begin
    rd_data_dly[0] <= rd_data;
    rd_data_dly[1] <= rd_data_dly[0];
    rd_data_dly[2] <= rd_data_dly[1];
