module output_ring_buffer_rd_ctr(
			// global signals
            input                clk,
            input                rst,
            // configuration signals
            input    [11:0]      iLength,
            input    [11:0]      iRead_start_addr,
            input    [1:0]       iResult_buffer_status,
            input                iBuffer_rdport_lock,
			input				 iPooling_enable,
			input				 iDeconv_enable_with_stride_neq_1,
			input	 [1:0]		 iPooling_im_num,
			input	 [3:0]		 iPooling_kernel_size,
			input	 [1:0]		 iPooling_kernel_stride,
			input	 [2:0]		 iPooling_pad_size,
			input	 [9:0]		 iPooling_block_col,
			input	 [9:0]		 iPooling_omap_col,
			input	 [9:0]		 iPooling_omap_row,
			input	 [9:0]		 iPooling_row_start,
			input	 [9:0]		 iPooling_row_end,
			input	 [9:0]		 iPooling_col_start,
			input	 [9:0]		 iPooling_col_end,
			input                iUp_sampling_enable,
			input                iRep_read_enable,
            //
            input                iConfig_valid,
            output    [1:0]      oResult_buffer_clear,
            output    reg        oConfig_data_sel,
            output    [1:0]      oConfig_status_clear,

            input                iStop_from_io,
            output               oStop_to_rd_ctr,

            output               oIS_data_for_io,
            output               oIS_data_for_pooling,
            output               oLast_data_block_proposal,

            output    [11:0]     oPre_data_block_start_addr,
            output               oPre_data_block_is_pooling,
            //
            output    [11:0]	 oRd_data_addr,
			output				 oRd_data_pad_flag,
			output				 oRd_pooling_clear,
            output				 oRd_data_valid
        );

reg        [11:0]   len_count;
wire                len_count_meet_border;

wire                count_valid;
reg                 pingpong_buf_sel;
wire                finish_one_block;
reg                 finish_one_block_dly;

// for pooling
reg     [9:0]   pooling_block_col_dly;
reg		[1:0]	im_num_count;
reg		[1:0]	im_num_count_dly1,im_num_count_dly2;
reg		[11:0]	data_block_start_addr_dly1,data_block_start_addr_dly2;

reg		[1:0]	im_num_dly1,im_num_dly2;
wire			im_num_count_meet_border;

reg		[3:0]	kernel_col_count;
wire			kernel_col_count_meet_border;

reg		[3:0]	kernel_row_count;
wire			kernel_row_count_meet_border;

reg		[9:0]	col_count;
wire			col_count_meet_border;

reg		[9:0]	row_count;
wire			row_count_meet_border;

wire            rep_valid;
reg             rep_count;
wire            rep_count_meet_border;

reg     [11:0]  gen_addr_1_p1;
reg     [4:0]   gen_addr_1_p2;
wire	[16:0]	gen_addr_1;
reg     [11:0]  gen_addr_2_p1;
reg     [4:0]   gen_addr_2_p2;
wire	[16:0]	gen_addr_2;
wire    [16:0]  gen_addr_p1;
reg     [11:0]  gen_addr_p2;

reg		[11:0]	gen_addr;
reg		[9:0]	pad_mask_1;
reg		[9:0]	pad_mask_2;
reg				pad_mask;
reg             pad_mask_dly1,pad_mask_dly2;

reg		[9:0]	row_start;
reg		[9:0]	row_end;
reg		[9:0]	col_start;
reg		[9:0]	col_end;

wire			kernel_col_valid;
wire			kernel_row_valid;
wire			col_valid;
wire			row_valid;

reg             work_flag;
//


reg	[11:0]	rd_data_addr;
reg	[11:0]	rd_data_addr_dly[2:0];
reg			count_valid_dly1,count_valid_dly2,count_valid_dly3,count_valid_dly4;
reg			pooling_enable_dly1, pooling_enable_dly2,pooling_enable_dly3,pooling_enable_dly4;
reg			pooling_clear_dly1, pooling_clear_dly2,pooling_clear_dly3,pooling_clear_dly4;
reg         up_sampling_enable_dly1, up_sampling_enable_dly2,up_sampling_enable_dly3,up_sampling_enable_dly4;

reg [1:0]   rdport_validation = 1'b0;

reg         protect_region_flag;
wire        protect_region_count_meet_border;
reg  [2:0]  protect_region_count;

//
always @(posedge clk)
    if(rst)
        oConfig_data_sel <= 1'b0;
    else if(finish_one_block)
        oConfig_data_sel <= ~oConfig_data_sel;

assign    oConfig_status_clear[0] = (~oConfig_data_sel) & finish_one_block;
assign    oConfig_status_clear[1] = oConfig_data_sel & finish_one_block;

always @(posedge clk)
    if(rst)
        pingpong_buf_sel <= 1'b0;
    else if(finish_one_block)
        pingpong_buf_sel <= ~pingpong_buf_sel;

always @(posedge clk)
    if(rst)
        rdport_validation <= 2'b0;
    else begin
        case(rdport_validation)
            2'b0: // check rdport allocation enable
                if((pingpong_buf_sel & iResult_buffer_status[1] & (~iStop_from_io) ||
                   (~pingpong_buf_sel) & iResult_buffer_status[0] & (~iStop_from_io)) & 
                   iConfig_valid & (~iBuffer_rdport_lock) & (~protect_region_flag))
                    rdport_validation <= 2'b01;
                else
                    rdport_validation <= 2'b00;
            2'b01: // is rdport occupied by input_buffer_rd_ctr unit
                if(iBuffer_rdport_lock) // yes, disable allocation process
                    rdport_validation <= 2'b0;
                else  //no, occupy the rdport
                    rdport_validation <= 2'b10;
            2'b10:
                rdport_validation <= 2'b11;
            2'b11:
                if(finish_one_block) // release rdport
                    rdport_validation <= 2'b0;
                else
                    rdport_validation <= 2'b11;
            default: rdport_validation <= 2'b0;
        endcase
    end

assign    count_valid = (pingpong_buf_sel & iResult_buffer_status[1] & (~iStop_from_io) ||
                        (~pingpong_buf_sel) & iResult_buffer_status[0] & (~iStop_from_io)) & 
                        iConfig_valid & (rdport_validation == 2'b11) & (~protect_region_flag);
/*
`ifdef DEBUG

reg     [31:0]  finish_block_count;
reg     [31:0]  count;

always @(posedge clk)
    if(rst)
        finish_block_count <= 0;
    else if(finish_one_block)
        finish_block_count <= finish_block_count + 1;

always @(posedge clk)
    if(rst)
        count <= 0;
    else if(count_valid)        
        count <= count + 1;

ila_output_ring_buf_rd_ctr ila_output_ring_buf_rdctr_isnt (
    .clk(clk),
    .probe0(pingpong_buf_sel), // 1
    .probe1(iResult_buffer_status), // 2
    .probe2(iStop_from_io), // 1
    .probe3(iConfig_valid), // 1
    .probe4(finish_one_block), //1
    .probe5(finish_block_count), // 32
    .probe6(count) // 32
);


`endif
*/
always @(posedge clk)
    work_flag <= count_valid & (~iPooling_enable);

assign  oStop_to_rd_ctr =  rdport_validation != 0;

always @(posedge clk)
    if(rst)
        len_count <= 12'd0;
    else if(count_valid & (~iPooling_enable) & (~iDeconv_enable_with_stride_neq_1) & (~iUp_sampling_enable)) begin
        if(len_count_meet_border)
            len_count <= 12'd0;
        else
            len_count <= len_count + 1'b1;
    end

assign    len_count_meet_border = (len_count == iLength);


assign    finish_one_block = (len_count_meet_border & count_valid & (~iPooling_enable) & (~iDeconv_enable_with_stride_neq_1) & (~iUp_sampling_enable) ||
							 im_num_count_meet_border & kernel_col_count_meet_border & count_valid &
							 kernel_row_count_meet_border & col_count_meet_border & row_count_meet_border) & (iRep_read_enable & rep_count_meet_border || (~iRep_read_enable));


always @(posedge clk)
    if(rst)
        protect_region_flag <= 1'b0;
    else if(finish_one_block & count_valid & iPooling_enable)
        protect_region_flag <= 1'b1;
    else if(protect_region_count_meet_border)
        protect_region_flag <= 1'b0;

always @(posedge clk)
    if(rst)
        protect_region_count <= 0;
    else if(protect_region_flag) begin
        if(protect_region_count_meet_border)
            protect_region_count <= 0;
        else
            protect_region_count <= protect_region_count + 1;
    end
assign  protect_region_count_meet_border = protect_region_count == 3'd6;

always @(posedge clk)
	if(rst)
		im_num_count <= 2'd0;
	else if(iPooling_enable & count_valid || iDeconv_enable_with_stride_neq_1 & count_valid || iUp_sampling_enable & count_valid) begin
		if(im_num_count_meet_border)
			im_num_count <= 2'd0;
		else
			im_num_count <= im_num_count + 1;
	end

assign	im_num_count_meet_border = (im_num_count == (iPooling_im_num-1));

assign	kernel_col_valid = iPooling_enable & count_valid & im_num_count_meet_border ||
						   (~iPooling_enable) & iDeconv_enable_with_stride_neq_1 & count_valid & im_num_count_meet_border || 
						   (~iPooling_enable) & (~iDeconv_enable_with_stride_neq_1) & iUp_sampling_enable & count_valid & im_num_count_meet_border;


always @(posedge clk)
	if(rst)
		kernel_col_count <= 4'd0;
	else if(kernel_col_valid) begin
		if(kernel_col_count_meet_border)
			kernel_col_count <= 4'd0;
		else
			kernel_col_count <= kernel_col_count + 1;
	end

assign	kernel_col_count_meet_border = (kernel_col_count == iPooling_kernel_size);

assign	kernel_row_valid = (iPooling_enable & count_valid & im_num_count_meet_border &
						    kernel_col_count_meet_border) || ((~iPooling_enable) & 
							iDeconv_enable_with_stride_neq_1 & count_valid & im_num_count_meet_border &
							kernel_col_count_meet_border & col_count_meet_border) || ((~iPooling_enable) & 
							(~iDeconv_enable_with_stride_neq_1) & iUp_sampling_enable & count_valid & im_num_count_meet_border &
							kernel_col_count_meet_border & col_count_meet_border);

always @(posedge clk)
	if(rst)
		kernel_row_count <= 4'd0;
	else if(kernel_row_valid) begin
		if(kernel_row_count_meet_border)
			kernel_row_count <= 4'd0;
		else
			kernel_row_count <= kernel_row_count + 1;
	end

assign	kernel_row_count_meet_border = (kernel_row_count == iPooling_kernel_size);

assign	col_valid = iPooling_enable & count_valid & im_num_count_meet_border & 
					kernel_col_count_meet_border & kernel_row_count_meet_border ||
					(~iPooling_enable) & iDeconv_enable_with_stride_neq_1 & count_valid & im_num_count_meet_border &
					kernel_col_count_meet_border || (~iPooling_enable) & (~iDeconv_enable_with_stride_neq_1) & 
					iUp_sampling_enable & count_valid & im_num_count_meet_border & kernel_col_count_meet_border;

always @(posedge clk)
	if(rst)
		col_count <= 10'd0;
	else if(col_valid) begin
		if(col_count_meet_border)
			col_count <= 10'd0;
		else
			col_count <= col_count + 1;
	end

assign	col_count_meet_border = (col_count == iPooling_omap_col);

assign	row_valid = (iPooling_enable & count_valid & im_num_count_meet_border &
					 kernel_col_count_meet_border & kernel_row_count_meet_border &
					 col_count_meet_border) || ((~iPooling_enable) & 
					 iDeconv_enable_with_stride_neq_1 & count_valid & im_num_count_meet_border &
					 kernel_col_count_meet_border & col_count_meet_border & 
					 kernel_row_count_meet_border) || ((~iPooling_enable) & 
					 (~iDeconv_enable_with_stride_neq_1) & iUp_sampling_enable & count_valid & im_num_count_meet_border &
					 kernel_col_count_meet_border & col_count_meet_border & 
					 kernel_row_count_meet_border);

always @(posedge clk)
	if(rst)
		row_count <= 10'd0;
	else if(row_valid) begin
		if(row_count_meet_border)
			row_count <= 10'd0;
		else
			row_count <= row_count + 1;
	end

assign	row_count_meet_border = (row_count == iPooling_omap_row);

assign  rep_valid = (iPooling_enable & count_valid & im_num_count_meet_border &
					 kernel_col_count_meet_border & kernel_row_count_meet_border &
					 col_count_meet_border & row_count_meet_border) || 
					 ((~iPooling_enable) & iDeconv_enable_with_stride_neq_1 & count_valid &  im_num_count_meet_border &
					 kernel_col_count_meet_border & col_count_meet_border & row_count_meet_border &
					 kernel_row_count_meet_border) || 
					 ((~iPooling_enable) & (~iDeconv_enable_with_stride_neq_1) & iUp_sampling_enable & count_valid & im_num_count_meet_border &
					 kernel_col_count_meet_border & col_count_meet_border & row_count_meet_border &
					 kernel_row_count_meet_border) ||
					 len_count_meet_border & count_valid & (~iPooling_enable) & (~iDeconv_enable_with_stride_neq_1) & (~iUp_sampling_enable);

always @(posedge clk)
    if(rst)
        rep_count <= 0;
    else if(rep_valid & iRep_read_enable)
        rep_count <= ~rep_count;

assign  rep_count_meet_border = rep_count == 1'b1;

always @(posedge clk) begin
    pooling_block_col_dly <= iPooling_block_col;
	im_num_dly1 <= iPooling_im_num;
	im_num_dly2 <= im_num_dly1;
	im_num_count_dly1<= im_num_count;
	im_num_count_dly2 <=im_num_count_dly1;
	data_block_start_addr_dly1 <= iRead_start_addr;
	data_block_start_addr_dly2 <= data_block_start_addr_dly1;
	row_start <= iPooling_row_start;
	row_end <= iPooling_row_end;
	col_start <= iPooling_col_start;
	col_end <= iPooling_col_end;
end

wire    [11:0]  gen_addr_1_p1p2_sum;
wire    [11:0]  gen_addr_2_p1p2_sum;

addr_mult_0 mult_0 (
    .CLK(clk),
    .A({{2{gen_addr_1_p1p2_sum[11]}},gen_addr_1_p1p2_sum}),
    .B(pooling_block_col_dly),
    .P(gen_addr_1)
);
addr_mult_1 mult_1 (
    .CLK(clk),
    .A({{2{gen_addr_2_p1p2_sum[11]}},gen_addr_2_p1p2_sum}),
    .B({4'b0,im_num_dly1}),
    .P(gen_addr_2)
);
addr_mult_1 mult_2 (
    .CLK(clk),
    .A(gen_addr_1[13:0]),
    .B({4'b0,im_num_dly2}),
    .P(gen_addr_p1)
);

assign  gen_addr_1_p1p2_sum = gen_addr_1_p1 + {{7{gen_addr_1_p2[4]}},gen_addr_1_p2};
assign  gen_addr_2_p1p2_sum = gen_addr_2_p1 + {{7{gen_addr_2_p2[4]}},gen_addr_2_p2};

always @(posedge clk) begin
	begin
	    gen_addr_1_p1 <= row_count*iPooling_kernel_stride;
	    gen_addr_1_p2 <= iUp_sampling_enable ? 5'b0 : ({1'b0,kernel_row_count} - iPooling_pad_size);
		//gen_addr_1 <= (gen_addr_1_p1 + gen_addr_1_p2)*pooling_block_col_dly;
		gen_addr_2_p1 <= col_count*iPooling_kernel_stride;
		gen_addr_2_p2 <= iUp_sampling_enable ? 5'b0 : {1'b0,kernel_col_count} - iPooling_pad_size;
		//gen_addr_2 <= (gen_addr_2_p1 + gen_addr_2_p2)*im_num_dly1;
		//gen_addr_p1 <= gen_addr_1*im_num_dly2;
		gen_addr_p2 <= gen_addr_2[11:0] + im_num_count_dly2 + data_block_start_addr_dly2;
		gen_addr <= gen_addr_p1[11:0] + gen_addr_p2;
	end

	pad_mask_1 <= row_count * iPooling_kernel_stride + kernel_row_count;
	pad_mask_2 <= col_count * iPooling_kernel_stride + kernel_col_count;

	if(pooling_enable_dly1 & (~((pad_mask_1 >= row_start) && (pad_mask_1 <= row_end) 
	   && (pad_mask_2 >= col_start) && (pad_mask_2 <= col_end))))
		pad_mask <= 1'b1;
	else
		pad_mask <= 1'b0;

    pad_mask_dly1 <= pad_mask;
    pad_mask_dly2 <= pad_mask_dly1;
end


assign    oResult_buffer_clear[0] = (~pingpong_buf_sel) & finish_one_block;
assign    oResult_buffer_clear[1] = pingpong_buf_sel & finish_one_block;

//


always @(posedge clk) begin
	count_valid_dly1 <= count_valid;
	count_valid_dly2 <= count_valid_dly1;
	count_valid_dly3 <= count_valid_dly2;
	count_valid_dly4 <= count_valid_dly3;
	rd_data_addr_dly[0] <= rd_data_addr;
	rd_data_addr_dly[1] <= rd_data_addr_dly[0];
	rd_data_addr_dly[2] <= rd_data_addr_dly[1];
	pooling_enable_dly1 <= iPooling_enable;
	pooling_enable_dly2 <= pooling_enable_dly1;
	pooling_enable_dly3 <= pooling_enable_dly2;
	pooling_enable_dly4 <= pooling_enable_dly3;
	pooling_clear_dly1 <= iPooling_enable & count_valid & im_num_count_meet_border & 
						  kernel_col_count_meet_border & kernel_row_count_meet_border;
	pooling_clear_dly2 <= pooling_clear_dly1;
	pooling_clear_dly3 <= pooling_clear_dly2;
	pooling_clear_dly4 <= pooling_clear_dly3;

	up_sampling_enable_dly1 <= iUp_sampling_enable;
	up_sampling_enable_dly2 <= up_sampling_enable_dly1;
	up_sampling_enable_dly3 <= up_sampling_enable_dly2;
	up_sampling_enable_dly4 <= up_sampling_enable_dly3;
end

always @(posedge clk) begin
    rd_data_addr <= len_count + iRead_start_addr;
end

assign	oRd_data_addr = ((~pooling_enable_dly4) & (~up_sampling_enable_dly4)) ? rd_data_addr_dly[2] : gen_addr;
assign	oRd_data_pad_flag = up_sampling_enable_dly4 ? 1'b0 : pad_mask_dly2;
assign	oRd_data_valid = count_valid_dly4;
assign	oRd_pooling_clear = pooling_clear_dly4;


assign  oIS_data_for_io = ((~pooling_enable_dly4) || up_sampling_enable_dly4) & oRd_data_valid;
assign  oIS_data_for_pooling = pooling_enable_dly4 & oRd_data_valid;

// for last data block detection
always @(posedge clk)
    finish_one_block_dly <= finish_one_block;

assign  oLast_data_block_proposal = finish_one_block_dly & (iResult_buffer_status == 2'b00);

assign  oPre_data_block_start_addr = iRead_start_addr;
assign  oPre_data_block_is_pooling = iPooling_enable & count_valid;
endmodule

