`include "fucore.vh"
module output_ring_buffer_wr_ctr (
            // global signals
				input				clk,
				input				rst,
				input				iInstruction_finish,
			// configuration signals
				input				iS_intermediate_result,
				input	[11:0]		iData_block_length,
				input				iData_valid,
			//
				input   [11:0]      iRd_data_addr,
				input               iStop_from_io,

				output				oIntermediate_write_area,
				output	[11:0]		oIntermediate_read_start_addr,
				output	[1:0]		oPingpong_buffer_status,
				input	[1:0]		iData_buffer_clear,
				output	reg			oConfig_data_sel,
				output	[1:0]		oConfig_status_clear,
				input   [11:0]      iPre_data_block_start_addr,
				input               iPre_data_block_is_pooling,
				output				oStop_to_input,
				output	reg [11:0]	oWr_data_addr
		);

reg		[1:0]		buffer_status;
wire	[1:0]		buffer_set;

reg		[11:0]		gen_addr;
reg     [11:0]      pre_add_store;
wire				gen_addr_meet_border;
reg                 pp_buf_flag;

reg				    wr_buf_sel;
reg                 gen_addr_meet_border_dly;
reg                 is_intermediate_result;

reg                 instruction_finish_flag;
reg                 rd_wr_conflict;
reg                 input_protect;

always @(posedge clk)
	if(rst)
		buffer_status <= 2'b0;
	else begin
		if(iData_buffer_clear[0])
			buffer_status[0] <= 1'b0;
		else if(buffer_set[0])
			buffer_status[0] <= 1'b1;

		if(iData_buffer_clear[1])
			buffer_status[1] <= 1'b0;
		else if(buffer_set[1])
			buffer_status[1] <= 1'b1;
	end
always @(posedge clk)
    if(rst)
        input_protect <= 0;
    else if(gen_addr_meet_border & iData_valid)
        input_protect <= 0;
    else if(iData_valid & (|buffer_status) & (~iS_intermediate_result))
        input_protect <= 1;

assign	buffer_set[0] = gen_addr_meet_border & iData_valid & (~iS_intermediate_result) & (~pp_buf_flag);
assign	buffer_set[1] = gen_addr_meet_border & iData_valid & (~iS_intermediate_result) & pp_buf_flag;

assign	oStop_to_input = (&buffer_status) || input_protect || rd_wr_conflict;

assign	oPingpong_buffer_status = buffer_status;

always @(posedge clk) begin
	oWr_data_addr <= gen_addr + pre_add_store;
end

always @(posedge clk)
	if(rst)
		gen_addr <= 12'd0;
	else if(iData_valid) begin
	    if(gen_addr_meet_border)
	         gen_addr <= 12'd0;
	    else
			 gen_addr <= gen_addr + 1'b1;
	end

assign	gen_addr_meet_border = (gen_addr == iData_block_length);

always @(posedge clk) begin
    gen_addr_meet_border_dly <= gen_addr_meet_border & iData_valid;
    is_intermediate_result <= iS_intermediate_result;
end

`ifndef SIM
always @(posedge clk)
    if(rst)
        pre_add_store <= 0;
	else if(instruction_finish_flag & (|iData_buffer_clear))
		pre_add_store <= 0;
    else if(gen_addr_meet_border_dly & (~is_intermediate_result))
        pre_add_store <= oWr_data_addr[11:0] + 1;
`else
always @(posedge clk)
    if(rst)
        pre_add_store <= 0;
	else if(instruction_finish_flag & (|iData_buffer_clear))
		pre_add_store <= 0;
    else if(gen_addr_meet_border_dly & (~is_intermediate_result))
        pre_add_store <= oWr_data_addr[11:0] + 1;

`endif

always @(posedge clk)
    if(rst)
        pp_buf_flag <= 1'b0;
    else if(iData_valid & gen_addr_meet_border & (~iS_intermediate_result))
        pp_buf_flag <= ~pp_buf_flag;

always @(posedge clk)
	if(rst)
		wr_buf_sel <= 1'b0;
	else if(gen_addr_meet_border & iData_valid & (~iS_intermediate_result))
		wr_buf_sel <= ~wr_buf_sel;

always @(posedge clk)
	if(rst)
		oConfig_data_sel <= 1'b0;
	else if(gen_addr_meet_border & iData_valid)
		oConfig_data_sel <= ~oConfig_data_sel;

always @(posedge clk)
    if(rst)
        instruction_finish_flag <= 1'b0;
    else if(iInstruction_finish)
        instruction_finish_flag <= 1'b1;
    else if(|iData_buffer_clear)
        instruction_finish_flag <= 1'b0;

assign	oConfig_status_clear[0] = gen_addr_meet_border & iData_valid & (~oConfig_data_sel);

assign	oConfig_status_clear[1] = gen_addr_meet_border & iData_valid & oConfig_data_sel;


assign	oIntermediate_write_area = wr_buf_sel;

assign	oIntermediate_read_start_addr = pre_add_store;

reg     [11:0]  addr_abs;
reg     [11:0]  addr_abs_real;

always @(posedge clk) begin
    addr_abs <= (iPre_data_block_start_addr > oWr_data_addr) ? (iPre_data_block_start_addr - oWr_data_addr) : (oWr_data_addr - iPre_data_block_start_addr);
    addr_abs_real <= iRd_data_addr > oWr_data_addr ? (iRd_data_addr - oWr_data_addr) : (oWr_data_addr - iRd_data_addr);
end


always @(posedge clk)
    if(rst)
        rd_wr_conflict <= 1'b0;
    else 
        rd_wr_conflict <= (iPre_data_block_is_pooling & (addr_abs < 11'd64)) || (iStop_from_io & (addr_abs_real < 11'd64));  // 64 should be bigger than the input_to_output latency (52 clock cycles)

endmodule

module	param_buf_wr_ctr (
			// global signals
				input					clk,
				input					rst,
			// configuration signals
				input	[4:0]			iParam_block_length,
				input	[1:0]			iParam_sel,
			//
				input					iParam_valid,
				input	[511:0]			iParam_data,

				/// !!!! changed parameter control mechanisim
				output	[1:0]			oParam_buffer_status,
				output					oParam_load_finish,
				/// !!! end chagned
				input					iParam_buffer_clear,
				output  reg				oParam_wr_valid,
				output	reg [6:0]		oParam_wr_addr,
				output	reg	[5:0]		oParam_id,
				output	reg	[511:0]		oParam_data
		);

reg	[1:0]		buffer_status;
wire			buffer_wr_finish;

reg	[4:0]		gen_addr;
wire			gen_addr_meet_border;
reg	[7:0]		id_count;
wire			id_count_meet_border;

reg             param_valid;

///!!! changed parameter control mechanisim
reg			    param_wr_sel_flag;
reg             param_clear_flag;
reg             param_clear_dly;

reg	[1:0]		real_count_border;
reg				adding_zero_flag;
reg	[7:0]		adding_zero_count;
wire			adding_zero_count_meet_border;

assign  oParam_load_finish = buffer_wr_finish;

//assign  oParam_rd_ppbuf_sel = param_clear_flag;

always @(posedge clk)
	case(iParam_sel)
		2'd0:	real_count_border <= 5'd7;
		2'd1:	real_count_border <= 5'd15;
		2'd2:	real_count_border <= 5'd31;
		default: real_count_border <= 5'd31;
	endcase

always @(posedge clk) begin
    if(rst)
        param_clear_flag <= 1'b0;
    else if(iParam_buffer_clear)
        param_clear_flag <= ~param_clear_flag;
end


always @(posedge clk)
	if(rst)
		gen_addr <= 5'b0;
	else if(iParam_valid) begin
		if(gen_addr_meet_border)
			gen_addr <= 5'd0;
		else 
			gen_addr <= gen_addr + 1'b1;
	end

assign	gen_addr_meet_border = (gen_addr == iParam_block_length);

always @(posedge clk)
	if(rst)
		id_count <= 8'd0;
	else if(iParam_valid & gen_addr_meet_border) begin
		if(id_count_meet_border)
			id_count <= 8'd0;
		else
			id_count <= id_count + 1'b1;
	end

assign	id_count_meet_border = (id_count == 8'd31);
/*
always @(posedge clk)
	if(rst)
		adding_zero_count <= 8'd0;
	else if(iParam_valid & gen_addr_meet_border) begin
		if(adding_zero_count_meet_border)
			adding_zero_count <= 8'd0;
		else
			adding_zero_count <= adding_zero_count + 1;
	end

assign	adding_zero_count_meet_border = (adding_zero_count == real_count_border);

always @(posedge clk)
	if(rst)
		adding_zero_flag <= 1'b0;
	else if(id_count_meet_border & gen_addr_meet_border & (adding_zero_flag || iParam_valid))
	    adding_zero_flag <= 1'b0;
	else if(adding_zero_count_meet_border & iParam_valid & gen_addr_meet_border)
		adding_zero_flag <= 1'b1;
*/
always @(posedge clk)
	if(rst)
		param_wr_sel_flag <= 1'b0;
	else if(iParam_valid & gen_addr_meet_border & id_count_meet_border)
		param_wr_sel_flag <= ~param_wr_sel_flag;

always @(posedge clk)
	if(rst)
		buffer_status <= 2'd0;
	else begin
		if(iParam_buffer_clear & (~param_clear_flag))
			buffer_status[0] <= 1'b0;
		else if(iParam_valid & gen_addr_meet_border & id_count_meet_border & (~param_wr_sel_flag))
			buffer_status[0] <= 1'b1;

		if(iParam_buffer_clear & param_clear_flag)
			buffer_status[1] <= 1'b0;
		else if(iParam_valid & gen_addr_meet_border & id_count_meet_border & param_wr_sel_flag)
			buffer_status[1] <= 1'b1;
	end

assign	buffer_wr_finish = iParam_valid & gen_addr_meet_border & id_count_meet_border;

assign	oParam_buffer_status = buffer_status;

always @(posedge clk)
	{oParam_id,oParam_wr_addr} <= {id_count[6:0],param_wr_sel_flag,gen_addr};

always @(posedge clk) begin
	oParam_data <=  iParam_data;
	oParam_wr_valid <=  iParam_valid;
end

endmodule

