							   iConfig_interconnection == 2'b01 ? 2'b01 : 2'b10;
assign	mux_data_right_3_sel = iConfig_branch_add_enable[2] || iConfig_specific_enable;

assign	mux_data_right_4_sel = (iConfig_branch_add_enable[3] || iConfig_specific_enable) ? 2'b00 :
							   iConfig_interconnection == 2'b01 ? 2'b01 : 2'b10;
assign	mux_data_left_2_sel = (~iConfig_branch_add_enable[4]) && (~iConfig_specific_enable);

assign	mux_data_left_4_sel = iConfig_branch_add_enable[5] || iConfig_specific_enable ? 2'b00 :
							  iConfig_interconnection == 2'b01 ? 2'b01 : 2'b10;

//
assign	#0.5 acc_data_1 = iData_a1 + acc_reg_1;
assign	#0.5 acc_data_2 = iData_a2 + acc_reg_2;
assign	#0.5 acc_data_3 = iData_a3 + acc_reg_3;
assign	#0.5 acc_data_4 = iData_a4 + acc_reg_4;

assign	acc_clear = iAcc_clear | iConfig_branch_add_enable[0];

always @(posedge clk) begin
	if(rst) begin
		acc_reg_1 <= 0;
		acc_reg_2 <= 0;
		acc_reg_3 <= 0;
		acc_reg_4 <= 0;
	end else if(iData_valid) begin
		if(acc_clear)
			acc_reg_1 <= 0;
		else
			acc_reg_1 <= acc_data_1;

		if(acc_clear)
			acc_reg_2 <= 0;
		else
			acc_reg_2 <= acc_data_2;

		if(acc_clear)
			acc_reg_3 <= 0;
		else
			acc_reg_3 <= acc_data_3;

		if(acc_clear)
			acc_reg_4 <= 0;
		else
			acc_reg_4 <= acc_data_4;
	end
end

// data locking to disable data switching.
always @(posedge clk)
	begin
	//begin
		acc_data_1_dly <= acc_data_1;
		acc_data_2_dly <= acc_data_2;
		acc_data_3_dly <= acc_data_3;
		acc_data_4_dly <= acc_data_4;
	end

always @(posedge clk) 
	begin
		data_b1_dly <= {{2{iData_b1[2*`DATAWIDTH+1]}},iData_b1};
		data_b2_dly1 <= {{2{iData_b2[2*`DATAWIDTH+1]}},iData_b2};
		data_b2_dly2 <= data_b2_dly1;
		data_b2_dly3 <= data_b2_dly2;
		data_b3_dly <= {{2{iData_b3[2*`DATAWIDTH+1]}},iData_b3};
		data_b4_dly1 <= {{2{iData_b4[2*`DATAWIDTH+1]}},iData_b4};
		data_b4_dly2 <= data_b4_dly1;
		data_b4_dly3 <= data_b4_dly2;
		data_b4_dly4 <= data_b4_dly3;
		data_b4_dly5 <= data_b4_dly4;
	end

always @(posedge clk) begin : loop
	integer i,j;
		for(i=1;i<4;i=i+1)
			data_valid_dly[i] <= data_valid_dly[i-1];
		for(j=1;j<8;j=j+1)
			acc_clear_dly[j] <= acc_clear_dly[j-1];
		data_valid_dly[0] <= iData_valid;
		acc_clear_dly[0] <= iAcc_clear;
end

always @(posedge clk) begin
	if(iConfig_branch_add_enable[1])
		oResult_valid <= data_valid_dly[2];
	else begin
	    if(iConfig_specific_enable)
	       oResult_valid <= acc_clear_dly[2];
	    else 
	    /*
		  case(iConfig_interconnection)
			 2'b00 : oResult_valid <= acc_clear_dly[2];
			 2'b01 : oResult_valid <= acc_clear_dly[4];
			 2'b10 : oResult_valid <= acc_clear_dly[6];
			 2'b11 : oResult_valid <= acc_clear_dly[6];
		  endcase
		 */
		  case(iConfig_interconnection)
			 2'b01 : oResult_valid <= acc_clear_dly[4];
			 2'b10 : oResult_valid <= acc_clear_dly[6];
		  endcase		

	end
end


assign	mux_data_right_1 = mux_data_right_1_sel ? data_b1_dly :
												  acc_data_2_dly;
assign	mux_data_right_2 = (mux_data_right_2_sel == 2'b0) ? data_b2_dly1 :
						   (mux_data_right_2_sel == 2'b01)? data_b2_dly3 :
															add_ch3_final_data;
assign	mux_data_right_3 = mux_data_right_3_sel ? data_b3_dly :
												  acc_data_4_dly;
assign	mux_data_right_4 = (mux_data_right_4_sel == 2'b00) ? data_b4_dly1 :
						   (mux_data_right_4_sel == 2'b01) ? data_b4_dly3 :
															 data_b4_dly5 ;
assign	mux_data_left_2 = mux_data_left_2_sel ? add_ch1_final_data :
												acc_data_2_dly;
assign	mux_data_left_4 = (mux_data_left_4_sel == 2'b00) ? acc_data_4_dly :
						  (mux_data_left_4_sel == 2'b01) ? add_ch3_final_data :
														   add_ch2_final_data ;

// RELU

always @(posedge clk) begin
	oResult_1 <= iConfig_relu_enable ? (add_ch1_final_data[2*`DATAWIDTH+4-1] ? 0 : add_ch1_final_data) : add_ch1_final_data;
	oResult_2 <= iConfig_relu_enable ? (add_ch2_final_data[2*`DATAWIDTH+4-1] ? 0 : add_ch2_final_data) : add_ch2_final_data;
	oResult_3 <= iConfig_relu_enable ? (add_ch3_final_data[2*`DATAWIDTH+4-1] ? 0 : add_ch3_final_data) : add_ch3_final_data;
	oResult_4 <= iConfig_relu_enable ? (add_ch4_final_data[2*`DATAWIDTH+4-1] ? 0 : add_ch4_final_data) : add_ch4_final_data;
end
`ifndef SIM

//
adder_18a18
	adder1 (
		.A(acc_data_1_dly),
		.B(mux_data_right_1),
		.CLK(clk),
		.S(add_ch1_final_data)
	);

adder_18a18
	adder2 (
		.A(mux_data_left_2),
		.B(mux_data_right_2),
		.CLK(clk),
		.S(add_ch2_final_data)
	);

adder_18a18
	adder3 (
		.A(acc_data_3_dly),
		.B(mux_data_right_3),
		.CLK(clk),
		.S(add_ch3_final_data)
	);

adder_18a18
	adder4 (
		.A(mux_data_left_4),
		.B(mux_data_right_4),
		.CLK(clk),
		.S(add_ch4_final_data)
	);

`else

reg [19:0]   add_ch1_final_data_t, add_ch1_final_data_tt;
reg [19:0]   add_ch2_final_data_t, add_ch2_final_data_tt;
reg [19:0]   add_ch3_final_data_t, add_ch3_final_data_tt;
reg [19:0]   add_ch4_final_data_t, add_ch4_final_data_tt;

always @(posedge clk) begin
    // 1
    add_ch1_final_data_t <= acc_data_1_dly + mux_data_right_1;
    add_ch1_final_data_tt <= add_ch1_final_data_t;
    //2
    add_ch2_final_data_t <= mux_data_left_2 + mux_data_right_2;
    add_ch2_final_data_tt <= add_ch2_final_data_t;
    //3
    add_ch3_final_data_t <= acc_data_3_dly + mux_data_right_3;
    add_ch3_final_data_tt <= add_ch3_final_data_t;
    //4
    add_ch4_final_data_t <= mux_data_left_4 + mux_data_right_4;
    add_ch4_final_data_tt <= add_ch4_final_data_t;

end

assign  add_ch1_final_data = add_ch1_final_data_tt;
assign  add_ch2_final_data = add_ch2_final_data_tt;
assign  add_ch3_final_data = add_ch3_final_data_tt;
assign  add_ch4_final_data = add_ch4_final_data_tt;
`endif


endmodule

