`include "fucore.vh"
`timescale 1ns/1ps
module	pe_array #(parameter	N = 8) (
			// global signals
				input							clk_sys,
				input							clk_dsp,
				input							rst,
			// configuration
				input	[1:0]					iConfig_interconnection,
				input							iConfig_relu_enable,
				input							iConfig_branch_add_enable,
				input	[1:0]					iConfig_channel_mask_sel,
				input	[3:0]					iConfig_result_bit_sel,
				input                           iConfig_intermediate_shift_enable,
				input   [3:0]                   iConfig_intermediate_right_shift_width,
				input   [2:0]                   iConfig_intermediate_left_shift_width,
				input   [3:0]                   iConfig_pe_branch_bitshift,
				input   [3:0]                   iConfig_intermediate_sel_count,
				input	[1:0]					iConfig_specific_sel_mask,
				input							iConfig_valid,
				output							oConfig_stop,
				input							iConfig_clear,
				output  reg                     oConfig_clear_ack,

				output	[3:0]					oResult_bit_sel,
				output  [3:0]                   oBranch_bit_sel,
				output  [3:0]                   oIntermediate_sel_count,
				output	[1:0]					oConfig_interconnection,
				output	[1:0]					oChannel_mask_sel,
				output							oIs_branch_add_enable,
				output	[1:0]					oSpecific_sel_mask,
				output                          oIntermediate_shift_enable,
				output  [3:0]                   oIntermediate_right_shift_width,
				output  [2:0]                   oIntermediate_left_shift_width,
			//
				input	[`DATAWIDTH*64*N-1:0]	iData,
				input							iParam_wr_enable,
				input	[6:0]					iParam_wr_addr,
				input	[5:0]					iParam_wr_id,
				input	[`DATAWIDTH*64-1:0]		iParam_wr_data,

				input	[5:0]					iParam_rd_addr,
				input							iParam_rd_enable,

                input                           iSpecific_enable,
				input	[(2*`DATAWIDTH+4)*128*N-1:0]		iIntermediate_data,
				input	[(2*`DATAWIDTH+4)*32*N-1:0]			iBranch_in_data,
				input	[8*N-1:0]							iBranch_in_datavalid,

			//
				input							iAcc_valid,
				input							iAcc_clear,
			//
				output	[(2*`DATAWIDTH+4)*128*N-1:0]	oResult,
				output	[N*32-1:0]						oResult_valid
		);

localparam	ASYN_LATENCY = 12; 
localparam	LATENCY_PE = 6; // ASYN_LATENCY/2;
localparam	LATENCY = 1+1+LATENCY_PE + 14;  // 1+1+3, 1: ctr latency, 1: read data latency, 3: pe compute latency
localparam  CONFIG_DLY = 5;
localparam  URAM_RD_LATENCY = 23;
//
reg					config_clear_dly[LATENCY+URAM_RD_LATENCY-1:0];

wire	[N*`PE_NUM/8-1:0]	result_valid;

reg		[1:0]		config_status;
reg					config_sel;
(*keep="true"*)reg	config_adopte_sel;
(*keep="true"*)reg  config_adopte_sel_rep;

reg		[1:0]		config_interconnection [1:0];
reg					config_relu_enable [1:0];
reg					config_branch_add_enable [1:0];
reg		[1:0]		config_channel_mask_sel [1:0];
reg		[3:0]		config_result_bit_sel [1:0];
reg                 config_intermediate_shift_enable [1:0];
reg     [3:0]       config_intermediate_right_shift_width [1:0];
reg     [2:0]       config_intermediate_left_shift_width [1:0];
reg     [3:0]       config_pe_branch_bitshift [1:0];
reg     [3:0]       config_intermediate_sel_count [1:0];
reg		[1:0]		config_specific_sel_mask [1:0];

wire	[1:0]		adopte_config_interconnection;
wire				adopte_config_relu_enable;
wire				adopte_config_branch_add_enable;

reg					acc_valid_dly[LATENCY_PE-1:0];
reg					acc_clear_dly[LATENCY_PE-1:0];

reg                 specific_enable_dly [2:0];
reg     [1:0]       adopte_config_interconnection_dly [2:0];
reg                 adopte_config_relu_enable_dly [2:0];
reg                 adopte_config_branch_add_enable_dly [2:0];


wire	[(2*`DATAWIDTH+4)*128*N-1:0]	branch_in_data;

always @(posedge clk_sys)
    oConfig_clear_ack <= config_clear_dly[LATENCY+URAM_RD_LATENCY-1];

always @(posedge clk_sys) begin : clc_delay
	integer i;
	config_clear_dly[0] <= iConfig_clear;
	for(i=1;i<LATENCY+URAM_RD_LATENCY;i=i+1)
		config_clear_dly[i] <= config_clear_dly[i-1];
end

always @(posedge clk_sys) begin : rd_delay
    integer j;
    specific_enable_dly[0] <= iSpecific_enable;
    adopte_config_interconnection_dly[0] <= adopte_config_interconnection;
    adopte_config_relu_enable_dly[0] <= adopte_config_relu_enable;
    adopte_config_branch_add_enable_dly[0] <= adopte_config_branch_add_enable;


    for(j=1;j<3;j=j+1) begin
        specific_enable_dly[j] <= specific_enable_dly[j-1];
        adopte_config_interconnection_dly[j] <= adopte_config_interconnection_dly[j-1];
        adopte_config_relu_enable_dly[j] <= adopte_config_relu_enable_dly[j-1];
        adopte_config_branch_add_enable_dly[j] <= adopte_config_branch_add_enable_dly[j-1];
    end

end

assign	oConfig_stop = & config_status;

always @(posedge clk_sys)
	if(rst)
		config_sel <= 1'b0;
	else if(iConfig_valid)
		config_sel <= ~config_sel;

always @(posedge clk_sys)
	if(rst)
		config_adopte_sel <= 1'b0;
	else if(config_clear_dly[LATENCY+URAM_RD_LATENCY-1])
		config_adopte_sel <= ~config_adopte_sel;

always @(posedge clk_sys)
    config_adopte_sel_rep <= config_adopte_sel;

always @(posedge clk_sys)
	if(rst)
		config_status <= 2'b0;
	else begin
		if(config_clear_dly[LATENCY+URAM_RD_LATENCY-1] & (~config_adopte_sel))
			config_status[0] <= 1'b0;
		else if(iConfig_valid & (~config_sel))
			config_status[0] <= 1'b1;

		if(config_clear_dly[LATENCY+URAM_RD_LATENCY-1] & config_adopte_sel)
			config_status[1] <= 1'b0;
		else if(iConfig_valid & config_sel)
			config_status[1] <= 1'b1;
	end

always @(posedge clk_sys)
	if(iConfig_valid) begin
		case(config_sel)
			1'b0 :
				begin
					config_interconnection[0] <= iConfig_interconnection;
					config_relu_enable[0] <= iConfig_relu_enable;
					config_branch_add_enable[0] <= iConfig_branch_add_enable;
					config_channel_mask_sel[0] <= iConfig_channel_mask_sel;
					config_result_bit_sel[0] <= iConfig_result_bit_sel;
					config_intermediate_shift_enable[0] <= iConfig_intermediate_shift_enable;
					config_intermediate_right_shift_width[0] <= iConfig_intermediate_right_shift_width;
					config_intermediate_left_shift_width[0] <= iConfig_intermediate_left_shift_width;
					config_pe_branch_bitshift[0] <= iConfig_pe_branch_bitshift;
					config_intermediate_sel_count[0] <= iConfig_intermediate_sel_count;
					config_specific_sel_mask[0] <= iConfig_specific_sel_mask;
				end
			1'b1 :
				begin
					config_interconnection[1] <= iConfig_interconnection;
					config_relu_enable[1] <= iConfig_relu_enable;
					config_branch_add_enable[1] <= iConfig_branch_add_enable;
					config_channel_mask_sel[1] <= iConfig_channel_mask_sel;
					config_result_bit_sel[1] <= iConfig_result_bit_sel;
					config_intermediate_shift_enable[1] <= iConfig_intermediate_shift_enable;
                    config_intermediate_right_shift_width[1] <= iConfig_intermediate_right_shift_width;
                    config_intermediate_left_shift_width[1] <= iConfig_intermediate_left_shift_width;
                    config_pe_branch_bitshift[1] <= iConfig_pe_branch_bitshift;
                    config_intermediate_sel_count[1] <= iConfig_intermediate_sel_count;
					config_specific_sel_mask[1] <= iConfig_specific_sel_mask;
				end
		endcase
	end

assign	adopte_config_interconnection = config_adopte_sel ? config_interconnection[1] :
															config_interconnection[0] ;
assign	adopte_config_relu_enable = config_adopte_sel ? config_relu_enable[1] :
														config_relu_enable[0] ;
assign	adopte_config_branch_add_enable = config_adopte_sel ? config_branch_add_enable[1] :
															  config_branch_add_enable[0] ;
assign	oIs_branch_add_enable = adopte_config_branch_add_enable;


assign	oChannel_mask_sel = config_adopte_sel ? config_channel_mask_sel[1] :
												config_channel_mask_sel[0] ;


assign	oResult_bit_sel = config_adopte_sel ? config_result_bit_sel[1] : config_result_bit_sel[0];

assign  oBranch_bit_sel = config_adopte_sel ? config_pe_branch_bitshift[1] : config_pe_branch_bitshift[0];
assign  oIntermediate_sel_count = config_adopte_sel ? config_intermediate_sel_count[1] : config_intermediate_sel_count[0];
assign	oSpecific_sel_mask = config_adopte_sel ? config_specific_sel_mask[1] : config_specific_sel_mask[0];

assign  oIntermediate_shift_enable = config_adopte_sel_rep ? config_intermediate_shift_enable[1] : config_intermediate_shift_enable[0];
assign  oIntermediate_right_shift_width = config_adopte_sel_rep ? config_intermediate_right_shift_width[1] : config_intermediate_right_shift_width[0];
assign  oIntermediate_left_shift_width = config_adopte_sel_rep ? config_intermediate_left_shift_width[1] : config_intermediate_left_shift_width[0];

assign	oConfig_interconnection = adopte_config_interconnection;




wire	[`DATAWIDTH*16-1:0]	data1 [512/64:0][N-1:0];
wire	[`DATAWIDTH*16-1:0]	data2 [512/64:0][N-1:0];
wire	[`DATAWIDTH*16-1:0]	data3 [512/64:0][N-1:0];
wire	[`DATAWIDTH*16-1:0]	data4 [512/64:0][N-1:0];

wire	[1:0]				bu_config_interconnection [512/64:0][N-1:0];
wire						bu_config_relu_enable	  [512/64:0][N-1:0];
wire						bu_config_branch_add_enable [512/64:0][N-1:0];
wire                        bu_config_specific_enable [512/64:0][N-1:0];

wire						param_wr_enable [512/64:0][N-1:0];
wire	[6:0]				param_wr_addr	[512/64:0][N-1:0];
wire	[5:0]				param_id		[512/64:0][N-1:0];
wire	[`DATAWIDTH*64-1:0]	param_wr_data	[512/64:0][N-1:0];

wire	[5:0]				param_rd_addr	[512/64:0][N-1:0];
wire						param_tdm_sel	[512/64:0][N-1:0];

wire						acc_valid		[512/64:0][N-1:0];
wire						acc_clear		[512/64:0][N-1:0];
wire						pe_result_sel	[512/64:0][N-1:0];



reg		[1:0]				adopte_config_interconnection_rep [N-1:0];
reg							adopte_config_relu_enable_rep [N-1:0];
reg							adopte_config_branch_add_enable_rep [N-1:0];

reg							param_wr_enable_rep [N-1:0];
reg		[6:0]				param_wr_addr_rep [N-1:0];
reg		[5:0]				param_wr_id_rep [N-1:0];
reg     [511:0]             param_wr_data_rep [N-1:0];
reg		[5:0]				param_rd_addr_rep [N-1:0];
reg	                        param_rd_enable_dly [2:0];
wire                        param_rd_enable_dly_delta;
reg							param_tdm_sel_rep [N-1:0];
reg                         param_tdm_sel_rep_dly[N-1:0][(LATENCY_PE+2)*2-1:0];  

reg							acc_valid_rep [N-1:0];
reg							acc_clear_rep [N-1:0];

//(*ASYNC_REG="true"*) reg	pe_result_sel_rep [N-1:0];

genvar i;
generate
	genvar core_1;
	for(core_1=0;core_1<N;core_1=core_1+1) begin
		for(i=0;i<128;i=i+1) begin : branch_data_convert
			if(i >= 32)
				assign	branch_in_data[core_1*(2*`DATAWIDTH+4)*128+i*(2*`DATAWIDTH+4)+:2*`DATAWIDTH+4] = 'b0;
			else
				assign	branch_in_data[core_1*(2*`DATAWIDTH+4)*128+i*(2*`DATAWIDTH+4)+:2*`DATAWIDTH+4] = iBranch_in_data[core_1*(2*`DATAWIDTH+4)*32+i*(2*`DATAWIDTH+4)+:2*`DATAWIDTH+4];
		end
	end
endgenerate

always @(posedge clk_sys) begin: pe_dly
	integer i;
	acc_valid_dly[0] <= iAcc_valid;
	acc_clear_dly[0] <= iAcc_clear;
	for(i=1;i<LATENCY_PE;i=i+1) begin
		acc_valid_dly[i] <= acc_valid_dly[i-1];
		acc_clear_dly[i] <= acc_clear_dly[i-1];
	end
end

always @(posedge clk_dsp) begin : result_sel_dly
    integer i,i_core;
    for(i_core=0;i_core<N;i_core=i_core+1) begin
        param_tdm_sel_rep_dly[i_core][0] <= param_tdm_sel_rep[i_core];
        for(i=1;i<(LATENCY_PE+2)*2;i=i+1) begin
            param_tdm_sel_rep_dly[i_core][i] <= param_tdm_sel_rep_dly[i_core][i-1];
        end
    end
end

always @(posedge clk_sys) begin: core_rep
	integer rep;
	for(rep=0;rep<N;rep=rep+1) begin
		adopte_config_interconnection_rep[rep] <= adopte_config_interconnection_dly[2]; //adopte_config_interconnection_rep[rep-1];
		adopte_config_relu_enable_rep[rep] <= adopte_config_relu_enable_dly[2]; //adopte_config_relu_enable_rep[rep-1];
		adopte_config_branch_add_enable_rep[rep] <= adopte_config_branch_add_enable_dly[2];
		//
		param_wr_enable_rep[rep] <= iParam_wr_enable; // param_wr_enable_rep[rep-1];
		param_wr_addr_rep[rep] <= iParam_wr_addr; //param_wr_addr_rep[rep-1];
		param_wr_data_rep[rep] <= iParam_wr_data;
		param_wr_id_rep[rep] <= iParam_wr_id; //param_wr_id_rep[rep-1];
		param_rd_addr_rep[rep] <= iParam_rd_addr; //param_rd_addr_rep[rep-1];
		//
		acc_valid_rep[rep] <= acc_valid_dly[LATENCY_PE-1];
		acc_clear_rep[rep] <= acc_clear_dly[LATENCY_PE-1];
	end
end
`ifndef SIM
/*
IBUF			rd_enalbe_dly_delta (
	.O			(param_rd_enable_dly_delta),
	.I			(iParam_rd_enable)
);
*/
assign  param_rd_enable_dly_delta = iParam_rd_enable;
`else
assign #0.1 param_rd_enable_dly_delta =  iParam_rd_enable;

`endif

always @(posedge clk_dsp) begin
	param_rd_enable_dly[0] <= param_rd_enable_dly_delta;
	param_rd_enable_dly[1] <= param_rd_enable_dly[0];		
	param_rd_enable_dly[2] <= param_rd_enable_dly[1];
end


genvar n,core;
generate
	for(core=0;core<N;core=core+1) begin : core_num

	// for configuration
	assign	bu_config_interconnection[0][core] = adopte_config_interconnection_rep[core];
	assign	bu_config_relu_enable[0][core] = adopte_config_relu_enable_rep[core];
	assign	bu_config_branch_add_enable[0][core] = adopte_config_branch_add_enable_rep[core];
	assign  bu_config_specific_enable[0][core] = specific_enable_dly[2];
	//
	assign	data1[0][core] = {iData[core*`DATAWIDTH*64+3*16*`DATAWIDTH+0*4*`DATAWIDTH+:4*`DATAWIDTH],
	                          iData[core*`DATAWIDTH*64+2*16*`DATAWIDTH+0*4*`DATAWIDTH+:4*`DATAWIDTH],
	                          iData[core*`DATAWIDTH*64+1*16*`DATAWIDTH+0*4*`DATAWIDTH+:4*`DATAWIDTH],
	                          iData[core*`DATAWIDTH*64+0*16*`DATAWIDTH+0*4*`DATAWIDTH+:4*`DATAWIDTH]};

	assign	data2[0][core] = {iData[core*`DATAWIDTH*64+3*16*`DATAWIDTH+1*4*`DATAWIDTH+:4*`DATAWIDTH],
                              iData[core*`DATAWIDTH*64+2*16*`DATAWIDTH+1*4*`DATAWIDTH+:4*`DATAWIDTH],
                              iData[core*`DATAWIDTH*64+1*16*`DATAWIDTH+1*4*`DATAWIDTH+:4*`DATAWIDTH],
                              iData[core*`DATAWIDTH*64+0*16*`DATAWIDTH+1*4*`DATAWIDTH+:4*`DATAWIDTH]};

	assign	data3[0][core] = {iData[core*`DATAWIDTH*64+3*16*`DATAWIDTH+2*4*`DATAWIDTH+:4*`DATAWIDTH],
                              iData[core*`DATAWIDTH*64+2*16*`DATAWIDTH+2*4*`DATAWIDTH+:4*`DATAWIDTH],
                              iData[core*`DATAWIDTH*64+1*16*`DATAWIDTH+2*4*`DATAWIDTH+:4*`DATAWIDTH],
                              iData[core*`DATAWIDTH*64+0*16*`DATAWIDTH+2*4*`DATAWIDTH+:4*`DATAWIDTH]};

	assign	data4[0][core] = {iData[core*`DATAWIDTH*64+3*16*`DATAWIDTH+3*4*`DATAWIDTH+:4*`DATAWIDTH],
                              iData[core*`DATAWIDTH*64+2*16*`DATAWIDTH+3*4*`DATAWIDTH+:4*`DATAWIDTH],
                              iData[core*`DATAWIDTH*64+1*16*`DATAWIDTH+3*4*`DATAWIDTH+:4*`DATAWIDTH],
                              iData[core*`DATAWIDTH*64+0*16*`DATAWIDTH+3*4*`DATAWIDTH+:4*`DATAWIDTH]};

	//
	assign	param_wr_enable[0][core] = param_wr_enable_rep[core];
	assign	param_wr_addr[0][core] = param_wr_addr_rep[core];
	assign  param_wr_data[0][core] = param_wr_data_rep[core];
	assign	param_id[0][core] = param_wr_id_rep[core];
	assign	param_rd_addr[0][core] = param_rd_addr_rep[core];
	assign	param_tdm_sel[0][core] = param_tdm_sel_rep[core];

	//
	assign	acc_valid[0][core] = acc_valid_rep[core];
	assign	acc_clear[0][core] = acc_clear_rep[core];
	assign	pe_result_sel[0][core] = param_tdm_sel_rep_dly[core][(LATENCY_PE+2)*2-2];
	//

	always @(posedge clk_dsp)
		if(rst)
			param_tdm_sel_rep[core] <= 1'b0;
		else if(param_rd_enable_dly[2])
			param_tdm_sel_rep[core] <= ~param_tdm_sel_rep[core];

	/*
	always @(posedge clk_dsp)
		if(rst)
			pe_result_sel_rep[core] <= 1'b0;
		else if(acc_clear_dly[LATENCY_PE-1])
			pe_result_sel_rep[core] <= ~pe_result_sel_rep[core];
    */
	//
	for(n=0;n<512/64;n=n+1) begin : gen_basic_unit
		basic_unit #(.INDEX(n)) basic_unit_inst
			(
			// global signals
				.clk_sys(clk_sys),
				.clk_dsp(clk_dsp),
				.rst(rst),
			// configuration
				.iConfig_interconnection(bu_config_interconnection[n][core]),
				.iConfig_relu_enable(bu_config_relu_enable[n][core]),
				.iConfig_branch_add_enable(bu_config_branch_add_enable[n][core]),
				.iConfig_specific_enable(bu_config_specific_enable[n][core]),

				.oConfig_interconnection(bu_config_interconnection[n+1][core]),
				.oConfig_relu_enable(bu_config_relu_enable[n+1][core]),
				.oConfig_branch_add_enable(bu_config_branch_add_enable[n+1][core]),
				.oConfig_specific_enable(bu_config_specific_enable[n+1][core]),
			//
				.iData1(data1[n][core]),
				.iData2(data2[n][core]),
				.iData3(data3[n][core]),
				.iData4(data4[n][core]),

				.oData1(data1[n+1][core]),
				.oData2(data2[n+1][core]),
				.oData3(data3[n+1][core]),
				.oData4(data4[n+1][core]),

			//
				.iParam_wr_enable(param_wr_enable[n][core]),
				.iParam_wr_addr(param_wr_addr[n][core]),
				.iParam_id(param_id[n][core]),
				.iParam_wr_data(param_wr_data[n][core]),

				.iParam_rd_addr(param_rd_addr[n][core]),
				.iParam_tdm_sel(param_tdm_sel[n][core]),

				.oParam_wr_enable(param_wr_enable[n+1][core]),
				.oParam_wr_addr(param_wr_addr[n+1][core]),
				.oParam_id(param_id[n+1][core]),
				.oParam_wr_data(param_wr_data[n+1][core]),

				.oParam_rd_addr(param_rd_addr[n+1][core]),
				.oParam_tdm_sel(param_tdm_sel[n+1][core]),
			//
				.iIntermediate_data_1(iIntermediate_data[core*(2*`DATAWIDTH+4)*128 + n*(2*`DATAWIDTH+4)*8*2+0*(2*`DATAWIDTH+4)*8+:(2*`DATAWIDTH+4)*8]),
				.iIntermediate_data_2(iIntermediate_data[core*(2*`DATAWIDTH+4)*128 + n*(2*`DATAWIDTH+4)*8*2+1*(2*`DATAWIDTH+4)*8+:(2*`DATAWIDTH+4)*8]),
				.iBranch_in_data_1(branch_in_data[core*(`DATAWIDTH*2+4)*128 + n*(2*`DATAWIDTH+4)*8*2 + 0*(2*`DATAWIDTH+4)*8+:(2*`DATAWIDTH+4)*8]),
				.iBranch_in_data_2(branch_in_data[core*(`DATAWIDTH*2+4)*128 + n*(2*`DATAWIDTH+4)*8*2 + 1*(2*`DATAWIDTH+4)*8+:(2*`DATAWIDTH+4)*8]),
				.iBranch_in_datavalid(iBranch_in_datavalid[core*8+n]),
			//
				.iAcc_valid(acc_valid[n][core]),
				.iAcc_clear(acc_clear[n][core]),
				.iPE_result_sel(pe_result_sel[n][core]),

				.oAcc_valid(acc_valid[n+1][core]),
				.oAcc_clear(acc_clear[n+1][core]),
				.oPE_result_sel(pe_result_sel[n+1][core]),

			//
				.oResult_g11_1(oResult[core*(`DATAWIDTH*2+4)*128 + n*(`DATAWIDTH*2+4)*16+0*(`DATAWIDTH*2+4)+:(`DATAWIDTH*2+4)]),
				.oResult_g11_2(oResult[core*(`DATAWIDTH*2+4)*128 + n*(`DATAWIDTH*2+4)*16+1*(`DATAWIDTH*2+4)+:(`DATAWIDTH*2+4)]),
				.oResult_g11_3(oResult[core*(`DATAWIDTH*2+4)*128 + n*(`DATAWIDTH*2+4)*16+2*(`DATAWIDTH*2+4)+:(`DATAWIDTH*2+4)]),
				.oResult_g11_4(oResult[core*(`DATAWIDTH*2+4)*128 + n*(`DATAWIDTH*2+4)*16+3*(`DATAWIDTH*2+4)+:(`DATAWIDTH*2+4)]),

				.oResult_g12_1(oResult[core*(`DATAWIDTH*2+4)*128 + n*(`DATAWIDTH*2+4)*16+4*(`DATAWIDTH*2+4)+:(`DATAWIDTH*2+4)]),
				.oResult_g12_2(oResult[core*(`DATAWIDTH*2+4)*128 + n*(`DATAWIDTH*2+4)*16+5*(`DATAWIDTH*2+4)+:(`DATAWIDTH*2+4)]),
				.oResult_g12_3(oResult[core*(`DATAWIDTH*2+4)*128 + n*(`DATAWIDTH*2+4)*16+6*(`DATAWIDTH*2+4)+:(`DATAWIDTH*2+4)]),
				.oResult_g12_4(oResult[core*(`DATAWIDTH*2+4)*128 + n*(`DATAWIDTH*2+4)*16+7*(`DATAWIDTH*2+4)+:(`DATAWIDTH*2+4)]),

				.oResult_g21_1(oResult[core*(`DATAWIDTH*2+4)*128 + n*(`DATAWIDTH*2+4)*16+8*(`DATAWIDTH*2+4)+:(`DATAWIDTH*2+4)]),
				.oResult_g21_2(oResult[core*(`DATAWIDTH*2+4)*128 + n*(`DATAWIDTH*2+4)*16+9*(`DATAWIDTH*2+4)+:(`DATAWIDTH*2+4)]),
				.oResult_g21_3(oResult[core*(`DATAWIDTH*2+4)*128 + n*(`DATAWIDTH*2+4)*16+10*(`DATAWIDTH*2+4)+:(`DATAWIDTH*2+4)]),
