`include "fucore.vh"
module	pe_array_if_onecore (
		// global signals
			input			clk,
			input			rst,
		//
			input	[`IN_BUFFER_DATAWIDTH-1:0]			iData,
			input										iData_valid,

			input	[3:0]								iResult_reuse_sel_count,
			input	[1:0]								iData_buffer_organization,

			output	[`DATAWIDTH*64-1:0]					oData,
			output										oData_valid,
		//

			input	[`BIAS_BUFFER_DATAWIDTH-1:0]		iBias_data,
			output	[128*(2*`DATAWIDTH+4)-1:0]			oBias_data,
			input										iS_add_bias_valid,

			input	[3:0]								iResult_bit_sel,
			input   [3:0]                               iBranch_bit_sel,
			input	[2*32-1:0]							iResult_rd_organization, 
			input                                       iPrevious_blk_channel_is_half_utilization,
		//
		    input                                       iSpecific_enable,
		    input   [1:0]                               iSpecific_sel_mask,
		    input   [9:0]                               iNum_in_each_row,	
			input										iS_conv_bypass,

		//
			input	[`OUT_BUFFER_DATAWIDTH-1:0]			iIntermediate_data,
			input	[7:0]  							    iS_add_intermediate_valid,
			input                                       iIntermediate_32mode_width_step_eq_2,
		//
			output	reg [32*(2*`DATAWIDTH+4)-1:0]		oBranch_add_data_1,
			output	reg	[7:0]							oBranch_data_valid,
		//
			input										iS_branch_add_valid
	);


reg		[`IN_BUFFER_DATAWIDTH-1:0]					data_temp;
reg		[`IN_BUFFER_DATAWIDTH-1:0]					data_reg;
//reg		[`IN_BUFFER_DATAWIDTH-1:0]					data_temp_shift [13:0];
reg													data_valid_temp [15:0];

reg		[128*(2*`DATAWIDTH+4)-1:0]					bias_tmp;

// lantecy = configuration latency + read data latency from bram
//reg													reuse_result_enable_dly [13:0];
reg		[3:0]										result_reuse_sel_count_dly [13:0];
reg		[3:0]										result_bit_sel_dly [3:0];
reg     [3:0]                                       branch_bit_sel_dly [11:0];

// to reduce fanout
(*keep="true"*)reg		[3:0]						result_bit_sel_dly4 [31:0];
//(*keep="true"*)reg		[3:0]						result_bit_sel_dly1 [15:0];
//(*keep="true"*)reg		[3:0]						result_bit_sel_dly8 [7:0];
(*keep="true"*)reg      [3:0]                       branch_bit_sel_dly8 [7:0];

wire	[(2*`DATAWIDTH+4)*64-1:0]					result_after_shift_t;
wire	[`DATAWIDTH*64-1:0]							result_after_shift;
reg		 										    r2i_count;
wire												r2i_count_meet_border;
reg		   										    r2i_count_dly [6:0];

wire	[128*(2*`DATAWIDTH+4)-1:0]				intermediate_result;
(*keep = "true"*)reg    [`OUT_BUFFER_DATAWIDTH*4-1:0] input_intermediate_reg;
reg		[1:0]	intermediate_result_input_count		[7:0];


(*keep="true"*)reg		[1:0]						data_buf_organization_dly[2:0];
reg		[32*(2*`DATAWIDTH+4)-1:0]					branch_data_1_dly[4:0];
reg		[16*(2*`DATAWIDTH+4)-1:0]					branch_data_1_high_dly;
reg		[32*(2*`DATAWIDTH+4)-1:0]					branch_data_2;
reg													branch_data_valid_dly[4:0];
reg													branch_data_valid_flag;


reg 	[1:0]							            result_rd_organization_dly[10:0];
reg     [2*32-1:0]                                  result_rd_organization_rep; 

//reg                                                 previous_blk_channel_is_half_utilization_dly[10:0];
reg     [31:0]                                      previous_blk_channel_is_half_utilization_rep;

reg     [31:0]                                      intermediate_32mode_width_step_eq_2_rep;

localparam	LATENCY = 3+1+7; // BRAM Read latency + interface_latency + pe latency
(*keep="true"*)reg		is_add_bias_valid [LATENCY+1+23-1:0][31:0];
wire    is_add_bias_valid_tmp[31:0];
reg		is_add_intermediate_valid [LATENCY-1:0];
reg		is_branch_add_valid [3:0];
reg		is_branch_add_valid_dly_rep [7:0];


reg		       	branch_in_data_comb_count;
reg		       	branch_in_data_comb_count_dly [2:0];
reg		       	branch_in_data_comb_count_dly_rep;
//
reg             specific_enable;
reg     [1:0]   specific_sel_mask;
reg     [9:0]   num_in_each_row;
reg             is_conv_bypass_dly[4:0];

reg     [9:0]   num_in_each_row_count;
reg     [1:0]   specific_count;
wire            mask_clear;
reg     [6:0]   mask_clear_dly;

wire    [7:0]   mask_clear_rep;

//
always @(posedge clk) begin: rd_dly
    integer i,j,z;

    //
    specific_enable <= iSpecific_enable;
    specific_sel_mask <= iSpecific_sel_mask;
    num_in_each_row <= iNum_in_each_row;

    //
    is_conv_bypass_dly[0] <= iS_conv_bypass;
    is_conv_bypass_dly[1] <= is_conv_bypass_dly[0];
    is_conv_bypass_dly[2] <= is_conv_bypass_dly[1];
    is_conv_bypass_dly[3] <= is_conv_bypass_dly[2];
    is_conv_bypass_dly[4] <= is_conv_bypass_dly[3];

    //

	result_reuse_sel_count_dly[0] <= iResult_reuse_sel_count;
	result_reuse_sel_count_dly[1] <= result_reuse_sel_count_dly[0];
	result_reuse_sel_count_dly[2] <= result_reuse_sel_count_dly[1];
	result_reuse_sel_count_dly[3] <= result_reuse_sel_count_dly[2];
	result_reuse_sel_count_dly[4] <= result_reuse_sel_count_dly[3];
    result_reuse_sel_count_dly[5] <= result_reuse_sel_count_dly[4];
    result_reuse_sel_count_dly[6] <= result_reuse_sel_count_dly[5];
    result_reuse_sel_count_dly[7] <= result_reuse_sel_count_dly[6];
    result_reuse_sel_count_dly[8] <= result_reuse_sel_count_dly[7];
    result_reuse_sel_count_dly[9] <= result_reuse_sel_count_dly[8];
    result_reuse_sel_count_dly[10] <= result_reuse_sel_count_dly[9];
    result_reuse_sel_count_dly[11] <= result_reuse_sel_count_dly[10];
    result_reuse_sel_count_dly[12] <= result_reuse_sel_count_dly[11];
     result_reuse_sel_count_dly[13] <= result_reuse_sel_count_dly[12];


	data_buf_organization_dly[0] <= iData_buffer_organization;
	data_buf_organization_dly[1] <= data_buf_organization_dly[0];
	data_buf_organization_dly[2] <= data_buf_organization_dly[1];

    result_rd_organization_dly[0] <= iResult_rd_organization[1:0];
    //previous_blk_channel_is_half_utilization_dly[0] <= iPrevious_blk_channel_is_half_utilization;

    for(j=1;j<11;j=j+1) begin
        result_rd_organization_dly[j] <= result_rd_organization_dly[j-1]; 
        //previous_blk_channel_is_half_utilization_dly[j] <= previous_blk_channel_is_half_utilization_dly[j-1];
    end

    for(z=0;z<32;z=z+1) begin
        result_rd_organization_rep[z*2+:2] <= result_rd_organization_dly[10]; 
        previous_blk_channel_is_half_utilization_rep[z] <= iPrevious_blk_channel_is_half_utilization;
        intermediate_32mode_width_step_eq_2_rep[z] <= iIntermediate_32mode_width_step_eq_2;
    end

	result_bit_sel_dly[0] <= iResult_bit_sel;
	for(i=1;i<4;i=i+1) begin
	   result_bit_sel_dly[i] <= result_bit_sel_dly[i-1];
	end

	branch_bit_sel_dly[0] <= iBranch_bit_sel;
	branch_bit_sel_dly[1] <= branch_bit_sel_dly[0];
	branch_bit_sel_dly[2] <= branch_bit_sel_dly[1];
	branch_bit_sel_dly[3] <= branch_bit_sel_dly[2];
	branch_bit_sel_dly[4] <= branch_bit_sel_dly[3];
	branch_bit_sel_dly[5] <= branch_bit_sel_dly[4];
	branch_bit_sel_dly[6] <= branch_bit_sel_dly[5];
	branch_bit_sel_dly[7] <= branch_bit_sel_dly[6];
	branch_bit_sel_dly[8] <= branch_bit_sel_dly[7];
	branch_bit_sel_dly[9] <= branch_bit_sel_dly[8];
	branch_bit_sel_dly[10] <= branch_bit_sel_dly[9];
	branch_bit_sel_dly[11] <= branch_bit_sel_dly[10];
end



generate
    genvar core_2_i,core_2_j,core_2_k;

	always @(posedge clk) begin : rep_sel
		integer i,j;
		result_bit_sel_dly4[0] <= result_bit_sel_dly[3];
		for(i=1;i<16;i=i+1) begin
            result_bit_sel_dly4[i] <= result_bit_sel_dly4[i-1];
        end

		//end
		/*
		for(j=0;j<16;j=j+1) begin
			result_bit_sel_dly1[j] <= result_bit_sel_dly[0];
		end
		result_bit_sel_dly8[0] <= result_bit_sel_dly[10];
		result_bit_sel_dly8[1] <= result_bit_sel_dly[10];
		result_bit_sel_dly8[2] <= result_bit_sel_dly[10];
		result_bit_sel_dly8[3] <= result_bit_sel_dly[10];
		result_bit_sel_dly8[4] <= result_bit_sel_dly[10];
		result_bit_sel_dly8[5] <= result_bit_sel_dly[10];
		result_bit_sel_dly8[6] <= result_bit_sel_dly[10];
		result_bit_sel_dly8[7] <= result_bit_sel_dly[10];
		*/
		branch_bit_sel_dly8[0] <= branch_bit_sel_dly[11];
		branch_bit_sel_dly8[1] <= branch_bit_sel_dly[11];
		branch_bit_sel_dly8[2] <= branch_bit_sel_dly[11];
		branch_bit_sel_dly8[3] <= branch_bit_sel_dly[11];
		branch_bit_sel_dly8[4] <= branch_bit_sel_dly[11];
		branch_bit_sel_dly8[5] <= branch_bit_sel_dly[11];
		branch_bit_sel_dly8[6] <= branch_bit_sel_dly[11];
		branch_bit_sel_dly8[7] <= branch_bit_sel_dly[11];

		//
		mask_clear_dly[0] <= mask_clear;
		mask_clear_dly[1] <= mask_clear_dly[0];
		mask_clear_dly[2] <= mask_clear_dly[1];
		mask_clear_dly[3] <= mask_clear_dly[2];
		mask_clear_dly[4] <= mask_clear_dly[3];
		mask_clear_dly[5] <= mask_clear_dly[4];
		mask_clear_dly[6] <= mask_clear_dly[5];
	end

    always @(posedge clk)
        if(rst)
            specific_count <= 2'b0;
        else if(specific_enable & (num_in_each_row_count == num_in_each_row) & (specific_count == specific_sel_mask))
            specific_count <= 2'd0;
        else if(iS_add_intermediate_valid[0] & specific_enable)
            specific_count <= specific_count + 1'b1;

    always @(posedge clk)
        if(rst)
            num_in_each_row_count <= 10'd0;
        else if(specific_enable & (num_in_each_row_count == num_in_each_row) & (specific_count == specific_sel_mask))
            num_in_each_row_count <= 10'd0;
        else if(iS_add_intermediate_valid[0] & specific_enable & (specific_count == 2'b11)) begin
            if(num_in_each_row_count == num_in_each_row)
                num_in_each_row_count <= 10'd0;
            else
                num_in_each_row_count <= num_in_each_row_count + 1'b1;
        end

    assign  mask_clear = (num_in_each_row_count == num_in_each_row) && (specific_count == specific_sel_mask) && specific_enable;
    assign  mask_clear_rep = {mask_clear_dly,mask_clear};

	for(core_2_i=0;core_2_i < 8;core_2_i=core_2_i+1) begin
		always @(posedge clk) begin
		    if(iS_add_intermediate_valid[core_2_i])
			    case(intermediate_result_input_count[core_2_i][0])
			     	1'd0:   input_intermediate_reg[0*`OUT_BUFFER_DATAWIDTH + core_2_i*`OUT_BUFFER_DATAWIDTH/8+:`OUT_BUFFER_DATAWIDTH/8] <= is_conv_bypass_dly[4] ? 'b0 : iIntermediate_data[core_2_i*`OUT_BUFFER_DATAWIDTH/8+:`OUT_BUFFER_DATAWIDTH/8];
			     	1'd1:   input_intermediate_reg[1*`OUT_BUFFER_DATAWIDTH + core_2_i*`OUT_BUFFER_DATAWIDTH/8+:`OUT_BUFFER_DATAWIDTH/8] <= is_conv_bypass_dly[4] ? 'b0 : iIntermediate_data[core_2_i*`OUT_BUFFER_DATAWIDTH/8+:`OUT_BUFFER_DATAWIDTH/8];
			     	//2'd2:   input_intermediate_reg[2*`OUT_BUFFER_DATAWIDTH + core_2_i*`OUT_BUFFER_DATAWIDTH/8+:`OUT_BUFFER_DATAWIDTH/8] <= is_conv_bypass_dly[4] ? 'b0 : iIntermediate_data[core_2_i*`OUT_BUFFER_DATAWIDTH/8+:`OUT_BUFFER_DATAWIDTH/8];
			     	//2'd3:   input_intermediate_reg[3*`OUT_BUFFER_DATAWIDTH + core_2_i*`OUT_BUFFER_DATAWIDTH/8+:`OUT_BUFFER_DATAWIDTH/8] <= is_conv_bypass_dly[4] ? 'b0 : iIntermediate_data[core_2_i*`OUT_BUFFER_DATAWIDTH/8+:`OUT_BUFFER_DATAWIDTH/8];
			    endcase
		end

		always @(posedge clk)
			if(rst)
				intermediate_result_input_count[core_2_i] <= 2'd0;
		    else if(mask_clear_rep[core_2_i]) 
		        intermediate_result_input_count[core_2_i] <= 2'd0;
		    else if(intermediate_32mode_width_step_eq_2_rep[core_2_i])
		        intermediate_result_input_count[core_2_i] <= 2'd0;
			else if(iS_add_intermediate_valid[core_2_i]) begin
				if(intermediate_result_input_count[core_2_i] == ((result_rd_organization_rep[core_2_i*2+:2] == 0) ? 3 : (previous_blk_channel_is_half_utilization_rep[core_2_i] ? 2'd0 : result_rd_organization_rep[core_2_i*2+:2])))  
					intermediate_result_input_count[core_2_i] <= 2'd0;
				else
					intermediate_result_input_count[core_2_i] <= intermediate_result_input_count[core_2_i] + 1'b1;
			end
	end
	for(core_2_j=0;core_2_j<32;core_2_j=core_2_j+1) begin
	    if(core_2_j >= 1)
	       assign  is_add_bias_valid_tmp[core_2_j] = is_add_bias_valid[0][core_2_j-1];
	    else
	       assign  is_add_bias_valid_tmp[core_2_j] = iS_add_bias_valid;
		always @(posedge clk) begin : valid_dly
			integer j;
			is_add_bias_valid[0][core_2_j] <= is_add_bias_valid_tmp[core_2_j];
			for(j=1;j<LATENCY+1+23;j=j+1) 
				is_add_bias_valid[j][core_2_j] <= is_add_bias_valid[j-1][core_2_j]; 
		end
	end

	for(core_2_k=0;core_2_k<8;core_2_k=core_2_k+1) begin
		always @(posedge clk) begin
			is_branch_add_valid_dly_rep[core_2_k] <= is_branch_add_valid[3];
		end
	end
endgenerate

always @(posedge clk) begin : branch_dly
	integer i;
	is_branch_add_valid[0] <= iS_branch_add_valid;
	for(i=1;i<4;i=i+1) begin
		is_branch_add_valid[i] <= is_branch_add_valid[i-1];
	end
end
always @(posedge clk) begin: dly_loop
    integer i;
	//is_add_bias_valid[0] <= iS_add_bias_valid;
	is_add_intermediate_valid[0] <= iS_add_intermediate_valid[0];

	for(i=1;i<LATENCY;i=i+1) begin
	//	is_add_bias_valid[i] <= is_add_bias_valid[i-1];
		is_add_intermediate_valid[i] <= is_add_intermediate_valid[i-1];
	end
end

//wire	reuse_result_enable;
wire		result_reuse_sel_count;

assign	result_reuse_sel_count = result_reuse_sel_count_dly[13][0];


always @(posedge clk)
	if(rst)
		r2i_count <= 1'd0;
	else if(branch_data_valid_dly[1]) begin
		if(r2i_count_meet_border)
			r2i_count <= 1'd0;
		else
			r2i_count <= r2i_count + 1'b1;
	end
assign	r2i_count_meet_border = (r2i_count == result_reuse_sel_count);

always @(posedge clk) begin : r2idly
	integer i;
	r2i_count_dly[0] <= r2i_count;
	for(i=1;i<7;i=i+1) 
		r2i_count_dly[i] <= r2i_count_dly[i-1];
end

always @(posedge clk) begin
	if(rst) begin
		branch_in_data_comb_count <= 1'b0;
		branch_data_valid_flag <= 1'b0;
	end else if(iS_branch_add_valid & iData_valid) begin
		case(iData_buffer_organization)
			2'd0:
				begin
					branch_in_data_comb_count <= ~branch_in_data_comb_count;
					branch_data_valid_flag <= (branch_in_data_comb_count == 2'd1);
				end
			2'd1:
				begin
					branch_in_data_comb_count <= 1'd0;
					branch_data_valid_flag <= 1'b1;
				end
		    2'd3:
		        begin
					branch_in_data_comb_count <= 1'd0;
					branch_data_valid_flag <= 1'b1;
				end
			default:
				begin
					branch_in_data_comb_count <= branch_in_data_comb_count;
					branch_data_valid_flag <= 1'b0;
				end
		endcase
	end else begin
		branch_in_data_comb_count <= branch_in_data_comb_count;
		branch_data_valid_flag <= 1'b0;
	end
	branch_in_data_comb_count_dly[0] <= branch_in_data_comb_count;
	branch_in_data_comb_count_dly[1] <= branch_in_data_comb_count_dly[0];
	branch_in_data_comb_count_dly[2] <= branch_in_data_comb_count_dly[1];
end

generate
		always @(posedge clk) 
			branch_in_data_comb_count_dly_rep <= branch_in_data_comb_count_dly[1];

		always @(posedge clk) begin : loop1
			integer i;
			data_reg <= iData;
			for(i=0;i<32;i=i+1) begin
			   branch_data_1_dly[0][i*(2*`DATAWIDTH+4)+:(2*`DATAWIDTH+4)] <= {{12{data_reg[i*`DATAWIDTH+`DATAWIDTH-1]}},data_reg[i*`DATAWIDTH+:`DATAWIDTH]} << branch_bit_sel_dly8[i/8];
			end
			branch_data_1_dly[1] <= branch_data_1_dly[0];
			branch_data_1_dly[2] <= branch_data_1_dly[1];
			/*
			case(data_buf_organization_dly[2])
				2'd0:
					case(branch_in_data_comb_count_dly[2])
