`include "fucore.vh"
module	pe_array_of #(parameter	N = 8) (
		//
			input									   clk,
			input									   rst,
		//
			input	[1:0]							   iPe_interconnection_mode,
			input                                      iSpecific_enable,
			input	[1:0]							   iPearray_mask_sel,
			input	[(2*`DATAWIDTH+4)*128*N-1:0]	   iResult,
			input	[N*32-1:0]						   iResult_valid,
		//
			input									   iS_branch_add_enable,
			input	[1:0]							   iSpecific_sel_mask,
			input   [9:0]							   iNum_each_row,
			input   [3:0]                              iWidth_step,
		//
			output	[(2*`DATAWIDTH+4)*32*N-1:0]		   oRe_organized_result,
			output	[N*8-1:0]						   oRe_organized_valid,
		//add
			input 									   iIs_32_mode
		);

reg		[2*`DATAWIDTH+4-1:0]		result_store_reg[N-1:0][127:0];

generate
	genvar core_1,core_1_i;
	for(core_1=0;core_1<N;core_1=core_1+1) begin
	    for(core_1_i=0;core_1_i<128;core_1_i=core_1_i+1) begin
		    always @(posedge clk) begin: out_d
			    integer i;
			    if(iResult_valid[core_1*32+core_1_i/4])
					result_store_reg[core_1][core_1_i] <= iResult[core_1*(2*`DATAWIDTH+4)*128+core_1_i*(2*`DATAWIDTH+4)+:(2*`DATAWIDTH+4)];
		    end
		end
	end
endgenerate

localparam	LATENCY = 8+6 ; // max latency of pe+pat

reg	[1:0]	pe_interconnection_mode_dly[LATENCY-1:0];
(*keep="true"*)reg	[1:0]	pe_interconnection_mode_dly_rep [N-1:0];
reg	[1:0]	pearray_mask_sel[LATENCY-1:0];
reg			is_branch_add_enable_dly[LATENCY-1:0];

reg	[1:0]	specific_sel_mask_dly [LATENCY-1:0];
reg	[9:0]	num_each_row_dly [LATENCY-1:0];
reg			is_specific_enable_dly[LATENCY-1:0];
reg         is_32_mode_dly[LATENCY-1:0];
reg         is_channel_suppress_dly[LATENCY-1:0];

(*keep="true"*)reg			is_branch_add_enable_dly_rep[N-1:0][15:0];
(*keep="true"*)reg			is_branch_add_enable_dly_temp_rep[N-1:0];

//(*keep="true"*)reg [1:0]	pe_interconnection_mode_sel[N-1:0][`OUT_CH-1:0];

always @(posedge clk) begin: dly
	integer i,j,core_rep_i,core_rep_j;
	pe_interconnection_mode_dly[0] <= iIs_32_mode ? 3'b11 : (iSpecific_enable ? 2'b00 : (iS_branch_add_enable === 1'b1) ? 2'b10 : iPe_interconnection_mode);
	pearray_mask_sel[0] <= iPearray_mask_sel;
	is_branch_add_enable_dly[0] <= iS_branch_add_enable;
	specific_sel_mask_dly[0] <= iSpecific_sel_mask;
	num_each_row_dly[0] <= iNum_each_row;
	is_specific_enable_dly[0] <= iSpecific_enable;
	is_32_mode_dly[0] <= iIs_32_mode;
	is_channel_suppress_dly[0] <= (iWidth_step == 4'd2) & iIs_32_mode;
	for(i=1; i<LATENCY; i=i+1) begin
		pe_interconnection_mode_dly[i] <= pe_interconnection_mode_dly[i-1];
		pearray_mask_sel[i] <= pearray_mask_sel[i-1];
		is_branch_add_enable_dly[i] <= is_branch_add_enable_dly[i-1];
		specific_sel_mask_dly[i] <= specific_sel_mask_dly[i-1];
		num_each_row_dly[i] <= num_each_row_dly[i-1];
		is_specific_enable_dly[i] <= is_specific_enable_dly[i-1];
		is_32_mode_dly[i] <= is_32_mode_dly[i-1];
		is_channel_suppress_dly[i] <= is_channel_suppress_dly[i-1];
	end

	for(core_rep_i=0;core_rep_i<N;core_rep_i=core_rep_i+1) begin
		for(core_rep_j=0;core_rep_j<16;core_rep_j=core_rep_j+1) begin
			is_branch_add_enable_dly_rep[core_rep_i][core_rep_j] <= is_branch_add_enable_dly[LATENCY-1];
		end
		is_branch_add_enable_dly_temp_rep[core_rep_i] <= is_branch_add_enable_dly[LATENCY-3];
		pe_interconnection_mode_dly_rep[core_rep_i] <= pe_interconnection_mode_dly[LATENCY-2];
	end
end

