always @(posedge clk) begin
	result_out_channel_valid <= iResult_valid[0] || (~is_channel_suppress_dly[LATENCY-1]) & (result_sel_count[0] != 0);
end

genvar z,z1,z2;
generate
	genvar core_2,t;
	for(core_2=0;core_2<N;core_2=core_2+1) begin
		//
		always @(posedge clk) begin
			if(rst)
				result_sel_count[core_2] <= 2'd0;
			else begin
			    case(pe_interconnection_mode_dly[LATENCY-1])
			        0:
			            begin
				            if(pearray_mask_sel[LATENCY-1] == 2'b01) begin // use 64 PEs, 1/2
				            	if(iResult_valid[32*core_2] || (|result_sel_count[core_2])) begin
				            		if(result_sel_count[core_2] == 2'b01)
				            			result_sel_count[core_2] <= 2'd0;
				            		else
				            			result_sel_count[core_2] <= result_sel_count[core_2] + 1'b1;
				            	end
				            end else if(pearray_mask_sel[LATENCY-1] == 2'b10) begin // use 128 PEs, full
				            	if(iResult_valid[32*core_2] || (|result_sel_count[core_2]))
				            		result_sel_count[core_2] <= result_sel_count[core_2] + 1'b1;
				            end else begin
				            	result_sel_count[core_2] <= 2'd0; // 1/4
				            end
				        end
				    1:  begin
				            if (pearray_mask_sel[LATENCY-1] == 2'b01) begin // use 64 PEs, 1/2 , 32-64, output 64 channels, we use 32
				                result_sel_count[core_2] <= 2'd0;
				            end else begin // full, use 128 PE, 32-64, we use all 64 channels
				                if(iResult_valid[32*core_2] || (|result_sel_count[core_2])) begin
				                    if(result_sel_count[core_2] == 2'b01)
                                        result_sel_count[core_2] <= 2'd0;
                                    else
                                        result_sel_count[core_2] <= result_sel_count[core_2] + 1'b1;
                                end
                            end
                        end
                    2:  result_sel_count[core_2] <= 2'd0;
		            3:	begin
				            if(iResult_valid[32*core_2] || (|result_sel_count[core_2])) begin
				                if(result_sel_count[core_2] == 2'b01)
                                    result_sel_count[core_2] <= 2'd0;
                                else
                                    result_sel_count[core_2] <= result_sel_count[core_2] + 1'b1;
                            end
                        end
                    default:
                        result_sel_count[core_2] <= 2'd0;
               endcase
			end
		end

		//

		always @(posedge clk) begin : valid_dly
			integer m;
			result_out_channel_valid_dly1[core_2][0] <= result_out_channel_valid;
			result_out_channel_valid_dly2[core_2][0] <= result_out_channel_valid_dly1[core_2][0];
			for(m=1;m<8;m=m+1) begin
				result_out_channel_valid_dly1[core_2][m] <= result_out_channel_valid_dly1[core_2][m-1];
				result_out_channel_valid_dly2[core_2][m] <= result_out_channel_valid_dly1[core_2][m];
			end
        end

		for(z=0;z<4;z=z+1) begin : channel_convert
			always @(posedge clk) begin : chc_1
				integer n1;
				result_sel_count_dly[core_2][8*z] <= result_sel_count[core_2];
				for(n1=1;n1<8;n1=n1+1) begin
					result_sel_count_dly[core_2][8*z+n1] <= result_sel_count_dly[core_2][8*z+n1-1];
				end
			end
		end

		for(z2=0;z2<8;z2=z2+1) begin
			for(z1=0;z1<4;z1=z1+1) begin : channel_convert1
				always @(posedge clk) begin
					case(pe_interconnection_mode_dly_rep[core_2])
						0 : 
							result_out_channel_rep1[core_2][4*z2+z1]  
								<= (result_sel_count_dly[core_2][z1*8+z2] == 2'b00) ? result_store_reg[core_2][4*(z1+4*z2)+0] :
                                   (result_sel_count_dly[core_2][z1*8+z2] == 2'b01) ? result_store_reg[core_2][4*(z1+4*z2)+1] :
                                   (result_sel_count_dly[core_2][z1*8+z2] == 2'b10) ? result_store_reg[core_2][4*(z1+4*z2)+2] :
																					  result_store_reg[core_2][4*(z1+4*z2)+3] ;
						1 : 
							result_out_channel_rep1[core_2][4*z2+z1] 
								<= result_sel_count_dly[core_2][z1*8+z2][0] ?   result_store_reg[core_2][4*(z1+4*z2)+3] : 
																				result_store_reg[core_2][4*(z1+4*z2)+1];
						2 :
							result_out_channel_rep1[core_2][4*z2+z1] <= result_store_reg[core_2][4*(z1+4*z2)+3];
						3 : 
							result_out_channel_rep1[core_2][4*z2+z1] 
								<= result_sel_count_dly[core_2][z1*8+z2][0] ?   result_store_reg[core_2][4*(z1+4*z2)+3] : 
																				result_store_reg[core_2][4*(z1+4*z2)+1];
						default:
							result_out_channel_rep1[core_2][4*z2+z1] <= result_store_reg[core_2][4*(z1+4*z2)+3];
					endcase

					result_out_channel_rep4[core_2][4*z2+z1] <= result_store_reg[core_2][4*z2+z1];

					if(is_branch_add_enable_dly_rep[core_2][(4*z2+z1)/2]) begin
						result_out_channel[core_2][4*z2+z1] <= result_out_channel_rep4[core_2][4*z2+z1];
					end else begin		
						result_out_channel[core_2][4*z2+z1] <= result_out_channel_rep1[core_2][4*z2+z1];
					end
				end
			end
		end
	end
endgenerate

reg		[1:0]	specific_count;
reg		[9:0]	num_in_each_row;
reg		[7:0]	mask_valid;
wire	[1:0]	specific_count_max;

assign 	specific_count_max = is_32_mode_dly[LATENCY-1] ? 2'd1 : 2'd3;

always @(posedge clk) begin
	if(rst)
		specific_count <= 2'd0;
	else if((is_specific_enable_dly[LATENCY-1] || is_32_mode_dly[LATENCY-1]) & result_out_channel_valid_dly1[0][0]) begin
		if(specific_count == specific_count_max)
			specific_count <= 2'd0;
		else 
			specific_count <= specific_count + 1'b1;
	end
end

always @(posedge clk) begin
	if(rst)
		num_in_each_row <= 0;
	else if((is_specific_enable_dly[LATENCY-1] || is_32_mode_dly[LATENCY-1]) & result_out_channel_valid_dly1[0][0] & (specific_count == specific_count_max) ) begin
		if(num_in_each_row == num_each_row_dly[LATENCY-1])
			num_in_each_row <= 10'd0;
		else
			num_in_each_row <= num_in_each_row + 1'b1;
	end
end

always @(posedge clk) begin : m_loop
	integer m_l;
	mask_valid[0] <= ~((is_specific_enable_dly[LATENCY-1] || is_32_mode_dly[LATENCY-1]) & result_out_channel_valid_dly1[0][0] &
			           (num_in_each_row == num_each_row_dly[LATENCY-1]) & (specific_count > specific_sel_mask_dly[LATENCY-1]));
	for(m_l=1;m_l<8;m_l=m_l+1) begin
		mask_valid[m_l] <= mask_valid[m_l-1];
	end
end


genvar n;
generate
	genvar core_4;
	for(core_4=0;core_4<N;core_4=core_4+1) begin
	    assign	oRe_organized_valid[core_4*8+:8] = is_branch_add_enable_dly_rep[core_4][0] ? 
	                                               {{4{result_out_channel_valid_dly2[core_4][1] & mask_valid[1]}},
	                                                {4{result_out_channel_valid_dly2[core_4][0] & mask_valid[0]}}
	                                               } : 
	                                               {result_out_channel_valid_dly2[core_4][7] & mask_valid[7],
													result_out_channel_valid_dly2[core_4][6] & mask_valid[6],
													result_out_channel_valid_dly2[core_4][5] & mask_valid[5],
													result_out_channel_valid_dly2[core_4][4] & mask_valid[4],
													result_out_channel_valid_dly2[core_4][3] & mask_valid[3],
													result_out_channel_valid_dly2[core_4][2] & mask_valid[2],
													result_out_channel_valid_dly2[core_4][1] & mask_valid[1],
													result_out_channel_valid_dly2[core_4][0] & mask_valid[0]};
		for(n=0;n<32;n=n+1) begin: out
			assign	oRe_organized_result[core_4*(2*`DATAWIDTH+4)*32 + n*(`DATAWIDTH*2+4)+:(`DATAWIDTH*2+4)] = result_out_channel[core_4][n];
		end
	end
endgenerate


