module	pooling_array #(parameter CH_NUM = 32,
					    parameter DATAWIDTH = 8,
						parameter N = 8)
		(
			input							clk,
			input							rst,
			//input				iData_from_output_buf,
			input   [1:0]					iPooling_channel_mode,
			input							iS_average_pooling,
			input   [7:0]					iAverage_pooling_weight,       
			input	[CH_NUM*DATAWIDTH*N-1:0]iData,
			input	[N*8-1:0]				iData_valid,
			input	[N*8-1:0]				iAcc_clear,

			output	[CH_NUM*DATAWIDTH*N-1:0]	oResult,
			output	[8*N-1:0]					oResult_valid
		);

wire	[CH_NUM*N-1:0]	result_valid;
wire	[CH_NUM*DATAWIDTH*2*N-1:0]	result;


(*keep="true"*)reg		[1:0]			pooling_channel_mode_core [N-1:0][CH_NUM-1:0];
(*keep="true"*)reg						is_average_pooling_core [N-1:0][CH_NUM-1:0];
(*keep="true"*)reg		[7:0]			average_pooling_weight_core [N-1:0][CH_NUM-1:0];

reg     [CH_NUM/4-1:0]                  is_average_pooling_dly;
reg     [1:0]                           pooling_channel_mode_dly[CH_NUM/4-1:0];
reg     [7:0]                           average_pooling_weight_dly[CH_NUM/4-1:0];



always @(posedge clk) begin : dly
    integer i;
    is_average_pooling_dly[0] <= iS_average_pooling;
    pooling_channel_mode_dly[0] <= iPooling_channel_mode;
    average_pooling_weight_dly[0] <= iAverage_pooling_weight;
    for(i=1;i<CH_NUM/4;i=i+1) begin
        is_average_pooling_dly[i] <= is_average_pooling_dly[i-1];
        pooling_channel_mode_dly[i] <= pooling_channel_mode_dly[i-1];
        average_pooling_weight_dly[i] <= average_pooling_weight_dly[i-1];
    end
end

integer j,k,kj;
always @(posedge clk) begin
	for(k=0;k<N;k=k+1) begin
		for(kj=0;kj<CH_NUM;kj=kj+1) begin
			is_average_pooling_core[k][kj] <= is_average_pooling_dly[kj/4];
			pooling_channel_mode_core[k][kj] <= pooling_channel_mode_dly[kj/4];
			average_pooling_weight_core[k][kj] <= average_pooling_weight_dly[kj/4];
		end
	end
end
genvar i,core;

generate
	for(core=0;core<N;core=core+1) begin
	for(i=0;i<CH_NUM;i=i+1) begin : pool
		pooling_unit #(.DATAWIDTH(2*DATAWIDTH))
			unit (
				.clk(clk),
				.rst(rst),
				//.iData_from_output_buf(data_from_output_buf_dly[6]),
				.iPooling_channel_mode(pooling_channel_mode_core[core][i]),
				.iS_average_pooling(is_average_pooling_core[core][i]),
				.iAverage_pooling_weight(average_pooling_weight_core[core][i]),
				.iData({{DATAWIDTH{iData[CH_NUM*DATAWIDTH*core + (i+1)*DATAWIDTH-1]}},iData[CH_NUM*DATAWIDTH*core + i*DATAWIDTH+:DATAWIDTH]}),
				.iData_valid({2{iData_valid[core*8+i/4]}}),
				.iClear({2{iAcc_clear[core*8+i/4]}}),
				.oResult(result[CH_NUM*DATAWIDTH*2*core+i*DATAWIDTH*2+:DATAWIDTH*2]),
				.oResult_valid(result_valid[CH_NUM*core + i])
			);   

		assign	oResult[CH_NUM*DATAWIDTH*core+i*DATAWIDTH+:DATAWIDTH] = result[CH_NUM*DATAWIDTH*2*core+i*DATAWIDTH*2+:DATAWIDTH];
		if(i%4 == 0)
		   assign	oResult_valid[8*core+i/4] = result_valid[core*CH_NUM+i];
	end


	end
endgenerate
