module pooling_unit #(parameter	DATAWIDTH = 16) (
		//
			input					clk,
			input					rst,
		//
			input   [1:0]           iPooling_channel_mode,
			input                   iS_average_pooling,
			input   [7:0]           iAverage_pooling_weight,
			input	[DATAWIDTH-1:0]	iData,
			input	[1:0]			iData_valid,
			input	[1:0]			iClear,

			output	reg [DATAWIDTH-1:0]	oResult,
			output	reg 		    oResult_valid
		);


reg		[DATAWIDTH-1:0]	data_reg [3:0];

initial begin 
    data_reg[0] = 8'h80;
    data_reg[1] = 8'h80;
    data_reg[2] = 8'h80;
    data_reg[3] = 8'h80;
end 

reg		[DATAWIDTH-1:0]	data_output [3:0];

reg		[1:0]			count;
reg		[1:0]			count_output;
reg 					count_output_valid;

wire	[DATAWIDTH-1:0]	max_data [3:0];
reg 	[DATAWIDTH-1:0]	data_sel_to_compare;

(*keep="true"*)reg				clear [3:0];
reg     [1:0]   pooling_channel_mode_dly [3:0];
reg     [7:0]   average_pooling_weight_dly [4:0];
reg             is_average_pooling_dly [4:0];
always @(posedge clk) begin

	pooling_channel_mode_dly[0] <= iPooling_channel_mode;
	pooling_channel_mode_dly[1] <= pooling_channel_mode_dly[0];
	pooling_channel_mode_dly[2] <= pooling_channel_mode_dly[1];
	pooling_channel_mode_dly[3] <= pooling_channel_mode_dly[2];

	average_pooling_weight_dly[0] <= iAverage_pooling_weight;
	average_pooling_weight_dly[1] <= average_pooling_weight_dly[0];
	average_pooling_weight_dly[2] <= average_pooling_weight_dly[1];
	average_pooling_weight_dly[3] <= average_pooling_weight_dly[2];
	average_pooling_weight_dly[4] <= average_pooling_weight_dly[3];

	is_average_pooling_dly[0] <= iS_average_pooling;
	is_average_pooling_dly[1] <= is_average_pooling_dly[0];
	is_average_pooling_dly[2] <= is_average_pooling_dly[1];
	is_average_pooling_dly[3] <= is_average_pooling_dly[2];
	is_average_pooling_dly[4] <= is_average_pooling_dly[3];
end

always @(posedge clk) begin
	clear[0] <= iClear[0];
	clear[1] <= iClear[1];
	clear[2] <= iClear[0];
	clear[3] <= iClear[1];
end

always @(posedge clk)
    case(iPooling_channel_mode)
        2'd0:   count <= 2'd0;
        2'd1:
            begin
                if(iData_valid[0] & (count == 2'd1))
                    count <= 2'd0;
                else if(iData_valid[0])
                    count <= count + 1'b1;
            end
        2'd2:
            begin
                if(iData_valid[0] & (count == 2'd2))
                    count <= 2'd0;
                else if(iData_valid[0])
                    count <= count + 1;
            end
        2'd3:
            begin
                if(iData_valid[0] & (count == 2'd3))
                    count <= 2'd0;
                else if(iData_valid[0])
                    count <= count + 1'b1;
            end
        default: count <= 2'd0;
   endcase

genvar i;

generate
    for(i=0;i<4;i=i+1) begin: gen_loop

        always @(posedge clk)
            if(rst)
                data_reg[i] <= {1'b1, {(DATAWIDTH-1){1'b0}}};
            else if(iS_average_pooling & (~iData_valid[1]))
                data_reg[i] <= {DATAWIDTH{1'b0}} ;
            else if(iData_valid[1] & clear[0])
                data_reg[i] <= iS_average_pooling ? {DATAWIDTH{1'b0}} : {1'b1, {(DATAWIDTH-1){1'b0}}};
            else if(iData_valid[1] && (count == i))
                data_reg[i] <= max_data[i];
    end
endgenerate

always @(posedge clk) begin
	if(iData_valid[0] & clear[0]) begin
		data_output[0] <= (iPooling_channel_mode == 2'd0) ? max_data[0] : data_reg[0];
		data_output[1] <= (iPooling_channel_mode == 2'd1) ? max_data[1] : data_reg[1];
		data_output[2] <= data_reg[2];
		data_output[3] <= max_data[3];
	end 
end

always @(*) begin
    case(count)
        2'd0:   data_sel_to_compare = data_reg[0];
        2'd1:   data_sel_to_compare = data_reg[1];
        2'd2:   data_sel_to_compare = data_reg[2];
        2'd3:   data_sel_to_compare = data_reg[3];
       default: data_sel_to_compare = data_reg[0];
    endcase
end

genvar rep_i;
generate
	for(rep_i=0;rep_i<4;rep_i=rep_i+1) begin
		assign	max_data[rep_i] = iS_average_pooling ? iData + data_sel_to_compare : 
		                          (~iData[DATAWIDTH-1]) & (data_sel_to_compare[DATAWIDTH-1]) ? iData :
		                          iData[DATAWIDTH-1] & (~data_sel_to_compare[DATAWIDTH-1]) ?  data_sel_to_compare :
								  (iData > data_sel_to_compare) ? iData : data_sel_to_compare;
	end
endgenerate

always @(posedge clk)
	count_output_valid <= iData_valid[0] & clear[1];

/*always @(posedge clk)
	if(rst)
		count_output <= 2'd0;
	else if(count_output_valid || (|count_output))
		count_output <= count_output + 1;*/

always @(posedge clk)
    if(rst)
        count_output <= 4'd0;
    else if(count_output_valid || (|count_output))
        case(pooling_channel_mode_dly[3])
            2'd0:   count_output <= 2'd0;
            2'd1:
                begin
                    if(count_output == 2'd1)
                        count_output <= 2'd0;
                    else
                        count_output <= count_output + 1;
                end
            2'd2:
                begin
                    if(count_output == 2'd2)
                        count_output <= 2'd0;
                    else
                        count_output <= count_output + 1;
                end
            2'd3:
                begin
                    if(count_output == 2'd3)
                        count_output <= 2'd0;
                    else
                        count_output <= count_output + 1;
                end
            default: count_output <= 2'd0;
        endcase

reg     [DATAWIDTH-1:0] result;
reg                     result_valid,result_valid_dly;
wire    [24:0]          average_mult;
always @(posedge clk)
    case(count_output)
        4'd0:   result <= data_output[0];
        4'd1:   result <= data_output[1];
        4'd2:   result <= data_output[2];
        4'd3:   result <= data_output[3];
                default: result <= data_output[0];
    endcase


always @(posedge clk) begin
	result_valid <= count_output_valid || (|count_output);
    result_valid_dly <= result_valid;
end


average_mult average_pool_mult (
    .CLK(clk),
    .A(result),
    .B(average_pooling_weight_dly[4]),
    .P(average_mult)
);

always @(posedge clk) begin
    oResult <= is_average_pooling_dly[4] ? average_mult[23:8] + average_mult[7] : result; 
    oResult_valid <= is_average_pooling_dly[4] ? result_valid_dly : result_valid;
end

/*

// round(a*w) or a
average_mult_sel average_pool_mult (
    .CLK(clk),
    .SEL(is_average_pooling_dly[3]),
    .CARRYIN(~result[DATAWIDTH-1]),
    .A(result),
    .B(average_pooling_weight_dly[4]),
    .C(8'b01111111),
    .P(average_mult)
);

assign  oResult = average_mult[23:8];
always @(posedge clk)
    oResult_valid <= result_valid_dly;

*/    
endmodule

`include "fucore.vh"
module	pre_pe (
		//global signals
			input							clk_sys,
			input							clk_dsp,
			input							rst,
		//
			input	[`DATAWIDTH-1:0]		iData_b1,
			input	[`DATAWIDTH-1:0]		iData_b2,
			input	[`DATAWIDTH-1:0]		iData_b3,
			input	[`DATAWIDTH-1:0]		iData_b4,

			input	[5:0]					iParam_rd_addr,	// {pingpong,addr} = {1bit, 5bit}
			input							iParam_tdm_sel,	// time-division-multiplexing select signal
		// write param signals
			input							iParam_wr_enable,
			input	[6:0]					iParam_wr_addr, // {fre-domain,addr} = {1bit, 6bit}
			input	[`DATAWIDTH*8-1:0]		iParam_wr_data,
