    dsa_input_set_sync[1] <= dsa_input_set_sync[0];
    dsa_input_set_sync[2] <= dsa_input_set_sync[1];
    dsa_input_status_set <= dsa_input_set_sync[1] & (~dsa_input_set_sync[2]);
