assign	result_write_instr_stop = result_write_instr_count > 4'd9;


Asy_fifo_addr    write_addr_inst(
	.rst(!app_aresetn),
	.wr_clk(app_clk),
	.rd_clk(c0_ddr_clk),
	.din(result_write_instr_addr),
	.wr_en(result_write_instr_valid),
	.rd_en(write_inst_fetch),
	.dout(result_inst_fetch_addr),
	.full(),
	.empty(result_write_instr_empty),
	.wr_data_count(result_write_instr_count)
);

Asy_wr_fifo_len    write_len_inst(
	.rst(!app_aresetn),
	.wr_clk(app_clk),
	.rd_clk(c0_ddr_clk),
	.din({result_write_instr_is_final_result,result_write_instr_len}), // 11 bit
	.wr_en(result_write_instr_valid),
	.rd_en(write_inst_fetch),
	.dout({result_inst_fetch_is_final,result_inst_fetch_len}),
	.full(),
	.empty()
);

genvar rw,rw_i;
generate
	for(rw=0;rw<FUCORE_NUM;rw=rw+1) begin
		for(rw_i=0;rw_i<8;rw_i=rw_i+1) begin
			result_data_fifo result_fifo_inst (
				.wr_clk(app_clk),
				.rd_clk(c0_ddr_clk),
				.rst(!app_aresetn),
				.wr_en(result_write_data_valid[rw*8+rw_i]),
				.din(result_write_data[rw*256+rw_i*32+:32]),
				.rd_en(data_fifo_rd[rw]),
				.dout(data_fifo_data_t[rw][rw_i*64+:64]),
				.empty(data_fifo_empty[rw*8+rw_i]),
				.full(),
				.prog_full(result_write_data_stop_t[rw*8+rw_i])
			);
		end
		assign	data_fifo_rd[rw] = (ddr_write_rd | dsa_write_data_rd) & (ddr_write_sel == 2'd0) & (write_data_for_core_count == rw);
		assign	result_write_data_stop[rw] = result_write_data_stop_t[rw*8];
	    assign  data_fifo_data[rw] = { data_fifo_data_t[rw][14*32+:32],
		                               data_fifo_data_t[rw][12*32+:32],
		                               data_fifo_data_t[rw][10*32+:32],
		                               data_fifo_data_t[rw][8*32+:32],
		                               data_fifo_data_t[rw][6*32+:32],
		                               data_fifo_data_t[rw][4*32+:32],
		                               data_fifo_data_t[rw][2*32+:32],
		                               data_fifo_data_t[rw][0*32+:32],
		                               data_fifo_data_t[rw][15*32+:32],
		                               data_fifo_data_t[rw][13*32+:32],
		                               data_fifo_data_t[rw][11*32+:32],
		                               data_fifo_data_t[rw][9*32+:32],
		                               data_fifo_data_t[rw][7*32+:32],
		                               data_fifo_data_t[rw][5*32+:32],
		                               data_fifo_data_t[rw][3*32+:32],
		                               data_fifo_data_t[rw][1*32+:32] };                           
	end

	always @(posedge c0_ddr_clk) begin
	    ddr_write_data_dly <= ddr_write_data;
	    ddr_write_data_valid_dly[0] <= ddr_write_rd;
	    ddr_write_data_valid_dly[1] <= ddr_write_data_valid_dly[0];
	    ddr_write_data_valid_dly[2] <= ddr_write_data_valid_dly[1];
	    ddr_write_result_valid <= ddr_write_rd & (ddr_write_sel == 2'd0);
	end

	if(FUCORE_NUM == 1) begin
		always @(*) begin
		/*
			data_fifo_sel_empty = (|data_fifo_empty) & (ddr_write_sel == 2'd0) ||
			                      mac_write_data_empty & (ddr_write_sel == 2'd1);
			                      */
			data_fifo_sel_empty = (|data_fifo_empty) & (ddr_write_sel == 2'd0);			                 
		end
		always @(posedge c0_ddr_clk)
		    case(ddr_write_sel)
		      2'd0: ddr_write_data <= data_fifo_data[0];
		      //2'd1: ddr_write_data <= mac_write_data_dout;
		      //default: ddr_write_data <= mac_write_data_dout;
		      2'd1: ddr_write_data <= 'b0;
		      default: ddr_write_data <= 'b0;
		    endcase

	end else if(FUCORE_NUM == 2) begin
		always @(*) begin
		    if(ddr_write_sel == 2'd0) 
			    if(write_data_for_core_count[1:0] == 0) begin
				    data_fifo_sel_empty = |data_fifo_empty[7:0];
			    end else begin
				    data_fifo_sel_empty = |data_fifo_empty[15:8];
	            end
	        else
	            //data_fifo_sel_empty = mac_write_data_empty;
	            data_fifo_sel_empty = 1'b1;

		end
		always @(posedge c0_ddr_clk) 
		    case(ddr_write_sel)
		       2'd0: begin 
		                 if(write_data_for_core_count[1:0] == 0)
		                     ddr_write_data <= data_fifo_data[0];
		                 else
		                     ddr_write_data <= data_fifo_data[1];
		             end
		       //2'd1: ddr_write_data <= mac_write_data_dout;
		       //default: ddr_write_data <= mac_write_data_dout;
		       2'd1: ddr_write_data <= 'b0;
		       default: ddr_write_data <= 'b0;
		    endcase
	end else if(FUCORE_NUM == 3) begin
		always @(*) begin
		    if(ddr_write_sel == 2'd0) 
			    case(write_data_for_core_count[1:0])
				    2'd0 : 
				        data_fifo_sel_empty = |data_fifo_empty[7:0];
				    2'd1 : 
				        data_fifo_sel_empty = |data_fifo_empty[15:8];
				    2'd2 : 
				        data_fifo_sel_empty = |data_fifo_empty[23:16];
				    default: 
				        data_fifo_sel_empty = |data_fifo_empty[7:0];
				endcase
			else
			    //data_fifo_sel_empty = mac_write_data_empty;
			    data_fifo_sel_empty = 1'b1;
		end
		always @(posedge c0_ddr_clk)
		    case(ddr_write_sel)
		        2'd0: begin
		                  case(write_data_for_core_count[1:0])
		                      2'd0 :
		                          ddr_write_data <= data_fifo_data[0];
		                      2'd1 :
		                          ddr_write_data <= data_fifo_data[1];
		                      2'd2 :
		                          ddr_write_data <= data_fifo_data[2];
		                      default:
		                          ddr_write_data <= data_fifo_data[0];
		                  endcase
		              end
		        //2'd1: ddr_write_data <= mac_write_data_dout;
		        //default: ddr_write_data <= mac_write_data_dout;
		        2'd1: ddr_write_data <= 'b0;
		        default : ddr_write_data <= 'b0;
		    endcase
	end else if(FUCORE_NUM == 4) begin
		always @(*) begin
		    if(ddr_write_sel == 2'd0)
			    case(write_data_for_core_count[1:0])
				    2'd0 : 
				        data_fifo_sel_empty = |data_fifo_empty[7:0];
				    2'd1 : 
				        data_fifo_sel_empty = |data_fifo_empty[15:8];
				    2'd2 : 
				        data_fifo_sel_empty = |data_fifo_empty[23:16];
				    2'd3 :
				        data_fifo_sel_empty = |data_fifo_empty[31:24];
				    default: 
				        data_fifo_sel_empty = |data_fifo_empty[7:0];
				endcase
			else
			    //data_fifo_sel_empty = mac_write_data_empty;
			    data_fifo_sel_empty = 1'b1;
		end
		always @(posedge c0_ddr_clk)
		    case(ddr_write_sel)
		        2'd0: begin
		                  case(write_data_for_core_count[1:0])
		                      2'd0 :
		                          ddr_write_data <= data_fifo_data[0];
		                      2'd1 :
		                          ddr_write_data <= data_fifo_data[1];
		                      2'd2 :
		                          ddr_write_data <= data_fifo_data[2];
		                      2'd3 :
		                          ddr_write_data <= data_fifo_data[3];
		                      default:
		                          ddr_write_data <= data_fifo_data[0];
		                  endcase
		              end
		        //2'd1:
		        //    ddr_write_data <= mac_write_data_dout;
		        //default: ddr_write_data <= mac_write_data_dout;
		        2'd1:
		            ddr_write_data <= 'b0;
		        default: ddr_write_data <= 'b0;
		    endcase	
	end
endgenerate



always @(posedge c0_ddr_clk)
 begin
    if(!c0_ddr_aresetn)
	   mst_exect_wstate <= IDLE;
    else begin
		case(mst_exect_wstate)
			IDLE:
				if(write_inst_req)
					mst_exect_wstate <= READ_INST;		// if inst fifo is not empty, enter execute state
				else
					mst_exect_wstate <= IDLE;
			READ_INST:
			    mst_exect_wstate <= GET_INST;
            GET_INST:
				mst_exect_wstate <= WAIT_DATA;			// read address and length from inst fifo
			WAIT_DATA:
				//if(~data_fifo_sel_empty)				// wait until result fifo has data 
					mst_exect_wstate <= EXECUTE_TRAN;
				//else
				//	mst_exect_wstate <= WAIT_DATA;
			EXECUTE_TRAN:
				if(ddr_write_data_over)					// complete a transfer
					mst_exect_wstate <= TRAN_OVER;
				else
					mst_exect_wstate <= EXECUTE_TRAN;
			TRAN_OVER:									// check if all the data an inst required has been transfered
				if(finish_write_inst & (~multi_core_write_flag) || finish_write_inst & multi_core_write_flag & (write_data_for_core_count == FUCORE_NUM - 1))
					mst_exect_wstate <= IDLE;
				else
					mst_exect_wstate <= GET_INST;
			default: mst_exect_wstate <= IDLE;
		endcase
	end
	mst_exect_wstate_dly <= mst_exect_wstate;
end
/*
assign  write_inst_req = (~result_write_instr_empty) & ctrl_valid_dly[2] & (~final_result_queue_almost_full) & (~data_fifo_empty[7]) ||
                         (~mac_write_dma_empty);

assign  ddr_write_priority_flag =  {(~result_write_instr_empty) & ctrl_valid_dly[2] & (~final_result_queue_almost_full) & (~data_fifo_empty[7]),
                                    ~mac_write_dma_empty};
*/

assign  write_inst_req = (~result_write_instr_empty)  & (~final_result_queue_almost_full) & (~data_fifo_empty[7]);

assign  ddr_write_priority_flag =  {(~result_write_instr_empty) & (~final_result_queue_almost_full) & (~data_fifo_empty[7]),
                                    1'b0};

always @(posedge c0_ddr_clk) begin
    if(~c0_ddr_aresetn)
        ddr_write_sel <= 0;
    else if((mst_exect_wstate == IDLE) && write_inst_req) begin
        casex(ddr_write_priority_flag)
            2'b1x : ddr_write_sel <= 2'd0;
            2'b01 : ddr_write_sel <= 2'd1;
        endcase
    end
end

assign  write_inst_fetch = (mst_exect_wstate == READ_INST) && (ddr_write_sel == 2'd0);
//assign  mac_write_dma_rd_en = (mst_exect_wstate == READ_INST) &&  (ddr_write_sel == 2'd1);

always @(posedge c0_ddr_clk) begin	
	/*write_inst_valid <= write_inst_fetch  || (multi_core_write_flag & finish_write_inst & (write_data_for_core_count != FUCORE_NUM-1)) ||
	                    mac_write_dma_rd_en;
	 */

	write_inst_valid <= write_inst_fetch  || (multi_core_write_flag & finish_write_inst & (write_data_for_core_count != FUCORE_NUM-1));                    
    write_inst_valid_dly <= write_inst_valid;
end

always @(posedge c0_ddr_clk)
    if(!c0_ddr_aresetn)
        multi_core_write_flag <= 1'b0;
    else if(write_inst_fetch)    
        multi_core_write_flag <= 1'b1;
    else if(finish_write_inst & (ddr_write_sel == 2'd0) & (write_data_for_core_count == FUCORE_NUM-1)) 
        multi_core_write_flag <= 1'b0;   


always @(posedge c0_ddr_clk) begin
	if(!c0_ddr_aresetn)
		write_data_for_core_count <= 0;
	else if(finish_write_inst & (ddr_write_sel == 2'd0) ) begin
		if(write_data_for_core_count == FUCORE_NUM-1)
			write_data_for_core_count <= 0;
		else
			write_data_for_core_count <= write_data_for_core_count + 1;
	end
end

always @(posedge c0_ddr_clk) begin
	if(!c0_ddr_aresetn)
		multicore_write_offset_addr <= 32'd0;
	else if(finish_write_inst & (ddr_write_sel == 2'd0) & multi_core_write_flag) begin
		if(write_data_for_core_count == FUCORE_NUM-1)
			multicore_write_offset_addr <= 32'd0;
		else
			multicore_write_offset_addr <= multicore_write_offset_addr + (ctrl_addrspace_len_eachcore << 3); // queue depth is 8, leftshift 8
	end
end

always @(posedge c0_ddr_clk) begin
	if(~c0_ddr_aresetn)
		final_result_count <= 32'd0;
	else if((result_inst_fetch_is_final == 2'b01) & ddr_write_result_valid) begin
		if(final_result_meet_border)
			final_result_count <= 0;
		else
			final_result_count <= final_result_count + 1;
	end
end

assign	final_result_meet_border = (final_result_count == (ctrl_result_len>>3)-1);


always @(posedge c0_ddr_clk) 
	if(~c0_ddr_aresetn)
		final_result_status_set <= 1'b0;
	else if(finish_write_inst & (ddr_write_sel == 2'd0))
		final_result_status_set <= 1'b0;
	else if(final_result_meet_border & (result_inst_fetch_is_final == 2'b01) & ddr_write_result_valid)
		final_result_status_set <= 1'b1;


assign  final_result_queue_incr = final_result_status_set & finish_write_inst & (ddr_write_sel == 2'd0); 

assign  final_result_queue_almost_full = final_result_queue_sel >= 6;



reg     final_result_queue_decr_sync [2:0];




always @(posedge c0_ddr_clk) begin
    final_result_queue_decr_sync[0] <= cnn0_result_batch_clear;
    final_result_queue_decr_sync[1] <= final_result_queue_decr_sync[0];
    final_result_queue_decr_sync[2] <= final_result_queue_decr_sync[1];
    //

end

//assign  cfg_change =  |config_change_enable_dly; 

assign  final_result_queue_decr = final_result_queue_decr_sync[1] & (~final_result_queue_decr_sync[2]); 
assign  cnn0_result_count = final_result_queue_sel; 

always @(posedge c0_ddr_clk)
	if(~c0_ddr_aresetn)
		final_result_queue_sel <= 3'b0;
	else begin
	   if(final_result_queue_incr & (~final_result_queue_decr))
	       final_result_queue_sel <= final_result_queue_sel + 1;
	   else if((~final_result_queue_incr) & final_result_queue_decr)
	       final_result_queue_sel <= final_result_queue_sel - 1;
	   else
	       final_result_queue_sel <= final_result_queue_sel;

	end

always @(posedge c0_ddr_clk)
    if(~c0_ddr_aresetn)
        cnn0_final_result_queue_incr_count <= 3'd0;
    else if(final_result_queue_incr)
        cnn0_final_result_queue_incr_count <= cnn0_final_result_queue_incr_count + 1;



//assign	result_status = final_result_status;

assign	ddr_write_data_over = write_finish_flag || (dsa_op1_write_flag & dsa_op1_write_ready & dsa_op1_write_count_hit_border);

//always @(posedge c0_ddr_clk)//
//	finish_write_inst <= ddr_write_data_over;
assign  finish_write_inst = (mst_exect_wstate == TRAN_OVER) && (wr_inst_req_length == 11'h0);




// for 512 bit, leftshift 3 bit, for 256 bit, leftshift 2 bit
//assign  ddr_write_len_sel = ({1'b0,result_inst_fetch_len}>>3) + 1;

always @(posedge c0_ddr_clk)
    case(ddr_write_sel)
        2'd0:   ddr_write_len_sel <= result_inst_fetch_len;
        2'd1:   ddr_write_len_sel <= 'b0;
        default: ddr_write_len_sel <= ddr_write_len_sel;                
    endcase

wire    [10:0]  ddr_write_len_sel_orig;

assign  ddr_write_len_sel_orig = ddr_write_len_sel + 1;

always @(posedge c0_ddr_clk) begin
	if(!c0_ddr_aresetn)
		wr_inst_req_length <= 11'h0;
	else begin
		if(write_inst_valid_dly)
			wr_inst_req_length <= (ddr_write_len_sel_orig>>3) + ddr_write_len_sel_orig[2]; 
		else if(ddr_write_data_over)
			wr_inst_req_length <= wr_inst_req_length - wr_tran_len;
	end
end

always @(posedge c0_ddr_clk) begin
	if(!c0_ddr_aresetn)
		wr_tran_len <= 8'h0;
	else begin
		if(mst_exect_wstate_dly == GET_INST) begin
            if(write_inst_valid_dly)
                wr_tran_len <= (ddr_write_len_sel >= 11'h3f7) ?  8'h7f : ((ddr_write_len_sel_orig>>3) + ddr_write_len_sel_orig[2]);
            else
			    wr_tran_len <= (wr_inst_req_length >= 11'h7f) ?  8'h7f : wr_inst_req_length;
	    end	else
			wr_tran_len <= wr_tran_len;
	end
end


reg     [31:0]  cnn0_final_result_incr_addr_offset; 
wire    [31:0]  final_result_incr_addr_offset;	

always @(posedge c0_ddr_clk)
    if(cnn0_final_result_queue_incr_count == 3'd0 & (~final_result_queue_incr))
        cnn0_final_result_incr_addr_offset <= 0;
    else if(final_result_queue_incr)
        cnn0_final_result_incr_addr_offset <= cnn0_final_result_incr_addr_offset + ctrl_addrspace_len_eachcore;





assign  final_result_incr_addr_offset =  cnn0_final_result_incr_addr_offset;
//assign  intermediate_result_incr_addr_offset =  cnn0_intermediate_result_incr_addr_offset;

//    

always @(posedge c0_ddr_clk)
    if(write_inst_valid_dly)
        case(ddr_write_sel)
       	    2'd0:
       	        //ddr_write_addr_sel <= ((result_inst_fetch_is_final == 2'b01) ? final_result_incr_addr_offset : 32'b0) + multicore_write_offset_addr + result_inst_fetch_addr;
       	        ddr_write_addr_sel <=  final_result_incr_addr_offset + multicore_write_offset_addr + result_inst_fetch_addr;
		    2'd1:
		        //ddr_write_addr_sel <= mac_write_dma_addr_dout;
		        ddr_write_addr_sel <= 'b0;
		    default:
		        ddr_write_addr_sel <= ddr_write_addr_sel;
		endcase   
	else if(ddr_write_data_over) 
        ddr_write_addr_sel <= ddr_write_addr_sel + (wr_tran_len << 3); //for 512 bit, rightshift 3 bit, for 256 bit, rightshift 2 bit


always @(posedge c0_ddr_clk) begin
	issue_write_tran_dly[0] <= (mst_exect_wstate == GET_INST) && (~(result_inst_fetch_is_final == 2'b11)); // not dsa-op1
	issue_write_tran_dly[1] <= issue_write_tran_dly[0];
end

assign ddr_write_enable = issue_write_tran_dly[1];
assign ddr_write_cnt = wr_tran_len;
assign ddr_write_addr = ddr_write_addr_sel << 3;	// convert from 64 bit to 8bit

// dsa-op1 write data processing 
reg     dsa_op1_bitwidth_converter_flag;
wire    dsa_output_fifo_empty;
wire    dsa_output_fifo_full;

always @(posedge c0_ddr_clk) begin 
    issue_dsa_op1_write_tran_dly[0] <= (mst_exect_wstate == GET_INST) && (result_inst_fetch_is_final == 2'b11);
    issue_dsa_op1_write_tran_dly[1] <= issue_dsa_op1_write_tran_dly[0];
    if (issue_dsa_op1_write_tran_dly[1]) 
        dsa_op1_len_store <= wr_tran_len;

    if (~c0_ddr_aresetn)
        dsa_op1_write_flag <= 1'b0;
    else if (issue_dsa_op1_write_tran_dly[1])
        dsa_op1_write_flag <= 1'b1;
    else if (dsa_op1_write_count_hit_border & dsa_op1_write_flag & dsa_op1_write_ready & dsa_op1_bitwidth_converter_flag) 
        dsa_op1_write_flag <= 1'b0; 

    if (~c0_ddr_aresetn)
        dsa_op1_bitwidth_converter_flag <= 1'b0;
    else if (dsa_op1_write_flag) begin
        dsa_op1_bitwidth_converter_flag <= ~dsa_op1_bitwidth_converter_flag;
    end else 
        dsa_op1_bitwidth_converter_flag <= 1'b0;


    if (~c0_ddr_aresetn)
        dsa_op1_write_count <= 8'd0; 
    else if(dsa_op1_write_flag & dsa_op1_write_ready & dsa_op1_bitwidth_converter_flag) begin 
        if (dsa_op1_write_count_hit_border)
            dsa_op1_write_count <= 8'd0;
        else 
            dsa_op1_write_count <= dsa_op1_write_count + 1; 
    end

    dsa_write_data_rd_dly[0] <= dsa_write_data_rd;
    dsa_write_data_rd_dly[1] <= dsa_write_data_rd_dly[0];
    dsa_write_data_rd_dly[2] <= dsa_write_data_rd_dly[1];
    dsa_write_data_rd_dly[3] <= dsa_write_data_rd_dly[2];
end      

assign dsa_op1_write_count_hit_border = dsa_op1_write_count == (dsa_op1_len_store - 1);

assign dsa_write_data_rd = dsa_op1_write_flag & dsa_op1_write_ready & dsa_op1_bitwidth_converter_flag;
