// read ddr state machine

always @(posedge c0_ddr_clk)
    if(!c0_ddr_aresetn)
        multi_core_read_flag <= 1'b0;
    else if(data_read_rd | intermediate_data_read_rd) 
        multi_core_read_flag <= 1'b1;
    else if(finish_read_inst && (read_data_for_core_count == FUCORE_NUM-1))
        multi_core_read_flag <= 1'b0;

always @(posedge c0_ddr_clk)
    if(!c0_ddr_aresetn)
        read_data_for_core_count <= 2'd0;
    else if(multi_core_read_flag & finish_read_inst) begin
        if(read_data_for_core_count == FUCORE_NUM-1)
            read_data_for_core_count <= 2'd0;
        else 
            read_data_for_core_count <= read_data_for_core_count + 1'b1;
    end

always @(posedge c0_ddr_clk)
    if(!c0_ddr_aresetn)
        multi_core_offset_addr <= 32'd0;
    else if(multi_core_read_flag & finish_read_inst) begin
        if(read_data_for_core_count == FUCORE_NUM-1) 
            multi_core_offset_addr <= 32'd0;
        else 
            multi_core_offset_addr <= multi_core_offset_addr +  (ctrl_addrspace_len_eachcore << 3); // queue depth is 8, so left shift 3 bit
    end   


always @(posedge c0_ddr_clk)
 begin
    if(!c0_ddr_aresetn)
	   mst_exect_rstate <= IDLE;
    else begin
		case(mst_exect_rstate)
			IDLE:
				if(read_inst_req)
					mst_exect_rstate <= READ_INST;		// if inst fifo is not empty, enter execute state
				else
					mst_exect_rstate <= IDLE;
			READ_INST:
			    mst_exect_rstate <= GET_INST;
            GET_INST:
				mst_exect_rstate <= WAIT_DATA;			// read address and length from inst fifo
			WAIT_DATA:
				if(read_data_fifo_rdy)							// wait until write data fifo has enough space for a transfer 
					mst_exect_rstate <= EXECUTE_TRAN;
				else
					mst_exect_rstate <= WAIT_DATA;
			EXECUTE_TRAN:
				if(ddr_read_data_over)							// complete a transfer
					mst_exect_rstate <= TRAN_OVER;
				else
					mst_exect_rstate <= EXECUTE_TRAN;
			TRAN_OVER:									// check if all the data an inst required has been transfered
				if(finish_read_inst & (~multi_core_read_flag) || multi_core_read_flag & finish_read_inst & (read_data_for_core_count == FUCORE_NUM-1))
					mst_exect_rstate <= IDLE;
				//else if(rd_inst_req_length == 10'h0)
				//    mst_exect_rstate <= TRAN_OVER;
				else
					mst_exect_rstate <= GET_INST;
			default: mst_exect_rstate <= IDLE;
		endcase
	end
end


always @(posedge c0_ddr_clk)	
    mst_exect_rstate_dly <= mst_exect_rstate;

assign read_inst_req = (((!data_read_empty) & (~batch_data_queue_empty)) | ((!param_read_empty) | (!bias_read_empty) |
                        (!inst_read_empty_channel[0]) | (!inst_read_empty_channel[1]) | (!inst_read_empty_channel[2])  |
                        (!inst_read_empty_channel[3]) | (!inst_read_empty_channel[4]) | (!intermediate_data_read_empty) & (~dsa_data_queue_empty)) & param_data_valid);

//assign read_data_fifo_rdy = (mst_exect_rstate == WAIT_DATA) && (ddr_read_count_sel <= 8'h56);
assign read_data_fifo_rdy = 1'b1;
assign data_read_rd = (mst_exect_rstate == READ_INST) && (ddr_read_sel == 4'd0);
assign param_read_rd = (mst_exect_rstate == READ_INST) && (ddr_read_sel == 4'd2);
assign bias_read_rd = (mst_exect_rstate == READ_INST) && (ddr_read_sel == 4'd1);

assign inst_read_rd_en[0] = (mst_exect_rstate == READ_INST) && (ddr_read_sel == 4'd3);
assign inst_read_rd_en[1] = (mst_exect_rstate == READ_INST) && (ddr_read_sel == 4'd4);
assign inst_read_rd_en[2] = (mst_exect_rstate == READ_INST) && (ddr_read_sel == 4'd5);
assign inst_read_rd_en[3] = (mst_exect_rstate == READ_INST) && (ddr_read_sel == 4'd6);
assign inst_read_rd_en[4] = (mst_exect_rstate == READ_INST) && (ddr_read_sel == 4'd7);

assign intermediate_data_read_rd = (mst_exect_rstate == READ_INST) && (ddr_read_sel == 4'd8);

//assign mac_read_dma_rd_en = (mst_exect_rstate == READ_INST) && (ddr_read_sel == 4'd8);

always @(posedge c0_ddr_clk) begin
	read_inst_valid <= data_read_rd | param_read_rd | bias_read_rd | (|inst_read_rd_en) | intermediate_data_read_rd | (multi_core_read_flag & finish_read_inst & (read_data_for_core_count != FUCORE_NUM-1));
	read_inst_valid_dly <= read_inst_valid;
end
assign ddr_rd_priority_flag = {(~data_read_empty) & (~batch_data_queue_empty),
                               ~bias_read_empty,
                               ~param_read_empty,
                               ~inst_read_empty_channel[0],
                               ~inst_read_empty_channel[1],
                               ~inst_read_empty_channel[2],
                               ~inst_read_empty_channel[3],
                               ~inst_read_empty_channel[4],
                               (~intermediate_data_read_empty) & (~dsa_data_queue_empty)}; // need add code to generate dsa_data_queue_empty
                               //~mac_dma_fifo_empty};

// select read type, 00---data, 01----bias, 10----param, and data has the highest previllge
always @(posedge c0_ddr_clk) begin
	if(~c0_ddr_aresetn)
		ddr_read_sel <= 4'b0;
	else begin
		if((mst_exect_rstate == IDLE) && read_inst_req) begin
		    casex(ddr_rd_priority_flag)
		        9'b1xxxxxxxx : ddr_read_sel <= 4'd0;
		        9'b01xxxxxxx : ddr_read_sel <= 4'd1;
		        9'b001xxxxxx : ddr_read_sel <= 4'd2;
		        9'b0001xxxxx : ddr_read_sel <= 4'd3;
		        9'b00001xxxx : ddr_read_sel <= 4'd4;
		        9'b000001xxx : ddr_read_sel <= 4'd5;
		        9'b0000001xx : ddr_read_sel <= 4'd6;
		        9'b00000001x : ddr_read_sel <= 4'd7;
		        9'b000000001 : ddr_read_sel <= 4'd8;
		    endcase
		end
	end
end
// get the data count & data len  signal of the selected FIFO

always @(posedge c0_ddr_clk) begin
    case(ddr_read_sel)
        4'd0 : 
            begin
                ddr_read_len_sel <= data_read_len_dout;
            end
        4'd1 : 
            begin
                ddr_read_len_sel <= bias_read_len_dout;
            end
        4'd2 : 
            begin
                ddr_read_len_sel <= param_read_len_dout;
            end
        4'd3 : 
            begin
                ddr_read_len_sel <= inst_read_len_dout[0];
            end
        4'd4 : 
            begin
                ddr_read_len_sel <= inst_read_len_dout[1];
            end
        4'd5 : 
            begin
                ddr_read_len_sel <= inst_read_len_dout[2];
            end
        4'd6 : 
            begin
                ddr_read_len_sel <= inst_read_len_dout[3];
            end
        4'd7 : 
            begin
                ddr_read_len_sel <= inst_read_len_dout[4];
            end
        4'd8 :
            begin
                ddr_read_len_sel <= intermediate_data_read_len_dout;
                //ddr_read_len_sel <= 'b0;
            end
        default: 
            begin
                ddr_read_len_sel <= data_read_len_dout;
            end
    endcase
end

// get the data len of the selected FIFO


// get read inst required data length and data length for coming transfer
always @(posedge c0_ddr_clk) begin
	if(!c0_ddr_aresetn)
		rd_inst_req_length <= 10'h0;
	else begin
		if(read_inst_valid_dly)
			rd_inst_req_length <= (ddr_read_len_sel >> 3) + 1'b1; // for 512 bit, leftshift 3 bit, for 256 bit, leftshift 2 bit
		else if(ddr_read_data_over)
			rd_inst_req_length <= rd_inst_req_length - rd_tran_len;
	end
end

always @(posedge c0_ddr_clk) begin
	if(!c0_ddr_aresetn)
		rd_tran_len <= 8'h0;
	else begin
		if(mst_exect_rstate_dly == GET_INST) begin
            if(read_inst_valid_dly) // each cmd read 128x512 bit
                rd_tran_len <= (ddr_read_len_sel >= 10'h3FF) ? 8'h80 : (ddr_read_len_sel >> 3) + 1'b1; // const 10'h3f for 256 bit; const 10'h7f for 512bit; for 512 bit, leftshift 3 bit, for 256 bit, leftshift 2 bit
            else
			    rd_tran_len <= (rd_inst_req_length > 10'h80) ? 8'h80 : rd_inst_req_length; 
	    end	else
			rd_tran_len <= rd_tran_len;
	end
end

assign ddr_read_cnt = rd_tran_len;


assign dsa_input_status_clear = issue_dsa_op1_write_tran_dly[0]; // we use next op1 input as the clear signal, just work for deformable case; 
                                                                 // more checks are needed for other dsa; 
                                                                 // for general purpose, a clear signal should provided from fucore instruction
// get start address from read inst and generate address for every transfer

reg      [32:0]      cnn0_batch_data_queue_addroffset;
wire     [32:0]      batch_data_queue_addroffset;



always @(posedge c0_ddr_clk)
    if((batch_data_read_sel == 3'd0) & (~cnn0_batch_finish_sync_ddr))
        cnn0_batch_data_queue_addroffset <= ctrl_idata_addr;
    else if(cnn0_batch_finish_sync_ddr)
        cnn0_batch_data_queue_addroffset <= cnn0_batch_data_queue_addroffset + ctrl_addrspace_len_eachcore; //ctrl_ncore_image_len;


assign  batch_data_queue_addroffset = cnn0_batch_data_queue_addroffset; 

always @(posedge c0_ddr_clk) begin
	if(!c0_ddr_aresetn)
	    rd_tran_addr <= 'b0;
	else begin
		if(read_inst_valid)
		    case(ddr_read_sel)
			    4'd0:	rd_tran_addr <= batch_data_queue_addroffset + data_read_addr_dout  + multi_core_offset_addr;
				4'd1:	rd_tran_addr <= bias_read_addr_dout + ctrl_param_addr;
				4'd2:	rd_tran_addr <= param_read_addr_dout + ctrl_param_addr;
				4'd3:   rd_tran_addr <= inst_read_addr_dout[0] + ctrl_instr_addr;
				4'd4:   rd_tran_addr <= inst_read_addr_dout[1] + ctrl_instr_addr;
				4'd5:   rd_tran_addr <= inst_read_addr_dout[2] + ctrl_instr_addr;
				4'd6:   rd_tran_addr <= inst_read_addr_dout[3] + ctrl_instr_addr;
				4'd7:   rd_tran_addr <= inst_read_addr_dout[4] + ctrl_instr_addr;
				4'd8:   rd_tran_addr <= batch_data_queue_addroffset + intermediate_data_read_addr_dout + multi_core_offset_addr; //mac_read_dma_addr_dout;
				default: rd_tran_addr <= rd_tran_addr;
			endcase
		else if(ddr_read_data_over)
			rd_tran_addr <= rd_tran_addr + (rd_tran_len << 3); // for 512 bit, rightshift 3 bit, for 256 bit, rightshift 2 bit
	end
end

assign ddr_read_addr = rd_tran_addr << 3; // convert from 64 bit to 8 bit
//assign ddr_read_enable = (mst_exect_rstate_dly == EXECUTE_TRAN) & (~(read_finish_dly | read_finish));
assign  ddr_read_enable = mst_exect_rstate_dly == EXECUTE_TRAN;

always @(posedge c0_ddr_clk)
    if(!c0_ddr_aresetn)
        ddr_read_id <= 4'd0;
    else if(ddr_read_sel == 4'b0)
        case(read_data_for_core_count)
            2'd0 : ddr_read_id <= 4'd9;
            2'd1 : ddr_read_id <= 4'd10;
            2'd2 : ddr_read_id <= 4'd11;
            2'd3 : ddr_read_id <= 4'd12;
        endcase
    else
        ddr_read_id <= ddr_read_sel;
//assign  ddr_read_id = {1'b0,ddr_read_sel};
assign finish_read_inst = (mst_exect_rstate == TRAN_OVER) && (rd_inst_req_length == 10'h0);/* & (rd_instr_issue_count == rd_instr_finish_count);*/
//assign ddr_read_data_over = read_finish;
assign  ddr_read_data_over = rd_instr_esp;



always @(posedge c0_ddr_clk)
    ddr_read_data_over_dly <= ddr_read_data_over;
/*
always @(posedge c0_ddr_clk) begin
    if(!c0_ddr_aresetn)
        rd_instr_issue_count <= 0;
    else if(mst_exect_rstate == READ_INST)
        rd_instr_issue_count <= 0;
    else if(ddr_read_data_over & (~ddr_read_data_over_dly))
        rd_instr_issue_count <= rd_instr_issue_count + 1;
    //
    if(!c0_ddr_aresetn)
        rd_instr_finish_count <= 0;
    else if(mst_exect_rstate == READ_INST)
        rd_instr_finish_count <= 0;
    else if(read_finish & (~read_finish_dly))
        rd_instr_finish_count <= rd_instr_finish_count + 1;
end
*/
always @(posedge c0_ddr_clk)
    read_finish_dly <= read_finish;

always @(posedge app_clk) begin
    data_read_busy <= (data_read_addr_count > 4'd9) || (intermediate_data_read_addr_count > 4'd9) ;
    param_read_busy <= param_read_addr_count > 4'd9;
    bias_read_busy <= bias_read_addr_count > 4'd9;
    inst_read_busy[0] <= inst_read_addr_count[0] > 4'd9;
    inst_read_busy[1] <= inst_read_addr_count[1] > 4'd9;
    inst_read_busy[2] <= inst_read_addr_count[2] > 4'd9;
    inst_read_busy[3] <= inst_read_addr_count[3] > 4'd9;
    inst_read_busy[4] <= inst_read_addr_count[4] > 4'd9;
end






assign  recv_fifo_is_full = ddr_read_bias_full || ddr_read_param_full || (|ddr_read_data_full) || (|inst_read_full);// || mac_read_data_fifo_full;

genvar core_num;
generate
   always @(posedge c0_ddr_clk) begin
       ddr_read_param_wren_predly[0] <= ddr_read_valid & (ddr_read_id_out == 4'd2);
       ddr_read_param_wren_predly[1] <= ddr_read_param_wren_predly[0];
       ddr_read_param_wren <= ddr_read_param_wren_predly[1];

       ddr_read_bias_wren_predly[0] <= ddr_read_valid & (ddr_read_id_out == 4'd1);
       ddr_read_bias_wren_predly[1] <= ddr_read_bias_wren_predly[0];
       ddr_read_bias_wren <= ddr_read_bias_wren_predly[1];

       ddr_read_data_fixed_predly[0] <= ddr_read_data;
       ddr_read_data_fixed_predly[1] <= ddr_read_data_fixed_predly[0];
   end

   for(core_num=0;core_num<FUCORE_NUM;core_num=core_num+1) begin
       always @(posedge c0_ddr_clk) begin
	       ddr_read_data_wren_predly[0][core_num] <= ddr_read_valid & ((ddr_read_id_out == (9+core_num)) || (ddr_read_id_out == 8));
	       ddr_read_data_wren_predly[1][core_num] <= ddr_read_data_wren_predly[0][core_num];
	       ddr_read_data_fixed[core_num] <= ddr_read_data_fixed_predly[1];
	       ddr_read_data_wren[core_num] <= ddr_read_data_wren_predly[1][core_num];
	   end

       fifo_ddr_read_only_for_data ddr_read_data_instr_t (
           .wr_clk             (c0_ddr_clk),
           .rd_clk             (app_clk),
           .rst                (!c0_ddr_aresetn),
           .wr_en              (ddr_read_data_wren[core_num]),
           .din                ({ddr_read_data_fixed[core_num][255:0],ddr_read_data_fixed[core_num][511:256]}), // 256 bits
           .rd_en              ((~ddr_read_data_empty[core_num]) & data_read_data_enable[core_num]),
           .dout               (data_read_data[core_num*256+:256]),                        // 256 bits
           .empty              (ddr_read_data_empty[core_num]),
           .full               (),
           .prog_full          (ddr_read_data_full[core_num]),
          // .wr_data_count      (ddr_read_data_count[core_num]),        // 7 bits
           .wr_rst_busy        (),
           .rd_rst_busy        ()
       );

       always @(posedge app_clk) begin
           data_read_data_valid_tmp[core_num] <=(~ddr_read_data_empty[core_num]) & data_read_data_enable[core_num];
           data_read_data_valid[core_num] <= data_read_data_valid_tmp[core_num];
       end

       assign   data_read_stop[core_num] = ddr_read_data_empty[core_num];
    end
	   /*
	always @(posedge c0_ddr_clk)
        if(!c0_ddr_aresetn)
            ddr_read_data_count_sel <= 0;
        else begin
            case(read_data_for_core_count)
                2'd0 : ddr_read_data_count_sel <= ddr_read_data_count[0];
                2'd1 : ddr_read_data_count_sel <= ddr_read_data_count[1];
                2'd2 : ddr_read_data_count_sel <= ddr_read_data_count[2];
                default: ddr_read_data_count_sel <= ddr_read_data_count[0];
            endcase
        end
        */
endgenerate


fifo_ddr_read_data ddr_read_param_inst(
    .wr_clk			(c0_ddr_clk),
	.rd_clk			(app_clk),
	.rst			(!c0_ddr_aresetn),
	.wr_en			(ddr_read_param_wren),
	.din			(ddr_read_data_fixed[0]),				// 256 bits
	.rd_en			((~ddr_read_param_empty) & param_read_data_ready),
	.dout			(param_read_data),						// 64 bits
	.empty			(ddr_read_param_empty),
	.full           (),
	.prog_full		(ddr_read_param_full),
	//.wr_data_count	(ddr_read_param_count),		// 6 bits
	.wr_rst_busy    (),
	.rd_rst_busy    ()
);

fifo_ddr_read_data ddr_read_bias_inst(
	.wr_clk			(c0_ddr_clk),
	.rd_clk			(app_clk),
	.rst			(!c0_ddr_aresetn),
	.wr_en			(ddr_read_bias_wren),
	.din			(ddr_read_data_fixed[0]),				// 256 bits
	.rd_en			((~ddr_read_bias_empty) & bias_read_data_ready),
	.dout			(bias_read_data),						// 64 bits
	.empty			(ddr_read_bias_empty),
	.full           (),
	.prog_full	    (ddr_read_bias_full),
	//.wr_data_count	(ddr_read_bias_count),		// 6 bits
	.wr_rst_busy    (),
    .rd_rst_busy    ()
);

reg    param_read_data_valid_tmp;
reg    bias_read_data_valid_tmp;

always @(posedge app_clk) begin
    param_read_data_valid_tmp <= (~ddr_read_param_empty) & param_read_data_ready;
    param_read_data_valid <= param_read_data_valid_tmp;
end

always @(posedge app_clk) begin
    bias_read_data_valid <= bias_read_data_valid_tmp;    
	bias_read_data_valid_tmp <= (~ddr_read_bias_empty) & bias_read_data_ready;
end

always @(posedge c0_ddr_clk) begin
   inst_read_data_wren_dly[0] <= {ddr_read_valid & (ddr_read_id_out == 4'd7),
                                  ddr_read_valid & (ddr_read_id_out == 4'd6),
                                  ddr_read_valid & (ddr_read_id_out == 4'd5),
                                  ddr_read_valid & (ddr_read_id_out == 4'd4),
                                  ddr_read_valid & (ddr_read_id_out == 4'd3)};
   inst_read_data_wren_dly[1] <= inst_read_data_wren_dly[0];
   inst_read_data_wren_dly[2] <= inst_read_data_wren_dly[1];
   /*
   mac_read_data_wren_dly[0] <= ddr_read_valid & (ddr_read_id_out == 4'd8); 
   mac_read_data_wren_dly[1] <= mac_read_data_wren_dly[0];
   mac_read_data_wren_dly[2] <= mac_read_data_wren_dly[1];
   */              
end

assign inst_read_data_wren[0] = inst_read_data_wren_dly[2][0];
assign inst_read_data_wren[1] = inst_read_data_wren_dly[2][1];
assign inst_read_data_wren[2] = inst_read_data_wren_dly[2][2];
assign inst_read_data_wren[3] = inst_read_data_wren_dly[2][3];
assign inst_read_data_wren[4] = inst_read_data_wren_dly[2][4];

//assign  mac_read_data_wren = mac_read_data_wren_dly[2];
endmodule

module	ultraram_unit (
		//
			input			         clk,
			input			         rst,
		//
			input    [127:0]         iWr_data,
			input                    iWr_enable,
			input    [15:0]          iWr_addr,
	    //
            input                    iRd_enable,
            output   reg [127:0]     oRd_data,
            input    [15:0]          iRd_addr,
            output   reg             oRd_data_valid
        );

parameter   N = 9;

/*
parameter   string CASCADE_ORDER[N] =    '{"FIRST",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "MIDDLE",
                                          "LAST"
                                         };
                                         */
wire    [127:0]     wr_data [N-1:0];        
wire    [22:0]      wr_addr [N-1:0];
wire                wr_enable [N-1:0];
wire                rdb_wr_a [N-1:0];

wire    [127+16:0]  rd_data [N-1:0];
wire    [22:0]      rd_addr [N-1:0];
wire                rd_access_b [N-1:0];
wire                rd_enable [N-1:0];
wire                rdb_wr_b [N-1:0];
// cas
wire    [22:0]      cas_out_addr_a_h [N:0];
wire    [22:0]      cas_out_addr_b_h [N:0];
wire    [8:0]       cas_out_bwe_a_h  [N:0];  
wire    [8:0]       cas_out_bwe_b_h  [N:0];  
wire    [71:0]      cas_out_din_a_h  [N:0];
wire    [71:0]      cas_out_dout_b_h [N:0];
wire                cas_out_en_a_h   [N:0];
wire                cas_out_en_b_h   [N:0];
wire                cas_out_rdaccess_b_h [N:0];
wire                cas_out_rdb_wr_a_h   [N:0];
wire                cas_out_rdb_wr_b_h   [N:0];

wire                cas_out_dbiterr_a_h  [N:0];
wire                cas_out_dbiterr_b_h  [N:0];
wire                cas_out_sbiterr_a_h  [N:0];
wire                cas_out_sbiterr_b_h  [N:0];
wire    [71:0]      cas_out_din_b_h [N:0];
wire    [71:0]      cas_out_dout_a_h [N:0];
wire                cas_out_rdaccess_a_h [N:0];

wire    [22:0]      cas_out_addr_a_l [N:0];
wire    [22:0]      cas_out_addr_b_l [N:0];
wire    [8:0]       cas_out_bwe_a_l  [N:0];  
wire    [8:0]       cas_out_bwe_b_l  [N:0];  
wire    [71:0]      cas_out_din_a_l  [N:0];
wire    [71:0]      cas_out_dout_b_l [N:0];
wire                cas_out_en_a_l   [N:0];
wire                cas_out_en_b_l   [N:0];
wire                cas_out_rdaccess_b_l [N:0];
wire                cas_out_rdb_wr_a_l   [N:0];
wire                cas_out_rdb_wr_b_l   [N:0];

wire                cas_out_dbiterr_a_l  [N:0];
wire                cas_out_dbiterr_b_l  [N:0];
wire                cas_out_sbiterr_a_l  [N:0];
wire                cas_out_sbiterr_b_l  [N:0];
wire    [71:0]      cas_out_din_b_l [N:0];
wire    [71:0]      cas_out_dout_a_l [N:0];
wire                cas_out_rdaccess_a_l [N:0];

reg     [11:0]      addr_a_dly[7:0];
reg     [127:0]     data_a_dly[7:0];
reg                 rdb_wr_a_dly[7:0];

reg     [11:0]      addr_b_dly [7:0];
reg                 rdb_wr_b_dly [7:0];
//=============================================

always @(posedge clk) begin : loop
    integer i;
    addr_a_dly[0] <= iWr_addr[11:0];
    data_a_dly[0] <= iWr_data;
    rdb_wr_a_dly[0] <=  iWr_enable;
    addr_b_dly[0] <= iRd_addr[11:0];
    rdb_wr_b_dly[0] <= ~iRd_enable;
    for(i=1;i < 8; i=i+1) begin
        addr_a_dly[i] <= addr_a_dly[i-1];
        data_a_dly[i] <= data_a_dly[i-1];
        rdb_wr_a_dly[i] <= rdb_wr_a_dly[i-1];
        addr_b_dly[i] <= addr_b_dly[i-1];
        rdb_wr_b_dly[i] <= rdb_wr_b_dly[i-1];
    end
end

//
reg         rd_data_valid_dly1, rd_data_valid_dly2;
reg [127:0] rd_data_dly1, rd_data_dly2;

always @(posedge clk) begin
/*
    oRd_data <= {rd_data[N-1][135:72],rd_data[N-1][63:0]}; 
    oRd_data_valid <= rd_access_b[N-1];
    */
    rd_data_dly1 <= {rd_data[N-1][135:72],rd_data[N-1][63:0]}; 
    rd_data_valid_dly1 <= rd_access_b[N-1];
    rd_data_dly2 <= rd_data_dly1;
    rd_data_valid_dly2 <= rd_data_valid_dly1;
    oRd_data <= rd_data_dly2;
    oRd_data_valid <= rd_data_valid_dly2;
end
//=============================================


assign  cas_out_addr_a_l[0] = 23'b0,           // 23-bit input: Port A cascade input address
        cas_out_addr_b_l[0] = 23'b0,           // 23-bit input: Port B cascade input address
        cas_out_bwe_a_l[0] = 9'b0,             // 9-bit input: Port A cascade Byte-write enable input
        cas_out_bwe_b_l[0] = 9'b0,             // 9-bit input: Port B cascade Byte-write enable input
        cas_out_dbiterr_a_l[0] = 1'b0,                     // 1-bit input: Port A cascade double-bit error flag input
        cas_out_dbiterr_b_l[0] = 1'b0,                     // 1-bit input: Port B cascade double-bit error flag input
        cas_out_din_a_l[0] = 72'b0,             // 72-bit input: Port A cascade input write mode data
        cas_out_din_b_l[0] = 72'b0,                             // 72-bit input: Port B cascade input write mode data
        cas_out_dout_a_l[0] = 72'b0,                            // 72-bit input: Port A cascade input read mode data
        cas_out_dout_b_l[0] = 72'b0,           // 72-bit input: Port B cascade input read mode data
        cas_out_en_a_l[0] = 1'b0,               // 1-bit input: Port A cascade enable input
        cas_out_en_b_l[0] = 1'b0,               // 1-bit input: Port B cascade enable input
        cas_out_rdaccess_a_l[0] = 1'b0,                        // 1-bit input: Port A cascade read status input
        cas_out_rdaccess_b_l[0] = 1'b0,   // 1-bit input: Port B cascade read status input
        cas_out_rdb_wr_a_l[0] = 1'b0,       // 1-bit input: Port A cascade read/write select input
        cas_out_rdb_wr_b_l[0] = 1'b0,       // 1-bit input: Port B cascade read/write select input
        cas_out_sbiterr_a_l[0] = 1'b0,                 // 1-bit input: Port A cascade single-bit error flag input
        cas_out_sbiterr_b_l[0] = 1'b0;                 // 1-bit input: Port B cascade single-bit error flag input

assign  cas_out_addr_a_h[0] = 23'b0,           // 23-bit input: Port A cascade input address
