private object ConnectedShape {
  val Hidden = 896
  val Intermediate = 4864
  val Lanes = 8
  val Tokens = 16
  val HiddenBeats = Hidden / Lanes
  val IntermediateBeats = Intermediate / Lanes
  val TotalBeats = Tokens * HiddenBeats
  val WeightWords = 7457664
  val RuntimeWords = 1056
}

private class ConnectedStreamIngress(
  dataBits: Int,
  addrBits: Int,
  beatsPerVector: Int,
  totalBeats: Int
) extends Module {
  require(dataBits > 0)
  require(addrBits > 0)
  require(beatsPerVector > 0)
  require(totalBeats > 0)
  require(totalBeats % beatsPerVector == 0)

  val io = IO(new Bundle {
    val enable = Input(Bool())
    val externalValid = Input(Bool())
    val externalReady = Output(Bool())
    val externalData = Input(UInt(dataBits.W))
    val out = Decoupled(new StreamBeat(StreamSpec(dataBits, addrBits)))
  })

  private val acceptedBeat = RegInit(0.U(addrBits.W))
  private val featureBeat = acceptedBeat % beatsPerVector.U
  private val active = io.enable && !reset.asBool

  io.out.valid := io.externalValid && active
  io.externalReady := io.out.ready && active
  io.out.bits.data := io.externalData
  io.out.bits.st := featureBeat === 0.U
  io.out.bits.addr := acceptedBeat
  io.out.bits.last := featureBeat === (beatsPerVector - 1).U

  when(io.out.fire) {
    acceptedBeat := Mux(
      acceptedBeat === (totalBeats - 1).U,
      0.U,
      acceptedBeat + 1.U
    )
  }
}

private class ConnectedCanonicalWordPacker(
  wordsPerWrite: Int,
  writeCount: Int
) extends Module {
  require(wordsPerWrite > 0)
  require(writeCount > 0)

  private val wordIndexBits = log2Ceil(wordsPerWrite max 2)
  private val writeAddrBits = log2Ceil(writeCount max 2)

  val io = IO(new Bundle {
    val in = Flipped(Decoupled(UInt(32.W)))
    val out = Decoupled(new WeightWrite(wordsPerWrite * 32, writeAddrBits))
    val loaded = Output(Bool())
  })

  private val words = Reg(Vec(wordsPerWrite, UInt(32.W)))
  private val wordIndex = RegInit(0.U(wordIndexBits.W))
  private val writeIndex = RegInit(0.U(writeAddrBits.W))
  private val pendingWrite = RegInit(false.B)
  private val allWritesLoaded = RegInit(false.B)

  io.in.ready := !pendingWrite && !allWritesLoaded

  when(io.in.fire) {
    words(wordIndex) := io.in.bits
    when(wordIndex === (wordsPerWrite - 1).U) {
      wordIndex := 0.U
      pendingWrite := true.B
    }.otherwise {
      wordIndex := wordIndex + 1.U
    }
  }

  io.out.valid := pendingWrite
  io.out.bits.addr := writeIndex
  io.out.bits.data := words.asUInt

  when(io.out.fire) {
    pendingWrite := false.B
    when(writeIndex === (writeCount - 1).U) {
      writeIndex := 0.U
      allWritesLoaded := true.B
    }.otherwise {
      writeIndex := writeIndex + 1.U
    }
  }

  io.loaded := allWritesLoaded
}

private class ConnectedWeightLoader extends Module {
  import ConnectedShape._

  private val AddressBits = log2Ceil(WeightWords)

  private val Rms1End = 896
  private val QkvWeightEnd = 516992
  private val QkvBiasEnd = 518144
  private val AttentionOutEnd = 919552
  private val Rms2End = 920448
  private val GateEnd = 3099520
  private val UpEnd = 5278592
  private val DownEnd = WeightWords

  val io = IO(new Bundle {
    val externalValid = Input(Bool())
    val externalReady = Output(Bool())
    val externalData = Input(UInt(32.W))
    val externalAddr = Input(UInt(AddressBits.W))
    val externalLast = Input(Bool())

    val rms1Weight = Decoupled(UInt(256.W))
    val qkvWeight = Decoupled(new WeightWrite(1024, log2Ceil(16128)))
    val qkvBias = Decoupled(new WeightWrite(256, log2Ceil(144)))
    val attentionOutWeight = Decoupled(new WeightWrite(8192, log2Ceil(1568)))
    val rms2Weight = Decoupled(UInt(256.W))
    val mlpGateWeight = Decoupled(new WeightWrite(1024, log2Ceil(68096)))
    val mlpUpWeight = Decoupled(new WeightWrite(1024, log2Ceil(68096)))
    val mlpDownWeight = Decoupled(new WeightWrite(1024, log2Ceil(68096)))
    val complete = Output(Bool())
  })

  private val rms1 = Module(new ConnectedCanonicalWordPacker(8, 112))
  private val qkvWeight = Module(new ConnectedCanonicalWordPacker(32, 16128))
  private val qkvBias = Module(new ConnectedCanonicalWordPacker(8, 144))
  private val attentionOut = Module(new ConnectedCanonicalWordPacker(256, 1568))
  private val rms2 = Module(new ConnectedCanonicalWordPacker(8, 112))
  private val gate = Module(new ConnectedCanonicalWordPacker(32, 68096))
  private val up = Module(new ConnectedCanonicalWordPacker(32, 68096))
  private val down = Module(new ConnectedCanonicalWordPacker(32, 68096))

  private val acceptedWord = RegInit(0.U(AddressBits.W))
  private val externalStreamAccepted = RegInit(false.B)
  private val finalWord = acceptedWord === (WeightWords - 1).U
  private val protocolMatch =
    !externalStreamAccepted &&
      io.externalAddr === acceptedWord &&
      io.externalLast === finalWord

  private val selectRms1 = acceptedWord < Rms1End.U
  private val selectQkvWeight =
    acceptedWord >= Rms1End.U && acceptedWord < QkvWeightEnd.U
  private val selectQkvBias =
    acceptedWord >= QkvWeightEnd.U && acceptedWord < QkvBiasEnd.U
  private val selectAttentionOut =
    acceptedWord >= QkvBiasEnd.U && acceptedWord < AttentionOutEnd.U
  private val selectRms2 =
    acceptedWord >= AttentionOutEnd.U && acceptedWord < Rms2End.U
  private val selectGate =
    acceptedWord >= Rms2End.U && acceptedWord < GateEnd.U
  private val selectUp =
    acceptedWord >= GateEnd.U && acceptedWord < UpEnd.U
  private val selectDown =
    acceptedWord >= UpEnd.U && acceptedWord < DownEnd.U

  rms1.io.in.valid := io.externalValid && protocolMatch && selectRms1
  qkvWeight.io.in.valid := io.externalValid && protocolMatch && selectQkvWeight
  qkvBias.io.in.valid := io.externalValid && protocolMatch && selectQkvBias
  attentionOut.io.in.valid := io.externalValid && protocolMatch && selectAttentionOut
  rms2.io.in.valid := io.externalValid && protocolMatch && selectRms2
  gate.io.in.valid := io.externalValid && protocolMatch && selectGate
  up.io.in.valid := io.externalValid && protocolMatch && selectUp
  down.io.in.valid := io.externalValid && protocolMatch && selectDown

  rms1.io.in.bits := io.externalData
  qkvWeight.io.in.bits := io.externalData
  qkvBias.io.in.bits := io.externalData
  attentionOut.io.in.bits := io.externalData
  rms2.io.in.bits := io.externalData
  gate.io.in.bits := io.externalData
  up.io.in.bits := io.externalData
  down.io.in.bits := io.externalData

  private val selectedReady = MuxCase(
    false.B,
    Seq(
      selectRms1 -> rms1.io.in.ready,
      selectQkvWeight -> qkvWeight.io.in.ready,
      selectQkvBias -> qkvBias.io.in.ready,
      selectAttentionOut -> attentionOut.io.in.ready,
      selectRms2 -> rms2.io.in.ready,
      selectGate -> gate.io.in.ready,
      selectUp -> up.io.in.ready,
      selectDown -> down.io.in.ready
    )
  )

  io.externalReady := protocolMatch && selectedReady

  when(io.externalValid && io.externalReady) {
    when(finalWord) {
      acceptedWord := 0.U
      externalStreamAccepted := true.B
    }.otherwise {
      acceptedWord := acceptedWord + 1.U
    }
  }

  io.rms1Weight.valid := rms1.io.out.valid
  io.rms1Weight.bits := rms1.io.out.bits.data
  rms1.io.out.ready := io.rms1Weight.ready

  io.qkvWeight.valid := qkvWeight.io.out.valid
  io.qkvWeight.bits := qkvWeight.io.out.bits
  qkvWeight.io.out.ready := io.qkvWeight.ready

  io.qkvBias.valid := qkvBias.io.out.valid
  io.qkvBias.bits := qkvBias.io.out.bits
  qkvBias.io.out.ready := io.qkvBias.ready

  io.attentionOutWeight.valid := attentionOut.io.out.valid
  io.attentionOutWeight.bits := attentionOut.io.out.bits
  attentionOut.io.out.ready := io.attentionOutWeight.ready

  io.rms2Weight.valid := rms2.io.out.valid
  io.rms2Weight.bits := rms2.io.out.bits.data
  rms2.io.out.ready := io.rms2Weight.ready

  io.mlpGateWeight.valid := gate.io.out.valid
  io.mlpGateWeight.bits := gate.io.out.bits
  gate.io.out.ready := io.mlpGateWeight.ready

  io.mlpUpWeight.valid := up.io.out.valid
  io.mlpUpWeight.bits := up.io.out.bits
  up.io.out.ready := io.mlpUpWeight.ready

  io.mlpDownWeight.valid := down.io.out.valid
  io.mlpDownWeight.bits := down.io.out.bits
  down.io.out.ready := io.mlpDownWeight.ready

  io.complete :=
    externalStreamAccepted &&
      rms1.io.loaded &&
      qkvWeight.io.loaded &&
      qkvBias.io.loaded &&
      attentionOut.io.loaded &&
      rms2.io.loaded &&
      gate.io.loaded &&
      up.io.loaded &&
      down.io.loaded
}

