class SingleLayerSemanticHarness extends Module {
  import ConnectedShape._

  private val WeightAddressBits = log2Ceil(WeightWords)
  private val RuntimeAddressBits = log2Ceil(RuntimeWords)
  private val p = GeneratedDesignParams.params

  val io = FlatIO(new Bundle {
    val start = Input(Bool())

    val input_0_valid = Input(Bool())
    val input_0_ready = Output(Bool())
    val input_0_data = Input(UInt(256.W))

    val output_valid = Output(Bool())
    val output_ready = Input(Bool())
    val output_data = Output(UInt(256.W))

    val weight_valid = Input(Bool())
    val weight_ready = Output(Bool())
    val weight_data = Input(UInt(32.W))
    val weight_addr = Input(UInt(WeightAddressBits.W))
    val weight_last = Input(Bool())

    val runtime_valid = Input(Bool())
    val runtime_ready = Output(Bool())
    val runtime_data = Input(UInt(32.W))
    val runtime_addr = Input(UInt(RuntimeAddressBits.W))
    val runtime_last = Input(Bool())
  })

  private val core = Module(new ConnectedObservableLlamaStyleBlock(p))
  private val weights = Module(new ConnectedWeightLoader)
  private val ingress = Module(
    new ConnectedStreamIngress(
      dataBits = 256,
      addrBits = p.inSpec.addrBits,
      beatsPerVector = HiddenBeats,
      totalBeats = TotalBeats
    )
  )

  weights.io.externalValid := io.weight_valid
  io.weight_ready := weights.io.externalReady
  weights.io.externalData := io.weight_data
  weights.io.externalAddr := io.weight_addr
  weights.io.externalLast := io.weight_last

  core.io.rms1Weight.valid := weights.io.rms1Weight.valid
  core.io.rms1Weight.bits := weights.io.rms1Weight.bits
  weights.io.rms1Weight.ready := core.io.rms1Weight.ready

  core.io.qkvWeight.valid := weights.io.qkvWeight.valid
  core.io.qkvWeight.bits := weights.io.qkvWeight.bits
  weights.io.qkvWeight.ready := core.io.qkvWeight.ready

  core.io.qkvBias.valid := weights.io.qkvBias.valid
  core.io.qkvBias.bits := weights.io.qkvBias.bits
  weights.io.qkvBias.ready := core.io.qkvBias.ready

  core.io.attentionOutWeight.valid := weights.io.attentionOutWeight.valid
  core.io.attentionOutWeight.bits := weights.io.attentionOutWeight.bits
  weights.io.attentionOutWeight.ready := core.io.attentionOutWeight.ready

  core.io.rms2Weight.valid := weights.io.rms2Weight.valid
  core.io.rms2Weight.bits := weights.io.rms2Weight.bits
  weights.io.rms2Weight.ready := core.io.rms2Weight.ready

  core.io.mlpGateWeight.valid := weights.io.mlpGateWeight.valid
  core.io.mlpGateWeight.bits := weights.io.mlpGateWeight.bits
  weights.io.mlpGateWeight.ready := core.io.mlpGateWeight.ready

  core.io.mlpUpWeight.valid := weights.io.mlpUpWeight.valid
  core.io.mlpUpWeight.bits := weights.io.mlpUpWeight.bits
  weights.io.mlpUpWeight.ready := core.io.mlpUpWeight.ready

  core.io.mlpDownWeight.valid := weights.io.mlpDownWeight.valid
  core.io.mlpDownWeight.bits := weights.io.mlpDownWeight.bits
  weights.io.mlpDownWeight.ready := core.io.mlpDownWeight.ready

  private val runtimeAccepted = RegInit(0.U(RuntimeAddressBits.W))
  private val runtimeStreamAccepted = RegInit(false.B)
  private val runtimeFinal = runtimeAccepted === (RuntimeWords - 1).U
  private val runtimeProtocolMatch =
    !runtimeStreamAccepted &&
      io.runtime_addr === runtimeAccepted &&
      io.runtime_last === runtimeFinal

  core.io.ropeRuntime.valid := io.runtime_valid && runtimeProtocolMatch
  core.io.ropeRuntime.bits.addr := runtimeAccepted
  core.io.ropeRuntime.bits.data := io.runtime_data
  core.io.ropeRuntimeLast := runtimeFinal
  io.runtime_ready := core.io.ropeRuntime.ready && runtimeProtocolMatch

  when(io.runtime_valid && io.runtime_ready) {
    when(runtimeFinal) {
      runtimeAccepted := 0.U
      runtimeStreamAccepted := true.B
    }.otherwise {
      runtimeAccepted := runtimeAccepted + 1.U
    }
  }

  private val loadComplete =
    weights.io.complete && runtimeStreamAccepted && core.io.ropeRuntimeLoaded

  ingress.io.enable := loadComplete
  ingress.io.externalValid := io.input_0_valid
  io.input_0_ready := ingress.io.externalReady
  ingress.io.externalData := io.input_0_data

