private object SemanticShape {
  val Hidden = 896
  val Intermediate = 4864
  val Lanes = 8
  val Tokens = 16
  val HiddenBeats = Hidden / Lanes
  val IntermediateBeats = Intermediate / Lanes
  val HiddenTotalBeats = Tokens * HiddenBeats
  val IntermediateTotalBeats = Tokens * IntermediateBeats
}

private class StreamIngress(
  dataBits: Int,
  addrBits: Int,
  beatsPerVector: Int,
  totalBeats: Int
) extends Module {
  require(dataBits > 0)
  require(addrBits > 0)
  require(beatsPerVector > 0)
  require(totalBeats > 0)
  require(totalBeats % beatsPerVector == 0)

  val io = IO(new Bundle {
    val enable = Input(Bool())
    val externalValid = Input(Bool())
    val externalReady = Output(Bool())
    val externalData = Input(UInt(dataBits.W))
    val out = Decoupled(new StreamBeat(StreamSpec(dataBits, addrBits)))
  })

  private val accepted = RegInit(0.U(addrBits.W))
  private val featureBeat = accepted % beatsPerVector.U
  private val active = io.enable && !reset.asBool

  io.out.valid := io.externalValid && active
  io.externalReady := io.out.ready && active
  io.out.bits.data := io.externalData
  io.out.bits.st := featureBeat === 0.U
  io.out.bits.addr := accepted
  io.out.bits.last := featureBeat === (beatsPerVector - 1).U

  when(io.out.fire) {
    accepted := Mux(accepted === (totalBeats - 1).U, 0.U, accepted + 1.U)
  }
}

private class CanonicalWordPacker(wordsPerWrite: Int, writeCount: Int) extends Module {
  require(wordsPerWrite > 0)
  require(writeCount > 0)

  private val wordIndexBits = log2Ceil(wordsPerWrite max 2)
  private val writeAddrBits = log2Ceil(writeCount max 2)

  val io = IO(new Bundle {
    val in = Flipped(Decoupled(UInt(32.W)))
    val out = Decoupled(new WeightWrite(wordsPerWrite * 32, writeAddrBits))
    val loaded = Output(Bool())
  })

  private val words = Reg(Vec(wordsPerWrite, UInt(32.W)))
  private val wordIndex = RegInit(0.U(wordIndexBits.W))
  private val writeIndex = RegInit(0.U(writeAddrBits.W))
  private val pending = RegInit(false.B)
  private val loaded = RegInit(false.B)

  io.in.ready := !pending && !loaded
  when(io.in.fire) {
    words(wordIndex) := io.in.bits
    when(wordIndex === (wordsPerWrite - 1).U) {
      wordIndex := 0.U
      pending := true.B
    }.otherwise {
      wordIndex := wordIndex + 1.U
    }
  }

  io.out.valid := pending
  io.out.bits.addr := writeIndex
  io.out.bits.data := words.asUInt

  when(io.out.fire) {
    pending := false.B
    when(writeIndex === (writeCount - 1).U) {
      writeIndex := 0.U
      loaded := true.B
    }.otherwise {
      writeIndex := writeIndex + 1.U
    }
  }

  io.loaded := loaded
}

private class SingleTargetWeightLoader(totalWords: Int, wordsPerWrite: Int) extends Module {
  require(totalWords > 0)
  require(totalWords % wordsPerWrite == 0)

  private val addressBits = log2Ceil(totalWords max 2)
  private val writeCount = totalWords / wordsPerWrite
  private val packer = Module(new CanonicalWordPacker(wordsPerWrite, writeCount))

  val io = IO(new Bundle {
    val externalValid = Input(Bool())
    val externalReady = Output(Bool())
    val externalData = Input(UInt(32.W))
    val externalAddr = Input(UInt(addressBits.W))
    val externalLast = Input(Bool())
    val out = Decoupled(new WeightWrite(wordsPerWrite * 32, log2Ceil(writeCount max 2)))
    val complete = Output(Bool())
  })

  private val accepted = RegInit(0.U(addressBits.W))
  private val streamAccepted = RegInit(false.B)
  private val finalWord = accepted === (totalWords - 1).U
  private val protocolMatch =
    !streamAccepted && io.externalAddr === accepted && io.externalLast === finalWord

  packer.io.in.valid := io.externalValid && protocolMatch
  packer.io.in.bits := io.externalData
  io.externalReady := packer.io.in.ready && protocolMatch

  when(io.externalValid && io.externalReady) {
    when(finalWord) {
      accepted := 0.U
      streamAccepted := true.B
    }.otherwise {
      accepted := accepted + 1.U
    }
  }

  io.out <> packer.io.out
  io.complete := streamAccepted && packer.io.loaded
}

private class AttentionWeightLoader extends Module {
  private val QkvWords = 516096
  private val BiasWords = 1152
  private val OutWords = 401408
  private val BiasOffset = QkvWords
  private val OutOffset = QkvWords + BiasWords
  private val TotalWords = QkvWords + BiasWords + OutWords
  private val AddressBits = log2Ceil(TotalWords)

  val io = IO(new Bundle {
    val externalValid = Input(Bool())
    val externalReady = Output(Bool())
    val externalData = Input(UInt(32.W))
    val externalAddr = Input(UInt(AddressBits.W))
    val externalLast = Input(Bool())
    val qkvWeight = Decoupled(new WeightWrite(1024, log2Ceil(16128)))
    val qkvBias = Decoupled(new WeightWrite(256, log2Ceil(144)))
    val outWeight = Decoupled(new WeightWrite(8192, log2Ceil(1568)))
    val complete = Output(Bool())
  })

  private val qkv = Module(new CanonicalWordPacker(32, 16128))
  private val bias = Module(new CanonicalWordPacker(8, 144))
  private val out = Module(new CanonicalWordPacker(256, 1568))
  private val accepted = RegInit(0.U(AddressBits.W))
  private val streamAccepted = RegInit(false.B)
  private val selectQkv = accepted < BiasOffset.U
  private val selectBias = accepted >= BiasOffset.U && accepted < OutOffset.U
  private val selectOut = accepted >= OutOffset.U
  private val finalWord = accepted === (TotalWords - 1).U
  private val protocolMatch =
    !streamAccepted && io.externalAddr === accepted && io.externalLast === finalWord

  qkv.io.in.valid := io.externalValid && protocolMatch && selectQkv
  qkv.io.in.bits := io.externalData
  bias.io.in.valid := io.externalValid && protocolMatch && selectBias
  bias.io.in.bits := io.externalData
  out.io.in.valid := io.externalValid && protocolMatch && selectOut
  out.io.in.bits := io.externalData

  private val selectedReady = Mux(selectQkv, qkv.io.in.ready, Mux(selectBias, bias.io.in.ready, out.io.in.ready))
  io.externalReady := protocolMatch && selectedReady

  when(io.externalValid && io.externalReady) {
    when(finalWord) {
      accepted := 0.U
      streamAccepted := true.B
    }.otherwise {
      accepted := accepted + 1.U
    }
  }

  io.qkvWeight <> qkv.io.out
  io.qkvBias <> bias.io.out
  io.outWeight <> out.io.out
  io.complete := streamAccepted && qkv.io.loaded && bias.io.loaded && out.io.loaded
}

