  })

  private val qkvParams = QKVProjectionParams(Hidden, 14, 2, 64, lanes = Lanes, elemBits = 16, qkvElemsPerBeat = 8, batchSize = Tokens, maxSeqLen = Tokens)
  private val ropeParams = RoPEParams(qkvParams, theta = 1000000.0)
  private val attentionParams = AttentionParams(Hidden, 14, 2, 64, Tokens, lanes = Lanes, elemBits = 16, qkvElemsPerBeat = 8, batchSize = Tokens)
  private val qkv = Module(new QKVProjection(qkvParams))
  private val rope = Module(new RoPE(ropeParams))
  private val attention = Module(new AttentionGQA(attentionParams))
  private val weights = Module(new AttentionWeightLoader)
  private val ingress = Module(new StreamIngress(128, qkvParams.linear.inputAddrBits, HiddenBeats, HiddenTotalBeats))

  weights.io.externalValid := io.weight_valid
  io.weight_ready := weights.io.externalReady
  weights.io.externalData := io.weight_data
  weights.io.externalAddr := io.weight_addr
  weights.io.externalLast := io.weight_last
  qkv.io.weight <> weights.io.qkvWeight
  qkv.io.bias <> weights.io.qkvBias
  attention.io.outWeight <> weights.io.outWeight

  private val runtimeAccepted = RegInit(0.U(11.W))
  private val runtimeStreamAccepted = RegInit(false.B)
  private val runtimeFinal = runtimeAccepted === 1055.U
  private val runtimeProtocolMatch =
    !runtimeStreamAccepted && io.runtime_addr === runtimeAccepted && io.runtime_last === runtimeFinal

  rope.io.runtime.valid := io.runtime_valid && runtimeProtocolMatch
  rope.io.runtime.bits.addr := io.runtime_addr
  rope.io.runtime.bits.data := io.runtime_data
  rope.io.runtimeLast := io.runtime_last
  io.runtime_ready := rope.io.runtime.ready && runtimeProtocolMatch

  when(io.runtime_valid && io.runtime_ready) {
    when(runtimeFinal) {
      runtimeAccepted := 0.U
      runtimeStreamAccepted := true.B
    }.otherwise {
      runtimeAccepted := runtimeAccepted + 1.U
    }
  }

  ingress.io.enable := weights.io.complete && runtimeStreamAccepted && rope.io.runtimeLoaded
  ingress.io.externalValid := io.input_0_valid
  io.input_0_ready := ingress.io.externalReady
  ingress.io.externalData := io.input_0_data
  qkv.io.in <> ingress.io.out
  rope.io.in <> qkv.io.out
  attention.io.in <> rope.io.out

  qkv.io.start := false.B
  qkv.io.cfg.seqlen := Tokens.U
  qkv.io.cfg.prefill := true.B
  qkv.io.cfg.singleQuery := false.B
  qkv.io.cfgValid := true.B
  qkv.io.qScale := IeeeMath.fp32One
  qkv.io.kScale := IeeeMath.fp32One
  qkv.io.vScale := IeeeMath.fp32One

  rope.io.cfg.seqlen := Tokens.U
  rope.io.cfg.prefill := true.B
  rope.io.cfg.singleQuery := false.B
  rope.io.cfgValid := true.B
  rope.io.position := 0.U

  attention.io.cfg.seqlen := Tokens.U
  attention.io.cfg.prefill := true.B
  attention.io.cfg.singleQuery := false.B
  attention.io.cfgValid := true.B
  attention.io.mask := 0.U
  attention.io.scoreScale := IeeeMath.fp32One
  attention.io.ctxInvScale := IeeeMath.fp32One
  attention.io.ctxZeroPoint := 0.U
  attention.io.outInvScale := IeeeMath.fp32One

  io.output_valid := attention.io.out.valid
  attention.io.out.ready := io.output_ready
  io.output_data := attention.io.out.bits.data

  private val traceCycle = RegInit(0.U(64.W))
  private val qkvTraceBeat = RegInit(0.U(log2Ceil(HiddenTotalBeats).W))
  private val ropeTraceBeat = RegInit(0.U(log2Ceil(HiddenTotalBeats).W))
  private val attentionTraceBeat = RegInit(0.U(log2Ceil(HiddenTotalBeats).W))

  when(!reset.asBool) {
    traceCycle := traceCycle + 1.U
  }

  when(qkv.io.out.fire) {
    when(qkvTraceBeat === 111.U || qkvTraceBeat === 112.U) {
      printf(p"SPATIALACC_INTERNAL_TRACE stage=stage_01_self_attention boundary=internal.stage_01_self_attention.qkv_projection_to_rope module=QKVProjection cycle=${traceCycle} beat=${qkvTraceBeat} valid=${qkv.io.out.valid} ready=${qkv.io.out.ready} data=${Hexadecimal(qkv.io.out.bits.data)}\n")
    }
    qkvTraceBeat := Mux(qkvTraceBeat === (HiddenTotalBeats - 1).U, 0.U, qkvTraceBeat + 1.U)
  }

  when(rope.io.out.fire) {
    when(ropeTraceBeat === 111.U || ropeTraceBeat === 112.U) {
      printf(p"SPATIALACC_INTERNAL_TRACE stage=stage_01_self_attention boundary=internal.stage_01_self_attention.rope_to_attention_gqa module=RoPE cycle=${traceCycle} beat=${ropeTraceBeat} valid=${rope.io.out.valid} ready=${rope.io.out.ready} data=${Hexadecimal(rope.io.out.bits.data)}\n")
    }
    ropeTraceBeat := Mux(ropeTraceBeat === (HiddenTotalBeats - 1).U, 0.U, ropeTraceBeat + 1.U)
  }

  when(attention.io.out.fire) {
    when(attentionTraceBeat === 111.U || attentionTraceBeat === 112.U) {
      printf(p"SPATIALACC_INTERNAL_TRACE stage=stage_01_self_attention boundary=boundary.edge_data_stage_01_self_attention_to_stage_02_residual_add_1_main module=AttentionGQA cycle=${traceCycle} beat=${attentionTraceBeat} valid=${attention.io.out.valid} ready=${attention.io.out.ready} data=${Hexadecimal(attention.io.out.bits.data)}\n")
    }
    attentionTraceBeat := Mux(attentionTraceBeat === (HiddenTotalBeats - 1).U, 0.U, attentionTraceBeat + 1.U)
  }
}

