def apply_agent_file_edits(
    output: dict[str, Any],
    run_dir: Path,
    out_dir: Path,
    *,
    allowed_exact_files: set[Path] | None = None,
    required_exact_files: set[Path] | None = None,
    required_noop_json_merges: dict[Path, dict[str, Any]] | None = None,
    required_template_pairs: set[str] | None = None,
    instrumentation_only_template_pairs: set[str] | None = None,
    repair_checkpoint: dict[str, Any] | None = None,
    allow_template_repair: bool | None = None,
    allow_board_integration: bool = False,
    allowed_semantic_rtl_files: set[Path] | None = None,
    require_exact_source_hash: bool = False,
    report_name: str = "agent_patch_application.json",
    agent_contract_blockers: list[str] | None = None,
    agent_contract_failure_class: str = "agent_output_contract",
    agent_contract_retry_on_blocked: bool = False,
) -> dict[str, Any]:
    raw_status = str(output.get("status") or "")
    approvals = output.get("approval_required_for", []) if isinstance(output.get("approval_required_for"), list) else []
    edits = output.get("file_edits", []) if isinstance(output.get("file_edits"), list) else []
    declared_blockers = (
        output.get("blocked_reasons", [])
        if isinstance(output.get("blocked_reasons"), list)
        else []
    )
    status = normalized_implementation_agent_status(output)
    blockers: list[str] = [
        str(value) for value in (agent_contract_blockers or []) if str(value)
    ]
    staged: list[tuple[Path, str, str, str]] = []
    protocol_normalizations: list[dict[str, Any]] = []
    total_bytes = 0
    seen_edit_targets: set[Path] = set()
    normalized_required_noop_json_merges = {
        path.resolve(): copy.deepcopy(value)
        for path, value in (required_noop_json_merges or {}).items()
        if isinstance(value, dict)
    }
    acknowledged_required_noop_merges: dict[Path, dict[str, Any]] = {}
    acknowledged_optional_noop_merges: dict[Path, dict[str, Any]] = {}
    rejected_prior_failed_board_attempt: dict[str, Any] | None = None
    agent_transaction_rejection: dict[str, Any] | None = None
    retry_agent_without_real_tool = False

    if status != raw_status:
        protocol_normalizations.append(
            {
                "field": "status",
                "from": raw_status,
                "to": status,
                "guard": "nonempty file_edits with no approval or declared blocker",
            }
        )

    if status != "ready_to_apply":
        blockers.append(f"implementation agent status is not ready_to_apply: {status}")
    if approvals:
        blockers.append(f"implementation agent requested approval: {approvals}")
    if not edits:
        blockers.append("implementation agent returned no file edits")

    for index, edit in enumerate(edits):
        if not isinstance(edit, dict):
            blockers.append(f"file_edits[{index}] is not an object")
            continue
        raw_path = str(edit.get("path") or "")
        target = Path(raw_path)
        target = target if target.is_absolute() else Path.cwd() / target
        target = target.resolve()
        if target in seen_edit_targets:
            blockers.append(
                f"file_edits[{index}] duplicates an earlier resolved target: {target}"
            )
            continue
        seen_edit_targets.add(target)
        operation = str(edit.get("operation") or "")
        expected = str(edit.get("expected_sha256") or "")
        content = str(edit.get("content") or "")
        json_content_supplied = "json_content" in edit
        json_content = edit.get("json_content")
        text_replacements_supplied = "text_replacements" in edit
        text_replacements = edit.get("text_replacements")
        if not allowed_capability_edit_target(
            target,
            run_dir,
            allow_template_repair=allow_template_repair,
            allow_board_integration=allow_board_integration,
            allowed_semantic_rtl_files=allowed_semantic_rtl_files,
        ):
            blockers.append(f"file_edits[{index}] target is outside the capability-repair write boundary: {target}")
            continue
        if allowed_exact_files is not None and target not in allowed_exact_files:
            blockers.append(f"file_edits[{index}] target is outside the current semantic repair phase: {target}")
            continue
        if operation not in {"create", "replace", "replace_text", "merge_json"}:
            blockers.append(f"file_edits[{index}] has unsupported operation: {operation}")
            continue
        if operation == "replace_text" and json_content_supplied:
            blockers.append(
                f"file_edits[{index}] replace_text cannot use json_content: {target}"
            )
            continue
        if json_content_supplied:
            if target.suffix.lower() != ".json":
                blockers.append(
                    f"file_edits[{index}] json_content is allowed only for .json targets: {target}"
                )
                continue
            if content:
                blockers.append(
                    f"file_edits[{index}] must use exactly one of content or json_content"
                )
                continue
            if not isinstance(json_content, dict):
                blockers.append(f"file_edits[{index}] json_content is not an object")
                continue
            if operation != "merge_json":
                content = json.dumps(json_content, indent=2, sort_keys=True) + "\n"
                protocol_normalizations.append(
                    {
                        "field": f"file_edits[{index}].json_content",
                        "operation": "serialize_structured_json_content",
                        "guard": "target suffix is .json and string content is empty",
                    }
                )
        elif operation == "merge_json":
            blockers.append(
                f"file_edits[{index}] merge_json requires json_content: {target}"
            )
            continue
        if operation == "create" and not target.exists() and expected == "absent":
            protocol_normalizations.append(
                {
                    "field": f"file_edits[{index}].expected_sha256",
                    "from": "absent",
                    "to": "",
                    "guard": "operation=create and target does not exist",
                }
            )
            expected = ""
        if target.exists() and operation not in {"replace", "replace_text", "merge_json"}:
            blockers.append(f"file_edits[{index}] must use replace for existing file: {target}")
            continue
        if not target.exists() and operation != "create":
            blockers.append(f"file_edits[{index}] must use create for missing file: {target}")
            continue
        actual = ""
        if target.exists():
            actual = sha256_file(target)
            # File versions are historical notes only.  Current source text,
            # path permissions, and unique replacement anchors decide whether
            # an edit can be applied; an old digest must not stop repair.
            if expected and expected != actual:
                protocol_normalizations.append(
                    {
                        "field": f"file_edits[{index}].expected_sha256",
                        "operation": "ignore_old_file_version",
                        "guard": "the current source is used for this edit",
                    }
                )
        elif expected:
            protocol_normalizations.append(
                {
                    "field": f"file_edits[{index}].expected_sha256",
                    "operation": "ignore_old_file_version_for_new_file",
                    "guard": "file creation is decided by the current path state",
                }
            )
        if operation == "merge_json":
            if text_replacements_supplied:
                blockers.append(
                    f"file_edits[{index}] merge_json cannot use text_replacements: {target}"
                )
                continue
            try:
                current_json = json.loads(target.read_text(encoding="utf-8"))
            except (OSError, UnicodeError, json.JSONDecodeError) as exc:
                blockers.append(
                    f"file_edits[{index}] merge_json cannot read current JSON object {target}: {exc}"
                )
                continue
            if not isinstance(current_json, dict):
                blockers.append(
                    f"file_edits[{index}] merge_json target is not a JSON object: {target}"
                )
                continue
            required_authority_patch = normalized_required_noop_json_merges.get(
                target
            )
            if (
                required_authority_patch is not None
                and json_content != required_authority_patch
            ):
                protocol_normalizations.append(
                    {
                        "field": f"file_edits[{index}].json_content",
                        "operation": (
                            "bind_framework_owned_checkpoint_contract_authority"
                        ),
                        "agent_supplied_patch_sha256": canonical_contract_sha256(
                            json_content
                        ),
                        "authority_patch_sha256": canonical_contract_sha256(
                            required_authority_patch
                        ),
                        "guard": (
                            "the complete checkpoint manifest contract is framework-owned; "
                            "the Agent merge declares intent but cannot change adapter paths, "
                            "hashes, ABI invariants, or the framework-derived DUT root"
                        ),
                    }
                )
                json_content = copy.deepcopy(required_authority_patch)
            merged_json = _deep_merge_json_object(current_json, json_content)
            if merged_json == current_json:
                required_noop_patch = normalized_required_noop_json_merges.get(
                    target
                )
                required_noop_acknowledgement = (
                    required_exact_files is not None
                    and target in {path.resolve() for path in required_exact_files}
                    and required_noop_patch is not None
                    and json_content == required_noop_patch
                )
                provenance_binding = (
                    _bind_current_exact_board_generation_provenance(
                        merged_json,
                        out_dir,
                    )
                    if allow_board_integration
                    and target.name == "dut_weight_binding_manifest.json"
                    and _exact_board_generation_provenance_rebind_intent(
                        json_content
                    )
                    else None
                )
                if provenance_binding is None and not required_noop_acknowledgement:
                    protocol_normalizations.append(
                        {
                            "field": f"file_edits[{index}].json_content",
                            "operation": "skip_unchanged_json_update",
                            "guard": "the current JSON already contains this update",
                        }
                    )
                    continue
                if provenance_binding is not None:
                    protocol_normalizations.append(provenance_binding)
                if required_noop_acknowledgement:
                    acknowledged_required_noop_merges[target] = {
                        "patch_sha256": canonical_contract_sha256(json_content),
                    }
            content = json.dumps(merged_json, indent=2, sort_keys=True) + "\n"
            protocol_normalizations.append(
                {
                    "field": f"file_edits[{index}].json_content",
                    "operation": "materialize_hash_bound_deep_json_merge",
                    "patch_sha256": canonical_contract_sha256(json_content),
                    "patched_leaf_paths": _json_patch_leaf_paths(json_content),
                    "guard": (
                        "pre-edit SHA-256 matched, target and patch were JSON objects, "
                        "explicit object keys were recursively merged, and omitted fields "
                        "were preserved without implicit deletion"
                    ),
                }
            )
        elif operation == "replace_text":
            if target.suffix.lower() == ".json":
                blockers.append(
                    f"file_edits[{index}] replace_text is not allowed for JSON: {target}"
                )
                continue
            if content:
                blockers.append(
                    f"file_edits[{index}] replace_text must use empty content: {target}"
                )
                continue
            if not isinstance(text_replacements, list) or not text_replacements:
                blockers.append(
                    f"file_edits[{index}] replace_text has no text_replacements: {target}"
                )
                continue
            try:
                before_text = target.read_text(encoding="utf-8")
            except (OSError, UnicodeError) as exc:
                blockers.append(
                    f"file_edits[{index}] replace_text cannot read UTF-8 source {target}: {exc}"
                )
                continue
            replacement_records: list[dict[str, Any]] = []
            replacement_error = False
            for replacement_index, replacement in enumerate(text_replacements):
                if not isinstance(replacement, dict):
                    blockers.append(
                        f"file_edits[{index}].text_replacements[{replacement_index}] is not an object"
                    )
                    replacement_error = True
                    break
                old_text = replacement.get("old_text")
                new_text = replacement.get("new_text")
                if not isinstance(old_text, str) or not old_text:
                    blockers.append(
                        f"file_edits[{index}].text_replacements[{replacement_index}].old_text is empty or invalid"
                    )
                    replacement_error = True
                    break
                if not isinstance(new_text, str):
                    blockers.append(
                        f"file_edits[{index}].text_replacements[{replacement_index}].new_text is invalid"
                    )
                    replacement_error = True
                    break
                match_count = before_text.count(old_text)
                if match_count != 1:
                    blockers.append(
                        f"file_edits[{index}].text_replacements[{replacement_index}].old_text must match exactly once in sequence; found {match_count}"
                    )
                    replacement_error = True
                    break
                if old_text == new_text:
                    blockers.append(
                        f"file_edits[{index}].text_replacements[{replacement_index}] does not change the source"
                    )
                    replacement_error = True
                    break
                start = before_text.find(old_text)
                replacement_records.append(
                    {
                        "replacement_index": replacement_index,
                        "start": start,
                        "end": start + len(old_text),
                    }
                )
            if replacement_error:
                continue
            ordered_records = sorted(replacement_records, key=lambda row: row["start"])
            for prior, current in zip(ordered_records, ordered_records[1:]):
                if current["start"] < prior["end"]:
                    blockers.append(
                        f"file_edits[{index}] replace_text anchors overlap in the pre-edit source"
                    )
                    replacement_error = True
                    break
            if replacement_error:
                continue
            patched_text = before_text
            for record in reversed(ordered_records):
                replacement = text_replacements[record["replacement_index"]]
                patched_text = (
                    patched_text[: record["start"]]
                    + replacement["new_text"]
                    + patched_text[record["end"] :]
                )
            if patched_text == before_text:
                blockers.append(
                    f"file_edits[{index}] replace_text leaves the source unchanged: {target}"
                )
                continue
            content = patched_text
            protocol_normalizations.append(
                {
                    "field": f"file_edits[{index}].text_replacements",
                    "operation": "materialize_unique_text_replacements",
                    "replacement_count": len(replacement_records),
                    "replacements": [
                        {
                            key: value
                            for key, value in record.items()
                            if key not in {"start", "end"}
                        }
                        for record in replacement_records
                    ],
                    "guard": (
                        "every old_text matched exactly once in the original source, "
                        "anchors did not overlap, and replacements "
                        "were materialized by descending original offset"
                    ),
                }
            )
        elif text_replacements_supplied:
            blockers.append(
                f"file_edits[{index}] text_replacements requires operation=replace_text"
            )
            continue
        if not content:
            blockers.append(f"file_edits[{index}] content is empty: {target}")
            continue
        if (
            allow_board_integration
            and target.name == "dut_weight_binding_manifest.json"
            and operation == "replace"
            and target.is_file()
        ):
            prior_manifest = read_json_if_exists(target)
