                        target,
                        prior_manifest,
                        out_dir,
                    )
                )
                and isinstance(agent_manifest, dict)
                and isinstance(prior_manifest.get("stage_harnesses"), dict)
                and isinstance(prior_manifest.get("single_layer_harness"), dict)
            ):
