                    agent_manifest,
                    prior_manifest,
                )
                content = json.dumps(agent_manifest, indent=2, sort_keys=True) + "\n"
                protocol_normalizations.append(
                    {
                        "field": f"file_edits[{index}].content",
                        "operation": "preserve_certified_lower_layer_bindings",
                        "preserved_fields": list(preserved_fields),
                        "certified_manifest_sha256": actual,
                        "guard": (
                            "board manifest replace over a certified lower-layer manifest with "
                            "complete stage and single-layer bindings"
                        ),
                    }
                )
            if isinstance(agent_manifest, dict):
                (
                    generation_record_path,
                    generation_record,
                    trusted_generation,
                ) = select_trusted_exact_board_generation_record(
                    out_dir,
                    expected_status="ready_to_apply",
                )
                harness = agent_manifest.get("multilayer_harness")
                if (
                    trusted_generation.get("status") == "pass"
                    and isinstance(harness, dict)
                ):
                    harness["generation_provenance"] = {
                        "mode": "llm",
                        "agent_id": generation_record.get("agent"),
                        "model": generation_record.get("model"),
                        "used_fallback": generation_record.get("used_fallback"),
                        "prompt_sha256": trusted_generation.get("prompt_sha256"),
                        "prompt_path": trusted_generation.get("prompt_path"),
                        "record_path": str(generation_record_path),
                        "record_sha256": trusted_generation.get("sha256"),
                    }
                    content = json.dumps(
                        agent_manifest, indent=2, sort_keys=True
                    ) + "\n"
                    protocol_normalizations.append(
                        {
                            "field": f"file_edits[{index}].content",
                            "operation": "bind_exact_board_llm_generation_provenance",
                            "trusted_generation_record": str(
                                generation_record_path
                            ),
                            "trusted_generation_record_sha256": (
                                trusted_generation.get("sha256")
                            ),
                            "prompt_sha256": trusted_generation.get(
                                "prompt_sha256"
                            ),
                            "guard": (
                                "current exact-board generation record is a "
                                "non-fallback ready_to_apply LLM record with "
                                "hash-verified prompt"
                            ),
                        }
                    )
        total_bytes += len(content.encode("utf-8"))
        if total_bytes > 2_000_000:
            blockers.append("implementation patch exceeds the 2 MB bounded-repair limit")
            continue
        if target.name == "dut_weight_binding_manifest.json":
            try:
                parsed = json.loads(content)
                if not isinstance(parsed, dict):
                    raise ValueError("manifest is not an object")
            except (json.JSONDecodeError, ValueError) as exc:
                blockers.append(f"DUT weight-binding manifest is invalid JSON: {exc}")
                continue
        # Keep the observed pre-edit identity in the framework record even
        # when a narrow replace_text edit intentionally omitted it from the
        # LLM response. Later real-tool failures need this provenance to
        # become reusable negative experiments.
        staged.append((target, content, operation, actual or expected))

    changed_source_hashes: dict[Path, tuple[str, str]] = {}
    semantic_manifest_path = (
        run_dir
        / "verification"
        / "semantic_testbench"
        / "semantic_testbench_manifest.json"
    ).resolve()
    binding_manifest_path = (
        run_dir
        / "generated"
        / "memory"
        / "dut_weight_binding_manifest.json"
    ).resolve()
    if allow_board_integration and allowed_semantic_rtl_files:
        allowed_semantic_paths = {
            path.resolve() for path in (allowed_semantic_rtl_files or set())
        }
        for target, content, _, expected in staged:
            if target not in allowed_semantic_paths or not target.is_file():
                continue
            before = sha256_file(target)
            after = hashlib.sha256(content.encode("utf-8")).hexdigest()
            if before and before != after:
                changed_source_hashes[target] = (before, after)

        # The connected-layer source is shared by the semantic and board
        # bindings. Keep both derived manifests in the same transaction as the
        # RTL edit; the board preflight manifest is regenerated later by the
        # normal finalizer, so its old copy remains historical evidence.
        staged_paths = {target for target, _, _, _ in staged}
        for derived_path, label in (
            (semantic_manifest_path, "semantic_testbench_manifest.json"),
            (binding_manifest_path, "dut_weight_binding_manifest.json"),
        ):
            if not changed_source_hashes or derived_path in staged_paths:
                continue
            if not derived_path.is_file():
                blockers.append(f"derived manifest is missing for source hash rebinding: {derived_path}")
                continue
            try:
                derived_content = derived_path.read_text(encoding="utf-8")
            except (OSError, UnicodeError) as exc:
                blockers.append(
                    f"{label} cannot be read for deterministic source hash rebinding: {exc}"
                )
                continue
            staged.append(
                (
                    derived_path,
                    derived_content,
                    "replace",
                    sha256_file(derived_path),
                )
            )
            staged_paths.add(derived_path)
            protocol_normalizations.append(
                {
                    "field": label,
                    "operation": "stage_manifest_for_semantic_source_hash_rebinding",
                    "changed_source_paths": sorted(
                        str(path) for path in changed_source_hashes
                    ),
                    "guard": (
                        "a current successful semantic RTL edit changed a source used by "
                        "the connected and board bindings"
                    ),
                }
            )

    if allow_board_integration and staged:
        board_root = (run_dir / "generated" / "board_integration").resolve()
        manifest_path = (
            run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json"
        ).resolve()
        staged_paths = {target for target, _, _, _ in staged}
        board_source_changed = any(
            target.is_relative_to(board_root)
            and target.suffix.lower() in BOARD_INTEGRATION_SOURCE_SUFFIXES
            for target in staged_paths
        )
        if board_source_changed and manifest_path not in staged_paths:
            if manifest_path.is_file():
                try:
                    manifest_content = manifest_path.read_text(encoding="utf-8")
                except (OSError, UnicodeError) as exc:
                    blockers.append(
                        f"current board binding manifest cannot be read for deterministic hash rebinding: {exc}"
                    )
                else:
                    staged.append(
                        (
                            manifest_path,
                            manifest_content,
                            "replace",
                            sha256_file(manifest_path),
                        )
                    )
                    protocol_normalizations.append(
                        {
                            "field": "dut_weight_binding_manifest.json",
                            "operation": "stage_existing_manifest_for_board_source_hash_rebinding",
                            "guard": (
                                "an agent-owned board source changed while the semantic "
                                "manifest contract remained unchanged"
                            ),
                        }
                    )
        staged_by_path = {target: content for target, content, _, _ in staged}
        normalized_staged: list[tuple[Path, str, str, str]] = []
        for target, content, operation, expected in staged:
            if target == semantic_manifest_path:
                try:
                    parsed_manifest = json.loads(content)
                except (json.JSONDecodeError, TypeError) as exc:
                    blockers.append(
                        f"semantic_testbench_manifest.json is invalid JSON during source hash rebinding: {exc}"
                    )
                    continue
                if not isinstance(parsed_manifest, dict):
                    blockers.append("semantic_testbench_manifest.json is not a JSON object")
                    continue
                rebound, rebind_report = rebind_changed_source_hashes_in_manifest(
                    parsed_manifest,
                    run_dir,
                    changed_source_hashes,
                    staged_content_by_path=staged_by_path,
                    require_match=True,
                )
                blockers.extend(
                    f"semantic_testbench_manifest.json: {error}"
                    for error in rebind_report.get("blockers", [])
                    if str(error)
                )
                protocol_normalizations.append(
                    {
                        "field": str(target),
                        "operation": "rebind_changed_source_hashes_in_manifest",
                        "report": rebind_report,
                    }
                )
                content = json.dumps(rebound, indent=2, sort_keys=True) + "\n"
                normalized_staged.append((target, content, operation, expected))
                continue
            if target.name != "dut_weight_binding_manifest.json":
                normalized_staged.append((target, content, operation, expected))
                continue
            try:
                manifest = json.loads(content)
            except json.JSONDecodeError:
                normalized_staged.append((target, content, operation, expected))
                continue
            provenance_already_bound = any(
                isinstance(row, dict)
                and row.get("operation")
                == "bind_exact_board_llm_generation_provenance"
                for row in protocol_normalizations
            )
            harness = manifest.get("multilayer_harness")
            if not provenance_already_bound and isinstance(harness, dict):
                (
                    generation_record_path,
                    generation_record,
                    trusted_generation,
                ) = select_trusted_exact_board_generation_record(
                    out_dir,
                    expected_status="ready_to_apply",
                )
                if trusted_generation.get("status") == "pass":
                    harness["generation_provenance"] = {
                        "mode": "llm",
                        "agent_id": generation_record.get("agent"),
                        "model": generation_record.get("model"),
                        "used_fallback": generation_record.get("used_fallback"),
                        "prompt_sha256": trusted_generation.get("prompt_sha256"),
                        "prompt_path": trusted_generation.get("prompt_path"),
                        "record_path": str(generation_record_path),
                        "record_sha256": trusted_generation.get("sha256"),
                    }
                    protocol_normalizations.append(
                        {
                            "field": "dut_weight_binding_manifest.json",
                            "operation": "bind_exact_board_llm_generation_provenance",
                            "trusted_generation_record": str(
                                generation_record_path
                            ),
                            "trusted_generation_record_sha256": (
                                trusted_generation.get("sha256")
                            ),
                            "prompt_sha256": trusted_generation.get(
                                "prompt_sha256"
                            ),
                            "guard": (
                                "an exact-board RTL repair auto-staged the semantic "
                                "manifest and the hash-bound generation record is a "
                                "non-fallback ready_to_apply LLM result"
                            ),
                        }
                    )
            manifest = canonicalize_exact_board_manifest_declarations(
                manifest,
                run_dir,
                out_dir,
                staged_content_by_path=staged_by_path,
            )
            board_plan = manifest.get("board_simulation_preflight_plan")
            if isinstance(board_plan, dict):
                board_testbench = (
                    board_plan.get("testbench", {})
                    if isinstance(board_plan.get("testbench"), dict)
                    else {}
                )
                declared_checkpoint_contract = board_testbench.get(
                    "simulation_checkpoint_contract"
                )
                if declared_checkpoint_contract is not None:
                    if not isinstance(declared_checkpoint_contract, dict):
                        blockers.append(
                            "simulation checkpoint contract in the board manifest is not an object"
                        )
                    else:
                        blockers.extend(
                            "simulation_checkpoint_contract: " + error
                            for error in checkpoint_contract_errors(
                                declared_checkpoint_contract
                            )
                        )
                missing_prerequisites = framework_vcs_plan_binding_missing_prerequisites(
                    run_dir,
                    str(
                        board_plan.get("validation_mode")
                        or "exact_sample_physical_ddr"
                    ),
                )
                if missing_prerequisites:
                    blockers.append(
                        "framework VCS-plan binding prerequisites are missing: "
                        + "; ".join(missing_prerequisites)
                    )
                else:
                    manifest, vcs_binding = bind_framework_vcs_compile_plan(
                        manifest,
                        run_dir,
                        out_dir,
                        target,
                    )
                    blockers.extend(vcs_binding.get("blockers", []))
                    if vcs_binding.get("status") == "pass":
                        protocol_normalizations.append(
                            {
                                "field": (
                                    "dut_weight_binding_manifest.json."
                                    "board_simulation_preflight_plan.vcs_compile_plan"
                                ),
                                "operation": "bind_framework_vcs_compile_plan",
                                "ordered_command_count": vcs_binding.get(
                                    "ordered_command_count"
                                ),
                                "compile_source_count": vcs_binding.get(
                                    "compile_source_count"
                                ),
                                "vcs_compile_plan_sha256": vcs_binding.get(
                                    "vcs_compile_plan_sha256"
                                ),
                                "guard": (
                                    "plan is regenerated from the agent-selected source replacement, "
                                    "fixture selection and testbench top plus immutable Vivado/fixture authority"
                                ),
                            }
                        )
            manifest, binding = bind_agent_owned_board_source_hashes(
                manifest,
                run_dir,
                staged_by_path,
            )
            if changed_source_hashes:
                manifest, rebind_report = rebind_changed_source_hashes_in_manifest(
                    manifest,
                    run_dir,
                    changed_source_hashes,
                    staged_content_by_path=staged_by_path,
                    require_match=True,
                )
                blockers.extend(
                    f"dut_weight_binding_manifest.json: {error}"
                    for error in rebind_report.get("blockers", [])
                    if str(error)
                )
                protocol_normalizations.append(
                    {
                        "field": str(target),
                        "operation": "rebind_changed_source_hashes_in_manifest",
                        "report": rebind_report,
                    }
                )
            blockers.extend(binding["blockers"])
            content = json.dumps(manifest, indent=2, sort_keys=True) + "\n"
            normalized_staged.append((target, content, operation, expected))
            if binding["bound_source_ids"]:
                protocol_normalizations.append(
                    {
                        "field": "dut_weight_binding_manifest.json",
                        "operation": "bind_agent_owned_board_source_hashes",
                        "bound_source_ids": binding["bound_source_ids"],
                        "guard": (
                            "board source identity is inside generated/board_integration "
                            "and its final content is available in the same staged edit or on disk"
                        ),
                    }
                )
        staged = normalized_staged
        total_bytes = sum(len(content.encode("utf-8")) for _, content, _, _ in staged)
        if total_bytes > 2_000_000 and "implementation patch exceeds the 2 MB bounded-repair limit" not in blockers:
            blockers.append("implementation patch exceeds the 2 MB bounded-repair limit")

    if required_template_pairs is not None:
        framework_root = (Path.cwd() / "accagent" / "framework" / "templates" / "operator_chisel").resolve()
        generated_root = (
            run_dir / "generated" / "chisel" / "src" / "main" / "scala" / "spatialaccagent" / "templates"
        ).resolve()
        staged_by_path = {target: content for target, content, _, _ in staged}
        edited_names = {
            target.name
            for target in staged_by_path
            if target.is_relative_to(framework_root) or target.is_relative_to(generated_root)
        }
        for name in sorted(required_template_pairs | edited_names):
            persistent = framework_root / name
            generated = generated_root / name
            if persistent not in staged_by_path or generated not in staged_by_path:
                blockers.append(f"semantic template repair must replace both persistent/generated copies of {name}")
                continue
            if staged_by_path[persistent] != staged_by_path[generated]:
                blockers.append(f"persistent/generated semantic template contents differ for {name}")

    if instrumentation_only_template_pairs is not None:
        framework_root = (Path.cwd() / "accagent" / "framework" / "templates" / "operator_chisel").resolve()
        generated_root = (
            run_dir / "generated" / "chisel" / "src" / "main" / "scala" / "spatialaccagent" / "templates"
        ).resolve()
        staged_by_path = {target: content for target, content, _, _ in staged}
        for name in sorted(instrumentation_only_template_pairs):
            persistent = framework_root / name
            generated = generated_root / name
            if persistent not in staged_by_path or generated not in staged_by_path:
                continue
            before = persistent.read_text(encoding="utf-8")
            blockers.extend(
                f"{name}: {error}"
                for error in template_trace_instrumentation_errors(
                    before,
                    staged_by_path[persistent],
                )
            )

    # Earlier failed candidates remain in the Agent's repair history, but they
    # are not a veto.  Current internal signals and the current code decide
    # whether the next small edit is worth running through real board VCS.

    normalized_required = {
        path.resolve() for path in (required_exact_files or set())
    }
    replace_text_contract_markers = (
        "replace_text cannot use json_content",
        "replace_text must use empty content",
        "replace_text has no text_replacements",
        ".text_replacements[",
        "replace_text anchors overlap",
        "text_replacements requires operation=replace_text",
    )
    replace_text_contract_blockers = [
        blocker
        for blocker in blockers
        if blocker.startswith("file_edits[")
        and any(marker in blocker for marker in replace_text_contract_markers)
    ]
    checkpoint_transaction_cascade = (
        "required checkpoint manifest no-op acknowledgement requires a "
        "materially changed paired atomic edit target",
        "implementation patch is missing a required atomic edit target:",
    )
    checkpoint_transaction_blockers_only = bool(replace_text_contract_blockers) and all(
        blocker in replace_text_contract_blockers
        or blocker.startswith(checkpoint_transaction_cascade)
        for blocker in blockers
    )
    if (
        status == "ready_to_apply"
        and not approvals
        and not declared_blockers
        and len(normalized_required) == 2
        and len(normalized_required_noop_json_merges) == 1
        and checkpoint_transaction_blockers_only
        and set(seen_edit_targets) == normalized_required
    ):
        manifest_path = next(iter(normalized_required_noop_json_merges))
        paired_path = next(iter(normalized_required - {manifest_path}), None)
        indexed_edits: dict[Path, dict[str, Any]] = {}
        for edit in edits:
            if not isinstance(edit, dict):
                continue
            raw_target = Path(str(edit.get("path") or ""))
            target = (
                raw_target if raw_target.is_absolute() else Path.cwd() / raw_target
            ).resolve()
            indexed_edits[target] = edit
        manifest_edit = indexed_edits.get(manifest_path, {})
        paired_edit = indexed_edits.get(paired_path, {}) if paired_path else {}
        if (
            manifest_path in acknowledged_required_noop_merges
            and manifest_edit.get("operation") == "merge_json"
            and paired_path is not None
            and paired_edit.get("operation") == "replace_text"
            and all(path.is_file() for path in normalized_required)
        ):
            retry_agent_without_real_tool = True
            agent_transaction_rejection = {
                "schema_version": "spatialaccagent.agent_transaction_rejection.v1",
                "status": "ready_for_agent_retry",
                "failure_class": "checkpoint_atomic_replace_text_contract",
                "blockers": copy.deepcopy(blockers),
                "file_edits_were_not_applied": True,
                "real_tool_replay_required_before_retry": False,
                "unchanged_pre_edit_files": [
                    {
                        "path": str(path),
                        "sha256": sha256_file(path),
                    }
                    for path in sorted(normalized_required)
                ],
            }

    replace_text_contract_only = bool(blockers) and all(
        blocker.startswith("file_edits[")
        and (
            ".text_replacements" in blocker
            or " replace_text " in blocker
        )
        for blocker in blockers
    )
    if (
        status == "ready_to_apply"
        and not approvals
        and not declared_blockers
        and agent_transaction_rejection is None
        and replace_text_contract_only
    ):
        retry_agent_without_real_tool = True
        agent_transaction_rejection = {
            "schema_version": "spatialaccagent.agent_transaction_rejection.v1",
            "status": "ready_for_agent_retry",
            "failure_class": "atomic_replace_text_contract",
            "blockers": copy.deepcopy(blockers),
            "file_edits_were_not_applied": True,
            "real_tool_replay_required_before_retry": False,
            "unchanged_pre_edit_files": [
                {
                    "path": str(path),
                    "sha256": sha256_file(path),
                }
                for path in sorted(seen_edit_targets)
                if path.is_file()
            ],
        }

    if (
        agent_contract_blockers
        and (status == "ready_to_apply" or agent_contract_retry_on_blocked)
        and not approvals
    ):
        retry_agent_without_real_tool = True
        agent_transaction_rejection = {
            "schema_version": "spatialaccagent.agent_transaction_rejection.v1",
            "status": "ready_for_agent_retry",
            "failure_class": agent_contract_failure_class,
            "blockers": list(dict.fromkeys(blockers)),
            "file_edits_were_not_applied": True,
            "real_tool_replay_required_before_retry": False,
            "unchanged_pre_edit_files": [
                {
                    "path": str(path),
                    "sha256": sha256_file(path),
                }
                for path in sorted(seen_edit_targets)
                if path.is_file()
            ],
        }

    if agent_transaction_rejection is not None:
        agent_transaction_rejection["rejected_file_edits"] = (
            rejected_file_edits_for_agent_retry(edits)
        )

    records = []
    if not blockers:
        ordered_staged = sorted(
            staged,
            key=lambda row: row[0].name == "dut_weight_binding_manifest.json",
        )
        for target, content, operation, expected in ordered_staged:
            target.parent.mkdir(parents=True, exist_ok=True)
            temp = target.with_name(f".{target.name}.spatialaccagent.tmp")
            temp.write_text(content, encoding="utf-8")
            temp.replace(target)
            records.append(
                {
                    "path": str(target),
                    "operation": operation,
                    "before_sha256": expected or None,
                    "after_sha256": sha256_file(target),
                    "bytes": target.stat().st_size,
                }
            )

    report = {
        "schema_version": "spatialaccagent.agent_patch_application.v1",
        "status": "pass" if not blockers else "blocked",
        "agent_status": status,
        "raw_agent_status": raw_status,
        "protocol_normalizations": protocol_normalizations,
        "files": records,
        "blockers": blockers,
        "retry_agent_without_real_tool": retry_agent_without_real_tool,
        "rejected_prior_failed_board_attempt": (
            rejected_prior_failed_board_attempt
        ),
        "agent_transaction_rejection": agent_transaction_rejection,
        "requested_validation": output.get("requested_validation", []),
        "repair_checkpoint": repair_checkpoint,
        "policy": {
            "all_edits_validated_before_any_write": True,
            "golden_reference_input_policy_and_verification_reports_are_read_only": True,
            "existing_generated_dut_rtl_is_read_only_for_capability_repair": True,
            "bounded_selected_template_repair_approved": (
                bounded_template_repair_approved()
                if allow_template_repair is None
                else allow_template_repair
            ),
            "semantic_selected_template_repair_approved": (
                semantic_template_repair_approved()
                if allow_template_repair is None
                else allow_template_repair and semantic_template_repair_approved()
            ),
            "template_repair_must_preserve_external_architecture_stage_order_memory_runtime_and_numeric_contracts": True,
            "template_instrumentation_blocks_are_mechanically_non_functional": (
                instrumentation_only_template_pairs is not None
            ),
            "exact_text_replacements_require_unique_anchors": True,
            "board_source_edits_rebind_derived_manifest_hashes": True,
            "prior_real_vcs_failed_board_source_state_is_never_rewritten_or_relaunched": True,
        },
    }
    report_path = out_dir / report_name
    write_json(report_path, report)
    report["path"] = str(report_path)
    return report


def normalize_harness_sources(
    harness: dict[str, Any],
    run_dir: Path,
) -> tuple[list[dict[str, Any]], str, list[str]]:
    allowed_roots = [
        (run_dir / "generated" / "semantic_harness").resolve(),
        (run_dir / "generated" / "chisel").resolve(),
    ]
    semantic_root = (run_dir / "generated" / "semantic_harness").resolve()
    rows: list[dict[str, Any]] = []
    combined: list[str] = []
    blockers: list[str] = []
    candidates: list[tuple[str, Any]] = []
    source_directory = harness.get("source_directory")
    resolved_source_directory: Path | None = None
    if source_directory:
        directory = Path(str(source_directory))
        if not directory.is_absolute():
            blockers.append(f"source_directory must be absolute: {directory}")
        else:
            directory = directory.resolve()
            if not directory.is_relative_to(semantic_root):
                blockers.append(f"source_directory is outside generated semantic-harness root: {directory}")
            elif not directory.is_dir():
                blockers.append(f"source_directory does not exist after elaboration: {directory}")
            else:
                resolved_source_directory = directory
                for path in sorted(directory.rglob("*")):
                    if path.is_file() and path.suffix.lower() in {".sv", ".v"}:
                        candidates.append(("source_directory", path))
    source_files = harness.get("source_files", [])
    if not isinstance(source_files, list):
        blockers.append("source_files must be a list when supplied")
        source_files = []
    # A successful re-elaboration makes the isolated directory authoritative.
    # Prior source rows may name diagnostic files that were intentionally removed.
    if resolved_source_directory is None:
        for index, item in enumerate(source_files):
            candidates.append((f"source_files[{index}]", item))

    seen_paths: set[Path] = set()
    module_owners: dict[str, Path] = {}
    for label, item in candidates:
        raw = item.get("path") if isinstance(item, dict) else item
        path = Path(str(raw or ""))
        path = path if path.is_absolute() else Path.cwd() / path
        path = path.resolve()
        if path in seen_paths:
            continue
        seen_paths.add(path)
        if resolved_source_directory is not None and not path.is_relative_to(resolved_source_directory):
            blockers.append(
                f"{label} is outside the declared isolated source_directory: {path}"
            )
            continue
        if not any(path.is_relative_to(root) for root in allowed_roots):
            blockers.append(f"{label} is outside generated harness/DUT roots: {path}")
            continue
        if path.suffix.lower() not in {".sv", ".v"} or not path.is_file():
            blockers.append(f"{label} is not an existing Verilog/SystemVerilog file: {path}")
            continue
        try:
            text = path.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError) as exc:
            blockers.append(f"cannot read harness source {path}: {exc}")
            continue
        for module in re.findall(r"(?m)^module\s+([A-Za-z_][A-Za-z0-9_$]*)\b", text):
            owner = module_owners.get(module)
            if owner is not None:
                blockers.append(
                    f"stage source set declares module {module} more than once: {owner} and {path}"
                )
            else:
                module_owners[module] = path
        rows.append({"path": str(path), "sha256": sha256_file(path)})
        combined.append(text)
    if not rows:
        blockers.append("harness has no valid source files after source-directory discovery")
    return rows, "\n".join(combined), blockers


def run_agent_requested_validation(
    output: dict[str, Any],
    run_dir: Path,
    out_dir: Path,
    timeout_sec: int,
    *,
    report_name: str = "agent_requested_validation.json",
) -> dict[str, Any]:
    requests = output.get("requested_validation", []) if isinstance(output.get("requested_validation"), list) else []
    generated_root = (run_dir / "generated" / "chisel").resolve()
    validated: list[tuple[list[str], Path, str]] = []
    blockers: list[str] = []
    allowed_flags = {"--no-server", "--batch", "--supershell=false"}
    for index, request in enumerate(requests):
        if not isinstance(request, dict):
            blockers.append(f"requested_validation[{index}] is not an object")
            continue
        argv = [str(value) for value in request.get("argv", [])]
        cwd = Path(str(request.get("cwd") or ""))
        cwd = cwd if cwd.is_absolute() else Path.cwd() / cwd
        cwd = cwd.resolve()
        purpose = str(request.get("purpose") or "")
        if cwd != generated_root:
            blockers.append(f"requested_validation[{index}] cwd is outside the generated Chisel project: {cwd}")
            continue
        if not argv or argv[0] != "sbt":
            blockers.append(f"requested_validation[{index}] may invoke only sbt")
            continue
        goals = [value for value in argv[1:] if value not in allowed_flags]
        if len(goals) != 1:
            blockers.append(f"requested_validation[{index}] must contain exactly one allowed sbt goal")
            continue
        goal = goals[0]
        if goal != "Compile/compile" and not re.fullmatch(
            r"runMain spatialaccagent\.semantic_harness\.[A-Za-z_][A-Za-z0-9_$.]*",
            goal,
        ):
            blockers.append(f"requested_validation[{index}] has disallowed sbt goal: {goal}")
            continue
        if any(value.startswith("-") and value not in allowed_flags for value in argv[1:]):
            blockers.append(f"requested_validation[{index}] has a disallowed sbt option")
            continue
        validated.append((argv, cwd, purpose))

    semantic_root = (run_dir / "generated" / "semantic_harness").resolve()
    declared_output_roots: set[Path] = set()

    def collect_declared_output_roots(value: Any) -> None:
        if isinstance(value, dict):
            source_directory = value.get("source_directory")
            if source_directory:
                path = Path(str(source_directory))
                if path.is_absolute():
                    path = path.resolve()
                    if path != semantic_root and path.is_relative_to(semantic_root):
                        declared_output_roots.add(path)
            for child in value.values():
                collect_declared_output_roots(child)
        elif isinstance(value, list):
            for child in value:
                collect_declared_output_roots(child)

    for edit in output.get("file_edits", []):
        if isinstance(edit, dict):
            collect_declared_output_roots(edit.get("json_content"))

    results = []
    heap_mb: int | None = None
    if not blockers:
        cache_root = (run_dir / "generated" / ".sbt_codegen_cache").resolve()
        sbt_global = cache_root / "sbt"
        sbt_boot = sbt_global / "boot"
        ivy_home = cache_root / "ivy2"
        coursier_cache = cache_root / "coursier"
        for path in (sbt_global, sbt_boot, ivy_home, coursier_cache):
            path.mkdir(parents=True, exist_ok=True)
        env = os.environ.copy()
        heap_mb = configured_sbt_heap_mb(env)
        local_opts = (
            f"-Xms256m -Xmx{heap_mb}m -XX:+UseG1GC "
            f"-Dsbt.global.base={sbt_global} "
            f"-Dsbt.boot.directory={sbt_boot} "
            f"-Dsbt.ivy.home={ivy_home} "
            "-Dsbt.server.autostart=false "
            "-Dsbt.server.forcestart=true"
        )
        env["SBT_OPTS"] = f"{env.get('SBT_OPTS', '')} {local_opts}".strip()
        env.setdefault("COURSIER_CACHE", str(coursier_cache))
        for argv, cwd, purpose in validated:
            cleaned_output_roots: list[str] = []
            if any(
                value.startswith("runMain spatialaccagent.semantic_harness.")
                for value in argv
            ):
                for emitted_root in sorted(declared_output_roots):
                    if emitted_root.exists():
                        shutil.rmtree(emitted_root)
                    emitted_root.mkdir(parents=True)
                    cleaned_output_roots.append(str(emitted_root))
            result = run_local_tool(argv, cwd, env, timeout_sec)
            results.append(
                {
                    "purpose": purpose,
                    "argv": argv,
                    "cwd": str(cwd),
                    "cleaned_output_root": (
                        cleaned_output_roots[0]
                        if len(cleaned_output_roots) == 1
                        else None
                    ),
                    "cleaned_output_roots": cleaned_output_roots,
                    **result,
                }
            )
            if result.get("status") != "pass":
                blockers.append(f"requested validation failed: {purpose or argv}")
                break

    report = {
        "schema_version": "spatialaccagent.agent_requested_validation.v1",
        "status": "pass" if not blockers else "fail",
        "requests": len(requests),
        "sbt_heap_mb": heap_mb,
        "results": results,
        "blockers": blockers,
    }
    report_path = out_dir / report_name
    write_json(report_path, report)
    report["path"] = str(report_path)
    return report


def harness_contract_errors(
    harness: dict[str, Any],
    required_hashes: set[str],
    expected_layout_hash: str,
    expected_runtime_hash: str,
    run_dir: Path,
    generated_modules: set[str],
) -> tuple[dict[str, Any], list[str]]:
    normalized = dict(harness)
    source_rows, source_text, blockers = normalize_harness_sources(harness, run_dir)
    normalized["source_files"] = source_rows
    top_module = str(harness.get("top_module") or "")
    top_sources: list[Path] = []
    for row in source_rows:
        path = Path(str(row["path"]))
        text = path.read_text(encoding="utf-8")
        if top_module and re.search(rf"(?m)^module\s+{re.escape(top_module)}\b", text):
            top_sources.append(path)
    if not top_module or not top_sources:
        blockers.append(f"harness top module is not declared by its source files: {top_module or '<missing>'}")
    wrapper_text = "\n".join(path.read_text(encoding="utf-8") for path in top_sources)
    top_port_text = ""
    if wrapper_text and top_module:
        declaration = re.search(rf"(?m)^module\s+{re.escape(top_module)}\b", wrapper_text)
        if declaration:
            cursor = declaration.end()

            def balanced_parentheses(start: int) -> tuple[str, int]:
                depth = 0
                for index in range(start, len(wrapper_text)):
                    char = wrapper_text[index]
                    if char == "(":
                        depth += 1
                    elif char == ")":
                        depth -= 1
                        if depth == 0:
                            return wrapper_text[start + 1 : index], index + 1
                return "", start

            while cursor < len(wrapper_text) and wrapper_text[cursor].isspace():
                cursor += 1
            if cursor < len(wrapper_text) and wrapper_text[cursor] == "#":
                cursor += 1
                while cursor < len(wrapper_text) and wrapper_text[cursor].isspace():
                    cursor += 1
                _, cursor = balanced_parentheses(cursor)
                while cursor < len(wrapper_text) and wrapper_text[cursor].isspace():
                    cursor += 1
            if cursor < len(wrapper_text) and wrapper_text[cursor] == "(":
                top_port_text, _ = balanced_parentheses(cursor)
    if top_sources and not top_port_text:
        blockers.append(f"semantic harness top-module port list could not be parsed: {top_module}")
    instantiated = [
        module
        for module in generated_modules
        if re.search(rf"\b{re.escape(module)}\s+(?:#\s*\([^;]*?\)\s*)?[A-Za-z_][A-Za-z0-9_$]*\s*\(", wrapper_text, re.DOTALL)
    ]
    if not instantiated:
        blockers.append("semantic harness does not instantiate a generated DUT module")
    declared_modules = set(
        re.findall(r"(?m)^module\s+([A-Za-z_][A-Za-z0-9_$]*)\b", source_text)
    )
    missing_instantiated_sources = sorted(set(instantiated) - declared_modules)
    if missing_instantiated_sources:
        blockers.append(
            "semantic harness source set is not self-contained for generated DUT modules: "
            + str(missing_instantiated_sources)
        )
    normalized["generated_dut_modules"] = sorted(instantiated)
    if re.search(r"\$readmem|expected\.memh|model_reference|golden", wrapper_text, re.IGNORECASE):
        blockers.append("semantic harness source attempts to read or reference expected/golden data")
    interface = harness.get("interface", {}) if isinstance(harness.get("interface"), dict) else {}
    inputs = interface.get("inputs", []) if isinstance(interface.get("inputs"), list) else []
    output = interface.get("output", {}) if isinstance(interface.get("output"), dict) else {}
    input_data_ports = {
        str(port.get("data_port"))
        for port in inputs
        if isinstance(port, dict) and port.get("data_port")
    }
    if has_interface_data_identity_path(
        wrapper_text,
        input_data_ports,
        str(output.get("data_port") or ""),
    ):
        blockers.append("semantic harness contains a direct input-to-output identity bypass")

    def missing(value: Any) -> bool:
        return value is None or value == "" or value == 0

    def require_declared_port(value: Any, label: str) -> None:
        port = str(value or "")
        if port and top_port_text and not re.search(rf"\b{re.escape(port)}\b", top_port_text):
            blockers.append(f"semantic harness top module does not declare {label}: {port}")

    for name in ("clock_port", "reset_port"):
        port = str(interface.get(name) or "")
        if not port or not top_port_text or not re.search(rf"\b{re.escape(port)}\b", top_port_text):
            blockers.append(f"semantic harness interface is missing connected {name}: {port or '<missing>'}")
    if not inputs:
        blockers.append("semantic harness interface has no input stream")
    for index, port in enumerate(inputs):
        if not isinstance(port, dict):
            blockers.append(f"semantic harness input {index} is not an object")
            continue
        for name in ("valid_port", "ready_port", "data_port", "data_width_bits"):
            value = port.get(name)
            if missing(value):
                blockers.append(f"semantic harness input {index} is missing {name}")
            elif name.endswith("_port"):
                require_declared_port(value, f"input {index} {name}")
        if not missing(port.get("last_port")):
            require_declared_port(port.get("last_port"), f"input {index} last_port")
    for name in ("valid_port", "ready_port", "data_port", "data_width_bits"):
        if missing(output.get(name)):
            blockers.append(f"semantic harness output is missing {name}")
        elif name.endswith("_port"):
            require_declared_port(output.get(name), f"output {name}")
    if not missing(output.get("last_port")):
        require_declared_port(output.get("last_port"), "output last_port")
    if not missing(interface.get("start_port")):
        require_declared_port(interface.get("start_port"), "start_port")
    for index, constant in enumerate(interface.get("constant_ports", [])):
        if not isinstance(constant, dict):
            blockers.append(f"semantic harness constant port {index} is not an object")
            continue
        if missing(constant.get("port")):
            blockers.append(f"semantic harness constant port {index} is missing port")
        else:
            require_declared_port(constant.get("port"), f"constant port {index}")

    consumed = {str(value) for value in harness.get("consumed_tensor_hashes", []) if str(value)}
    missing_hashes = sorted(required_hashes - consumed)
    if missing_hashes:
        blockers.append(f"semantic harness is missing {len(missing_hashes)} required tensor hash(es)")
    normalized["consumed_tensor_hashes"] = sorted(consumed)
    if required_hashes:
        if harness.get("weight_layout_contract_sha256") != expected_layout_hash:
            blockers.append("weighted semantic harness does not bind the required weight-layout contract hash")
        if harness.get("default_or_identity_weight_fallback_disabled") is not True:
            blockers.append("weighted semantic harness does not disable default/identity fallback")
        loader = interface.get("weight_loader", {}) if isinstance(interface.get("weight_loader"), dict) else {}
        for name in (
            "valid_port",
            "ready_port",
            "data_port",
            "data_width_bits",
            "addr_port",
            "addr_width_bits",
            "last_port",
        ):
            if missing(loader.get(name)):
                blockers.append(f"weighted semantic harness loader is missing {name}")
            elif name.endswith("_port"):
                require_declared_port(loader.get(name), f"weight loader {name}")
        if loader.get("data_width_bits") not in {32, "32"}:
            blockers.append("weighted semantic harness loader data width must be 32 bits")
    if expected_runtime_hash:
        if harness.get("runtime_constant_contract_sha256") != expected_runtime_hash:
            blockers.append("semantic harness does not bind the required runtime-constant contract hash")
        runtime_loader = interface.get("runtime_loader", {}) if isinstance(interface.get("runtime_loader"), dict) else {}
        for name in (
            "valid_port",
            "ready_port",
            "data_port",
            "data_width_bits",
            "addr_port",
            "addr_width_bits",
            "last_port",
        ):
            if missing(runtime_loader.get(name)):
                blockers.append(f"runtime-constant semantic harness loader is missing {name}")
            elif name.endswith("_port"):
                require_declared_port(runtime_loader.get(name), f"runtime loader {name}")
        if runtime_loader.get("data_width_bits") not in {32, "32"}:
            blockers.append("runtime-constant semantic harness loader data width must be 32 bits")
        normalized["runtime_constant_contract_sha256"] = expected_runtime_hash
    return normalized, blockers


def connected_harness_contract_errors(
    harness: dict[str, Any],
    requirements: dict[str, Any],
    run_dir: Path,
    generated_modules: set[str],
) -> tuple[dict[str, Any], list[str]]:
    weight_contract = (
        requirements.get("connected_weight_stream_contract", {})
        if isinstance(requirements.get("connected_weight_stream_contract"), dict)
        else {}
    )
    runtime_contract = (
        requirements.get("connected_runtime_stream_contract", {})
        if isinstance(requirements.get("connected_runtime_stream_contract"), dict)
        else {}
    )
    overlap_contract = (
        requirements.get("single_layer_pipeline_overlap_contract", {})
        if isinstance(requirements.get("single_layer_pipeline_overlap_contract"), dict)
        else {}
    )
    required_hashes = {
        str(row.get("sha256"))
        for row in requirements.get("single_layer_required_tensors", [])
        if isinstance(row, dict) and row.get("sha256")
    }
    weight_hash = str(weight_contract.get("contract_sha256") or "")
    runtime_hash = str(runtime_contract.get("contract_sha256") or "")
    normalized, blockers = harness_contract_errors(
        harness,
        required_hashes,
        weight_hash,
        runtime_hash,
        run_dir,
        generated_modules,
    )
    if not weight_hash or weight_contract.get("status") != "pass":
        blockers.append("connected canonical weight-stream contract is not ready")
    if not runtime_hash or runtime_contract.get("status") != "pass":
        blockers.append("connected canonical runtime-stream contract is not ready")
    trace_contract_hash = str(
        overlap_contract.get("trace_contract_sha256")
        or overlap_contract.get("contract_sha256")
        or ""
    )
    expected_fields = {
        "connected_weight_stream_contract_sha256": weight_hash,
        "connected_runtime_stream_contract_sha256": runtime_hash,
        "pipeline_plan_sha256": requirements.get("pipeline_plan_sha256"),
    }
    for field, expected in expected_fields.items():
        if not expected or harness.get(field) != expected:
            blockers.append(f"connected semantic harness does not bind required {field}")
        else:
            normalized[field] = expected
    compatible_trace_contracts = {
        str(value)
        for value in overlap_contract.get("compatible_trace_contract_sha256s", [])
        if str(value)
    }
    compatible_trace_contracts.add(trace_contract_hash)
    if (
        not trace_contract_hash
        or str(harness.get("pipeline_overlap_trace_contract_sha256") or "")
        not in compatible_trace_contracts
    ):
        blockers.append(
            "connected semantic harness does not bind required pipeline_overlap_trace_contract_sha256"
        )
    else:
        normalized["pipeline_overlap_trace_contract_sha256"] = trace_contract_hash
    blockers.extend(connected_loader_route_errors(harness, weight_contract, runtime_contract))
    route_contract = (
        harness.get("loader_route_contract", {})
        if isinstance(harness.get("loader_route_contract"), dict)
        else {}
    )
    normalized["loader_route_contract"] = route_contract
    normalized["loader_route_contract_sha256"] = hashlib.sha256(
        json.dumps(route_contract, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    return normalized, blockers


def bind_agent_owned_board_source_hashes(
    manifest: dict[str, Any],
    run_dir: Path,
    staged_content_by_path: dict[Path, str],
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Bind agent-owned board manifest rows to their final same-batch contents."""

    normalized = copy.deepcopy(manifest)
    board_root = (run_dir / "generated" / "board_integration").resolve()
    staged_content = {
        path.resolve(): content for path, content in staged_content_by_path.items()
    }
    source_hashes: dict[str, str] = {}
    bound_source_ids: set[str] = set()
    blockers: list[str] = []

    def bind_source_row(row: Any, label: str) -> str | None:
        if not isinstance(row, dict):
            return None
        raw_path = str(row.get("path") or row.get("local_path") or "").strip()
        if not raw_path:
            return None
        path = Path(raw_path).expanduser()
        path = path if path.is_absolute() else Path.cwd() / path
        try:
            path = path.resolve()
        except OSError as exc:
            blockers.append(f"{label} path cannot be resolved before board hash binding: {exc}")
            return None
        if (
            not path.is_relative_to(board_root)
            or path.suffix.lower() not in {".v", ".sv"}
        ):
            return None
        content = staged_content.get(path)
        if content is not None:
            digest = hashlib.sha256(content.encode("utf-8")).hexdigest()
        elif path.is_file():
            digest = sha256_file(path)
        else:
            blockers.append(
                f"{label} agent-owned board source is neither staged nor present: {path}"
            )
            return None
        row["sha256"] = digest
        if "local_sha256" in row:
            row["local_sha256"] = digest
        source_id = str(row.get("source_id") or "").strip()
        if source_id:
            prior = source_hashes.get(source_id)
            if prior is not None and prior != digest:
                blockers.append(
                    f"{label} source_id resolves to conflicting final board source hashes: {source_id}"
                )
            else:
                source_hashes[source_id] = digest
                bound_source_ids.add(source_id)
        return digest

    def bind_source_rows(value: Any, label: str) -> None:
        if not isinstance(value, list):
            return
        for index, row in enumerate(value):
            bind_source_row(row, f"{label}[{index}]")

    top_harness = normalized.get("multilayer_harness")
    if isinstance(top_harness, dict):
        bind_source_rows(
            top_harness.get("source_files"),
            "multilayer_harness.source_files",
        )

    plan = normalized.get("board_simulation_preflight_plan")
    if isinstance(plan, dict):
        plan_harness = plan.get("multilayer_harness")
        if isinstance(plan_harness, dict):
            bind_source_rows(
                plan_harness.get("source_files"),
                "board_simulation_preflight_plan.multilayer_harness.source_files",
            )

        replacements = plan.get("source_replacements")
        if isinstance(replacements, list):
            for index, replacement in enumerate(replacements):
                if not isinstance(replacement, dict):
                    continue
                digest = bind_source_row(
                    replacement.get("source"),
                    f"board_simulation_preflight_plan.source_replacements[{index}].source",
                )
                generated_path = str(
                    replacement.get("generated_source_path") or ""
                ).strip()
                if generated_path:
                    generated_row = {
                        "source_id": replacement.get("generated_source_id"),
                        "path": generated_path,
                    }
                    generated_digest = bind_source_row(
                        generated_row,
                        f"board_simulation_preflight_plan.source_replacements[{index}]",
                    )
                    digest = generated_digest or digest
                if digest:
                    replacement["generated_source_sha256"] = digest

        testbench_plan = plan.get("testbench")
        if isinstance(testbench_plan, dict):
            testbench_source = testbench_plan.get("source")
            if isinstance(testbench_source, dict):
                testbench_digest = bind_source_row(
                    testbench_source,
                    "board_simulation_preflight_plan.testbench.source",
                )
            else:
                testbench_digest = bind_source_row(
                    testbench_plan,
                    "board_simulation_preflight_plan.testbench",
                )
            scan = testbench_plan.get("forbidden_construct_scan")
            if testbench_digest and isinstance(scan, dict):
                scan["source_sha256"] = testbench_digest
            debug_contract = testbench_plan.get("debug_observability_contract")
            probes = (
                debug_contract.get("probes")
                if isinstance(debug_contract, dict)
                else None
            )
            if isinstance(probes, list):
                for probe in probes:
                    if not isinstance(probe, dict):
                        continue
                    digest = source_hashes.get(str(probe.get("source_id") or ""))
                    if digest:
                        probe["source_sha256"] = digest

        monitor_contract = plan.get("protocol_monitor_contract")
        monitors = (
            monitor_contract.get("monitors")
            if isinstance(monitor_contract, dict)
            else None
        )
        if isinstance(monitors, list):
            for index, monitor in enumerate(monitors):
                if isinstance(monitor, dict):
                    bind_source_rows(
                        monitor.get("source_files"),
                        (
                            "board_simulation_preflight_plan.protocol_monitor_contract."
                            f"monitors[{index}].source_files"
                        ),
                    )

        evidence_records = plan.get("generated_evidence_records")
        if isinstance(evidence_records, list):
            for row in evidence_records:
                if not isinstance(row, dict):
                    continue
                digest = source_hashes.get(str(row.get("source_id") or ""))
                if digest:
                    row["source_sha256"] = digest

    top_evidence_records = normalized.get("generated_evidence_records")
    if isinstance(top_evidence_records, list):
        for row in top_evidence_records:
            if not isinstance(row, dict):
                continue
            digest = source_hashes.get(str(row.get("source_id") or ""))
            if digest:
                row["source_sha256"] = digest

    return normalized, {
        "bound_source_ids": sorted(bound_source_ids),
        "blockers": list(dict.fromkeys(blockers)),
    }


def board_integration_binding_errors(
    manifest: dict[str, Any],
    single_layer_harness: dict[str, Any],
    run_dir: Path,
    out_dir: Path,
    single_layer_certificate_path: Path | None = None,
    source_provenance: dict[str, Any] | None = None,
) -> tuple[dict[str, Any] | None, list[str]]:
    from accagent.framework.board_acceptance_contract import compile_source_set_fingerprint

    blockers: list[str] = []
    identity_path = run_dir / "verification" / "board_interface" / "board_source_identity.json"
    model_path = run_dir / "input" / "model_config.json"
    catalog_path = run_dir / "verification" / "model_weights" / "transformer_block_weight_catalog.json"
    memory_path = run_dir / "generated" / "chisel" / "memory" / "memory_layout.json"
    runtime_paths = exact_board_memory_runtime_paths(run_dir, out_dir)
    runtime_contract = read_json_if_exists(runtime_paths["contract"])
    image_manifest = read_json_if_exists(runtime_paths["image_manifest"])
    identity = read_json_if_exists(identity_path)
    model = read_json_if_exists(model_path)
    task_card = read_json_if_exists(run_dir / "input" / "task_card.json")
    catalog = read_json_if_exists(catalog_path)
    try:
        board_scope = resolve_board_validation_scope(task_card, model)
    except BoardValidationScopeError as exc:
        return None, [f"board validation scope is invalid: {exc}"]
    model_layer_count = board_scope.model_layer_count
    target_layers = board_scope.validation_layer_count
    validation_layer_indices = list(board_scope.layer_indices)
    required_hashes = {
        str(row.get("source_slice_sha256"))
        for row in catalog.get("tensors", [])
        if (
            isinstance(row, dict)
            and row.get("layer_index") in validation_layer_indices
            and row.get("source_slice_sha256")
        )
    }
    consumed_hashes = {
        str(value) for value in manifest.get("board_consumed_tensor_hashes", []) if str(value)
    }
    harness = manifest.get("multilayer_harness")
    if not isinstance(harness, dict):
        return None, ["DUT binding has no LLM-generated multi-layer board integration harness"]

    generation_record_path, generation_record, trusted_generation = (
        select_trusted_exact_board_generation_record(
            out_dir,
            expected_status="ready_to_apply",
        )
    )
    generation_output = trusted_generation.get("output", {})
    current_generation_is_trusted = (
        generation_record.get("agent") == EXACT_BOARD_GENERATION_AGENT
        and generation_record.get("mode") == "llm"
        and generation_record.get("used_fallback") is False
        and bool(generation_record.get("model"))
        and not generation_record.get("error")
        and trusted_generation.get("status") == "pass"
        and normalized_implementation_agent_status(generation_output)
        == "ready_to_apply"
    )
    durable_provenance = _attested_exact_board_generation_provenance(
        harness,
        source_provenance or {},
    )
    # Once an applied Agent transaction has been archived and attested, that
    # immutable provenance remains authoritative across deterministic
    # rematerialization.  The canonical LLM result path is mutable and may
    # already contain a later rejected or unrelated attempt.
    if durable_provenance is not None:
        provenance = durable_provenance
    elif current_generation_is_trusted:
        provenance = {
            "mode": "llm",
            "agent_id": generation_record.get("agent"),
            "model": generation_record.get("model"),
            "used_fallback": generation_record.get("used_fallback"),
            "prompt_sha256": trusted_generation.get("prompt_sha256"),
            "record_path": str(generation_record_path),
            "record_sha256": sha256_file(generation_record_path),
        }
    else:
        provenance = copy.deepcopy(
            harness.get("generation_provenance")
            if isinstance(harness.get("generation_provenance"), dict)
            else {}
        )
        blockers.append("multi-layer board integration is not bound to a non-fallback LLM generation agent")

    board_root = (run_dir / "generated" / "board_integration").resolve()
    certified_resume_rows: dict[str, tuple[Path, str]] = {}
    for index, row in enumerate(single_layer_harness.get("source_files", [])):
        if not isinstance(row, dict):
            continue
        path = Path(str(row.get("path") or "")).resolve()
        source_hash = str(row.get("sha256") or "")
        if source_hash:
            certified_resume_rows[
                f"certified_kernel.{index:04d}.{source_hash[:16]}"
            ] = (path, source_hash)
    source_rows: list[dict[str, Any]] = []
    source_texts: list[str] = []
    declared_modules: set[str] = set()
    module_owners: dict[str, Path] = {}
    source_ids: set[str] = set()
    for index, row in enumerate(harness.get("source_files", [])):
        if not isinstance(row, dict):
            blockers.append(f"multilayer_harness.source_files[{index}] is not an object")
            continue
        path = Path(str(row.get("path") or ""))
        path = path if path.is_absolute() else Path.cwd() / path
        path = path.resolve()
        source_id = str(row.get("source_id") or "")
        role = str(row.get("role") or "")
        if role == "generated_kernel":
            expected = certified_resume_rows.get(source_id)
            if (
                expected is not None
                and path == expected[0]
                and str(row.get("sha256") or "") == expected[1]
            ):
                continue
            blockers.append(
                f"multilayer_harness.source_files[{index}] is not an exact framework-materialized certified source"
            )
            continue
        if not source_id or source_id in source_ids:
            blockers.append(f"multilayer_harness.source_files[{index}] has a missing or duplicate source_id")
        else:
            source_ids.add(source_id)
        if role not in {"compute_slot_adapter", "generated_accelerator"}:
            blockers.append(
                f"multilayer_harness.source_files[{index}] role must be compute_slot_adapter or generated_accelerator"
            )
        if not path.is_relative_to(board_root):
            blockers.append(f"multi-layer board source is outside generated/board_integration: {path}")
            continue
        if path.suffix.lower() not in {".sv", ".v"} or not path.is_file():
            blockers.append(f"multi-layer board source is missing or is not RTL: {path}")
            continue
        actual_hash = sha256_file(path)
        if row.get("sha256") and row.get("sha256") != actual_hash:
            blockers.append(f"multi-layer board source hash mismatch: {path}")
            continue
        text = path.read_text(encoding="utf-8")
        modules = re.findall(r"(?m)^\s*module\s+([A-Za-z_][A-Za-z0-9_$]*)\b", text)
        for module in modules:
            if module in module_owners:
                blockers.append(
                    f"multi-layer board source set declares module {module} more than once: "
                    f"{module_owners[module]} and {path}"
                )
            module_owners[module] = path
            declared_modules.add(module)
        source_rows.append(
            {
                **row,
                "path": str(path),
                "sha256": actual_hash,
                "declared_modules": modules,
                "dependencies": [str(value) for value in row.get("dependencies", []) if str(value)],
            }
        )
        source_texts.append(text)

    certified_kernel_ids: list[str] = []
    for index, row in enumerate(single_layer_harness.get("source_files", [])):
        if not isinstance(row, dict):
            blockers.append(f"certified single-layer source_files[{index}] is not an object")
            continue
        path = Path(str(row.get("path") or "")).resolve()
        if not path.is_file() or path.suffix.lower() not in {".sv", ".v"}:
            blockers.append(f"certified single-layer source is missing or invalid: {path}")
            continue
        actual_hash = sha256_file(path)
        if row.get("sha256") != actual_hash:
            blockers.append(f"certified single-layer source hash mismatch: {path}")
            continue
        source_id = f"certified_kernel.{index:04d}.{actual_hash[:16]}"
        if source_id in source_ids:
            blockers.append(f"certified single-layer source_id collision: {source_id}")
            continue
        source_ids.add(source_id)
        text = path.read_text(encoding="utf-8")
        modules = re.findall(r"(?m)^\s*module\s+([A-Za-z_][A-Za-z0-9_$]*)\b", text)
        for module in modules:
            if module in module_owners:
                blockers.append(
                    f"board compile source set declares module {module} more than once: "
                    f"{module_owners[module]} and {path}"
                )
            module_owners[module] = path
            declared_modules.add(module)
        certified_kernel_ids.append(source_id)
        source_rows.append(
            {
                "source_id": source_id,
                "role": "generated_kernel",
                "path": str(path),
                "sha256": actual_hash,
                "declared_modules": modules,
                "dependencies": [],
            }
        )
        source_texts.append(text)
    if not source_rows:
        blockers.append("multi-layer board integration has no hash-verified generated RTL sources")

    top_module = str(harness.get("top_module") or "")
    single_layer_top = str(single_layer_harness.get("top_module") or "")
    if not top_module or top_module not in declared_modules:
        blockers.append("multi-layer board top_module is not declared by its generated source set")
    if not single_layer_top or harness.get("verified_single_layer_top_module") != single_layer_top:
        blockers.append("multi-layer board harness is not bound to the certified single-layer top module")
    combined_source = "\n".join(source_texts)
    actual_kernel_count = (
        len(
            re.findall(
                rf"\b{re.escape(single_layer_top)}\s+(?:#\s*\(.*?\)\s*)?[A-Za-z_][A-Za-z0-9_$]*\s*\(",
                combined_source,
                re.DOTALL,
            )
        )
        if single_layer_top
        else 0
    )
    if actual_kernel_count != 1 or harness.get("instantiated_kernel_count") != 1:
        blockers.append("multi-layer board shell must instantiate exactly one reusable certified single-layer kernel")

    if model_layer_count <= 0:
        blockers.append("target model layer count is missing")
    if (
        manifest.get("model_layer_count", model_layer_count) != model_layer_count
        or manifest.get("validation_layer_indices", validation_layer_indices)
        != validation_layer_indices
        or manifest.get("all_target_layers") is not board_scope.covers_full_model
        or int(manifest.get("bound_layer_count") or 0) != target_layers
        or harness.get("target_layer_count") != target_layers
    ):
        blockers.append("board scheduler does not bind the current validation workload")
    if (
        catalog.get("status") != "pass"
        or catalog.get("scope_coverage_complete") is not True
        or not required_hashes
        or required_hashes != consumed_hashes
    ):
        blockers.append("board binding does not cover the exact validation-layer Transformer-block weights")

    integration = manifest.get("board_integration_contract", {}) if isinstance(manifest.get("board_integration_contract"), dict) else {}
    identity_hashes = {
        "source_closure_sha256": identity.get("selected_simulation_source_closure_sha256"),
        "compute_slot_abi_sha256": identity.get("compute_slot_abi_sha256"),
        "timing_contract_sha256": identity.get("timing_contract_sha256"),
        "axi_interfaces_sha256": identity.get("axi_interfaces_sha256"),
    }
    if identity.get("status") != "pass":
        blockers.append("LLM-interpreted exact board identity has not passed deterministic fact validation")
    for field, expected in identity_hashes.items():
        if not expected or integration.get(field) != expected:
            blockers.append(f"board integration contract does not bind current {field}")
    if not memory_path.is_file() or integration.get("memory_layout_sha256") != sha256_file(memory_path):
        blockers.append("board integration contract does not bind the current stage memory-layout proposal")
    required_runtime_hashes = {
        "board_memory_runtime_contract_sha256": (
            sha256_file(runtime_paths["contract"])
            if runtime_paths["contract"].is_file()
            else None
        ),
        "full_weight_image_manifest_sha256": (
            sha256_file(runtime_paths["image_manifest"])
            if runtime_paths["image_manifest"].is_file()
            else None
        ),
        "full_weight_image_sha256": (
            sha256_file(runtime_paths["image"])
            if runtime_paths["image"].is_file()
            else None
        ),
    }
    if runtime_paths["runtime_capture"].is_file():
        required_runtime_hashes[
            "full_layer_runtime_capture_contract_sha256"
        ] = sha256_file(runtime_paths["runtime_capture"])
    runtime_constants = (
        runtime_contract.get("runtime_constants", {})
        if isinstance(runtime_contract.get("runtime_constants"), dict)
        else {}
    )
    if runtime_constants.get("enabled") is True:
        required_runtime_hashes.update(
            {
                "full_runtime_image_manifest_sha256": (
                    sha256_file(runtime_paths["runtime_image_manifest"])
                    if runtime_paths["runtime_image_manifest"].is_file()
                    else None
                ),
                "full_runtime_image_sha256": (
                    sha256_file(runtime_paths["runtime_image"])
                    if runtime_paths["runtime_image"].is_file()
                    else None
                ),
            }
        )
    if (
        runtime_contract.get("validation", {}).get("status") != "pass"
        or image_manifest.get("status") != "pass"
        or image_manifest.get("image_sha256")
        != required_runtime_hashes["full_weight_image_sha256"]
    ):
        blockers.append("current validated board runtime/weight-image authority is unavailable")
    for field, expected in required_runtime_hashes.items():
        if not expected or integration.get(field) != expected:
            blockers.append(f"board integration contract does not bind current {field}")

    required_mechanisms = {
        "scheduler": ("enabled", "all_validation_layers"),
        "double_weight_buffer": ("enabled",),
        "activation_ping_pong": ("enabled", "terminal_writeback_from_output_bank"),
        "final_writeback": ("enabled", "only_after_last_layer"),
        "intra_layer_spatial_pipeline": (
            "preserved",
            "different_tokens_overlap_across_required_dataflow",
            "heterogeneous_stage_latency_supported",
            "stage_turnover_gaps_are_diagnostic",
        ),
    }
    for mechanism, required_true_fields in required_mechanisms.items():
        contract = integration.get(mechanism, {}) if isinstance(integration.get(mechanism), dict) else {}
        if any(contract.get(field) is not True for field in required_true_fields):
            blockers.append(f"board integration contract does not preserve required mechanism {mechanism}")
    prefetch = (
        integration.get("background_prefetch", {})
        if isinstance(integration.get("background_prefetch"), dict)
        else {}
    )
    if board_scope.requires_next_layer_prefetch:
        if (
            prefetch.get("enabled") is not True
            or prefetch.get("overlaps_current_layer_compute") is not True
            or prefetch.get("prefetch_scope") != "next_layer_weights"
            or prefetch.get("next_layer_prefetch_required") is not True
        ):
            blockers.append("board integration contract does not preserve next-layer prefetch overlap")
    elif (
        prefetch.get("enabled") is not False
        or prefetch.get("overlaps_current_layer_compute") is not False
        or prefetch.get("prefetch_scope") != "none"
        or prefetch.get("next_layer_prefetch_required") is not False
    ):
        blockers.append("single-layer terminal board schedule fabricates next-layer prefetch")
    weight_buffer = integration.get("double_weight_buffer", {}) if isinstance(integration.get("double_weight_buffer"), dict) else {}
    activation_buffer = integration.get("activation_ping_pong", {}) if isinstance(integration.get("activation_ping_pong"), dict) else {}
    spatial_pipeline = integration.get("intra_layer_spatial_pipeline", {}) if isinstance(integration.get("intra_layer_spatial_pipeline"), dict) else {}
    if weight_buffer.get("bank_count", 0) < 2:
        blockers.append("board integration weight buffer has fewer than two banks")
    if activation_buffer.get("bank_count", 0) < 2:
        blockers.append("board integration activation buffer has fewer than two banks")
    if weight_buffer.get("atomic_layer_switch") is not board_scope.requires_next_layer_prefetch:
        blockers.append("board integration weight-bank switch does not match validation scope")
    if activation_buffer.get("inter_layer_chaining") is not board_scope.requires_next_layer_prefetch:
        blockers.append("board integration activation chaining does not match validation scope")
    if spatial_pipeline.get("serial_leaf_execution") is not False:
        blockers.append("board integration contract does not forbid serial leaf-module execution")
    if (
        spatial_pipeline.get("pipeline_semantics")
        != "elastic_rate_insensitive_token_pipeline"
        or spatial_pipeline.get("all_stages_same_cycle_concurrency_required") is not False
    ):
        blockers.append(
            "board integration contract does not preserve elastic rate-insensitive pipeline semantics"
        )

    certificate_path = single_layer_certificate_path.resolve() if single_layer_certificate_path else Path()
    certificate = read_json_if_exists(certificate_path) if certificate_path.is_file() else {}
    if not certificate_path.is_file() or certificate.get("status") != "pass":
        blockers.append("single-layer promotion certificate is missing or is not pass")
        certificate_artifact: dict[str, Any] = {}
    else:
        certificate_artifact = {
            "path": str(certificate_path),
            "sha256": sha256_file(certificate_path),
        }

    normalized = {
        **harness,
        "generation_provenance": provenance,
        "source_files": source_rows,
        "source_set_sha256": compile_source_set_fingerprint(source_rows),
        "certified_kernel_source_ids": certified_kernel_ids,
        "single_layer_promotion_certificate": certificate_artifact,
        "verified_single_layer_top_module": single_layer_top,
        "instantiated_kernel_count": actual_kernel_count,
        "target_layer_count": target_layers,
    }
    return normalized, blockers


def _exact_board_closure_rows(identity: dict[str, Any]) -> list[dict[str, Any]]:
    closure = identity.get("selected_simulation_source_closure")
    if isinstance(closure, list):
        return [row for row in closure if isinstance(row, dict)]
    if isinstance(closure, dict):
        for field in ("source_files", "sources", "files", "materialized_sources"):
            rows = closure.get(field)
            if isinstance(rows, list):
                return [row for row in rows if isinstance(row, dict)]
    return []


def _safe_board_relative_path(value: Any) -> bool:
    path = Path(str(value or ""))
    return bool(path.name) and not path.is_absolute() and ".." not in path.parts


def _generated_rtl_modules(path: Path) -> list[str]:
    text = path.read_text(encoding="utf-8", errors="ignore")
    text = re.sub(r"/\*.*?\*/", "", text, flags=re.DOTALL)
    text = re.sub(r"//[^\n]*", "", text)
    return sorted(
        set(
            re.findall(
                r"\bmodule\s+(?:automatic\s+)?([A-Za-z_][A-Za-z0-9_$]*)\b",
                text,
            )
        )
    )


def _normalize_exact_board_source(
    row: Any,
    *,
    label: str,
    base_dir: Path,
    blockers: list[str],
    generated_role: str | None = None,
    allowed_root: Path | None = None,
) -> dict[str, Any] | None:
    if not isinstance(row, dict):
        blockers.append(f"{label} is not an object")
        return None
    source_id = str(row.get("source_id") or "").strip()
    role = str(row.get("role") or row.get("source_role") or "").strip().lower()
    raw_path = str(row.get("path") or row.get("local_path") or "").strip()
    expected_hash = str(row.get("sha256") or row.get("local_sha256") or "").strip().lower()
    if not source_id:
        blockers.append(f"{label}.source_id is missing")
    if generated_role is not None and role != generated_role:
        blockers.append(f"{label}.role must be {generated_role}")
    if not role:
        blockers.append(f"{label}.role is missing")
    if not raw_path:
        blockers.append(f"{label}.path/local_path is missing")
        return None
    path = Path(raw_path).expanduser()
    path = path if path.is_absolute() else base_dir / path
    try:
        path = path.resolve()
    except OSError as exc:
        blockers.append(f"{label} path cannot be resolved: {exc}")
        return None
    if allowed_root is not None and not path.is_relative_to(allowed_root.resolve()):
        blockers.append(f"{label} is outside generated/board_integration: {path}")
    if not path.is_file():
        blockers.append(f"{label} source file is missing: {path}")
        return None
    if generated_role is not None or role in {
        "compute_slot_adapter",
        "generated_accelerator",
        "generated_kernel",
        "testbench",
        "protocol_monitor",
    }:
        if path.suffix.lower() not in {".sv", ".v"}:
            blockers.append(f"{label} generated source is not Verilog/SystemVerilog: {path}")
            return None
    actual_hash = sha256_file(path)
    if not re.fullmatch(r"[0-9a-f]{64}", expected_hash):
        blockers.append(f"{label}.sha256 is missing or invalid")
    elif actual_hash != expected_hash:
        blockers.append(f"{label} hash mismatch: {path}")
    dependencies = row.get("dependencies")
    if not isinstance(dependencies, list) or not all(
        isinstance(value, str) and value.strip() for value in dependencies
    ):
        blockers.append(f"{label}.dependencies must be a list of non-empty source IDs")
        dependencies = []
    dependencies = [str(value).strip() for value in dependencies]
    if len(dependencies) != len(set(dependencies)):
        blockers.append(f"{label}.dependencies contains duplicates")
    declared_modules = row.get("declared_modules")
    if generated_role is not None or role in {
        "compute_slot_adapter",
        "generated_accelerator",
        "generated_kernel",
        "testbench",
        "protocol_monitor",
    }:
        actual_modules = _generated_rtl_modules(path)
        if not isinstance(declared_modules, list) or {
            str(value).strip() for value in declared_modules if str(value).strip()
        } != set(actual_modules):
            blockers.append(f"{label}.declared_modules does not match the generated RTL")
        declared_modules = actual_modules
    elif not isinstance(declared_modules, list) or not all(
        isinstance(value, str) and value.strip() for value in declared_modules
    ):
        blockers.append(f"{label}.declared_modules must be a list of module identities")
        declared_modules = []
    else:
        declared_modules = sorted({str(value).strip() for value in declared_modules})
    staged_path = row.get("staged_path")
    if staged_path is not None and not _safe_board_relative_path(staged_path):
        blockers.append(f"{label}.staged_path is unsafe")
    normalized = copy.deepcopy(row)
    normalized.update(
        {
            "source_id": source_id,
            "role": role,
            "path": str(path),
            "sha256": actual_hash,
            "dependencies": dependencies,
            "declared_modules": declared_modules,
        }
    )
    normalized.pop("local_path", None)
    normalized.pop("local_sha256", None)
    return normalized


def _normalize_exact_board_artifact(
    row: Any,
    *,
    label: str,
    base_dir: Path,
    blockers: list[str],
) -> dict[str, Any] | None:
    if not isinstance(row, dict):
        blockers.append(f"{label} is missing")
        return None
    raw_path = str(row.get("path") or "").strip()
    expected_hash = str(row.get("sha256") or "").strip().lower()
    if not raw_path:
        blockers.append(f"{label}.path is missing")
        return None
    path = Path(raw_path).expanduser()
    path = path if path.is_absolute() else base_dir / path
    try:
        path = path.resolve()
    except OSError as exc:
        blockers.append(f"{label} path cannot be resolved: {exc}")
        return None
    if not path.is_file():
        blockers.append(f"{label} file is missing: {path}")
        return None
    actual_hash = sha256_file(path)
    if not re.fullmatch(r"[0-9a-f]{64}", expected_hash):
        blockers.append(f"{label}.sha256 is missing or invalid")
    elif actual_hash != expected_hash:
        blockers.append(f"{label} hash mismatch: {path}")
    normalized = copy.deepcopy(row)
    normalized.update({"path": str(path), "sha256": actual_hash})
    return normalized


def authoritative_board_weight_artifact(
    image_manifest: dict[str, Any],
) -> dict[str, Any]:
    """Project the immutable full-weight manifest into the board artifact schema."""

    image = image_manifest.get("image")
    image = image if isinstance(image, dict) else {}
    projected = {
        key: copy.deepcopy(image_manifest[key])
        for key in (
            "accelerator_scope",
            "scope_coverage_complete",
            "accelerator_weight_catalog_sha256",
            "source_checkpoint_sha256",
            "packed_tensor_hashes",
            "manifest_contract_sha256",
            "total_bytes",
            "layer_segments",
        )
        if key in image_manifest
    }
    projected.update(
        {
            "path": image_manifest.get("path") or image.get("path"),
            "sha256": image_manifest.get("image_sha256") or image.get("sha256"),
            "total_bytes": image_manifest.get("total_bytes")
            or image.get("total_bytes")
            or image.get("byte_count"),
        }
    )
    return projected


def materialize_exact_board_preflight_manifest(
    manifest: dict[str, Any],
    normalized_multilayer: dict[str, Any],
    run_dir: Path,
) -> dict[str, Any]:
    """Mechanically bind LLM board outputs to the exact-board preflight contract."""

    from accagent.framework.board_acceptance_contract import (
        PROTOCOL_MONITOR_REPORT_OUTPUT_KEY,
        REQUIRED_PROTOCOL_MONITOR_CHECKS,
        REQUIRED_PROTOCOL_REPORT_FIELDS,
        REQUIRED_TESTBENCH_AST_CHECKS,
        canonical_contract_sha256,
        compile_source_set_fingerprint,
        source_closure_fingerprint,
        validate_exact_board_preflight,
    )

    run_dir = run_dir.resolve()
    board_root = (run_dir / "generated" / "board_integration").resolve()
    identity_path = run_dir / "verification" / "board_interface" / "board_source_identity.json"
    semantic_path = run_dir / "verification" / "semantic_testbench" / "semantic_testbench_manifest.json"
    model_path = run_dir / "input" / "model_config.json"
    catalog_path = run_dir / "verification" / "model_weights" / "transformer_block_weight_catalog.json"
    memory_path = run_dir / "generated" / "chisel" / "memory" / "memory_layout.json"
    runtime_paths = exact_board_memory_runtime_paths(
        run_dir,
        run_dir / "repair_execution",
    )
    output_dir = run_dir / "verification" / "board_simulation"
    output_path = output_dir / "board_simulation_manifest.json"
    materialization_path = output_dir / "board_simulation_preflight_materialization.json"
    blockers: list[str] = []

    identity = read_json_if_exists(identity_path)
    semantic = read_json_if_exists(semantic_path)
    model = read_json_if_exists(model_path)
    catalog = read_json_if_exists(catalog_path)
    plan = manifest.get("board_simulation_preflight_plan")
    if not isinstance(plan, dict):
        plan = {}
        blockers.append("board_simulation_preflight_plan is missing")
    validation_mode = str(plan.get("validation_mode") or "exact_sample_physical_ddr")
    compute_slot_axi_mode = validation_mode == "compute_slot_axi"
    if compute_slot_axi_mode:
        external_fixture, external_fixture_rows, fixture_context_by_hash = {}, [], {}
    else:
        external_fixture, external_fixture_rows, fixture_context_by_hash = (
            _materialize_external_fixture_preflight_selection(plan, run_dir, blockers)
        )

    closure_rows = _exact_board_closure_rows(identity)
    if not closure_rows:
        blockers.append("exact board identity has no selected simulation source closure")
    normalized_closure: list[dict[str, Any]] = []
    for index, row in enumerate(closure_rows):
        normalized = _normalize_exact_board_source(
            row,
            label=f"board identity closure source[{index}]",
            base_dir=identity_path.parent,
            blockers=blockers,
        )
        if normalized is not None:
            normalized_closure.append(normalized)
    compile_closure_rows = [
        row for row in normalized_closure if _exact_board_simulator_compile_input(row)
    ]
    sample_runtime_auxiliary_files: list[dict[str, Any]] = []
    for row in normalized_closure:
        if _exact_board_simulator_compile_input(row):
            continue
        runtime_name = Path(str(row.get("remote_path") or row.get("path") or "")).name
        if not _safe_board_relative_path(runtime_name):
            blockers.append(
                f"sample-project runtime auxiliary source has no safe runtime basename: {row.get('source_id')}"
            )
            continue
        sample_runtime_auxiliary_files.append(
            {**copy.deepcopy(row), "runtime_staged_path": runtime_name}
        )
    if compute_slot_axi_mode:
        sample_runtime_auxiliary_files = []

    closure_hash = source_closure_fingerprint(normalized_closure) if normalized_closure else ""
    declared_closure_hash = str(identity.get("selected_simulation_source_closure_sha256") or "")
    if not closure_hash or declared_closure_hash != closure_hash:
        blockers.append("recomputed exact board source-closure hash does not match board identity")
    abi = identity.get("compute_slot_abi") if isinstance(identity.get("compute_slot_abi"), dict) else {}
    timing = identity.get("timing_contract") if isinstance(identity.get("timing_contract"), dict) else {}
    axi_interfaces = identity.get("axi_interfaces") if isinstance(identity.get("axi_interfaces"), list) else []
    abi_hash = canonical_contract_sha256(abi) if abi else ""
    timing_hash = canonical_contract_sha256(timing) if timing else ""
    axi_hash = canonical_contract_sha256(axi_interfaces) if axi_interfaces else ""
    for field, actual in (
        ("compute_slot_abi_sha256", abi_hash),
        ("timing_contract_sha256", timing_hash),
        ("axi_interfaces_sha256", axi_hash),
    ):
        if not actual or str(identity.get(field) or "") != actual:
            blockers.append(f"recomputed {field} does not match board identity")

    task_card = read_json_if_exists(run_dir / "input" / "task_card.json")
    try:
        board_scope = resolve_board_validation_scope(task_card, model)
    except BoardValidationScopeError as exc:
        blockers.append(f"board validation scope is invalid: {exc}")
        board_scope = None
    model_layers = int(model.get("num_layers") or model.get("num_hidden_layers") or 0)
    catalog_layers = int(catalog.get("target_layer_count") or 0)
    if model_layers <= 0 or catalog_layers != model_layers:
        blockers.append("target model and Transformer-block catalog layer counts are missing or inconsistent")
    target_layers = (
        board_scope.validation_layer_count if board_scope is not None else 0
    )
    validation_layer_indices = (
        list(board_scope.layer_indices) if board_scope is not None else []
    )
    covers_full_model = (
        board_scope.covers_full_model if board_scope is not None else False
    )
    requires_next_layer_prefetch = (
        board_scope.requires_next_layer_prefetch if board_scope is not None else False
    )
    tensor_rows = [row for row in catalog.get("tensors", []) if isinstance(row, dict)]
    complete_catalog_tensor_hashes = sorted(
        {
            str(row.get("source_slice_sha256") or "").lower()
            for row in tensor_rows
            if re.fullmatch(r"[0-9a-fA-F]{64}", str(row.get("source_slice_sha256") or ""))
        }
    )
    if (
        catalog.get("status") != "pass"
        or catalog.get("scope_coverage_complete") is not True
        or catalog.get("accelerator_scope") != "transformer_blocks_only"
        or int(catalog.get("tensor_count") or 0) != len(tensor_rows)
        or len(complete_catalog_tensor_hashes) != len(tensor_rows)
    ):
        blockers.append("complete unique Transformer-block tensor catalog is not hash-valid")
    required_tensor_hashes = sorted(
        {
            str(row.get("source_slice_sha256") or "").lower()
            for row in tensor_rows
            if (
                row.get("layer_index") in validation_layer_indices
                and re.fullmatch(
                    r"[0-9a-fA-F]{64}",
                    str(row.get("source_slice_sha256") or ""),
                )
            )
        }
    )
    catalog_has_explicit_layer_indices = any(
        "layer_index" in row for row in tensor_rows
    )
    if (
        not required_tensor_hashes
        and covers_full_model
        and not catalog_has_explicit_layer_indices
    ):
        # Historical full-model catalogs had no per-tensor layer field. Do not
        # apply this compatibility path to a scoped board workload.
        required_tensor_hashes = complete_catalog_tensor_hashes
    if not required_tensor_hashes:
        blockers.append("board validation scope has no real Transformer-block tensor hashes")
    declared_tensor_hashes = {
        str(value).lower()
        for value in manifest.get("board_consumed_tensor_hashes", [])
        if re.fullmatch(r"[0-9a-fA-F]{64}", str(value))
    }
    if declared_tensor_hashes != set(required_tensor_hashes):
        blockers.append("board binding tensor hashes do not exactly cover the current Transformer-block catalog")

    harness_rows: list[dict[str, Any]] = []
    for index, row in enumerate(normalized_multilayer.get("source_files", [])):
        role = str(row.get("role") or "").lower() if isinstance(row, dict) else ""
        normalized = _normalize_exact_board_source(
            row,
            label=f"multilayer harness source[{index}]",
            base_dir=Path.cwd(),
            blockers=blockers,
            generated_role=role or None,
            allowed_root=None if role == "generated_kernel" else board_root,
        )
        if normalized is not None:
            harness_rows.append(normalized)
    harness = copy.deepcopy(normalized_multilayer)
    harness["source_files"] = harness_rows
    harness["source_set_sha256"] = compile_source_set_fingerprint(harness_rows)
    harness["target_layer_count"] = target_layers

    testbench_plan = plan.get("testbench")
    testbench_source_plan = (
        testbench_plan.get("source")
        if isinstance(testbench_plan, dict)
        and isinstance(testbench_plan.get("source"), dict)
        else testbench_plan
    )
    testbench = _normalize_exact_board_source(
        testbench_source_plan,
        label="board testbench source",
        base_dir=Path.cwd(),
        blockers=blockers,
        generated_role="testbench",
        allowed_root=board_root,
    )
    if testbench is None:
        testbench = (
            copy.deepcopy(testbench_source_plan)
            if isinstance(testbench_source_plan, dict)
            else {}
        )
    if (
        isinstance(testbench_plan, dict)
        and isinstance(testbench_plan.get("source"), dict)
    ):
        testbench.update(
            {
                key: copy.deepcopy(value)
                for key, value in testbench_plan.items()
                if key != "source"
            }
        )
    control = abi.get("control_abi") if isinstance(abi.get("control_abi"), dict) else {}
    testbench.update(
        {
            "timing_contract_sha256": timing_hash,
            "compute_slot_abi_sha256": abi_hash,
            "control_abi_sha256": canonical_contract_sha256(control),
        }
    )
    declared_checkpoint_contract = testbench.get("simulation_checkpoint_contract")
    if isinstance(declared_checkpoint_contract, dict):
        rebound_checkpoint_contract, checkpoint_framework_binding = (
            rebind_checkpoint_framework_adapter_artifacts(
                declared_checkpoint_contract
            )
        )
        testbench["simulation_checkpoint_contract"] = rebound_checkpoint_contract
        blockers.extend(
            "checkpoint framework authority: " + str(error)
            for error in checkpoint_framework_binding.get("errors", [])
            if str(error)
        )
    else:
        checkpoint_framework_binding = {
            "schema_version": (
                "spatialaccagent.checkpoint_framework_adapter_binding.v1"
            ),
            "status": "not_present",
            "changed": False,
            "errors": [],
        }
    if compute_slot_axi_mode:
        testbench.pop("external_simulation_fixture_contract_sha256", None)
        testbench.pop("external_memory_component", None)
        testbench["uses_memory_model_source_ids"] = []
        plan_memory_model = plan.get("compute_slot_axi_transaction_memory_model")
        testbench_memory_model = testbench.get("axi_transaction_memory_model")
        memory_model = (
            copy.deepcopy(plan_memory_model)
            if isinstance(plan_memory_model, dict)
            else {}
        )
        if isinstance(testbench_memory_model, dict):
            for field, value in testbench_memory_model.items():
                if field in memory_model and memory_model[field] != value:
                    blockers.append(
                        "compute-slot AXI transaction-memory declarations conflict "
                        f"for field: {field}"
                    )
                memory_model[field] = copy.deepcopy(value)
        memory_model.update(
            {
                "boundary": "compute_slot_axi",
                "axi_interfaces_sha256": axi_hash,
                "timing_contract_sha256": timing_hash,
            }
        )
        testbench["axi_transaction_memory_model"] = memory_model
    else:
        testbench.update(
            {
                "external_simulation_fixture_contract_sha256": external_fixture.get(
                    "contract_sha256"
                ),
                "external_memory_component": copy.deepcopy(
                    external_fixture.get("model_instance", {})
                ),
            }
        )
    scan = testbench.get("forbidden_construct_scan")
    if isinstance(scan, dict):
        scan = copy.deepcopy(scan)
        scan["source_sha256"] = testbench.get("sha256")
        if compute_slot_axi_mode:
            scan.update(
                {
                    "required": False,
                    "status": "planned",
                    "producer": "existing_simulator_compile",
                }
            )
        if scan.get("required") is True and str(scan.get("method") or "").lower() == "hdl_ast":
            report = scan.get("report_output") if isinstance(scan.get("report_output"), dict) else {}
            report_path = str(report.get("path") or "")
            tool = scan.get("tool") if isinstance(scan.get("tool"), dict) else {}
            invocation = (
                copy.deepcopy(scan.get("invocation"))
                if isinstance(scan.get("invocation"), dict)
                else {}
            )
            argv = [str(value) for value in invocation.get("argv", []) if str(value)]
            argv = [value for value in argv if value not in {"{source}", "{report}"}]
            if argv and argv[0].startswith("-") and str(tool.get("name") or ""):
                argv.insert(0, str(tool["name"]))
            replaced_report = False
            if report_path:
                for index, value in enumerate(argv):
                    if value == report_path:
                        argv[index] = "{report}"
                        replaced_report = True
                        break
            if not replaced_report:
                argv.extend(["--report", "{report}"])
            argv.extend(["--source", "{source}"])
            invocation.update(
                {
                    "argv": argv,
                    "cwd": (
                        invocation.get("cwd")
                        if _safe_board_relative_path(invocation.get("cwd"))
                        else FRAMEWORK_VCS_COMMAND_CWD
                    ),
                    "shell": False,
                }
            )
            scan["invocation"] = invocation
            scan["required_checks"] = sorted(REQUIRED_TESTBENCH_AST_CHECKS)
        testbench["forbidden_construct_scan"] = scan

    monitor_contract = copy.deepcopy(
        plan.get("protocol_monitor_contract")
        if isinstance(plan.get("protocol_monitor_contract"), dict)
        else {}
    )
    monitors = monitor_contract.get("monitors")
    if not isinstance(monitors, list):
        monitors = []
        blockers.append("board protocol_monitor_contract.monitors is missing")
    normalized_monitors: list[dict[str, Any]] = []
    for monitor_index, monitor in enumerate(monitors):
        if not isinstance(monitor, dict):
            blockers.append(f"board protocol monitor[{monitor_index}] is not an object")
            continue
        normalized_monitor = copy.deepcopy(monitor)
        if not str(normalized_monitor.get("interface") or ""):
            normalized_monitor["interface"] = str(
                normalized_monitor.get("interface_name") or ""
            )
        declared_fatal_checks = {
            str(value)
            for value in normalized_monitor.get("fatal_checks", [])
            if str(value)
        }
        nested_contract = (
            normalized_monitor.get("contract")
            if isinstance(normalized_monitor.get("contract"), dict)
            else {}
        )
        declared_fatal_checks.update(
            str(value) for value in nested_contract.get("fatal_checks", []) if str(value)
        )
        structured_checks = [
            copy.deepcopy(value)
            for value in normalized_monitor.get("checks", [])
            if isinstance(value, dict)
        ]
        checks_by_kind = {
            str(value.get("kind") or ""): value
            for value in structured_checks
            if str(value.get("kind") or "")
        }
        for kind in sorted(declared_fatal_checks):
            checks_by_kind[kind] = {
                **copy.deepcopy(checks_by_kind.get(kind, {})),
                "kind": kind,
                "enabled": True,
                "severity": "fatal",
            }
        normalized_monitor["checks"] = [
            checks_by_kind[kind] for kind in sorted(checks_by_kind)
        ]
        structured_report = (
            copy.deepcopy(normalized_monitor.get("structured_report"))
            if isinstance(normalized_monitor.get("structured_report"), dict)
            else copy.deepcopy(nested_contract.get("structured_report", {}))
        )
        if structured_report:
            structured_report["required_fields"] = sorted(
                {
                    str(value)
                    for value in structured_report.get("required_fields", [])
                    if str(value)
                }
                | REQUIRED_PROTOCOL_REPORT_FIELDS
            )
            normalized_monitor["structured_report"] = structured_report
        source_rows = monitor.get("source_files")
        if not isinstance(source_rows, list):
            source_rows = []
            blockers.append(f"board protocol monitor[{monitor_index}].source_files is missing")
        normalized_sources: list[dict[str, Any]] = []
        for source_index, row in enumerate(source_rows):
            normalized = _normalize_exact_board_source(
                row,
                label=f"board protocol monitor[{monitor_index}] source[{source_index}]",
                base_dir=Path.cwd(),
                blockers=blockers,
                generated_role="protocol_monitor",
                allowed_root=board_root,
            )
            if normalized is not None:
                normalized_sources.append(normalized)
        normalized_monitor["source_files"] = normalized_sources
        normalized_monitors.append(normalized_monitor)
    monitor_contract["monitors"] = normalized_monitors
    monitor_contract["axi_interfaces_sha256"] = axi_hash
    expected_axi_names = {
        str(value.get("name") or "") for value in axi_interfaces if str(value.get("name") or "")
    }
    monitor_axi_names = [
        str(value.get("interface") or "")
        for value in normalized_monitors
        if str(value.get("interface") or "")
    ]
    monitor_contract["all_axi_interfaces_covered"] = (
        set(monitor_axi_names) == expected_axi_names
        and len(monitor_axi_names) == len(set(monitor_axi_names))
    )

    generated_rows = [*harness_rows, testbench]
    generated_rows.extend(
        row
        for monitor in normalized_monitors
        for row in monitor.get("source_files", [])
        if isinstance(row, dict)
    )
    generated_rows = [row for row in generated_rows if isinstance(row, dict) and row.get("source_id")]
    generated_by_id = {str(row.get("source_id")): row for row in generated_rows}
    generated_ids = [str(row.get("source_id")) for row in generated_rows]
    if len(generated_ids) != len(set(generated_ids)):
        blockers.append("generated harness/kernel/testbench/monitor source IDs are not unique")
    generated_paths = [str(row.get("path") or "") for row in generated_rows]
    if len(generated_paths) != len(set(generated_paths)):
        blockers.append("generated harness/kernel/testbench/monitor source paths are not unique")
    closure_ids = {
        str(row.get("source_id") or "") for row in normalized_closure if row.get("source_id")
    }
    fixture_ids = [
        str(row.get("source_id") or "")
        for row in external_fixture_rows
        if row.get("source_id")
    ]
    if len(fixture_ids) != len(set(fixture_ids)):
        blockers.append("selected external fixture compiler input IDs are not unique")
    fixture_collisions = set(fixture_ids).intersection(closure_ids | set(generated_ids))
    if fixture_collisions:
        blockers.append(
            f"external fixture source IDs collide with sample/generated sources: {sorted(fixture_collisions)}"
        )

    replaced_ids = [str(value) for value in abi.get("replaced_source_ids", []) if str(value)]
    replacement_plan = plan.get("source_replacements")
    if not isinstance(replacement_plan, list):
        replacement_plan = []
        blockers.append("board_simulation_preflight_plan.source_replacements is missing")
    source_replacements: list[dict[str, Any]] = []
    for index, row in enumerate(replacement_plan):
        if not isinstance(row, dict):
            blockers.append(f"board source replacement[{index}] is not an object")
            continue
        normalized = copy.deepcopy(row)
        normalized["compute_slot_abi_sha256"] = abi_hash
        source_replacements.append(normalized)
    replacement_by_source = {
        str(row.get("replaced_source_id") or ""): row
        for row in source_replacements
        if str(row.get("replaced_source_id") or "")
    }
    if set(replacement_by_source) != set(replaced_ids):
        blockers.append("source replacement plan does not cover exactly compute_slot_abi.replaced_source_ids")

    preserved_rows = [
        row for row in compile_closure_rows if str(row.get("source_id") or "") not in set(replaced_ids)
    ]
    if compute_slot_axi_mode:
        preserved_rows = []
    compile_rows: list[dict[str, Any]] = []
    emitted_generated: set[str] = set()
    if not compute_slot_axi_mode:
        for row in compile_closure_rows:
            source_id = str(row.get("source_id") or "")
            if source_id not in set(replaced_ids):
                compile_rows.append(row)
                continue
            replacement = replacement_by_source.get(source_id, {})
            generated_id = str(replacement.get("generated_source_id") or "")
            generated = generated_by_id.get(generated_id)
            if generated is not None and generated_id not in emitted_generated:
                compile_rows.append(generated)
                emitted_generated.add(generated_id)
        compile_rows.extend(external_fixture_rows)
    for row in generated_rows:
        source_id = str(row.get("source_id") or "")
        if source_id not in emitted_generated:
            compile_rows.append(row)
            emitted_generated.add(source_id)

    compile_plan = copy.deepcopy(
        plan.get("vcs_compile_plan")
        if isinstance(plan.get("vcs_compile_plan"), dict)
        else {}
    )
    facts_path_text = str(identity.get("vivado_facts_path") or "")
    facts_path = Path(facts_path_text).expanduser() if facts_path_text else Path()
    if facts_path_text and not facts_path.is_absolute():
        facts_path = identity_path.parent / facts_path
    facts = read_json_if_exists(facts_path) if facts_path.is_file() else {}
    actual_facts_hash = sha256_file(facts_path) if facts_path.is_file() else ""
    identity_facts_hash = str(identity.get("vivado_facts_sha256") or "")
    frozen_identity_attestation: dict[str, Any] = {}
    if compute_slot_axi_mode:
        frozen_identity_attestation, frozen_compile_plan = (
            materialize_frozen_compute_slot_identity_attestation(
                run_dir=run_dir,
                identity=identity,
                identity_path=identity_path,
                current_facts_sha256=actual_facts_hash,
            )
        )
        if frozen_identity_attestation:
            compile_plan = frozen_compile_plan
    if compile_plan.get("schema_version") != "spatialaccagent.vcs_compile_plan.v1":
        blockers.append("board_simulation_preflight_plan.vcs_compile_plan schema_version is missing or unsupported")
    if compile_plan.get("status") != "ready":
        blockers.append("board_simulation_preflight_plan.vcs_compile_plan.status is not ready")
    tool_profile_path = run_dir / "input" / "tool_profile.json"
    tool_profile = read_json_if_exists(tool_profile_path)
    configured_tools = [
        row
        for row in tool_profile.get("tools", [])
        if isinstance(row, dict) and row.get("role") == "functional_verification"
    ]
    configured_tool = configured_tools[0] if len(configured_tools) == 1 else {}
    if len(configured_tools) != 1:
        blockers.append("tool_profile must contain exactly one configured functional_verification tool")
    planned_tool = (
        compile_plan.get("tool_binding")
        if isinstance(compile_plan.get("tool_binding"), dict)
        else {}
    )
    for field in ("role", "name", "host", "port", "executable"):
        if not configured_tool or planned_tool.get(field) != configured_tool.get(field):
            blockers.append(f"vcs_compile_plan.tool_binding.{field} does not match current tool_profile")
    compile_top = str(compile_plan.get("top_module") or "")
    planned_top = str(plan.get("top_module") or "")
    if not compile_top or compile_top != planned_top:
        blockers.append("vcs_compile_plan.top_module does not match the generated board testbench top")
    expected_compile_by_id = {
        str(row.get("source_id") or ""): row
        for row in [*preserved_rows, *external_fixture_rows, *generated_rows]
        if str(row.get("source_id") or "")
    }
    export_contexts = (
        facts.get("simulation", {}).get("simulator_export_contexts", [])
        if isinstance(facts.get("simulation"), dict)
        else []
    )
    context_by_hash: dict[str, str] = {}
    for index, row in enumerate(export_contexts):
        if not isinstance(row, dict):
            blockers.append(f"Vivado simulator export context[{index}] is not an object")
            continue
        context_hash = str(row.get("sha256") or "").lower()
        context_text = str(row.get("text") or "")
        actual_context_hash = hashlib.sha256(context_text.encode("utf-8")).hexdigest()
        if not context_text or context_hash != actual_context_hash:
            blockers.append(f"Vivado simulator export context[{index}] text/hash binding is invalid")
            continue
        context_by_hash[context_hash] = context_text
    if not context_by_hash and not frozen_identity_attestation:
        blockers.append("Vivado fact bundle has no hash-bound VCS export command context")
    if (
        not facts
        or not actual_facts_hash
        or (
            actual_facts_hash != identity_facts_hash
            and not frozen_identity_attestation
        )
    ):
        blockers.append("board identity Vivado fact bundle is missing or hash-invalid")
    authority = (
        compile_plan.get("compile_authority")
        if isinstance(compile_plan.get("compile_authority"), dict)
        else {}
    )
    declared_context_hashes = authority.get("simulator_export_context_sha256s")
    expected_context_hashes = (
        set(
            map(
                str,
                frozen_identity_attestation.get(
                    "attested_simulator_export_context_sha256s", []
                ),
            )
        )
        if frozen_identity_attestation
        else set(context_by_hash)
    )
    if (
        authority.get("vivado_facts_path") != facts_path_text
        or authority.get("vivado_facts_sha256") != identity_facts_hash
        or not isinstance(declared_context_hashes, list)
        or set(map(str, declared_context_hashes)) != expected_context_hashes
    ):
        blockers.append("vcs_compile_plan.compile_authority does not bind the exact Vivado export facts")
    declared_fixture_context_hashes = authority.get(
        "external_fixture_export_context_sha256s"
    )
    if compute_slot_axi_mode:
        if authority.get("external_fixture_contract_sha256") not in (None, "") or (
            declared_fixture_context_hashes not in (None, [])
        ):
            blockers.append(
                "compute_slot_axi compile authority must not bind external fixture sources"
            )
    elif (
        authority.get("external_fixture_contract_sha256")
        != external_fixture.get("contract_sha256")
        or not isinstance(declared_fixture_context_hashes, list)
        or set(map(str, declared_fixture_context_hashes))
        != set(fixture_context_by_hash)
    ):
        blockers.append(
            "vcs_compile_plan.compile_authority does not bind the exact external fixture export"
        )
    combined_context_by_hash = {**context_by_hash, **fixture_context_by_hash}

    ordered_commands = compile_plan.get("ordered_commands")
    if not isinstance(ordered_commands, list) or not ordered_commands:
        ordered_commands = []
        blockers.append("vcs_compile_plan.ordered_commands is missing or empty")
    ordered_source_ids: list[str] = []
    compile_commands: list[dict[str, Any]] = []
    elaboration_commands: list[dict[str, Any]] = []
    fixture_include_ids = {
        str(row.get("include_dir_id") or "")
        for row in external_fixture.get("include_directories", [])
        if isinstance(row, dict) and str(row.get("include_dir_id") or "")
    }
    shell_tokens = {"|", "||", "&&", ";", ">", ">>", "<", "<<"}
    for index, command in enumerate(ordered_commands):
        label = f"vcs_compile_plan.ordered_commands[{index}]"
        if not isinstance(command, dict):
            blockers.append(f"{label} is not an object")
            continue
        if command.get("order") != index:
            blockers.append(f"{label}.order is not contiguous")
        phase = str(command.get("phase") or "")
        if phase not in {"compile", "elaborate"}:
            blockers.append(f"{label}.phase is neither compile nor elaborate")
        elif phase == "compile":
            compile_commands.append(command)
        else:
            elaboration_commands.append(command)
        if command.get("tool_role") != "functional_verification":
            blockers.append(f"{label}.tool_role does not bind the configured simulator")
        executable = str(command.get("executable") or "")
        if (
            not executable
            or any(value in executable for value in ("\x00", "\n", "\r"))
            or any(char.isspace() for char in executable)
        ):
            blockers.append(f"{label}.executable is missing or unsafe")
        refs = command.get("authority_refs")
        ref_set = {str(value) for value in refs} if isinstance(refs, list) else set()
        authorized_context_hashes = (
            expected_context_hashes | set(fixture_context_by_hash)
            if frozen_identity_attestation
            else set(combined_context_by_hash)
        )
        if not ref_set or not ref_set.issubset(authorized_context_hashes):
            blockers.append(f"{label}.authority_refs do not bind Vivado-exported VCS commands")
        elif (
            not frozen_identity_attestation
            and executable != str(configured_tool.get("executable") or "")
            and not any(
                re.search(
                    rf"(?:^|[\s'\"=]){re.escape(executable)}(?:$|[\s'\"\\])",
                    combined_context_by_hash[ref],
                    flags=re.MULTILINE,
                )
                for ref in ref_set
            )
        ):
            blockers.append(f"{label}.executable is not authorized by tool_profile or referenced Vivado export")
        if command.get("shell") is not False:
            blockers.append(f"{label}.shell must be false")
        if not _safe_board_relative_path(command.get("cwd")):
            blockers.append(f"{label}.cwd is not a safe relative staging path")
        env = command.get("env")
        if not isinstance(env, dict) or not all(
            isinstance(key, str)
            and key
            and "=" not in key
            and isinstance(value, str)
            and "\x00" not in value
            for key, value in env.items()
        ):
            blockers.append(f"{label}.env is not a safe string mapping")
        argv = command.get("argv")
        if not isinstance(argv, list) or not argv:
            blockers.append(f"{label}.argv is missing or empty")
            argv = []
        token_source_ids: list[str] = []
        token_include_ids: list[str] = []
        literal_argv: list[str] = []
        for token_index, token in enumerate(argv):
            if isinstance(token, str):
                literal_argv.append(token)
                if (
                    not token
                    or any(value in token for value in ("\x00", "\n", "\r"))
                    or token in shell_tokens
                ):
                    blockers.append(f"{label}.argv[{token_index}] is an unsafe shell/redirection token")
            elif isinstance(token, dict) and set(token) == {"source_id"}:
                source_id = str(token.get("source_id") or "")
                token_source_ids.append(source_id)
                if not source_id:
                    blockers.append(f"{label}.argv[{token_index}].source_id is missing")
            elif isinstance(token, dict) and set(token) == {"include_dir_id"}:
                include_dir_id = str(token.get("include_dir_id") or "")
                token_include_ids.append(include_dir_id)
                if not include_dir_id or include_dir_id not in fixture_include_ids:
                    blockers.append(
                        f"{label}.argv[{token_index}].include_dir_id is not fixture-authorized"
                    )
            else:
                blockers.append(
                    f"{label}.argv[{token_index}] is not a literal, source_id, or include_dir_id token"
                )
        source_ids = command.get("source_ids")
        if not isinstance(source_ids, list) or list(map(str, source_ids)) != token_source_ids:
            blockers.append(f"{label}.source_ids do not exactly match argv source tokens")
        if phase == "compile":
            if not token_source_ids:
                blockers.append(f"{label} compile command has no source token")
            if set(token_source_ids).intersection(fixture_ids) and not ref_set.intersection(
                fixture_context_by_hash
            ):
                blockers.append(
                    f"{label} external fixture compiler inputs are not bound to their export context"
                )
            ordered_source_ids.extend(token_source_ids)
        elif token_source_ids:
            blockers.append(f"{label} elaboration command must not compile source tokens")
        if phase != "compile" and token_include_ids:
            blockers.append(f"{label} include-directory tokens are valid only for compile commands")
        command["_validated_literal_argv"] = literal_argv

    if (
        len(ordered_source_ids) != len(set(ordered_source_ids))
        or set(ordered_source_ids) != set(expected_compile_by_id)
    ):
        blockers.append(
            "vcs_compile_plan ordered compile commands must cover every transformed source ID exactly once"
        )
    if set(ordered_source_ids).intersection(replaced_ids):
        blockers.append("vcs_compile_plan ordered commands reference a replaced sample-project source")
    if (
        ordered_source_ids
        and set(ordered_source_ids) == set(expected_compile_by_id)
        and len(ordered_source_ids) == len(set(ordered_source_ids))
    ):
        compile_rows = [expected_compile_by_id[source_id] for source_id in ordered_source_ids]
    output_name = str(compile_plan.get("output") or "")
    if output_name != "simv":
        blockers.append("vcs_compile_plan.output must be the safe simulator artifact simv")
    if len(elaboration_commands) != 1 or not ordered_commands or ordered_commands[-1] not in elaboration_commands:
        blockers.append("vcs_compile_plan must end with exactly one elaboration command")
    elif (
        planned_top not in elaboration_commands[0].get("_validated_literal_argv", [])
        or output_name not in elaboration_commands[0].get("_validated_literal_argv", [])
    ):
        blockers.append("vcs_compile_plan elaboration argv does not bind top_module and simv output")
    if (
        not compute_slot_axi_mode
        and len(compile_commands) == 1
        and len(expected_compile_by_id) > 1
    ):
        fallback_literals = compile_commands[0].get("_validated_literal_argv", [])
        if (
            compile_commands[0].get("executable") == configured_tool.get("executable")
            and "-sverilog" in fallback_literals
        ):
            blockers.append("vcs_compile_plan cannot collapse the Vivado export into a single -sverilog fallback")
    for command in ordered_commands:
        if isinstance(command, dict):
            command.pop("_validated_literal_argv", None)
    compile_plan["tool_profile_sha256"] = (
        sha256_file(tool_profile_path) if tool_profile_path.is_file() else None
    )

    evidence_records = copy.deepcopy(
        plan.get("generated_evidence_records")
        if isinstance(plan.get("generated_evidence_records"), list)
        else []
    )
    if not evidence_records:
        blockers.append("board_simulation_preflight_plan.generated_evidence_records is empty")
    for index, row in enumerate(evidence_records):
        if not isinstance(row, dict):
            blockers.append(f"generated evidence record[{index}] is not an object")
            continue
        source_id = str(row.get("source_id") or "")
        source = generated_by_id.get(source_id, {})
        if not source or str(row.get("source_sha256") or "").lower() != str(source.get("sha256") or "").lower():
            blockers.append(f"generated evidence record[{index}] does not hash-bind its generated source")

    integration = copy.deepcopy(
        manifest.get("board_integration_contract")
        if isinstance(manifest.get("board_integration_contract"), dict)
        else {}
    )
    runtime_contract = read_json_if_exists(runtime_paths["contract"])
    runtime_image_manifest = read_json_if_exists(
        runtime_paths["runtime_image_manifest"]
    )
    memory_hash = sha256_file(memory_path) if memory_path.is_file() else ""
    for field, expected in (
        ("source_closure_sha256", closure_hash),
        ("compute_slot_abi_sha256", abi_hash),
        ("timing_contract_sha256", timing_hash),
        ("axi_interfaces_sha256", axi_hash),
        ("memory_layout_sha256", memory_hash),
    ):
        if not expected or str(integration.get(field) or "") != expected:
            blockers.append(f"board integration contract does not bind recomputed {field}")
        integration[field] = expected

    for field, path in (
        ("board_memory_runtime_contract_sha256", runtime_paths["contract"]),
        ("full_weight_image_manifest_sha256", runtime_paths["image_manifest"]),
        ("full_weight_image_sha256", runtime_paths["image"]),
    ):
        expected = sha256_file(path) if path.is_file() else ""
        if not expected:
            blockers.append(f"framework-owned board artifact is unavailable for {field}")
        integration[field] = expected
    if runtime_paths["runtime_capture"].is_file():
        integration["full_layer_runtime_capture_contract_sha256"] = sha256_file(
            runtime_paths["runtime_capture"]
        )

    runtime_constants = (
        runtime_contract.get("runtime_constants", {})
        if isinstance(runtime_contract.get("runtime_constants"), dict)
        else {}
    )
    runtime_enabled = runtime_constants.get("enabled") is True
    runtime_plan_artifact = {
        "path": str(runtime_paths["contract"]),
        "sha256": (
            sha256_file(runtime_paths["contract"])
            if runtime_paths["contract"].is_file()
            else ""
        ),
    }
    runtime_constant_binding: dict[str, Any] = {
        "enabled": runtime_enabled,
        "board_memory_runtime_contract": runtime_plan_artifact,
    }
    runtime_implementation = copy.deepcopy(
        integration.get("runtime_constants")
        if isinstance(integration.get("runtime_constants"), dict)
        else {}
    )
    runtime_implementation["enabled"] = runtime_enabled
    runtime_image_artifact: dict[str, Any] = {}
    if runtime_enabled:
        runtime_manifest_artifact = {
            "path": str(runtime_paths["runtime_image_manifest"]),
            "sha256": (
                sha256_file(runtime_paths["runtime_image_manifest"])
                if runtime_paths["runtime_image_manifest"].is_file()
                else ""
            ),
        }
        runtime_image_artifact = {
            "path": str(runtime_paths["runtime_image"]),
            "sha256": (
                sha256_file(runtime_paths["runtime_image"])
                if runtime_paths["runtime_image"].is_file()
                else ""
            ),
            "byte_count": (
                runtime_paths["runtime_image"].stat().st_size
                if runtime_paths["runtime_image"].is_file()
                else 0
            ),
        }
        runtime_constant_binding.update(
            {
                "runtime_image_manifest": runtime_manifest_artifact,
                "runtime_image": runtime_image_artifact,
            }
        )
        integration.update(
            {
                "full_runtime_image_manifest_sha256": runtime_manifest_artifact[
                    "sha256"
                ],
                "full_runtime_image_sha256": runtime_image_artifact["sha256"],
            }
        )
        runtime_implementation.update(
            {
                "runtime_plan_contract_sha256": runtime_contract.get(
                    "contract_sha256"
                ),
                "runtime_image_manifest_sha256": runtime_manifest_artifact[
                    "sha256"
                ],
                "runtime_image_manifest_contract_sha256": runtime_image_manifest.get(
                    "manifest_contract_sha256"
                ),
                "runtime_image_sha256": runtime_image_artifact["sha256"],
                "connected_runtime_stream_contract_sha256": runtime_constants.get(
                    "connected_runtime_stream_contract_sha256"
                ),
                "loader_abi_sha256": canonical_contract_sha256(
                    runtime_constants.get("loader_abi", {})
                ),
                "load_schedule_sha256": canonical_contract_sha256(
                    runtime_constants.get("load_schedule", [])
                ),
            }
        )
    integration["runtime_constants"] = runtime_implementation

    if semantic.get("status") != "ready":
        blockers.append("semantic testbench manifest is not ready")
    board_semantic = semantic.get("board") if isinstance(semantic.get("board"), dict) else {}
    semantic_reference_captured = (
        board_semantic.get("all_target_layer_reference_captured") is True
        if covers_full_model
        else board_semantic.get("scoped_layer_reference_captured") is True
    )
    if (
        not semantic_reference_captured
        or int(board_semantic.get("expected_target_layers") or 0) != target_layers
    ):
        blockers.append("semantic board artifacts do not cover the current validation scope")
    input_artifact = _normalize_exact_board_artifact(
        board_semantic.get("input_vector"),
        label="semantic board input vector",
        base_dir=semantic_path.parent,
        blockers=blockers,
    )
    expected_artifact = _normalize_exact_board_artifact(
        board_semantic.get("expected_output"),
        label="semantic board expected output",
        base_dir=semantic_path.parent,
        blockers=blockers,
    )
    plan_artifacts = plan.get("artifacts") if isinstance(plan.get("artifacts"), dict) else {}
    authoritative_weight_manifest = read_json_if_exists(runtime_paths["image_manifest"])
    if authoritative_weight_manifest.get("status") != "pass":
        blockers.append("framework full-weight image manifest is missing or is not pass")
    weight_artifact = _normalize_exact_board_artifact(
        authoritative_board_weight_artifact(authoritative_weight_manifest),
        label="framework-materialized complete board weight image",
        base_dir=run_dir,
        blockers=blockers,
    )
    for name, semantic_artifact in (
        ("input", input_artifact),
        ("expected_output", expected_artifact),
    ):
        planned = plan_artifacts.get(name)
        if isinstance(planned, dict) and semantic_artifact is not None:
            if (
                str(planned.get("sha256") or "") != semantic_artifact.get("sha256")
                or Path(str(planned.get("path") or "")).resolve()
                != Path(str(semantic_artifact.get("path") or "")).resolve()
            ):
                blockers.append(f"board preflight planned {name} differs from immutable semantic artifact")
    planned_weight_artifact = plan_artifacts.get("weight_image")
    if isinstance(planned_weight_artifact, dict) and weight_artifact is not None:
        planned_path = str(planned_weight_artifact.get("path") or "")
        if planned_path:
            candidate = Path(planned_path)
            candidate = candidate if candidate.is_absolute() else run_dir / candidate
            if candidate.resolve() != Path(str(weight_artifact.get("path") or "")).resolve():
                blockers.append(
                    "board preflight planned weight_image.path differs from immutable framework authority"
                )
        planned_sha = str(planned_weight_artifact.get("sha256") or "")
        if planned_sha and planned_sha != str(weight_artifact.get("sha256") or ""):
            blockers.append(
                "board preflight planned weight_image.sha256 differs from immutable framework authority"
            )
    if weight_artifact is not None:
        packed_hashes = {
            str(value).lower()
            for value in weight_artifact.get(
                "packed_tensor_hashes", weight_artifact.get("tensor_hashes", [])
            )
            if re.fullmatch(r"[0-9a-fA-F]{64}", str(value))
        }
        if (
            weight_artifact.get("scope_coverage_complete") is not True
            or weight_artifact.get("accelerator_scope") != "transformer_blocks_only"
            or weight_artifact.get("accelerator_weight_catalog_sha256")
            != (sha256_file(catalog_path) if catalog_path.is_file() else None)
            or weight_artifact.get("source_checkpoint_sha256")
            != catalog.get("source_checkpoint_sha256")
            or packed_hashes != set(required_tensor_hashes)
        ):
            blockers.append("complete board weight image is not bound to every current Transformer-block tensor")
        authoritative_image_path = Path(
            str(authoritative_weight_manifest.get("path") or "")
        )
        if (
            authoritative_weight_manifest.get("status") != "pass"
            or not authoritative_image_path.is_absolute()
            or authoritative_image_path.resolve()
            != Path(str(weight_artifact.get("path") or "")).resolve()
            or authoritative_weight_manifest.get("image_sha256")
            != weight_artifact.get("sha256")
            or authoritative_weight_manifest.get("manifest_contract_sha256")
            != weight_artifact.get("manifest_contract_sha256")
            or authoritative_weight_manifest.get("total_bytes")
            != weight_artifact.get("total_bytes")
            or authoritative_weight_manifest.get("layer_segments")
            != weight_artifact.get("layer_segments")
        ):
            blockers.append(
                "board preflight weight image differs from the framework-materialized current authority"
            )

    execution_outputs = copy.deepcopy(
        plan.get("execution_outputs")
        if isinstance(plan.get("execution_outputs"), dict)
        else {}
    )
    protocol_reports = execution_outputs.get(PROTOCOL_MONITOR_REPORT_OUTPUT_KEY)
    if not isinstance(protocol_reports, list):
        alias_reports = execution_outputs.pop("protocol_reports", None)
        protocol_reports = alias_reports if isinstance(alias_reports, list) else []
    reports_by_interface = {
        str(value.get("interface") or value.get("interface_name") or ""): copy.deepcopy(value)
        for value in protocol_reports
        if isinstance(value, dict)
        and str(value.get("interface") or value.get("interface_name") or "")
    }
    for monitor in normalized_monitors:
        interface_name = str(monitor.get("interface") or "")
        report = monitor.get("structured_report")
        if not interface_name or not isinstance(report, dict):
            continue
        reports_by_interface[interface_name] = {
            **reports_by_interface.get(interface_name, {}),
            "interface": interface_name,
            "path": report.get("path"),
            "schema_version": report.get("schema_version"),
        }
    execution_outputs[PROTOCOL_MONITOR_REPORT_OUTPUT_KEY] = [
        reports_by_interface[name] for name in sorted(reports_by_interface)
    ]
    if not execution_outputs:
        blockers.append("board_simulation_preflight_plan.execution_outputs is missing")
    output_paths: list[str] = []
    protocol_report_aliases = {
        (
            str(row.get("path") or ""),
            str(row.get("schema_version") or ""),
        )
        for row in execution_outputs[PROTOCOL_MONITOR_REPORT_OUTPUT_KEY]
        if isinstance(row, dict)
    }

    def validate_output_paths(value: Any, label: str) -> None:
        if isinstance(value, dict):
            for key, item in value.items():
                if key == "path":
                    if not _safe_board_relative_path(item):
                        blockers.append(f"{label}.path is not a safe relative output path")
                    elif (
                        label == "execution_outputs.axi_protocol_report"
                        and (
                            str(item),
                            str(value.get("schema_version") or ""),
                        )
                        in protocol_report_aliases
                    ):
                        continue
                    else:
                        output_paths.append(str(Path(str(item))))
                else:
                    validate_output_paths(item, f"{label}.{key}")
        elif isinstance(value, list):
            for index, item in enumerate(value):
                validate_output_paths(item, f"{label}[{index}]")

    validate_output_paths(execution_outputs, "execution_outputs")
    if len(output_paths) != len(set(output_paths)):
        blockers.append("board execution output paths are not unique")

    top_module = str(plan.get("top_module") or "").strip()
    if not top_module:
        blockers.append("board_simulation_preflight_plan.top_module is missing")
    pass_regex = str(plan.get("pass_regex") or "")
    if not pass_regex:
        blockers.append("board_simulation_preflight_plan.pass_regex is missing")
    rtl_output_file = plan.get("rtl_output_file")
    boundary_trace_file = plan.get("boundary_trace_file")
    for field, value in (
        ("rtl_output_file", rtl_output_file),
        ("boundary_trace_file", boundary_trace_file),
    ):
        if not _safe_board_relative_path(value):
            blockers.append(f"board_simulation_preflight_plan.{field} is unsafe or missing")
    vcs = copy.deepcopy(plan.get("vcs") if isinstance(plan.get("vcs"), dict) else {})
    if not isinstance(vcs.get("compile_args"), list) or not all(
        isinstance(value, str) for value in vcs.get("compile_args", [])
    ):
        blockers.append("board_simulation_preflight_plan.vcs.compile_args must be a string list")
    runtime_plusargs = vcs.get("runtime_plusargs")
    if not isinstance(runtime_plusargs, dict) or not runtime_plusargs or not all(
        isinstance(key, str)
        and key
        and isinstance(value, str)
        and value in {"input", "weight_image", "runtime_image", "expected_output"}
        for key, value in runtime_plusargs.items()
    ):
        blockers.append("board_simulation_preflight_plan.vcs.runtime_plusargs is invalid")
    elif runtime_enabled and "runtime_image" not in set(runtime_plusargs.values()):
        blockers.append(
            "board_simulation_preflight_plan.vcs.runtime_plusargs does not stage the runtime image"
        )

    board_manifest = {
        "schema_version": "spatialaccagent.board_simulation_manifest.v1",
        "validation_mode": validation_mode,
        "status": "ready" if not blockers else "incomplete",
        **(
            {
                "frozen_compute_slot_identity_attestation": frozen_identity_attestation
            }
            if frozen_identity_attestation
            else {}
        ),
        "exact_sample_wrapper_unmodified": True,
        "source_identity_sha256": sha256_file(identity_path) if identity_path.is_file() else None,
        "source_files": compile_rows,
        "compile_source_ids": [str(row.get("source_id")) for row in compile_rows],
        "compiled_sample_source_ids": [str(row.get("source_id")) for row in preserved_rows],
        "replaced_sample_source_ids": replaced_ids,
        "generated_source_ids": generated_ids,
        **(
            {"external_simulation_fixture": external_fixture}
            if not compute_slot_axi_mode
            else {}
        ),
        "sample_runtime_auxiliary_files": sample_runtime_auxiliary_files,
        "source_replacements": source_replacements,
        "synthesis_sources_excluded": True,
        "source_closure_sha256": closure_hash,
        "compile_source_set_sha256": compile_source_set_fingerprint(compile_rows),
        "compute_slot_abi_sha256": abi_hash,
        "timing_contract_sha256": timing_hash,
        "axi_interfaces_sha256": axi_hash,
        "multilayer_harness": harness,
        "model_layer_count": model_layers,
        "validation_layer_indices": validation_layer_indices,
        "all_target_layers": covers_full_model,
        "target_layer_count": target_layers,
        "bound_layer_count": target_layers,
        "board_consumed_tensor_hashes": required_tensor_hashes,
        "board_integration_contract": integration,
        "board_integration_contract_sha256": canonical_contract_sha256(integration),
        "runtime_constant_binding": runtime_constant_binding,
        "checkpoint_framework_authority_binding": copy.deepcopy(
            checkpoint_framework_binding
        ),
        "testbench": testbench,
        "top_module": top_module,
        "protocol_monitor_contract": monitor_contract,
        "protocol_monitor_contract_sha256": canonical_contract_sha256(monitor_contract),
        "generated_evidence_records": evidence_records,
        "execution_outputs": execution_outputs,
        "vcs_compile_plan": compile_plan,
        "vcs_compile_plan_sha256": canonical_contract_sha256(compile_plan),
        "artifacts": {
            "input": input_artifact or {},
            "weight_image": weight_artifact or {},
            **({"runtime_image": runtime_image_artifact} if runtime_enabled else {}),
            "expected_output": expected_artifact or {},
        },
        "semantic_testbench_manifest": {
            "path": str(semantic_path),
            "sha256": sha256_file(semantic_path) if semantic_path.is_file() else None,
        },
        "pass_regex": pass_regex,
        "rtl_output_file": rtl_output_file,
        "boundary_trace_file": boundary_trace_file,
        "vcs": vcs,
        **(
            {"remote_workdir": plan.get("remote_workdir")}
            if plan.get("remote_workdir") is not None
            else {}
        ),
    }
    write_json(output_path, board_manifest)
    preflight = validate_exact_board_preflight(identity_path, output_path)
    blockers.extend(str(value) for value in preflight.get("blockers", []) if str(value))
    blockers = list(dict.fromkeys(blockers))
    status = "pass" if not blockers and preflight.get("status") == "pass" else "incomplete"
    report = {
        "schema_version": "spatialaccagent.board_simulation_preflight_materialization.v1",
        "status": status,
        "manifest": str(output_path),
        "manifest_sha256": sha256_file(output_path),
        "manifest_status": board_manifest.get("status"),
        "vcs_compile_plan_sha256": board_manifest.get("vcs_compile_plan_sha256"),
        "exact_board_preflight": preflight,
        "checkpoint_framework_authority_binding": copy.deepcopy(
            checkpoint_framework_binding
        ),
        "blockers": blockers,
    }
    write_json(materialization_path, report)
    report["path"] = str(materialization_path)
    return report


def finalize_dut_weight_binding_manifest(
    run_dir: Path,
    out_dir: Path,
    *,
    require_single_layer: bool = False,
    require_board: bool = False,
    single_layer_certificate_path: Path | None = None,
) -> dict[str, Any]:
    manifest_path = run_dir / "generated" / "memory" / "dut_weight_binding_manifest.json"
    requirements_path = run_dir / "verification" / "semantic_testbench" / "dut_weight_binding_requirements.json"
    source_provenance: dict[str, Any] = {}
    patch_path = out_dir / "agent_patch_application.json"
    prior_materialization_path = out_dir / "dut_weight_binding_materialization.json"
    prior_materialization = read_json_if_exists(prior_materialization_path)
    source_agent_manifest_sha256 = sha256_file(manifest_path) if manifest_path.is_file() else ""
    if source_agent_manifest_sha256 and patch_path.is_file():
        patch_report = read_json_if_exists(patch_path)
        patch_files = (
            patch_report.get("files", [])
            if patch_report.get("status") == "pass"
            and patch_report.get("blockers") == []
            and isinstance(patch_report.get("files"), list)
            else []
        )
        for row in patch_files:
            if not isinstance(row, dict):
                continue
            try:
                row_path = Path(str(row.get("path") or "")).resolve()
            except OSError:
                continue
            if (
                row_path == manifest_path.resolve()
                and row.get("after_sha256") == source_agent_manifest_sha256
            ):
                source_provenance = {
                    "source_patch_application": str(patch_path),
                    "source_patch_application_sha256": sha256_file(patch_path),
                    "source_agent_manifest": str(manifest_path),
                    "source_agent_manifest_sha256": source_agent_manifest_sha256,
                }
                break
        if not source_provenance:
            provenance_fields = (
                "source_patch_application",
                "source_patch_application_sha256",
                "source_agent_manifest",
                "source_agent_manifest_sha256",
            )
            try:
                prior_patch_path = Path(
                    str(prior_materialization.get("source_patch_application") or "")
                ).resolve()
                prior_agent_manifest_path = Path(
                    str(prior_materialization.get("source_agent_manifest") or "")
                ).resolve()
            except OSError:
                prior_patch_path = Path()
                prior_agent_manifest_path = Path()
            prior_agent_sha = str(
                prior_materialization.get("source_agent_manifest_sha256") or ""
            )
            patch_attests_agent_manifest = any(
                isinstance(row, dict)
                and Path(str(row.get("path") or "")).resolve()
                == manifest_path.resolve()
                and row.get("after_sha256") == prior_agent_sha
                for row in patch_files
                if row.get("path")
            )
            if (
                prior_materialization.get("schema_version")
                == "spatialaccagent.dut_weight_binding_materialization.v1"
                and prior_materialization.get("manifest_sha256")
                == source_agent_manifest_sha256
                and all(prior_materialization.get(field) for field in provenance_fields)
                and prior_patch_path == patch_path.resolve()
                and prior_materialization.get("source_patch_application_sha256")
                == sha256_file(patch_path)
                and prior_agent_manifest_path == manifest_path.resolve()
                and patch_attests_agent_manifest
            ):
                source_provenance = {
                    field: prior_materialization[field]
                    for field in provenance_fields
                }
    blockers: list[str] = []
    if not manifest_path.is_file():
        blockers.append(f"agent patch did not create DUT weight-binding manifest: {manifest_path}")
        manifest: dict[str, Any] = {}
    else:
        manifest = read_json_if_exists(manifest_path)
    if require_board and manifest:
        manifest = canonicalize_exact_board_manifest_declarations(
            manifest,
            run_dir,
            out_dir,
        )
    if require_board:
        source_provenance = prefer_archived_exact_board_source_provenance(
            manifest,
            manifest_path,
            out_dir,
            source_provenance,
        )
    checkpoint_framework_binding = (
        rebind_manifest_checkpoint_framework_authority(manifest)
        if require_board
        else {
            "schema_version": (
                "spatialaccagent.checkpoint_manifest_framework_binding.v1"
            ),
            "status": "not_required",
            "changed": False,
        }
    )
    if checkpoint_framework_binding.get("status") == "fail":
        blockers.extend(
            "checkpoint_framework_authority: " + str(error)
            for error in checkpoint_framework_binding.get(
                "adapter_binding", {}
            ).get("errors", [])
            if str(error)
        )
    requirements = read_json_if_exists(requirements_path)
    if not requirements:
        blockers.append(f"DUT weight-binding requirements are missing: {requirements_path}")
    if require_board and isinstance(
        manifest.get("board_simulation_preflight_plan"), dict
    ):
        selection_refresh_blockers: list[str] = []
        _materialize_external_fixture_preflight_selection(
            manifest["board_simulation_preflight_plan"],
            run_dir,
            selection_refresh_blockers,
        )
        blockers.extend(
            f"board_preflight: {value}" for value in selection_refresh_blockers
        )

    generated_modules: set[str] = set()
    generated_source_candidates = [
        *(run_dir / "generated" / "chisel").glob("*.sv"),
        *(run_dir / "generated" / "semantic_harness").rglob("*.sv"),
        *(run_dir / "generated" / "semantic_harness").rglob("*.v"),
        *(run_dir / "generated" / "board_integration").rglob("*.sv"),
        *(run_dir / "generated" / "board_integration").rglob("*.v"),
    ]
    for source in generated_source_candidates:
        try:
            generated_modules.update(
                re.findall(r"(?m)^module\s+([A-Za-z_][A-Za-z0-9_$]*)\b", source.read_text(encoding="utf-8"))
            )
        except (OSError, UnicodeDecodeError):
            continue

    stage_harnesses = manifest.get("stage_harnesses", {}) if isinstance(manifest.get("stage_harnesses"), dict) else {}
    normalized_harnesses: dict[str, Any] = {}
    all_consumed: set[str] = set()
    lower_layer_certificate = reusable_operator_leaf_promotion_certificate(run_dir)
    reuse_certified_lower_layer = (
        (require_single_layer or require_board)
        and lower_layer_certificate.get("status") == "pass"
    )
    for row in requirements.get("stage_requirements", []):
        if not isinstance(row, dict):
            continue
        stage_id = str(row.get("stage_id") or "")
        required_hashes = {
            str(item.get("sha256"))
            for item in row.get("required_tensors", [])
            if isinstance(item, dict) and item.get("sha256")
        }
        harness = stage_harnesses.get(stage_id)
        if not isinstance(harness, dict):
            blockers.append(f"DUT binding has no agent-generated harness for {stage_id}")
            continue
        if reuse_certified_lower_layer:
            normalized = copy.deepcopy(harness)
            errors = certified_stage_harness_metadata_errors(harness, row)
        else:
            normalized, errors = harness_contract_errors(
                harness,
                required_hashes,
                str(row.get("weight_layout_contract_sha256") or ""),
                str(row.get("runtime_constant_contract_sha256") or ""),
                run_dir,
                generated_modules,
            )
        normalized_harnesses[stage_id] = normalized
        all_consumed.update(str(value) for value in normalized.get("consumed_tensor_hashes", []))
        blockers.extend(f"{stage_id}: {error}" for error in errors)

    required_global = {
        str(row.get("sha256"))
        for row in requirements.get("single_layer_required_tensors", [])
        if isinstance(row, dict) and row.get("sha256")
    }
    missing_global = sorted(required_global - all_consumed)
    if missing_global:
        blockers.append(f"agent-generated leaf harnesses do not cover {len(missing_global)} required tensor hash(es)")

    normalized_single_layer: dict[str, Any] | None = None
    if require_single_layer or require_board:
        single_layer_harness = manifest.get("single_layer_harness")
        if not isinstance(single_layer_harness, dict):
            blockers.append("DUT binding has no agent-generated connected single-layer harness")
        else:
            normalized_single_layer, single_errors = connected_harness_contract_errors(
                single_layer_harness,
                requirements,
                run_dir,
                generated_modules,
            )
            all_consumed.update(
                str(value)
                for value in normalized_single_layer.get(
                    "consumed_tensor_hashes", []
                )
            )
            blockers.extend(f"single_layer: {error}" for error in single_errors)

    normalized_multilayer: dict[str, Any] | None = None
    if require_board and normalized_single_layer is not None:
        integration = copy.deepcopy(
            manifest.get("board_integration_contract")
            if isinstance(manifest.get("board_integration_contract"), dict)
            else {}
        )
        runtime_paths = exact_board_memory_runtime_paths(run_dir, out_dir)
        for field, path in (
            ("board_memory_runtime_contract_sha256", runtime_paths["contract"]),
            ("full_weight_image_manifest_sha256", runtime_paths["image_manifest"]),
            ("full_weight_image_sha256", runtime_paths["image"]),
            (
                "full_layer_runtime_capture_contract_sha256",
                runtime_paths["runtime_capture"],
            ),
            (
                "full_runtime_image_manifest_sha256",
                runtime_paths["runtime_image_manifest"],
            ),
            ("full_runtime_image_sha256", runtime_paths["runtime_image"]),
        ):
            if path.is_file():
                integration[field] = sha256_file(path)
        manifest["board_integration_contract"] = integration
        normalized_multilayer, board_errors = board_integration_binding_errors(
            manifest,
            normalized_single_layer,
            run_dir,
            out_dir,
            single_layer_certificate_path,
            source_provenance,
        )
        blockers.extend(f"board_integration: {error}" for error in board_errors)

    manifest.update(
        {
            "schema_version": "spatialaccagent.dut_weight_binding_manifest.v1",
            "status": "pass" if not blockers else "incomplete",
            "accelerator_scope": "transformer_blocks_only",
            "source_checkpoint_sha256": requirements.get("source_checkpoint_sha256"),
            "source_reference_sha256": requirements.get("source_reference_sha256"),
            "numeric_policy_sha256": requirements.get("numeric_policy_sha256"),
            "model_semantic_adapter_sha256": requirements.get("model_semantic_adapter_sha256"),
            "scope_coverage_complete": not blockers,
            "dut_consumes_bound_weights": not blockers,
            "default_or_identity_weight_fallback_disabled": not blockers,
            "consumed_tensor_hashes": sorted(all_consumed),
            "stage_harnesses": normalized_harnesses,
            **(
                {"single_layer_harness": normalized_single_layer}
                if normalized_single_layer is not None
                else {}
            ),
            **(
                {"multilayer_harness": normalized_multilayer}
                if normalized_multilayer is not None
                else {}
            ),
            "materialization": {
                "source": "agent_file_edits_plus_framework_hash_validation",
                "requirements": str(requirements_path),
                "requirements_sha256": sha256_file(requirements_path) if requirements_path.is_file() else None,
                "executed_weight_consumption_pending_real_simulation": True,
                "verification_scope": (
                    "board_axi_ddr_closure"
                    if require_board
                    else "single_layer_closure"
                    if require_single_layer
                    else "operator_leaf_closure"
                ),
                "golden_or_reference_files_modified": False,
                "checkpoint_framework_authority_binding": copy.deepcopy(
                    checkpoint_framework_binding
                ),
            },
            "materialization_blockers": blockers,
        }
    )
    board_preflight: dict[str, Any] | None = None
    if require_board:
        if isinstance(manifest.get("board_simulation_preflight_plan"), dict):
            missing_prerequisites = (
                framework_vcs_plan_binding_missing_prerequisites(
                    run_dir,
                    str(
                        manifest["board_simulation_preflight_plan"].get(
                            "validation_mode"
                        )
                        or "exact_sample_physical_ddr"
                    ),
                )
            )
            if missing_prerequisites:
                blockers.append(
                    "board_preflight: framework VCS-plan binding prerequisites are "
                    "missing: " + "; ".join(missing_prerequisites)
                )
            else:
                manifest, vcs_binding = bind_framework_vcs_compile_plan(
                    manifest,
                    run_dir,
                    out_dir,
                    manifest_path,
                )
                blockers.extend(
                    f"board_preflight: {value}"
                    for value in vcs_binding.get("blockers", [])
                )
        if normalized_multilayer is None:
            blockers.append("board_integration: normalized multi-layer harness is unavailable for exact preflight")
        else:
            board_preflight = materialize_exact_board_preflight_manifest(
                manifest,
                normalized_multilayer,
                run_dir,
            )
            blockers.extend(
                f"board_preflight: {error}"
                for error in board_preflight.get("blockers", [])
                if str(error)
            )
    blockers = list(dict.fromkeys(blockers))
    manifest.update(
        {
            "status": "pass" if not blockers else "incomplete",
            "scope_coverage_complete": not blockers,
            "dut_consumes_bound_weights": not blockers,
            "default_or_identity_weight_fallback_disabled": not blockers,
            "materialization_blockers": blockers,
        }
    )
    materialization = manifest.get("materialization")
    if isinstance(materialization, dict) and require_board:
        materialization.update(
            {
                "board_simulation_preflight_manifest": (
                    board_preflight.get("manifest") if board_preflight is not None else None
                ),
                "board_simulation_preflight_manifest_sha256": (
                    board_preflight.get("manifest_sha256") if board_preflight is not None else None
                ),
                "board_simulation_preflight_status": (
                    board_preflight.get("status") if board_preflight is not None else "incomplete"
                ),
                "board_simulation_execution_pending_real_vcs": True,
            }
        )
    write_json(manifest_path, manifest)
    report = {
        "schema_version": "spatialaccagent.dut_weight_binding_materialization.v1",
        "status": "pass" if not blockers else "incomplete",
        "manifest": str(manifest_path),
        "manifest_sha256": sha256_file(manifest_path),
        "stage_harness_count": len(normalized_harnesses),
        "single_layer_harness_materialized": normalized_single_layer is not None,
        "board_integration_harness_materialized": normalized_multilayer is not None,
        "board_simulation_preflight_materialized": (
            board_preflight is not None and board_preflight.get("status") == "pass"
        ),
        "board_simulation_preflight_manifest": (
            board_preflight.get("manifest") if board_preflight is not None else None
        ),
        "board_simulation_preflight_manifest_sha256": (
            board_preflight.get("manifest_sha256") if board_preflight is not None else None
        ),
        "vcs_compile_plan_sha256": (
            board_preflight.get("vcs_compile_plan_sha256") if board_preflight is not None else None
        ),
        "board_simulation_preflight_report": (
            board_preflight.get("path") if board_preflight is not None else None
        ),
        "consumed_tensor_hash_count": len(all_consumed),
            "checkpoint_framework_authority_binding": copy.deepcopy(
                checkpoint_framework_binding
            ),
            "lower_layer_certificate_reuse": copy.deepcopy(
                lower_layer_certificate
            ),
            "blockers": blockers,
            **source_provenance,
        }
    report_path = out_dir / "dut_weight_binding_materialization.json"
    write_json(report_path, report)
    report["path"] = str(report_path)
    return report
"
